  function emailConfigured(){
    return !!(emailCfg.publicKey && emailCfg.serviceId && emailCfg.templateId && (emailCfg.officeEmail));
  }

  // downscale a signature dataURL so PDFs/email attachments stay small
  function downscaleDataUrl(dataUrl, maxWidth){
    return new Promise((resolve)=>{
      const img = new Image();
      img.onload = ()=>{
        const scale = Math.min(1, maxWidth / img.width);
        const c = document.createElement('canvas');
        c.width = img.width*scale; c.height = img.height*scale;
        const ctx = c.getContext('2d');
        ctx.drawImage(img, 0, 0, c.width, c.height);
        resolve(c.toDataURL('image/png'));
      };
      img.onerror = ()=> resolve(dataUrl);
      img.src = dataUrl;
    });
  }

  // send the generated PDF via EmailJS as a dynamic attachment
  async function sendEmailWithPdf(doc, data, filename){
    await loadAwesScript('emailjs', awesLibs.emailjs);
    if(!emailConfigured()) return {ok:false, reason:'not_configured'};
    try{ emailjs.init({publicKey: emailCfg.publicKey}); }catch(e){}
    const base64 = doc.output('datauristring').split(',')[1];
    // rough size check — most free/personal EmailJS plans cap attachments around 500KB
    const approxBytes = base64.length * 0.75;
    if(approxBytes > 480000){
      return {ok:false, reason:'too_large'};
    }
    const toEmail = (data.custEmail || '').trim();
    const recipients = toEmail ? (toEmail+','+emailCfg.officeEmail) : emailCfg.officeEmail;
    const templateParams = {
      to_email: recipients,
      sr_no: data.srNo || '',
      customer_name: data.custName || '',
      service_date: data.date || '',
      pdf_attachment: base64,
      pdf_filename: filename
    };
    try{
      await emailjs.send(emailCfg.serviceId, emailCfg.templateId, templateParams);
      return {ok:true};
    }catch(err){
      console.error('EmailJS error', err);
      return {ok:false, reason:'send_failed'};
    }
  }


// ---------- meta bar live update ----------
  $('svcDate').addEventListener('change', ()=> $('metaDate').textContent = fmtDate($('svcDate').value));

  // ---------- init defaults ----------
  // Which dispatch ticket + equipment line item (if any) the report
  // currently being filed is tied to — set by srApplyJobOrder (dispatch.js)
  // when a technician picks a piece of equipment off a Job Order, read by
  // the save handler in pdf.js to mark that item "reported" once the report
  // goes through. Declared here because resetForm() below runs once at load
  // time, before dispatch.js's own module code has executed.
  let srCurrentTicketId = null;
  let srCurrentEquipId = null;
  // Set instead of srCurrentEquipId when a technician has picked MULTIPLE
  // equipment items off one Job Order to batch-sign — see
  // srApplyJobOrderBatch() (dispatch.js) and the submit loop in pdf.js.
  // Each entry is one equipment item off the ticket's equipmentList.
  let srBatchEquipItems = null;

  // Service category (Aircon / Ventilation / General Scope — see
  // SERVICE_CATEGORIES in core.js).
  //   srPickerCategory — what the technician chose on the Select Category
  //     entry screen; filters the Job Order picker. NOT cleared by
  //     resetForm(), because srApplyJobOrder calls resetForm() and still
  //     needs it afterwards.
  //   srCurrentCategory — the category of the report actually being filed;
  //     saved as serviceCategory. Cleared by resetForm(), set when a job
  //     order is applied or a saved report is reopened.
  let srPickerCategory = null;
  let srCurrentCategory = null;
  function srSetReportCategory(key){
    srCurrentCategory = key || null;
    const pill = $('metaCategory');
    if(!pill) return;
    const label = serviceCategoryLabel(srCurrentCategory);
    pill.textContent = label;
    pill.style.display = label ? '' : 'none';
  }

  // Progressive-section state. Declared HERE, at the top of the module,
  // rather than beside the functions that use it further down: resetForm()
  // is called at load and assigns srMaxSection, so a `let` declared after
  // that call site leaves it in the temporal dead zone — which threw
  // "Cannot access 'srMaxSection' before initialization" and took the
  // whole bundle (and therefore the whole page) down with it.
  // The wizard's steps. Section 1 (Customer's Information) is deliberately
  // NOT a step — it comes from the Job Order and the technician cannot edit
  // it, so it is filled silently and never shown. Sections 8-10 are the
  // split of what used to be one "Acknowledgment" card, so Time & Remarks,
  // the technician's signature and the customer's signature each get their
  // own screen.
  const SR_SECTION_TITLES = {
    1:"Customer's Information", 2:'Equipment Details', 3:'Report Summary',
    4:'Components / Parts Needed', 5:'Works Done to this unit', 6:'Operation Parameters',
    7:'Installation Parameters', 8:'Time & Remarks', 9:'Technician Signature',
    10:'Customer Acknowledgment'
  };
  const SR_FIRST_SECTION = 2;   // the wizard always starts at Equipment Details
  const SR_LAST_SECTION = 10;
  let srMaxSection = 1;
  // The ONE section currently on screen (srRevealSections hides the rest).
  // srMaxSection is still the furthest reached — it's what the chip
  // navigator and the progress bar are built from.
  let srCurrentSection = 1;
  function resetForm(){
    // Scoped to the Service Report view only. This used to select every text,
    // number, textarea and checkbox on the page, so starting a new report also
    // wiped whatever the user had typed into the Dispatch, Leave, Cash Advance,
    // Customers and Admin forms — all of which live in the same document.
    const scope = $('serviceReportView') || document;
    scope.querySelectorAll('input[type=text], input[type=number], textarea').forEach(el=>el.value='');
    scope.querySelectorAll('input[type=checkbox]').forEach(el=>{ el.checked=false; el.closest('.chk')?.classList.remove('checked'); });
    $('svcDate').value = todayISO();
    $('timeIn').value=''; $('timeOut').value='';
    $('findingsList').innerHTML=''; $('recsList').innerHTML=''; $('servicesDoneList').innerHTML='';
    addListRow('findingsList'); addListRow('recsList'); addListRow('servicesDoneList');
    $('materialsBody').innerHTML=''; materialRowCount=0;
    $('isInstallToggle').checked=false; $('installSection').classList.remove('open');
    loadCustomerEquipment(null);
    clearEquipPickedId();
    setEquipTab(null);
    $('custDetailsWrap').style.display = 'none';
    // Technicians must pick an authorized Job Order before Customer's Info
    // (and everything after it) appears — admin has no Job Order gate and
    // always sees it directly. srRenderJobOrderPicker/srApplyJobOrder
    // re-confirm this on their own paths too; this just sets the sane
    // default whenever the form is reset from anywhere else.
    const sec1 = $('sec1Card');
    if(sec1) sec1.style.display = (currentUser && currentUser.role==='admin') ? '' : 'none';
    // Every step card, including sec9/sec10 added when Acknowledgment was
    // split — the old fixed list stopped at sec8 and left the two new
    // signature steps visible after a reset.
    for(let n=2; n<=10; n++){
      const el = $('sec'+n+'Card'); if(el) el.style.display = 'none';
    }
    $('materialsTableWrap').style.display = 'none';
    collapseAllSections();
    toggleCollapsibleSection($('sec1Head'), true); // keep section 1 (Customer's Info) open — it's the entry point
    if($('srJobOrderHead')) toggleCollapsibleSection($('srJobOrderHead'), true); // keep the Job Order picker open too
    if(sigCustomerPad) sigCustomerPad.clear();
    if(sigTechPad) sigTechPad.clear();
    unlockSignature('sigCustomer'); unlockSignature('sigTech');
    $('sigCustomerPh').style.display='flex'; $('sigTechPh').style.display='flex';
    $('metaDate').textContent = fmtDate($('svcDate').value);
    $('statusPill').textContent='Draft'; $('statusPill').className='status-pill status-draft';
    currentSrNo = null;
    currentTechnicianId = null;
    srCurrentTicketId = null;
    srSetReportCategory(null);
    // Back to an ad-hoc report with no job order, where choosing between an
    // existing unit and a new one genuinely applies again. 'flex', not '',
    // because the bar's layout comes from an inline display:flex.
    if($('equipTabBar')) $('equipTabBar').style.display = 'flex';
    if($('phase3Toggle')) $('phase3Toggle').checked = false;
    if(typeof srApplyPhaseMode === 'function') srApplyPhaseMode();
    srCurrentEquipId = null;
    srBatchEquipItems = null;
    if($('srBatchBanner')) $('srBatchBanner').style.display = 'none';
    $('metaSrNo').textContent='—';
    clearInvalid();
    applyTechNameDefault();
    srMaxSection = 1;
    srCurrentSection = 1;
    srUpdateFooterBar();
    srRenderStepper();
  }
  resetForm();
  // ---------- progressive sections ----------
  // The report has 8 sections. They used to all appear at once the moment a
  // customer was set, which is a wall of fields on a phone in the field.
  // Now each one reveals as the previous is finished, via a Continue button
  // appended to every section body. Sections already revealed STAY
  // revealed, so going back to change something never means re-walking the
  // form. The step tracker above stays visible throughout either way.
  // Section 2 is filled automatically per unit in batch mode (see
  // srBatchBanner), so it's skipped rather than shown empty.
  function srSectionIsSkipped(n){
    if(n===1) return true; // customer info: inherited from the Job Order, never shown
    // Batch mode fills equipment details per unit at submit time, so
    // srApplyJobOrderBatch hides that card. Without this the wizard still
    // counted it as the current step and parked on a hidden card with no
    // Next button — a dead end on "Step 1 of 8 · Equipment Details".
    if(n===2 && srBatchEquipItems && srBatchEquipItems.length > 1) return true;
    // Installation Parameters is behind a toggle — off means the unit wasn't
    // newly installed on this visit, so the step is skipped entirely.
    if(n===7){ const t = $('installToggle'); return !(t && t.checked); }
    return false;
  }
  function srNextSection(n){
    let next = n+1;
    while(next<=SR_LAST_SECTION && srSectionIsSkipped(next)) next++;
    return next;
  }
  function srPrevSection(n){
    let prev = n-1;
    while(prev>=SR_FIRST_SECTION && srSectionIsSkipped(prev)) prev--;
    return prev < SR_FIRST_SECTION ? SR_FIRST_SECTION : prev;
  }
  // Only sections with genuinely required fields block progress. Everything
  // else continues freely — gating optional sections would turn progressive
  // disclosure into an obstacle rather than a simplification.
  function srSectionBlocker(n){
    if(n===1){
      if(!$('custName').value.trim()) return 'Enter the customer name to continue';
      if(!$('svcDate').value) return 'Set the service date to continue';
      const email = $('custEmail').value.trim();
      if(!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return 'A valid customer email is required — the report is sent there';
      return null;
    }
    return null;
  }
  // The footer (Save Draft / Generate & Share Report) belongs to the END of
  // the form. It used to show for the entire "Create New" tab, which was
  // right when every section was visible at once — but with progressive
  // sections it meant offering "Generate & Share Report" while the
  // technician was still on Customer's Information. It now appears only
  // once the last section (Acknowledgment, where the signatures are) has
  // been reached, and stays visible after that so they can still scroll up
  // to edit and come back.
  function srUpdateFooterBar(){
    const bar = $('footerBar');
    if(!bar) return;
    const newPanel = $('srNewPanel');
    const onNewTab = newPanel && newPanel.style.display !== 'none';
    bar.style.display = (onNewTab && srCurrentSection >= SR_LAST_SECTION) ? 'flex' : 'none';
  }
  // A section counts as already handled when the Job Order prefill has
  // filled everything it asks for (srApplyJobOrder populates customer
  // details, the equipment fields, and the trouble call). There's nothing
  // to do on those, so the form opens past them instead of making the
  // technician page through screens of data they didn't type and can't
  // usefully change.
  function srSectionPrefilled(n){
    if(n===1){
      return !!$('custName').value.trim() && !!$('svcDate').value && !!$('custEmail').value.trim();
    }
    if(n===2){
      return srSectionIsSkipped(2)
        || !!($('equipType').value.trim() || $('modelCU').value.trim() || $('modelFCU').value.trim());
    }
    // Section 3 is deliberately NEVER treated as prefilled. The Job Order
    // supplies its trouble call, but Findings and Recommendations — the
    // substance of the report — start empty, and skipping past it would
    // take a technician to the signatures without ever asking for them.
    return false; // 3-8 always need real input
  }
  // First section that actually needs attention.
  function srFirstUnfilledSection(){
    for(let n=1; n<=SR_LAST_SECTION; n++){
      if(srSectionIsSkipped(n)) continue;
      if(!srSectionPrefilled(n)) return n;
    }
    return SR_LAST_SECTION;
  }

  // Only the CURRENT section is on screen. Showing every unlocked section
  // at once rebuilt the same wall of fields progressive disclosure exists
  // to avoid — by the last section the page was all eight again. Earlier
  // sections stay reachable through the chip navigator (srRenderSectionNav)
  // rather than by scrolling past them.
  function srRevealSections(){
    for(let n=1; n<=SR_LAST_SECTION; n++){
      const card = $('sec'+n+'Card');
      if(!card) continue;
      if(n===1 && currentUser && currentUser.role!=='admin' && !srCurrentTicketId){
        card.style.display = 'none'; // no Job Order picked yet
        continue;
      }
      const isCurrent = (n===srCurrentSection && !srSectionIsSkipped(n));
      card.style.display = isCurrent ? '' : 'none';
      // Showing the CARD isn't enough — these are collapsible, and the
      // body starts display:none, so without this the technician had to
      // tap the header open on every single step.
      if(isCurrent){
        const head = card.querySelector('.collapsible-head');
        if(head) toggleCollapsibleSection(head, true);
      }
      // NOTE: the equipment tab bar is NOT toggled here. This runs from
      // revealSectionsAfterCustomer(), which srApplyJobOrder calls BEFORE
      // it assigns srCurrentTicketId — so any check of that id here reads
      // null and gets it wrong. It's hidden in srApplyJobOrder /
      // srApplyJobOrderBatch instead (after the id is set) and restored
      // by resetForm for ad-hoc reports.
    }
    srRenderSectionNav();
    srUpdateFooterBar();
    srRenderStepper();
  }

  // Chips for every section reached so far, so going back to fix something
  // is one tap instead of a scroll through hidden cards.
  // Chips removed: the single progress line above is the only indicator
  // now, and it deliberately shows just the current step. Kept as a no-op
  // so the existing call sites don't need unpicking.
  function srRenderSectionNav(){
    const host = $('srSectionNav');
    if(!host) return;
    host.innerHTML = ''; host.style.display = 'none';
    if(true) return;
    if(srMaxSection<=1 && srCurrentSection<=1){ host.innerHTML = ''; host.style.display='none'; return; }
    host.style.display = '';
    let html = '';
    for(let n=1; n<=SR_LAST_SECTION; n++){
      if(srSectionIsSkipped(n)) continue;
      if(n>srMaxSection) continue;
      const cls = n===srCurrentSection ? 'sr-nav-chip active' : 'sr-nav-chip';
      html += '<button type="button" class="'+cls+'" data-sr-nav="'+n+'">'+n+'</button>';
    }
    host.innerHTML = '<span class="sr-nav-label">Section</span>'+html;
  }
  function srGoToSection(n){
    if(n>SR_LAST_SECTION) n = SR_LAST_SECTION;
    if(n<1) n = 1;
    srCurrentSection = n;
    srMaxSection = Math.max(srMaxSection, n);
    srRevealSections();
    const head = $('sec'+n+'Head');
    if(head) toggleCollapsibleSection(head, true);
    window.scrollTo({top:0, behavior:'smooth'});
  }
  // Appended once at startup — putting these in the markup would mean
  // eight near-identical blocks kept in sync by hand.
  function srInstallContinueButtons(){
    for(let n=SR_FIRST_SECTION; n<=SR_LAST_SECTION; n++){
      const body = $('sec'+n+'Body');
      if(!body || body.querySelector('.sr-step-nav')) continue;
      const wrap = document.createElement('div');
      wrap.className = 'sr-continue-wrap sr-step-nav';
      // Back on every step except the first; Next on every step except the
      // last (where the footer's Generate/Save buttons take over).
      const backBtn = n>SR_FIRST_SECTION
        ? '<button type="button" class="btn btn-secondary sr-back-btn" data-sr-back="'+n+'">\u2190 Back</button>'
        : '';
      const nextBtn = n<SR_LAST_SECTION
        ? '<button type="button" class="btn btn-primary sr-continue-btn" data-sr-section="'+n+'">Next \u2192</button>'
        : '';
      wrap.innerHTML = backBtn + nextBtn;
      body.appendChild(wrap);
    }
    document.addEventListener('click', (e)=>{
      const back = e.target.closest('.sr-back-btn');
      if(!back) return;
      srGoToSection(srPrevSection(parseInt(back.getAttribute('data-sr-back'), 10)));
    });
    // Chip navigator — delegated, since the chips are re-rendered on every
    // section change.
    document.addEventListener('click', (e)=>{
      const chip = e.target.closest('[data-sr-nav]');
      if(!chip) return;
      srGoToSection(parseInt(chip.getAttribute('data-sr-nav'), 10));
    });
    document.addEventListener('click', (e)=>{
      const btn = e.target.closest('.sr-continue-btn');
      if(!btn) return;
      const n = parseInt(btn.getAttribute('data-sr-section'), 10);
      const blocker = srSectionBlocker(n);
      if(blocker){ toast(blocker); return; }
      const head = $('sec'+n+'Head');
      if(head) toggleCollapsibleSection(head, false); // collapse the one just finished
      srGoToSection(srNextSection(n));
    });
  }
  // Continue labels shift when batch mode skips section 2, so refresh them
  // whenever that mode changes.
  // Kept as a no-op: the step buttons now read plainly "Back" / "Next", so
  // there are no per-section labels to keep in sync. Still called from
  // dispatch.js when batch mode toggles.
  function srRefreshContinueLabels(){ srRenderSectionNav(); }

  // Resuming a saved draft: every step is reachable, but the technician is
  // put back at the FIRST step and walks forward from there, one screen at
  // a time — same as a new report. (Dropping them straight at the last
  // step would skip whatever the draft is still missing.)
  function srSetAllSectionsRevealed(){
    srMaxSection = SR_LAST_SECTION;
    srCurrentSection = SR_FIRST_SECTION;
    srRevealSections();
  }

  // Installation toggle reveals its own fields and re-evaluates whether
  // step 7 exists at all (srSectionIsSkipped reads this checkbox).
  (function(){
    const t = $('installToggle');
    if(!t) return;
    t.addEventListener('change', ()=>{
      const wrap = $('installFieldsWrap');
      if(wrap) wrap.style.display = t.checked ? '' : 'none';
      srRenderSectionNav();
    });
  })();
  // =====================================================================
  // Wizard entry flow: instruction gate -> Create New / Saved Draft ->
  // job order -> Single / Multiple -> unit -> the step form.
  // Each screen is a card; srShowEntry() shows exactly one of them (or
  // none, once the form itself is running).
  // =====================================================================
  // Entry point from the Report tab / bottom nav / Create New tab. The
  // instruction gate is shown EVERY time a new report is started, and
  // "I Understand" is the only way through to Create New / Saved Draft.
  const SR_ENTRY_SCREENS = ['srEntryGate','srEntryChoice','srEntryCategory','srEntryMode'];
  function srShowEntry(which){
    SR_ENTRY_SCREENS.forEach(id=>{ const el = $(id); if(el) el.style.display = (id===which) ? '' : 'none'; });
    const showingEntry = !!which;
    // While an entry screen is up, the form, its stepper, chips and footer
    // all stay out of the way.
    ['srStepperContainer','srSectionNav'].forEach(id=>{ const el=$(id); if(el) el.style.display = showingEntry ? 'none' : ''; });
    // The Job Order picker is a step of its own. Only ever HIDDEN here —
    // showing it is the Create New tile's job. Re-showing it on every
    // srShowEntry(null) is what left it stuck above every step of the
    // wizard after a unit was already chosen.
    if(showingEntry && $('srJobOrderCard')) $('srJobOrderCard').style.display = 'none';
    for(let n=1; n<=SR_LAST_SECTION; n++){ const c=$('sec'+n+'Card'); if(c && showingEntry) c.style.display='none'; }
    if(showingEntry && $('footerBar')) $('footerBar').style.display = 'none';
    // The old always-on instructions card is redundant now that the gate
    // shows the same content up front.
    if($('srInstructionsCard')) $('srInstructionsCard').style.display = 'none';
    if(!showingEntry) srRevealSections();
  }
  function srStartReportFlow(){
    const body = $('srEntryGateBody');
    const howto = $('srInstructionsBody');
    if(body){
      body.innerHTML = (howto ? howto.innerHTML : '<p>Fill each step and tap Continue. You will sign at the end.</p>')
        + '<button type="button" class="btn btn-primary" id="srGateOkBtn" style="width:100%; margin-top:14px;">I Understand</button>';
      const ok = body.querySelector('#srGateOkBtn');
      if(ok) ok.onclick = ()=> srShowEntry('srEntryChoice');
    }
    srShowEntry('srEntryGate');
  }
  if($('srTileCreateNew')) $('srTileCreateNew').addEventListener('click', ()=>{
    srPickerCategory = null;
    srShowEntry('srEntryCategory');
  });
  document.querySelectorAll('[data-sr-cat]').forEach(tile=>{
    tile.addEventListener('click', ()=>{
      srPickerCategory = tile.dataset.srCat;
      srShowEntry(null);
      if($('srJobOrderCard')) $('srJobOrderCard').style.display = '';
      // The Job Order picker already exists and is titled "Select from Job
      // Order" — reuse it rather than building a second list.
      if(typeof srRenderJobOrderPicker === 'function') srRenderJobOrderPicker();
    });
  });
  if($('srEntryCategoryBack')) $('srEntryCategoryBack').addEventListener('click', ()=>{
    srPickerCategory = null;
    srShowEntry('srEntryChoice');
  });
  if($('srJobOrderChangeCat')) $('srJobOrderChangeCat').addEventListener('click', ()=>{
    srPickerCategory = null;
    srShowEntry('srEntryCategory');
  });
  if($('srTileSavedDraft')) $('srTileSavedDraft').addEventListener('click', ()=>{
    // Hide every entry screen outright rather than going through
    // srShowEntry(null), which also re-reveals a form section on the way
    // out — pointless here and a source of flicker before the panel
    // switches. srShowTab does the rest (panel swap + loads the drafts).
    SR_ENTRY_SCREENS.forEach(id=>{ const el=$(id); if(el) el.style.display='none'; });
    if($('srJobOrderCard')) $('srJobOrderCard').style.display = 'none';
    // srShowTab — NOT showServiceReportTab, which doesn't exist.
    if(typeof srShowTab === 'function') srShowTab('draft');
  });
  // Back from Single/Multiple returns to the JOB ORDER LIST — the screen
  // it was actually reached from — not to the Create New / Saved Draft
  // tiles two steps earlier.
  if($('srEntryModeBack')) $('srEntryModeBack').addEventListener('click', ()=>{
    srShowEntry(null);
    if($('srJobOrderCard')) $('srJobOrderCard').style.display = '';
  });

  srInstallContinueButtons();

  // ---------- progressive step tracker ----------
  // Same jo-stepper visual language as the Job Order / Cash Advance
  // trackers. Re-rendered at every state change below rather than on every
  // keystroke — resetForm, applying a Job Order (single or batch), signing,
  // and submitting all call this directly.
  // One progress line, driven by the WIZARD SECTIONS themselves.
  //
  // This used to render a separate four-stage tracker (Job Order Selected /
  // Details Filled / Signed / Submitted) plus a section line plus a row of
  // numbered chips — three different progress indicators stacked on top of
  // each other, all saying overlapping things, and the chips advertised
  // every section already visited when only the current one matters.
  function srRenderStepper(){
    const container = $('srStepperContainer');
    if(!container) return;
    // Steps that actually exist for this report (Installation Parameters
    // drops out when its toggle is off, so "of N" stays truthful).
    const steps = [];
    for(let n=SR_FIRST_SECTION; n<=SR_LAST_SECTION; n++){
      if(!srSectionIsSkipped(n)) steps.push(n);
    }
    const total = steps.length;
    const pos = Math.max(1, steps.indexOf(srCurrentSection) + 1);
    const pct = total ? Math.round((pos/total)*100) : 0;
    container.innerHTML =
      '<div class="sr-progress">'+
        '<div class="sr-progress-head">'+
          '<span class="sr-progress-step">Step '+pos+' of '+total+'</span>'+
          '<span class="sr-progress-name">'+escapeHtml(SR_SECTION_TITLES[srCurrentSection]||'')+'</span>'+
        '</div>'+
        '<div class="sr-progress-bar"><span style="width:'+pct+'%"></span></div>'+
      '</div>';
  }
  ['custName','svcDate'].forEach(id=>{ const el = $(id); if(el){ el.addEventListener('input', srRenderStepper); el.addEventListener('change', srRenderStepper); } });
  srRenderStepper();
  // Auto-fills the Technician Name field from the logged-in account (still
  // editable, in case a different technician actually performed the work).
  function applyTechNameDefault(){
    if(currentUser && currentUser.name) $('techName').value = currentUser.name;
  }

  // ---------- validation ----------
  function clearInvalid(){
    document.querySelectorAll('.field.invalid').forEach(f=>f.classList.remove('invalid'));
  }
  function validate(){
    clearInvalid();
    let ok = true;
    if(!$('custName').value.trim()){ $('f_custName').classList.add('invalid'); ok=false; }
    if(!$('svcDate').value){ $('f_date').classList.add('invalid'); ok=false; }
    const email = $('custEmail').value.trim();
    if(!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){ $('f_custEmail').classList.add('invalid'); ok=false; }
    return ok;
  }

  // ---------- gather form data ----------
  function gatherData(){
    const findings = Array.from($('findingsList').querySelectorAll('textarea')).map(t=>t.value.trim()).filter(Boolean);
    const recs = Array.from($('recsList').querySelectorAll('textarea')).map(t=>t.value.trim()).filter(Boolean);
    const servicesDone = Array.from($('servicesDoneList').querySelectorAll('textarea')).map(t=>t.value.trim()).filter(Boolean);
    const materials = Array.from($('materialsBody').querySelectorAll('tr')).map(tr=>({
      description: tr.querySelector('.m-desc').value.trim(),
      qty: tr.querySelector('.m-qty').value.trim(),
      unit: tr.querySelector('.m-unit').value.trim()
    })).filter(r=>r.description||r.qty||r.unit);

    return {
      srNo: currentSrNo,
      serviceCategory: srCurrentCategory,
      technicianId: currentTechnicianId || (currentUser ? currentUser.id : null),
      date: $('svcDate').value,
      custName: $('custName').value.trim(),
      custAddress: $('custAddress').value.trim(),
      contactNo: $('contactNo').value.trim(),
      contactPerson: $('contactPerson').value.trim(),
      equipType: $('equipType').value.trim(), modelCU:$('modelCU').value.trim(), serialCU:$('serialCU').value.trim(),
      modelFCU:$('modelFCU').value.trim(), serialFCU:$('serialFCU').value.trim(),
      coolCap:$('coolCap').value.trim(), mountType:$('mountType').value.trim(),
      brand:$('brand').value.trim(), refrigerantType:$('refrigerantType').value.trim(),
      compressorType:$('compressorType').value.trim(), equipLocation:$('equipLocation').value.trim(),
      troubleCall:$('troubleCall').value.trim(), findings, recs, materials, servicesDone,
      before:{
        amp:[$('b_amp_l1').value,$('b_amp_l2').value,$('b_amp_l3').value],
        volt:[$('b_volt_l12').value,$('b_volt_l23').value,$('b_volt_l31').value],
        pressure:[$('b_press_suction').value,$('b_press_discharge').value],
        temp:$('b_temp').value, airflow:$('b_airflow').value
      },
      after:{
        amp:[$('a_amp_l1').value,$('a_amp_l2').value,$('a_amp_l3').value],
        volt:[$('a_volt_l12').value,$('a_volt_l23').value,$('a_volt_l31').value],
        pressure:[$('a_press_suction').value,$('a_press_discharge').value],
        temp:$('a_temp').value, airflow:$('a_airflow').value
      },
      isInstall: $('isInstallToggle').checked,
      install:{
        pd:[$('pd_suction').value,$('pd_discharge').value,$('pd_drain').value],
        pl:[$('pl_refline').value,$('pl_drain').value],
        ws:[$('ws_feeder').value,$('ws_control').value],
        breaker:$('circuit_breaker').value,
        pi:[$('pi_refline').value,$('pi_drain').value],
        riser:$('riser_height').value, ptrap:$('ptrap').value, bracketType:$('bracketType').value
      },
      timeIn:$('timeIn').value, timeOut:$('timeOut').value, remarks:$('remarks').value.trim(),
      custPrintedName:$('custPrintedName').value.trim(), techName:$('techName').value.trim(),
      custEmail: $('custEmail').value.trim(),
      sigCustomerRaw: sigCustomerPad.isEmpty() ? null : sigCustomerPad.toDataURL('image/png'),
      sigTechRaw: sigTechPad.isEmpty() ? null : sigTechPad.toDataURL('image/png')
    };
  }
  async function gatherDataForOutput(){
    await ensureSignaturePads();
    const data = gatherData();
    data.sigCustomer = data.sigCustomerRaw ? await downscaleDataUrl(data.sigCustomerRaw, 400) : null;
    data.sigTech = data.sigTechRaw ? await downscaleDataUrl(data.sigTechRaw, 400) : null;
    return data;
  }

  // ---------- save draft ----------
  // Returns SAVE_CLOUD / SAVE_QUEUED / SAVE_FAILED so callers stop telling the
  // user "saved" when the write actually failed and nothing was retained.
  // Drafts save locally first when there is no signal, then upload on their
  // own via the outbox (see registerOutboxHandler('report', ...) below) —
  // triggered automatically on 'online', on the app coming back to the
  // foreground, and by the periodic safety-net timer in core.js. "Sync now"
  // just runs that same flush immediately on demand.
  async function saveReport(srNo, data){
    // Which customer_equipment row this report is for is decided by an
    // explicit earlier choice, not guessed here: getEquipPickedId() (set
    // by renderEquipPicker()'s click handler, or by openReport() when
    // resuming a draft/batch item that already has one) is the real id if
    // the technician picked an existing record and hasn't edited a field
    // since. Otherwise this is content the technician typed via "+ Add
    // New" — genuinely new, so cloudAddCustomerEquipment() just creates a
    // fresh row, no matching against what's already on file.
    const matchedCustomer = customersCache.find(c=> c.name.toLowerCase() === (data.custName||'').trim().toLowerCase());
    if(matchedCustomer) data.equipmentId = getEquipPickedId() || await cloudAddCustomerEquipment(matchedCustomer.id, data);
    let result = SAVE_FAILED;
    if(await ensureCloud() && await cloudSaveReport(srNo, data)) result = SAVE_CLOUD;
    // Keep only the downscaled signatures on disk: the full-resolution raw
    // canvas exports are several hundred KB each and were being persisted for
    // no reason, filling local storage and bloating every upload.
    const persisted = Object.assign({}, data);
    delete persisted.sigCustomerRaw;
    delete persisted.sigTechRaw;
    try{ await window.storage.set('report:'+srNo, JSON.stringify(persisted), false); }
    catch(e){ console.error('local report save failed', e); }
    if(result!==SAVE_CLOUD){
      // Queue it so it uploads by itself the next time there is a connection,
      // instead of living only on this phone until someone reopens it.
      if(await outboxQueue('report', srNo, persisted)) result = SAVE_QUEUED;
    }
    return result;
  }
  registerOutboxHandler('report', async (srNo, payload)=>{
    let finalSr = srNo;
    // A report numbered offline gets a real sequential SR number now that the
    // server is reachable, so provisional ids never reach the shared history.
    if(isProvisionalSrNo(srNo)){
      const real = await cloudNextSrNo((payload.date || todayISO()).replace(/-/g,''));
      if(real) finalSr = real;
    }
    payload.srNo = finalSr;
    const ok = await cloudSaveReport(finalSr, payload);
    if(!ok) throw new Error('report upload failed');
    if(finalSr !== srNo){
      try{
        await window.storage.set('report:'+finalSr, JSON.stringify(payload), false);
        await window.storage.delete('report:'+srNo);
      }catch(e){}
    }
  });
  $('saveDraftBtn').addEventListener('click', async ()=>{
    if(!$('custName').value.trim()){ toast('Add a customer name before saving'); $('f_custName').classList.add('invalid'); return; }
    if(!currentSrNo){ currentSrNo = await nextSrNo(); $('metaSrNo').textContent = currentSrNo; }
    const data = await gatherDataForOutput();
    const res = await saveReport(currentSrNo, data);
    if(res===SAVE_FAILED){ toast('Could not save '+currentSrNo+' — nothing was stored, please try again'); return; }
    toast(res===SAVE_CLOUD
      ? ('Draft saved to shared cloud: '+currentSrNo)
      : ('Draft saved on this device — it will upload automatically when you are online'));
    resetForm();
  });

  // =====================================================================
  // Multiple Reports — per-unit Operation Parameters
  //
  // Everything else in the wizard is shared across the selected units, but
  // readings are not: copying one unit's voltages and pressures onto every
  // other unit would be fabricating measurements. So this one step keeps a
  // separate set of values per unit.
  //
  // Presented as a tab strip rather than a Next-per-unit loop: five units
  // as five near-identical screens gives no sense of progress and makes it
  // easy to tab past one unnoticed. Tabs show a tick once a unit has
  // readings, so what's still missing is visible at a glance.
  // =====================================================================
  const SR_OP_FIELDS = [
    'a_temp','a_airflow','a_press_suction','a_press_discharge','a_volt_l12','a_volt_l23','a_volt_l31','a_amp_l1','a_amp_l2','a_amp_l3',
    'b_temp','b_airflow','b_press_suction','b_press_discharge','b_volt_l12','b_volt_l23','b_volt_l31','b_amp_l1','b_amp_l2','b_amp_l3'
  ];
  let srOpParamsByUnit = {};   // unitId -> {field: value}
  let srOpActiveUnitId = null;
  // Survives srRenderOpUnitTabs(), which rebuilds the card via innerHTML —
  // without this the checkbox was recreated unchecked the moment it was
  // ticked, so the tick never appeared.
  let srOpApplyAllChecked = false;

  function srOpReadFields(){
    const out = {};
    SR_OP_FIELDS.forEach(f=>{ const el = $(f); if(el) out[f] = el.value; });
    return out;
  }
  function srOpWriteFields(vals){
    SR_OP_FIELDS.forEach(f=>{ const el = $(f); if(el) el.value = (vals && vals[f]) || ''; });
  }
  function srOpHasValues(vals){
    return !!vals && SR_OP_FIELDS.some(f=> (vals[f]||'').trim());
  }
  // Which readings actually apply right now. A single-phase unit has no
  // L2/L3 or L23/L31, so counting them would make every single-phase unit
  // look permanently incomplete.
  function srOpRequiredFields(){
    const phase3 = !!($('phase3Toggle') && $('phase3Toggle').checked);
    return SR_OP_FIELDS.filter(f=>{
      if(phase3) return true;
      return !/_l2$|_l3$|_l23$|_l31$/.test(f);
    });
  }
  // empty / partial / complete — what a tech (or a supervisor reviewing
  // later) needs to see at a glance across ten-plus units in a building.
  function srOpStatus(vals){
    const req = srOpRequiredFields();
    const filled = req.filter(f=> (vals && (vals[f]||'').trim())).length;
    if(filled===0) return {key:'empty', label:'Empty', filled:0, total:req.length};
    if(filled<req.length) return {key:'partial', label:'Partial', filled, total:req.length};
    return {key:'complete', label:'Complete', filled, total:req.length};
  }
  // A unit's values, using what's on screen for the one being edited.
  function srOpValuesFor(unitId){
    return String(unitId)===String(srOpActiveUnitId) ? srOpReadFields() : (srOpParamsByUnit[unitId] || {});
  }
  // Store whatever is on screen against the unit currently selected.
  function srOpStashActive(){
    if(srOpActiveUnitId) srOpParamsByUnit[srOpActiveUnitId] = srOpReadFields();
  }
  function srOpSelectUnit(unitId){
    srOpStashActive();
    srOpActiveUnitId = unitId;
    srOpWriteFields(srOpParamsByUnit[unitId]);
    srRenderOpUnitTabs();
  }
  // One unit at a time: its name, a reminder that these readings belong to
  // THIS unit only, a switch to copy the current readings across all of
  // them, and arrows to step between units. Replaces the tab strip, which
  // showed every unit at once and made it easy to lose track of which one
  // the fields on screen actually belonged to.
  function srRenderOpUnitTabs(){
    const host = $('srOpUnitTabs');
    if(!host) return;
    const items = srBatchEquipItems || [];
    if(items.length < 2){ host.style.display = 'none'; host.innerHTML = ''; return; }
    host.style.display = '';
    let idx = items.findIndex(it=> String(it.id)===String(srOpActiveUnitId));
    if(idx < 0) idx = 0;
    const item = items[idx];
    const name = typeof dtEquipSummaryLine === 'function' ? dtEquipSummaryLine(item) : ('Unit '+(idx+1));
    const st = srOpStatus(srOpValuesFor(item.id));
    const done = items.filter(it=> srOpStatus(srOpValuesFor(it.id)).key==='complete').length;
    host.innerHTML =
      '<div class="sr-op-unit">'+
        '<div class="sr-op-unit-top">'+
          '<button type="button" class="sr-op-arrow" data-sr-unit-step="-1"'+(idx===0?' disabled':'')+' aria-label="Previous unit">&#8249;</button>'+
          '<div class="sr-op-unit-main">'+
            '<div class="sr-op-unit-name">'+escapeHtml(name)+'</div>'+
            '<div class="sr-op-unit-note">Record all readings for this particular unit.</div>'+
            '<span class="sr-op-badge '+st.key+'">'+st.label+' \u00b7 '+st.filled+'/'+st.total+'</span>'+
          '</div>'+
          '<button type="button" class="sr-op-arrow" data-sr-unit-step="1"'+(idx===items.length-1?' disabled':'')+' aria-label="Next unit">&#8250;</button>'+
        '</div>'+
        '<div class="sr-op-unit-foot">'+
          '<button type="button" class="sr-op-unit-count" id="srOpOpenList">'+
            'Unit '+(idx+1)+' of '+items.length+' \u00b7 '+done+' complete \u2014 view all'+
          '</button>'+
          '<label class="sr-op-apply">'+
            '<input type="checkbox" id="srOpApplyAll"'+(srOpApplyAllChecked?' checked':'')+'>'+
            '<span>Apply to this '+items.length+' equipment then edit later</span>'+
          '</label>'+
        '</div>'+
      '</div>';
    srOpSyncHeaderLink();
  }
  // Arrows step between units, saving whatever is on screen first.
  document.addEventListener('click', (e)=>{
    const arrow = e.target.closest('[data-sr-unit-step]');
    if(!arrow || arrow.disabled) return;
    const items = srBatchEquipItems || [];
    let idx = items.findIndex(it=> String(it.id)===String(srOpActiveUnitId));
    if(idx < 0) idx = 0;
    const next = idx + parseInt(arrow.getAttribute('data-sr-unit-step'), 10);
    if(next < 0 || next >= items.length) return;
    srOpSelectUnit(items[next].id);
  });
  // "Apply to this N equipment then edit later" — copies the readings now
  // on screen onto every other unit, as a ONE-TIME copy. Deliberately not a
  // live link: "then edit later" means each unit stays independently
  // editable afterwards, and a continuous sync would silently overwrite
  // those edits.
  document.addEventListener('change', (e)=>{
    if(!e.target || e.target.id !== 'srOpApplyAll') return;
    if(!e.target.checked){ srOpApplyAllChecked = false; return; }
    const items = srBatchEquipItems || [];
    const vals = srOpReadFields();
    if(!srOpHasValues(vals)){
      toast('Enter this unit\'s readings first, then switch this on to copy them');
      e.target.checked = false;
      srOpApplyAllChecked = false;
      return;
    }
    items.forEach(it=>{ srOpParamsByUnit[it.id] = Object.assign({}, vals); });
    srOpApplyAllChecked = true;
    srRenderOpUnitTabs();
    toast('Readings copied to all '+items.length+' units — you can still edit each one');
  });

  document.addEventListener('click', (e)=>{
    const tab = e.target.closest('[data-sr-unit]');
    if(!tab) return;
    srOpSelectUnit(tab.getAttribute('data-sr-unit'));
  });
  // Called when the batch selection is made, to start clean.
  function srOpResetForBatch(items){
    srOpParamsByUnit = {};
    srOpApplyAllChecked = false;
    srOpActiveUnitId = (items && items.length) ? (items[0].id || '0') : null;
    srRenderOpUnitTabs();
  }
  // Readings for one unit, for submitBatchReports.
  function srOpParamsFor(unitId){
    if(unitId===srOpActiveUnitId) srOpStashActive();
    return srOpParamsByUnit[unitId] || {};
  }

  // ---- Single-phase vs 3-phase electrical fields ----
  // Default is SINGLE phase: one Amperage box and one Voltage box. The
  // three-box-per-row layout applied to every unit regardless, and most
  // units on file are single-phase — three empty boxes invite blank or
  // guessed readings, and a blank reading in a service report is worse
  // than no row at all. Switching the toggle on reveals L2/L3 and
  // L23/L31.
  function srApplyPhaseMode(){
    const on = !!($('phase3Toggle') && $('phase3Toggle').checked);
    // Clear the extra phases when switching back to single: a hidden field
    // that kept its value would put an L2/L3 reading on a report whose
    // author was told the unit is single-phase.
    $$('.sr-phase3').forEach(el=>{
      el.style.display = on ? '' : 'none';
      if(!on) el.value = '';
    });
    const amp = $('ampRowLabel'), volt = $('voltRowLabel');
    if(amp) amp.textContent = on ? 'Amperage (L1/L2/L3)' : 'Amperage';
    if(volt) volt.textContent = on ? 'Voltage (L12/L23/L31)' : 'Voltage';
    // The FIRST box of each row names its measurement even in 3-phase mode
    // ("Amps L1", not just "L1"): on a phone the row-label column is hidden
    // (see the max-width:700px rules in app.css), so a bare "L1" would
    // leave nothing on screen saying whether the row is amperage or
    // voltage. The 2nd/3rd boxes sit beside it, so L2/L3 read fine.
    // A/V with UNICODE subscripts (U+2081..2083) — an input placeholder is
    // plain text, so <sub> markup isn't possible here. The A and V prefixes
    // also keep each row self-identifying on mobile, where the row-label
    // column is hidden.
    const l1 = $('a_amp_l1'), bl1 = $('b_amp_l1'), v12 = $('a_volt_l12'), bv12 = $('b_volt_l12');
    [l1, bl1].forEach(el=>{ if(el) el.placeholder = on ? 'A\u2081' : 'Amps'; });
    [v12, bv12].forEach(el=>{ if(el) el.placeholder = on ? 'V\u2081' : 'Volts'; });
  }
  if($('phase3Toggle')) $('phase3Toggle').addEventListener('change', srApplyPhaseMode);
  srApplyPhaseMode();

  // ---- All-units list (Operation Parameters) ----
  // Secondary entry point into the same per-unit data: tapping the step
  // header or the "view all" counter shows every unit with its status, so
  // completeness can be checked without stepping through each one.
  function srRenderOpListOverlay(){
    const body = $('srOpListBody');
    if(!body) return;
    const items = srBatchEquipItems || [];
    if(items.length===0){ body.innerHTML = '<div class="empty-state">No units in this report.</div>'; return; }
    const done = items.filter(it=> srOpStatus(srOpValuesFor(it.id)).key==='complete').length;
    body.innerHTML =
      '<p class="sr-oplist-summary">'+done+' of '+items.length+' units have complete readings. Tap a unit to open it.</p>'+
      items.map((it,i)=>{
        const st = srOpStatus(srOpValuesFor(it.id));
        const name = typeof dtEquipSummaryLine === 'function' ? dtEquipSummaryLine(it) : ('Unit '+(i+1));
        const current = String(it.id)===String(srOpActiveUnitId);
        return '<button type="button" class="sr-oplist-row'+(current?' current':'')+'" data-sr-oplist="'+escapeHtml(String(it.id))+'">'+
          '<span class="sr-oplist-name">'+escapeHtml(name)+'</span>'+
          '<span class="sr-op-badge '+st.key+'">'+st.label+' \u00b7 '+st.filled+'/'+st.total+'</span>'+
        '</button>';
      }).join('');
  }
  function srOpOpenList(){
    // Stash what's on screen first, or the unit being edited shows its
    // previously-saved status instead of what the tech just typed.
    srOpStashActive();
    srRenderOpListOverlay();
    $('srOpListOverlay').classList.add('open');
  }
  function srOpCloseList(){ $('srOpListOverlay').classList.remove('open'); }
  if($('closeSrOpList')) $('closeSrOpList').addEventListener('click', srOpCloseList);
  if($('srOpListOverlay')) $('srOpListOverlay').addEventListener('click', (e)=>{ if(e.target.id==='srOpListOverlay') srOpCloseList(); });
  document.addEventListener('click', (e)=>{
    if(e.target.closest('#srOpOpenList')){ srOpOpenList(); return; }
    const row = e.target.closest('[data-sr-oplist]');
    if(row){ srOpSelectUnit(row.getAttribute('data-sr-oplist')); srOpCloseList(); }
  });
  // The step header is the other way in, but it ALSO toggles the card's
  // collapse — so opening the list on any header tap would fight that.
  // A dedicated "View all" chip is injected into the header instead, and
  // only in batch mode, where there is more than one unit to compare.
  function srOpSyncHeaderLink(){
    const head = $('sec6Head');
    if(!head) return;
    let chip = head.querySelector('.sr-op-head-link');
    const many = (srBatchEquipItems||[]).length > 1;
    if(!many){ if(chip) chip.remove(); return; }
    if(!chip){
      chip = document.createElement('button');
      chip.type = 'button';
      chip.className = 'sr-op-head-link';
      chip.textContent = 'View all units';
      chip.addEventListener('click', (e)=>{ e.stopPropagation(); srOpOpenList(); });
      head.insertBefore(chip, head.querySelector('.card-caret'));
    }
  }


// ---------- build PDF ----------
  const AWES_LOGO_B64 = 'data:image/png;base64,';

  // A report can reach buildPdf from three directions: straight off the form
  // (gatherDataForOutput), out of local storage, or out of the cloud via
  // rowToReport. Older cloud rows are missing fields entirely, and History used
  // to crash here on `data.recs.length` with no visible error at all because the
  // click handler had no catch. Normalise once, up front, so every downstream
  // .length / .join / .forEach is safe.
  function normalizeReportForPdf(data){
    const d = Object.assign({}, data || {});
    d.findings     = Array.isArray(d.findings) ? d.findings : [];
    d.recs         = Array.isArray(d.recs) ? d.recs : [];
    d.servicesDone = Array.isArray(d.servicesDone) ? d.servicesDone : [];
    d.materials    = Array.isArray(d.materials) ? d.materials : [];
    d.before  = normalizeOperatingData(d.before);
    d.after   = normalizeOperatingData(d.after);
    d.install = normalizeInstallData(d.install);
    d.sigCustomer = asSignature(d.sigCustomer);
    d.sigTech     = asSignature(d.sigTech);
    return d;
  }

  async function buildPdf(rawData){
    const data = normalizeReportForPdf(rawData);
    await loadAwesScript('jspdf', awesLibs.jspdf);
    await loadAwesScript('autotable', awesLibs.autotable);
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF('p','pt','a4');
    const pageW = doc.internal.pageSize.getWidth();
    const margin = 40;
    let y = 44;

    const headerH = 112;
    doc.setFillColor(21,77,52);
    doc.rect(0,0,pageW,headerH,'F');
    try{ doc.addImage(AWES_LOGO_B64,'PNG', margin, 14, 108, 36); }catch(e){}
    doc.setTextColor(255,255,255);
    doc.setFont('helvetica','bold'); doc.setFontSize(13);
    doc.text('SERVICE REPORT', pageW-margin, 28, {align:'right'});
    doc.setFont('helvetica','bold'); doc.setFontSize(10);
    doc.text('SR No: '+(data.srNo||'—'), pageW-margin, 42, {align:'right'});
    doc.setFont('helvetica','normal'); doc.setFontSize(10);
    doc.text('Date: '+(data.date||'—'), pageW-margin, 55, {align:'right'});
    doc.text('Category: '+serviceCategoryLabel(reportCategoryOf(data)), pageW-margin, 68, {align:'right'});
    doc.setFont('helvetica','bold'); doc.setFontSize(9);
    doc.text('AW Engineering Services', margin, 64);
    doc.setFont('helvetica','normal'); doc.setFontSize(8);
    doc.text('Air Conditioning & Ventilation System', margin, 75);
    doc.setFontSize(7.5);
    doc.text('3F DJET Commercial Bldg., Imelda Ave., Karangalan Vill., Manggahan, Pasig City', margin, 87);
    doc.text('8441-6497 / 8441-6796   •   awes.manila@gmail.com', margin, 98);
    doc.setTextColor(0,0,0);
    y = headerH + 18;

    // The Time In/Out fields are captured from <input type="time">, which
    // stores a plain 24-hour "HH:MM" string with no AM/PM indicator. The PDF
    // preview/output printed that raw string (e.g. "04:44"), leaving it
    // ambiguous whether a service happened at 4 in the morning or afternoon.
    // Render it as 12-hour time with an explicit AM/PM suffix instead.
    function fmtTime12h(hhmm){
      if(!hhmm) return '';
      const m = /^(\d{1,2}):(\d{2})/.exec(hhmm);
      if(!m) return hhmm;
      let h = parseInt(m[1], 10);
      const min = m[2];
      const ampm = h >= 12 ? 'PM' : 'AM';
      h = h % 12; if(h === 0) h = 12;
      return h + ':' + min + ' ' + ampm;
    }
    function sectionHeader(title){
      doc.setFillColor(31,122,80);
      doc.rect(margin, y, pageW-margin*2, 18, 'F');
      doc.setTextColor(255,255,255); doc.setFont('helvetica','bold'); doc.setFontSize(10);
      doc.text(title.toUpperCase(), margin+6, y+12.5);
      doc.setTextColor(0,0,0);
      y += 26;
    }
    function kv(label, value, xOffset, width){
      doc.setFont('helvetica','bold'); doc.setFontSize(9);
      doc.text(label, margin+xOffset, y);
      doc.setFont('helvetica','normal');
      const lines = doc.splitTextToSize(value || '—', width);
      doc.text(lines, margin+xOffset, y+11);
      return lines.length;
    }
    function checkPageBreak(needed){
      if(y + needed > 790){ doc.addPage(); y = 40; }
    }

    // 1. Customer info
    sectionHeader('1. Customer\'s Information');
    kv('SR NO.', data.srNo, 0, 240); kv('DATE', data.date, 300, 220); y += 22;
    let h1 = kv('CUSTOMER NAME', data.custName, 0, 250);
    kv('CONTACT NO.', data.contactNo, 300, 220);
    y += Math.max(h1,1)*11 + 12;
    let h2 = kv('ADDRESS', data.custAddress, 0, 250);
    kv('CONTACT PERSON', data.contactPerson, 300, 220);
    y += Math.max(h2,1)*11 + 16;

    // 2. Equipment
    checkPageBreak(90);
    sectionHeader('2. Equipment Description');
    kv('EQUIPMENT TYPE', data.equipType || '—', 0, 500); y += 24;
    kv('MODEL NO. (CU)', data.modelCU, 0, 240); kv('SERIAL NO. (CU)', data.serialCU, 300, 220); y += 22;
    kv('MODEL NO. (FCU)', data.modelFCU, 0, 240); kv('SERIAL NO. (FCU)', data.serialFCU, 300, 220); y += 22;
    kv('COOLING CAPACITY', data.coolCap, 0, 240); kv('MOUNTING TYPE', data.mountType, 300, 220); y += 22;
    kv('BRAND / MANUFACTURER', data.brand, 0, 240); kv('REFRIGERANT TYPE', data.refrigerantType, 300, 220); y += 22;
    kv('COMPRESSOR TYPE', data.compressorType, 0, 240); kv('LOCATION', data.equipLocation, 300, 220); y += 26;

    // 3. Report summary
    checkPageBreak(100);
    sectionHeader('3. Report Summary');
    doc.setFont('helvetica','bold'); doc.setFontSize(9); doc.text('TROUBLE CALL / REASON FOR SERVICE', margin, y);
    doc.setFont('helvetica','normal');
    let tc = doc.splitTextToSize(data.troubleCall || '—', pageW-margin*2);
    doc.text(tc, margin, y+11); y += tc.length*11 + 16;

    checkPageBreak(60);
    doc.setFont('helvetica','bold'); doc.setFontSize(9); doc.text('FINDINGS / EVALUATION', margin, y); y+=12;
    doc.setFont('helvetica','normal');
    if(data.findings.length===0){ doc.text('—', margin+8, y); y+=13; }
    data.findings.forEach(f=>{
      checkPageBreak(20);
      const lines = doc.splitTextToSize('• '+f, pageW-margin*2-8);
      doc.text(lines, margin+8, y); y += lines.length*11+3;
    });
    y += 6;

    checkPageBreak(60);
    doc.setFont('helvetica','bold'); doc.setFontSize(9); doc.text('RECOMMENDATION/S', margin, y); y+=12;
    doc.setFont('helvetica','normal');
    if(data.recs.length===0){ doc.text('—', margin+8, y); y+=13; }
    data.recs.forEach(r=>{
      checkPageBreak(20);
      const lines = doc.splitTextToSize('• '+r, pageW-margin*2-8);
      doc.text(lines, margin+8, y); y += lines.length*11+3;
    });
    y += 10;

    // 4. Components / Parts Needed to Replace
    checkPageBreak(60);
    sectionHeader('4. Components / Parts Needed to Replace');
    const rows = data.materials.map((m,i)=>[
      String(i+1)+'.', m.description||m.details||'—', m.qty||'—', m.unit||'—'
    ]);
    doc.autoTable({
      startY: y,
      margin:{left:margin, right:margin},
      head:[['Item No.','Item Description','Qty','Unit']],
      body: rows.length? rows : [['1.','—','—','—']],
      styles:{fontSize:8.5, cellPadding:4},
      headStyles:{fillColor:[231,243,236], textColor:[21,77,52], fontStyle:'bold'},
      columnStyles:{0:{cellWidth:40},2:{cellWidth:50},3:{cellWidth:50}}
    });
    y = doc.lastAutoTable.finalY + 18;

    // 5. Services Done
    checkPageBreak(60);
    sectionHeader('5. Services Done');
    doc.setFont('helvetica','normal'); doc.setFontSize(9);
    if(!data.servicesDone || data.servicesDone.length===0){ doc.text('—', margin+8, y); y+=13; }
    (data.servicesDone||[]).forEach(s=>{
      checkPageBreak(20);
      const lines = doc.splitTextToSize('• '+s, pageW-margin*2-8);
      doc.text(lines, margin+8, y); y += lines.length*11+3;
    });
    y += 6;

    // 6. Operating data
    checkPageBreak(120);
    sectionHeader('6. Operating Data');
    doc.autoTable({
      startY:y, margin:{left:margin,right:margin},
      head:[['','Before Servicing','After Servicing']],
      body:[
        ['Amperage (L1/L2/L3)', data.before.amp.join(' / ')||'—', data.after.amp.join(' / ')||'—'],
        ['Voltage (L12/L23/L31)', data.before.volt.join(' / ')||'—', data.after.volt.join(' / ')||'—'],
        ['Pressure (Suction/Discharge)', data.before.pressure.join(' / ')||'—', data.after.pressure.join(' / ')||'—'],
        ['Supply Air Temp (°C)', data.before.temp||'—', data.after.temp||'—'],
        ['Air Volume Flow Rate (cfm)', data.before.airflow||'—', data.after.airflow||'—']
      ],
      styles:{fontSize:8.5, cellPadding:4},
      headStyles:{fillColor:[231,243,236], textColor:[21,77,52], fontStyle:'bold'}
    });
    y = doc.lastAutoTable.finalY + 18;

    // 7. Installation data
    if(data.isInstall){
      checkPageBreak(100);
      sectionHeader('7. Installation Data');
      doc.autoTable({
        startY:y, margin:{left:margin,right:margin},
        body:[
          ['Pipe Diameter (in) — Suction/Discharge/Drain', data.install.pd.join(' / ')||'—'],
          ['Pipe Length (ft) — Ref\'t Line/Drain', data.install.pl.join(' / ')||'—'],
          ['Wire Size (awg) — Feeder/Control', data.install.ws.join(' / ')||'—'],
          ['Circuit Breaker (amp)', data.install.breaker||'—'],
          ['Pipe Insulation (in) — Ref\'t Line/Drain', data.install.pi.join(' / ')||'—'],
          ['Riser Pipes Height (m)', data.install.riser||'—'],
          ['P-Trap', data.install.ptrap||'—'],
          ['Accu Bracket Type', data.install.bracketType||'—']
        ],
        styles:{fontSize:8.5, cellPadding:4},
        theme:'plain'
      });
      y = doc.lastAutoTable.finalY + 18;
    }

    // 8. Terms & Conditions of Service
    const tcSections = [
      {
        heading: 'Preventive Maintenance Service (PMS)',
        body: 'PMS consists strictly of cleaning, routine inspection, and operational checks, and does not constitute a warranty on the equipment or its future performance. A limited 7-day workmanship guarantee covers only the direct physical labor (e.g., proper reassembly and drain line clearance). Pre-existing defects, component failures, and additional repairs require a separate quote and approval.'
      },
      {
        heading: 'Repair Works',
        body: 'Repairs cover only the specified scope and agreed-upon components. Replaced parts carry a 90-day warranty against manufacturing defects, while related labor carries a 30-day guarantee or as indicated in our proposal. Warranty is void if damage results from power surges, voltage fluctuations, unauthorized tampering, or external site factors.'
      },
      {
        heading: 'Installation Works',
        body: 'Installation workmanship and piping integrity are guaranteed for 6 months or as indicated in our proposal from commissioning. Equipment warranties are covered separately by the manufacturer. Warranty excludes damages from electrical supply issues, lack of routine maintenance, unauthorized modifications, or improper operation. Sign-off confirms turnover in good operating condition.'
      }
    ];
    // Terms & Conditions and Acknowledgment belong together as the closing
    // block of the report. Estimate the combined height up front so the pair
    // is always pushed to a fresh page together rather than being split, and
    // always ends up as the last block at the bottom of the printout.
    doc.setFont('helvetica','normal'); doc.setFontSize(7.5);
    let tcHeight = 26;
    tcSections.forEach(sec=>{
      const bodyLines = doc.splitTextToSize(sec.body, pageW-margin*2);
      tcHeight += 10 + bodyLines.length*9.5 + 8;
    });
    const ackHeight = 190;
    checkPageBreak(tcHeight + ackHeight);

    sectionHeader('8. Terms & Conditions of Service');
    tcSections.forEach(sec=>{
      doc.setFont('helvetica','bold'); doc.setFontSize(8); doc.setTextColor(21,77,52);
      doc.text(sec.heading, margin, y); y += 10;
      doc.setFont('helvetica','normal'); doc.setFontSize(7.5); doc.setTextColor(60,68,63);
      const lines = doc.splitTextToSize(sec.body, pageW-margin*2);
      doc.text(lines, margin, y); y += lines.length*9.5 + 8;
      doc.setTextColor(0,0,0);
    });
    y += 4;

    // 9. Acknowledgment
    checkPageBreak(190);
    sectionHeader('9. Acknowledgment');
    doc.setFont('helvetica','italic'); doc.setFontSize(8.5); doc.setTextColor(70,80,74);
    const ackLines = doc.splitTextToSize(
      'By signing below, the Client confirms that the scope of works indicated in this report has been performed to satisfaction and that the equipment was turned over in good, operational condition. The Client acknowledges, understands, and agrees to the Terms & Conditions set forth above.',
      pageW-margin*2
    );
    doc.text(ackLines, margin, y);
    doc.setTextColor(0,0,0);
    y += ackLines.length*11 + 12;
    kv('TIME IN', fmtTime12h(data.timeIn)||'—', 0, 150); kv('TIME OUT', fmtTime12h(data.timeOut)||'—', 200, 150); y+=22;
    doc.setFont('helvetica','bold'); doc.setFontSize(9); doc.text('REMARKS', margin, y);
    doc.setFont('helvetica','normal');
    const remLines = doc.splitTextToSize(data.remarks||'—', pageW-margin*2);
    doc.text(remLines, margin, y+11); y += remLines.length*11 + 18;

    checkPageBreak(150);
    const colW = (pageW - margin*2 - 20)/2;
    const sigY = y;
    doc.setDrawColor(220,227,221);
    doc.rect(margin, sigY, colW, 80);
    doc.rect(margin+colW+20, sigY, colW, 80);
    if(data.sigCustomer){ try{ doc.addImage(data.sigCustomer,'PNG', margin+6, sigY+6, colW-12, 55); }catch(e){} }
    if(data.sigTech){ try{ doc.addImage(data.sigTech,'PNG', margin+colW+26, sigY+6, colW-12, 55); }catch(e){} }
    if(data.backEntry){
      // Recorded after the fact by admin — say so where signatures would be.
      doc.setFontSize(8); doc.setTextColor(138,90,0);
      doc.text('Not signed — recorded after the fact', margin+colW/2, sigY+34, {align:'center'});
      doc.text('Not signed — recorded after the fact', margin+colW+20+colW/2, sigY+34, {align:'center'});
      doc.setTextColor(0,0,0);
    }
    doc.setFontSize(8.5);
    doc.text('Customer — '+(data.custPrintedName||'_______________'), margin+4, sigY+72);
    doc.text('Technician — '+(data.techName||'_______________'), margin+colW+24, sigY+72);
    y = sigY + 96;
    if(data.backEntry){
      doc.setFontSize(8); doc.setTextColor(110,110,110);
      const when = data.enteredAt ? new Date(data.enteredAt).toLocaleDateString('en-PH', {year:'numeric', month:'short', day:'numeric'}) : '';
      const note = doc.splitTextToSize('PAST SERVICE RECORD — entered by '+(data.enteredByName||'admin')+(when ? ' on '+when : '')+
        ' from the technician\u2019s account of work performed on '+(data.date||'the date above')+'. Not signed on site.', pageW-margin*2);
      doc.text(note, margin, y); y += note.length*10 + 6;
      doc.setTextColor(0,0,0);
    }

    doc.setFontSize(8); doc.setTextColor(120,130,124);
    doc.text('Generated on '+new Date().toLocaleString('en-PH'), margin, 815);

    return doc;
  }

  // title: share-sheet title (defaults to the Service Report wording used by
  // every existing caller). Purchase Orders pass their own.
  // Used only by the Service Report submit flow ("Generate & Share Report"),
  // which hands the finished report off automatically. Everywhere a PDF is
  // *viewed*, the viewer's own Download / Share buttons are used instead.
  async function shareOrDownloadPdf(doc, filename, title){
    const blob = doc.output('blob');
    if(navigator.canShare && navigator.canShare({files:[new File([blob], filename, {type:'application/pdf'})]})){
      try{
        await navigator.share({
          files:[new File([blob], filename, {type:'application/pdf'})],
          title: title || 'AWES Service Report',
          text: (title ? title : 'Service report')+' — '+filename
        });
        return 'shared';
      }catch(e){ /* user cancelled or unsupported — fall through to download */ }
    }
    doc.save(filename);
    return 'downloaded';
  }

  // ---- PDF viewer actions: Download and Share are separate on purpose ----
  // Download always saves the file to the device; Share always opens the
  // phone's share sheet (Messenger, Viber, Gmail, Drive…). Neither silently
  // turns into the other.
  function pdfSafeFilename(name){
    const n = String(name || 'document.pdf').replace(/[\\/:*?"<>|]+/g, '-').trim() || 'document.pdf';
    return /\.pdf$/i.test(n) ? n : n + '.pdf';
  }
  function downloadPdfFile(doc, filename){
    doc.save(pdfSafeFilename(filename));
  }
  // Returns 'shared' | 'cancelled' | 'unsupported'.
  async function sharePdfFiles(items, title){
    const files = items.map(it=> new File([it.doc.output('blob')], pdfSafeFilename(it.filename), { type:'application/pdf' }));
    if(!(navigator.share && navigator.canShare && navigator.canShare({ files }))) return 'unsupported';
    try{
      await navigator.share({ files, title: title || 'AWES Document', text: (title || 'AWES document') + ' — ' + files.map(f=> f.name).join(', ') });
      return 'shared';
    }catch(e){
      return (e && e.name === 'AbortError') ? 'cancelled' : 'unsupported';
    }
  }

  // Lets PDFs that weren't built with jsPDF (uploaded memos, supplier
  // documents, receipt PDFs) go through the same viewer. It mimics the
  // three jsPDF methods the viewer uses: output('arraybuffer'|'blob') and save().
  async function pdfDocFromBlob(blob){
    const buf = await blob.arrayBuffer();
    const pdfBlob = blob.type === 'application/pdf' ? blob : new Blob([buf], { type:'application/pdf' });
    return {
      output(type){
        if(type === 'blob') return pdfBlob;
        return buf.slice(0); // pdf.js detaches the buffer it's given
      },
      save(filename){
        const url = URL.createObjectURL(pdfBlob);
        const a = document.createElement('a');
        a.href = url; a.download = pdfSafeFilename(filename);
        document.body.appendChild(a); a.click(); a.remove();
        setTimeout(()=> URL.revokeObjectURL(url), 60000);
      }
    };
  }
  function pdfDataUrlToBlob(dataUrl){
    const m = /^data:([^;,]+)?(;base64)?,(.*)$/.exec(dataUrl || '');
    if(!m) throw new Error('not a data URL');
    const mime = m[1] || 'application/octet-stream';
    if(!m[2]) return new Blob([decodeURIComponent(m[3])], { type:mime });
    const bin = atob(m[3]);
    const bytes = new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++) bytes[i] = bin.charCodeAt(i);
    return new Blob([bytes], { type:mime });
  }
  // An uploaded photo (a scanned memo, a permit snapshot) is wrapped in a
  // one-page PDF so it also gets the viewer's Download / Share.
  async function pdfDocFromImage(src){
    await loadAwesScript('jspdf', awesLibs.jspdf);
    const img = await new Promise((res, rej)=>{ const i = new Image(); i.onload = ()=> res(i); i.onerror = ()=> rej(new Error('image load failed')); i.src = src; });
    const { jsPDF } = window.jspdf;
    const w = img.naturalWidth || 595, h = img.naturalHeight || 842;
    const doc = new jsPDF({ orientation: w > h ? 'l' : 'p', unit:'pt', format:[w, h], compress:true });
    const c = document.createElement('canvas'); c.width = w; c.height = h;
    c.getContext('2d').drawImage(img, 0, 0);
    doc.addImage(c.toDataURL('image/jpeg', 0.9), 'JPEG', 0, 0, w, h);
    return doc;
  }
  // One entry point for "open this file in the PDF viewer": a Blob, a data:
  // URL, or a jsPDF doc; PDFs and images both work.
  async function openFileInPdfViewer(source, filename, title){
    let doc;
    if(source && typeof source.output === 'function') doc = source;
    else{
      const blob = typeof source === 'string' ? pdfDataUrlToBlob(source) : source;
      const isImage = /^image\//.test(blob.type || '');
      if(isImage){
        const url = URL.createObjectURL(blob);
        try{ doc = await pdfDocFromImage(url); } finally { URL.revokeObjectURL(url); }
      }else doc = await pdfDocFromBlob(blob);
    }
    const ov = $('previewOverlay');
    ov.querySelector('h3').textContent = title || filename || 'Document';
    $('previewOkBtn').textContent = 'Close';
    ov.style.zIndex = '99'; // sits above whichever sheet opened it
    ov.classList.add('open');
    setPreviewZoom(1);
    await renderPdfPreview(doc, pdfSafeFilename(filename || title || 'document'), title || '');
  }

  // Mobile browsers use canvas rendering for reliable PDF preview. PDF.js is lazy-loaded.
  async function ensurePdfJs(){
    await loadAwesScript('pdfjs', awesLibs.pdfjs);
    pdfjsLib.GlobalWorkerOptions.workerSrc = 'https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js';
  }
  let previewRenderToken = 0;
  // Tracks whichever doc is currently sitting in the preview overlay, so
  // the new Download button (added alongside Close/"Continue to
  // Signatures") has something to hand to shareOrDownloadPdf() without
  // every call site needing its own click handler — renderPdfPreview()
  // is the one place all four preview entry points (pre-signing draft,
  // admin/tech "View", customer portal "View Full Report (PDF)") already
  // funnel through.
  let previewCurrentDoc = null;
  let previewCurrentFilename = 'Report.pdf';
  let previewCurrentTitle = '';
  // Batch previews (one report per unit) put every doc here so Download
  // saves all of them and Share sends all of them together.
  let previewCurrentDocs = [];
  function closePreview(){
    $('previewOverlay').classList.remove('open');
    previewRenderToken++; // invalidate any in-flight render
    const frame = $('previewFrame');
    frame.innerHTML = '<div class="empty-state" style="display:none;">Rendering preview…</div>';
    previewCurrentDoc = null;
    previewCurrentDocs = [];
    previewCurrentTitle = '';
    $('previewOverlay').style.zIndex = '';
  }
  async function renderPdfPreview(doc, filename, title){
    previewCurrentDoc = doc;
    previewCurrentFilename = filename || 'Report.pdf';
    previewCurrentTitle = title || '';
    previewCurrentDocs = [{ doc, filename: previewCurrentFilename }];
    const myToken = ++previewRenderToken;
    const frame = $('previewFrame');
    frame.innerHTML = '';
    const loading = document.createElement('div');
    loading.className = 'empty-state';
    loading.textContent = 'Rendering preview…';
    frame.appendChild(loading);

    await ensurePdfJs();
    const arrayBuffer = doc.output('arraybuffer');
    const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;
    if(myToken !== previewRenderToken) return; // overlay was closed / superseded
    frame.innerHTML = '';

    for(let pageNum = 1; pageNum <= pdf.numPages; pageNum++){
      if(myToken !== previewRenderToken) return;
      const page = await pdf.getPage(pageNum);
      const scale = Math.min(2, (frame.clientWidth || 700) / page.getViewport({ scale: 1 }).width);
      const viewport = page.getViewport({ scale: Math.max(scale, 1) });
      const canvas = document.createElement('canvas');
      canvas.width = viewport.width;
      canvas.height = viewport.height;
      canvas.className = 'preview-page';
      canvas.style.cssText = 'max-width:100%; height:auto; display:block; margin:0 auto 12px; box-shadow:0 1px 4px rgba(0,0,0,.2); background:#fff;';
      const ctx = canvas.getContext('2d');
      await page.render({ canvasContext: ctx, viewport }).promise;
      if(myToken !== previewRenderToken) return;
      frame.appendChild(canvas);
    }
    applyPreviewZoom(); // pages created after the zoom was set
  }
  // Renders several reports one after another in the same scrollable
  // frame, each under its unit's name.
  async function renderPdfPreviewMulti(docs){
    const myToken = ++previewRenderToken;
    const frame = $('previewFrame');
    frame.innerHTML = '<div class="empty-state">Rendering '+docs.length+' reports…</div>';
    await ensurePdfJs();
    frame.innerHTML = '';
    for(let i=0; i<docs.length; i++){
      if(myToken !== previewRenderToken) return;
      const head = document.createElement('div');
      head.className = 'preview-doc-head';
      head.textContent = 'Report '+(i+1)+' of '+docs.length+(docs[i].label ? ' — '+docs[i].label : '');
      frame.appendChild(head);
      const pdf = await pdfjsLib.getDocument({ data: docs[i].doc.output('arraybuffer') }).promise;
      for(let pageNum=1; pageNum<=pdf.numPages; pageNum++){
        if(myToken !== previewRenderToken) return;
        const page = await pdf.getPage(pageNum);
        const scale = Math.min(2, (frame.clientWidth || 700) / page.getViewport({scale:1}).width);
        const viewport = page.getViewport({ scale: Math.max(scale, 1) });
        const canvas = document.createElement('canvas');
        canvas.width = viewport.width; canvas.height = viewport.height;
        canvas.className = 'preview-page';
        canvas.style.cssText = 'max-width:100%; height:auto; display:block; margin:0 auto 12px; box-shadow:0 1px 4px rgba(0,0,0,.2); background:#fff;';
        await page.render({ canvasContext: canvas.getContext('2d'), viewport }).promise;
        if(myToken !== previewRenderToken) return;
        frame.appendChild(canvas);
      }
    }
    // Download / Share act on every report in the batch, not just the first.
    previewCurrentDoc = docs[0] ? docs[0].doc : null;
    previewCurrentFilename = (docs[0] && docs[0].filename) || 'service-report.pdf';
    previewCurrentTitle = 'Service Reports';
    previewCurrentDocs = docs.map((d, i)=> ({ doc: d.doc, filename: d.filename || ('service-report-' + (i+1) + '.pdf') }));
    applyPreviewZoom(); // pages created after the zoom was set
  }
  // ---- Preview zoom ----
  // A report rendered to fit a phone screen is unreadable; zoom lets a
  // technician (or the customer signing) actually check the figures
  // before it goes out.
  let previewZoom = 1;
  function applyPreviewZoom(){
    $$('.preview-page', $('previewFrame')).forEach(c=>{
      c.style.maxWidth = (100 * previewZoom)+'%';
      c.style.width = (100 * previewZoom)+'%';
    });
    const lbl = $('previewZoomLabel');
    if(lbl) lbl.textContent = Math.round(previewZoom*100)+'%';
    // Only let the frame scroll sideways once there's something to scroll.
    $('previewFrame').style.overflowX = previewZoom > 1 ? 'auto' : 'hidden';
  }
  function setPreviewZoom(z){
    previewZoom = Math.min(3, Math.max(0.5, Math.round(z*10)/10));
    applyPreviewZoom();
  }
  if($('previewZoomIn')) $('previewZoomIn').addEventListener('click', ()=> setPreviewZoom(previewZoom + 0.25));
  if($('previewZoomOut')) $('previewZoomOut').addEventListener('click', ()=> setPreviewZoom(previewZoom - 0.25));
  if($('previewZoomReset')) $('previewZoomReset').addEventListener('click', ()=> setPreviewZoom(1));

  $('previewBtn').addEventListener('click', async ()=>{
    if(!validate()){ toast('Please fill required fields before previewing'); return; }
    $('previewBtn').disabled = true; $('previewBtn').textContent = 'Building preview…';
    try{
      const data = await gatherDataForOutput();
      const batch = (typeof srBatchEquipItems !== 'undefined' && srBatchEquipItems) ? srBatchEquipItems : null;
      $('previewOverlay').querySelector('h3').textContent = 'Report Preview';
      $('previewOkBtn').textContent = 'Looks Good — Continue to Signatures';
      $('previewOverlay').classList.add('open');
      setPreviewZoom(1); // every preview starts at fit-to-width
      if(batch && batch.length > 1){
        // Batch produces ONE REPORT PER UNIT, but preview only ever built
        // the first — so the other units' reports went out having never
        // been looked at. Build them all, each with its own equipment
        // fields and its own operating readings, exactly as
        // submitBatchReports will.
        const docs = [];
        for(const item of batch){
          const d = Object.assign({}, data);
          if(typeof EQUIP_FIELD_KEYS !== 'undefined') EQUIP_FIELD_KEYS.forEach(k=> d[k] = item[k] || '');
          if(typeof srOpParamsFor === 'function' && typeof SR_OP_FIELDS !== 'undefined'){
            const own = srOpParamsFor(item.id || '');
            SR_OP_FIELDS.forEach(f=> d[f] = own[f] || '');
          }
          docs.push({ doc: await buildPdf(d), label: (typeof dtEquipSummaryLine==='function' ? dtEquipSummaryLine(item) : ''), filename: (d.srNo||'service-report')+'-unit-'+(docs.length+1)+'.pdf' });
        }
        await renderPdfPreviewMulti(docs);
      }else{
        const doc = await buildPdf(data);
        await renderPdfPreview(doc, (data.srNo||'service-report')+'.pdf');
      }
    }catch(e){
      console.error(e);
      toast('Could not build preview');
    }finally{
      $('previewBtn').disabled = false; $('previewBtn').innerHTML = icon('eye')+' Preview Report Before Signing';
    }
  });
  $('closePreview').addEventListener('click', closePreview);
  $('previewOkBtn').addEventListener('click', closePreview);
  // Neither button closes the overlay — someone checking a report over a
  // weak field connection may want to save/send it and keep looking, or
  // try again if the save or share didn't go through.
  $('previewDownloadBtn').addEventListener('click', async ()=>{
    if(!previewCurrentDocs.length) return;
    const btn = $('previewDownloadBtn');
    btn.disabled = true;
    try{
      for(const it of previewCurrentDocs) downloadPdfFile(it.doc, it.filename);
      toast(previewCurrentDocs.length > 1 ? previewCurrentDocs.length + ' PDFs downloaded' : 'PDF downloaded');
    }catch(err){
      console.error('preview download failed', err);
      toast('Could not download this PDF');
    }finally{ btn.disabled = false; }
  });
  $('previewShareBtn').addEventListener('click', async ()=>{
    if(!previewCurrentDocs.length) return;
    const btn = $('previewShareBtn');
    btn.disabled = true;
    try{
      const how = await sharePdfFiles(previewCurrentDocs, previewCurrentTitle || previewCurrentFilename);
      if(how === 'unsupported') toast('Sharing isn\u2019t supported on this browser — use Download instead');
    }catch(err){
      console.error('preview share failed', err);
      toast('Could not share this PDF');
    }finally{ btn.disabled = false; }
  });

  function showShareSuccess(detail){
    $('shareSuccessDetail').textContent = detail || '';
    $('shareSuccessOverlay').classList.add('open');
  }
  $('shareSuccessHomeBtn').addEventListener('click', ()=>{
    $('shareSuccessOverlay').classList.remove('open');
    resetForm();
    showHome();
  });

  // Batch-sign submit path (2+ equipment items selected off one Job Order,
  // see srApplyJobOrderBatch in dispatch.js). Everything gathered from the
  // form — including the one signature — is shared across every report;
  // only the equipment-identity fields (EQUIP_FIELD_KEYS) differ, pulled
  // straight from each selected item rather than the (hidden) form fields.
  async function submitBatchReports(){
    const items = srBatchEquipItems;
    const ticketId = srCurrentTicketId;
    const baseData = await gatherDataForOutput();
    let savedCount = 0, failedCount = 0;
    const toShare = [];
    for(const item of items){
      const srNo = await nextSrNo();
      const data = Object.assign({}, baseData, { srNo, completed:true });
      EQUIP_FIELD_KEYS.forEach(k=> data[k] = item[k] || '');
      // Operating readings are the ONE thing that isn't shared across a
      // batch — copying one unit's voltages and pressures onto the others
      // would be inventing measurements. Each unit's own values come from
      // the tab strip on the Operation Parameters step (srOpParamsFor in
      // ui.js); any field that unit has no value for is blanked rather
      // than inheriting the previous unit's number.
      if(typeof srOpParamsFor === 'function' && typeof SR_OP_FIELDS !== 'undefined'){
        const own = srOpParamsFor(item.id || '');
        SR_OP_FIELDS.forEach(f=> data[f] = own[f] || '');
      }
      if(item.scope && item.scope.length) data.troubleCall = item.scope.join('; ');
      // Same reuse-by-real-id as the single-report path (srApplyJobOrder) —
      // each item's own equipmentId (stamped on at ticket-creation time),
      // not a fresh content comparison, decides whether saveReport() below
      // reuses that row or creates a new one.
      setEquipPickedId(item.equipmentId || null);
      const saveResult = await saveReport(srNo, data);
      if(saveResult===SAVE_FAILED){ failedCount++; continue; }
      savedCount++;
      await dtMarkEquipmentReported(ticketId, item.id, srNo);
      const doc = await buildPdf(data);
      toShare.push({ srNo, doc, data });
    }
    // Once, after the whole batch rather than per item: the ticket can only
    // complete when the LAST unit lands, so checking inside the loop would
    // fire a pointless read for every earlier one.
    if(ticketId && typeof dtCheckAutoComplete === 'function'){
      await dtCheckAutoComplete(ticketId);
    }
    if(savedCount===0){
      toast('Could not save any of the '+items.length+' reports — fix the connection or free up space, then try again');
      return;
    }
    $('statusPill').textContent='Completed'; $('statusPill').className='status-pill status-done';
    $('metaSrNo').textContent = savedCount+' reports (batch)';
    srRenderStepper();
    // Send/share each generated PDF in turn — there is no single combined
    // file, so this is N separate emails (silent, no UI per one) or N
    // share/download prompts (the browser/OS share sheet, one after another).
    let emailedCount = 0;
    for(const {srNo, doc, data} of toShare){
      const filename = srNo+'.pdf';
      if(emailConfigured()){
        const emailResult = await sendEmailWithPdf(doc, data, filename);
        if(emailResult.ok) emailedCount++;
        else await shareOrDownloadPdf(doc, filename);
      }else{
        await shareOrDownloadPdf(doc, filename);
      }
    }
    let summary = savedCount+' of '+items.length+' reports generated'+(failedCount ? ' ('+failedCount+' failed to save — retry those individually)' : '')+'.';
    summary += emailConfigured() ? (' '+emailedCount+' emailed to the customer.') : ' Shared/downloaded to this device.';
    showShareSuccess(summary);
  }

  $('genPdfBtn').addEventListener('click', async ()=>{
    if(!validate()){ toast('Please fill required fields'); return; }
    $('genPdfBtn').disabled = true;
    $('genPdfBtn').textContent = 'Building PDF…';
    try{
      if(srBatchEquipItems && srBatchEquipItems.length > 0){
        await submitBatchReports();
        return;
      }
      if(!currentSrNo){ currentSrNo = await nextSrNo(); $('metaSrNo').textContent = currentSrNo; }
      const data = await gatherDataForOutput();
      Object.assign(data, {completed:true});
      const saveResult = await saveReport(currentSrNo, data);
      if(saveResult===SAVE_FAILED){
        // Don't hand over a PDF for a report that was not stored anywhere.
        toast('Could not save this report — fix the connection or free up space, then try again');
        return;
      }
      if(saveResult===SAVE_QUEUED) toast('Saved on this device — it will upload when you are online');
      // If this report was filed against a specific piece of equipment on a
      // dispatch ticket, mark that item reported so the ticket's progress
      // ("38 of 100 reported") picks it up. Best-effort — never blocks or
      // fails the report save itself.
      if(srCurrentTicketId && srCurrentEquipId){
        await dtMarkEquipmentReported(srCurrentTicketId, srCurrentEquipId, currentSrNo);
        // Filing the report IS the completion signal now — there is no
        // "Mark Completed" tap any more. This flips the job order to
        // Completed only when this was the last unresolved unit.
        if(typeof dtCheckAutoComplete === 'function') await dtCheckAutoComplete(srCurrentTicketId);
      }
      // "Closed" throughout, so the word means the same thing on the report
      // as it does on the job order it belongs to.
      $('statusPill').textContent='Closed'; $('statusPill').className='status-pill status-done';
      srRenderStepper();
      const doc = await buildPdf(data);
      const filename = (currentSrNo||'service-report')+'.pdf';

      if(emailConfigured()){
        $('genPdfBtn').textContent = 'Sending email…';
        const emailResult = await sendEmailWithPdf(doc, data, filename);
        if(emailResult.ok){
          showShareSuccess('Emailed to the customer and saved to the shared cloud.');
        }else if(emailResult.reason==='too_large'){
          await shareOrDownloadPdf(doc, filename);
          showShareSuccess('PDF was too large to email, so it was shared/downloaded instead.');
        }else{
          await shareOrDownloadPdf(doc, filename);
          showShareSuccess('Auto-email failed, so it was shared/downloaded instead.');
        }
      }else{
        const result = await shareOrDownloadPdf(doc, filename);
        showShareSuccess(result==='shared' ? 'Report '+filename+' was shared.' : 'Report '+filename+' was downloaded to this device.');
      }
    }catch(e){
      console.error(e);
      toast('Something went wrong generating the PDF');
    }finally{
      $('genPdfBtn').disabled = false;
      $('genPdfBtn').textContent = 'Generate & Share Report';
    }
  });

  // ---------- new report ----------
  $('newBtn').addEventListener('click', ()=>{
    if(confirm('Start a new blank report? Unsaved changes will be lost.')) resetForm();
  });


// ---------- history ----------
  async function loadHistory(containerId, filter, onlyUserId, searchText){
    const list = $(containerId || 'historyList');
    list.innerHTML = '<div class="empty-state">Loading…</div>';
    let reports = null;
    if(await ensureCloud()){
      reports = await cloudListReports();
    }
    if(reports===null){
      reports = [];
      try{
        const res = await window.storage.list('report:', false);
        const keys = (res && res.keys) ? res.keys.slice().reverse() : [];
        for(const key of keys){
          try{ const item = await window.storage.get(key, false); reports.push(JSON.parse(item.value)); }catch(e){}
        }
      }catch(e){}
    }
    if(onlyUserId) reports = reports.filter(d=> d.technicianId===onlyUserId);
    if(filter==='draft') reports = reports.filter(d=> !d.completed);
    else if(filter==='completed') reports = reports.filter(d=> d.completed);
    // filter==='all' (or omitted) keeps everything, unfiltered.
    const q = (searchText||'').trim().toLowerCase();
    if(q) reports = reports.filter(d=> (d.custName||'').toLowerCase().includes(q) || (d.srNo||'').toLowerCase().includes(q));
    if(reports.length===0){
      const emptyMsg = q ? 'No reports match "'+searchText.trim()+'".'
        : filter==='draft' ? 'No draft reports yet.'
        : filter==='completed' ? 'No completed reports yet.'
        : 'No saved reports yet.';
      list.innerHTML = '<div class="empty-state">'+emptyMsg+'</div>';
      return;
    }
    list.innerHTML = '';
    reports.forEach(d=>{
      const row = document.createElement('div');
      row.className = 'hist-item';
      // Customer names are free text typed by technicians, so they must be
      // escaped before being injected as HTML.
      // Drafts aren't finished yet, so they get actions for finishing/removing
      // the draft rather than the open/PDF actions that make sense once a
      // report is completed. This is keyed off the report's own completed
      // state (not the current tab) so it's also correct on the "All" tab,
      // which mixes drafts and completed reports in one list.
      const isDraft = !d.completed;
      row.innerHTML =
        '<div class="hist-info"><b>'+escapeHtml(d.custName||'Untitled')+'</b>'+
        '<span>'+escapeHtml(d.srNo||'')+' · '+escapeHtml(d.date||'')+' · '+(d.completed?'Completed':'Draft')+
          (d.backEntry ? '<span class="hist-tag-past" title="Recorded after the fact by '+escapeHtml(d.enteredByName||'admin')+'">Past service</span>' : '')+'</span></div>'+
        (isDraft
          ? '<div class="hist-actions"><button data-act="continue">Continue</button><button data-act="delete" class="danger">Delete</button></div>'
          : '<div class="hist-actions"><button data-act="view">View</button></div>');
      if(isDraft){
        // "Continue" reopens the draft in the form so the technician can
        // finish filling it out and submit it — same underlying action as
        // opening a report, just labeled for what a draft actually needs next.
        row.querySelector('[data-act="continue"]').addEventListener('click', async (e)=>{
          e.stopPropagation();
          try{ await openReport(d); }
          catch(err){ console.error('openReport failed', err); toast('Could not open this draft'); }
        });
        row.querySelector('[data-act="delete"]').addEventListener('click', async (e)=>{
          e.stopPropagation();
          if(!confirm('Delete this draft? "'+(d.custName||'Untitled')+'" ('+(d.srNo||'')+') cannot be recovered.')) return;
          try{
            // The local storage shim reports success even for a key that was
            // never there (e.g. a draft that only exists in the cloud), so it
            // can't be used to paper over a failed cloud delete. When cloud is
            // reachable, trust its result; only fall back to local-only deletion
            // when we're offline.
            let ok;
            if(await ensureCloud()){
              ok = await cloudDeleteReport(d.srNo);
              try{ await window.storage.delete('report:'+d.srNo, false); }catch(e){}
            }else{
              try{ await window.storage.delete('report:'+d.srNo, false); ok = true; }
              catch(e){ ok = false; }
            }
            if(ok){ toast('Draft deleted'); row.remove(); }
            else toast('Could not delete this draft — check your connection and try again');
          }catch(err){ console.error('delete draft failed', err); toast('Could not delete this draft'); }
        });
      }else{
        // "View" opens the completed report as a PDF preview (reusing the same
        // preview overlay the form uses before signing) rather than dropping
        // the technician back into the editable form — a completed report is
        // meant to be looked at, not re-edited.
        row.querySelector('[data-act="view"]').addEventListener('click', async (e)=>{
          e.stopPropagation();
          try{
            const doc = await buildPdf(d);
            // Reuse the pre-signing preview overlay, but relabel it — this is
            // a completed report being viewed, not a draft on its way to
            // signatures, so the default "Continue to Signatures" copy doesn't apply.
            $('previewOverlay').querySelector('h3').textContent = d.custName ? d.custName : 'Report';
            $('previewOkBtn').textContent = 'Close';
            $('previewOverlay').classList.add('open');
            await renderPdfPreview(doc, (d.srNo||'service-report')+'.pdf');
          }catch(err){
            console.error('view report failed', err);
            toast('Could not open this report');
          }
        });
      }
      list.appendChild(row);
    });
  }
  async function openReport(d){
    showServiceReport();
    resetForm();
    currentSrNo = d.srNo; $('metaSrNo').textContent = d.srNo||'—';
    currentTechnicianId = d.technicianId || (currentUser ? currentUser.id : null);
    srSetReportCategory(reportCategoryOf(d));
    $('custName').value = d.custName||''; $('svcDate').value = d.date||todayISO();
    $('metaDate').textContent = fmtDate($('svcDate').value);
    $('custAddress').value = d.custAddress||''; $('contactNo').value = d.contactNo||''; $('contactPerson').value = d.contactPerson||'';
    $('custEmail').value = d.custEmail||'';
    // Re-establish equipment context for this report's customer, so its
    // equipment dropdowns work correctly if the technician reopens this field.
    const matchedCustomer = customersCache.find(c=> c.name.toLowerCase() === (d.custName||'').trim().toLowerCase());
    loadCustomerEquipment(matchedCustomer ? matchedCustomer.id : null);
    setEquipTab('addnew');
    $('custDetailsWrap').style.display = '';
    $('sec1Card').style.display = '';
    // A saved draft resumes INSIDE the wizard, one step at a time — same
    // as a new report. This used to dump every section card on screen at
    // once, which is exactly the wall of fields the wizard removes.
    // srGoToSection lands on the first step and srRevealSections hides the
    // rest; the step is expanded for us, so no expandAllSections() here.
    if(typeof srSetAllSectionsRevealed === 'function') srSetAllSectionsRevealed();
    $('equipType').value = d.equipType || (Array.isArray(d.equipCodes) ? d.equipCodes.join(', ') : '') || '';
    $('modelCU').value=d.modelCU||''; $('serialCU').value=d.serialCU||'';
    $('modelFCU').value=d.modelFCU||''; $('serialFCU').value=d.serialFCU||'';
    $('coolCap').value=d.coolCap||''; $('mountType').value=d.mountType||'';
    $('brand').value=d.brand||''; $('refrigerantType').value=d.refrigerantType||'';
    $('compressorType').value=d.compressorType||''; $('equipLocation').value=d.equipLocation||'';
    // This report already has a resolved customer_equipment row (it was
    // set the first time this was saved) — restore it so re-saving without
    // touching the equipment fields reuses that same row instead of
    // creating a new one. Editing any field here still clears it, same as
    // any other pick (watchEquipFieldsForManualEdit).
    setEquipPickedId(d.equipmentId || null);
    $('troubleCall').value=d.troubleCall||'';
    $('findingsList').innerHTML=''; (d.findings&&d.findings.length?d.findings:['']).forEach(f=>addListRow('findingsList',f));
    $('recsList').innerHTML=''; (d.recs&&d.recs.length?d.recs:['']).forEach(r=>addListRow('recsList',r));
    $('servicesDoneList').innerHTML='';
    const svcArr = Array.isArray(d.servicesDone) ? d.servicesDone : (d.servicesDone ? [d.servicesDone] : []);
    (svcArr.length?svcArr:['']).forEach(s=>addListRow('servicesDoneList',s));
    $('materialsBody').innerHTML=''; materialRowCount=0;
    (d.materials&&d.materials.length?d.materials:[{},{},{}]).forEach(m=>addMaterialRow(m));
    // Legacy/cloud rows can carry partial objects (e.g. {} or a missing `amp`
    // array), which used to throw on `d.before.amp[0]`. Normalise first.
    {
      const before = normalizeOperatingData(d.before);
      $('b_amp_l1').value=before.amp[0]||''; $('b_amp_l2').value=before.amp[1]||''; $('b_amp_l3').value=before.amp[2]||'';
      $('b_volt_l12').value=before.volt[0]||''; $('b_volt_l23').value=before.volt[1]||''; $('b_volt_l31').value=before.volt[2]||'';
      $('b_press_suction').value=before.pressure[0]||''; $('b_press_discharge').value=before.pressure[1]||'';
      $('b_temp').value=before.temp||''; $('b_airflow').value=before.airflow||'';
      const after = normalizeOperatingData(d.after);
      $('a_amp_l1').value=after.amp[0]||''; $('a_amp_l2').value=after.amp[1]||''; $('a_amp_l3').value=after.amp[2]||'';
      $('a_volt_l12').value=after.volt[0]||''; $('a_volt_l23').value=after.volt[1]||''; $('a_volt_l31').value=after.volt[2]||'';
      $('a_press_suction').value=after.pressure[0]||''; $('a_press_discharge').value=after.pressure[1]||'';
      $('a_temp').value=after.temp||''; $('a_airflow').value=after.airflow||'';
    }
    $('isInstallToggle').checked = !!d.isInstall;
    $('installSection').classList.toggle('open', !!d.isInstall);
    {
      const inst = normalizeInstallData(d.install);
      $('pd_suction').value=inst.pd[0]||''; $('pd_discharge').value=inst.pd[1]||''; $('pd_drain').value=inst.pd[2]||'';
      $('pl_refline').value=inst.pl[0]||''; $('pl_drain').value=inst.pl[1]||'';
      $('ws_feeder').value=inst.ws[0]||''; $('ws_control').value=inst.ws[1]||'';
      $('circuit_breaker').value=inst.breaker||'';
      $('pi_refline').value=inst.pi[0]||''; $('pi_drain').value=inst.pi[1]||'';
      $('riser_height').value=inst.riser||''; $('ptrap').value=inst.ptrap||'';
      $('bracketType').value=inst.bracketType||'';
    }
    $('timeIn').value=d.timeIn||''; $('timeOut').value=d.timeOut||''; $('remarks').value=d.remarks||'';
    $('custPrintedName').value=d.custPrintedName||''; $('techName').value=d.techName || (currentUser ? currentUser.name : '') || '';
    const sigCust = asSignature(d.sigCustomer), sigTech = asSignature(d.sigTech);
    // fromDataURL loads the image asynchronously (it returns a promise), so the
    // lock is applied only once the pad has actually finished drawing the
    // restored signature — otherwise isEmpty() could still read true and skip it.
    if(sigCust){ await ensureSignaturePads(); await Promise.resolve(sigCustomerPad.fromDataURL(sigCust)); $('sigCustomerPh').style.display='none'; lockSignature('sigCustomer'); }
    if(sigTech){ await ensureSignaturePads(); await Promise.resolve(sigTechPad.fromDataURL(sigTech)); $('sigTechPh').style.display='none'; lockSignature('sigTech'); }
    $('statusPill').textContent = d.completed ? 'Completed' : 'Draft';
    $('statusPill').className = 'status-pill ' + (d.completed ? 'status-done' : 'status-draft');
    srShowTab('new', {skipReset:true});
    window.scrollTo({top:0, behavior:'smooth'});
  }

  // ---------- Manage Service Reports (admin-only full page) — the "Saved
