  // =====================================================================
  // Web Push — real OS notifications (sound, lock screen, app closed)
  //
  // Everything the app called a "notification" before this was in-app
  // only: a Realtime subscription updating a badge or firing a toast while
  // the app happened to be open and focused. That misses exactly the cases
  // that matter — a job order dispatched while the technician's phone is
  // in their pocket, a fee proposed while the customer is doing something
  // else.
  //
  // Requires:
  //   - 20260916_03_push_subscriptions.sql (the subscriptions table)
  //   - the send-push Edge Function deployed, with VAPID secrets set
  //   - PUSH_PUBLIC_KEY below matching the deployed VAPID_PUBLIC_KEY
  //
  // Nothing here is load-bearing: if push isn't set up, isn't supported,
  // or the user declines, every function degrades to a silent no-op and
  // the app behaves exactly as it did before.
  // =====================================================================

  // Must match VAPID_PUBLIC_KEY in the Edge Function's secrets. The public
  // half is meant to ship to clients — it only lets a browser create a
  // subscription addressed to this server. The PRIVATE key never leaves
  // Supabase.
  const PUSH_PUBLIC_KEY = 'BDNnVSgi4tWomDM6KYn76Ng907epPyoPe2KZhBiopghXTPvSFW929BLSztbmTTwbLFahih7BIQVLdQz7vLmbEzc';

  function pushSupported(){
    return typeof window !== 'undefined'
      && 'serviceWorker' in navigator
      && 'PushManager' in window
      && 'Notification' in window;
  }

  function urlBase64ToUint8Array(base64String){
    const padding = '='.repeat((4 - base64String.length % 4) % 4);
    const base64 = (base64String + padding).replace(/-/g, '+').replace(/_/g, '/');
    const raw = atob(base64);
    const out = new Uint8Array(raw.length);
    for(let i=0; i<raw.length; i++) out[i] = raw.charCodeAt(i);
    return out;
  }

  // True when an existing subscription was made with PUSH_PUBLIC_KEY.
  // Browsers that don't expose options.applicationServerKey are assumed to
  // match (keeps the old behaviour rather than churning subscriptions).
  function pushKeyMatches(sub){
    try{
      const k = sub && sub.options && sub.options.applicationServerKey;
      if(!k) return true;
      const a = new Uint8Array(k), b = urlBase64ToUint8Array(PUSH_PUBLIC_KEY);
      if(a.length !== b.length) return false;
      for(let i=0; i<a.length; i++) if(a[i] !== b[i]) return false;
      return true;
    }catch(e){ return true; }
  }

  // Subscribes this device and stores the endpoint. Safe to call repeatedly
  // — the browser returns the SAME subscription for a device+origin, and
  // the row upserts on endpoint, so re-running never creates duplicates.
  async function pushSubscribe(){
    if(!pushSupported() || !currentUser) return false;
    if(Notification.permission !== 'granted') return false;
    if(!(await ensureCloud())) return false;
    try{
      const reg = await navigator.serviceWorker.ready;
      let sub = await reg.pushManager.getSubscription();
      // A subscription is bound to the VAPID public key it was created
      // with. After a key rotation, the browser still holds the OLD one,
      // and every push sent with the new key is rejected — so throw it
      // away and subscribe again under the current key.
      if(sub && !pushKeyMatches(sub)){
        const oldEndpoint = sub.endpoint;
        try{ await sub.unsubscribe(); }catch(e){}
        try{ await db.from('push_subscriptions').delete().eq('endpoint', oldEndpoint); }catch(e){}
        sub = null;
      }
      if(!sub){
        sub = await reg.pushManager.subscribe({
          userVisibleOnly: true, // required by Chrome; every push must show something
          applicationServerKey: urlBase64ToUint8Array(PUSH_PUBLIC_KEY)
        });
      }
      const json = sub.toJSON();
      if(!json || !json.keys) return false;
      const { error } = await db.from('push_subscriptions').upsert({
        user_id: currentUser.id,
        customer_id: currentUser.role==='customer' ? (currentUser.customerId || null) : null,
        role: currentUser.role==='admin' ? 'admin' : (currentUser.role==='customer' ? 'customer' : 'tech'),
        endpoint: json.endpoint,
        p256dh: json.keys.p256dh,
        auth: json.keys.auth,
        user_agent: navigator.userAgent.slice(0, 300),
        last_seen_at: new Date().toISOString()
      }, { onConflict: 'endpoint' });
      if(error) throw error;
      return true;
    }catch(e){ console.error('push subscribe failed', describeCloudError(e)); return false; }
  }

  // Asks for permission, then subscribes. Called from the in-app prompt
  // rather than on load: a permission dialog that appears before someone
  // understands what it's for is usually dismissed, and a dismissal is
  // sticky — the browser won't ask again.
  async function pushRequestPermission(){
    if(!pushSupported()){ toast('This device does not support notifications'); return false; }
    if(Notification.permission === 'denied'){
      toast('Notifications are blocked — turn them back on in your browser settings for this site');
      return false;
    }
    let perm = Notification.permission;
    if(perm !== 'granted') perm = await Notification.requestPermission();
    if(perm !== 'granted'){ toast('Notifications stay off — you can turn them on later'); return false; }
    const ok = await pushSubscribe();
    toast(ok ? 'Notifications are on for this device' : 'Could not turn on notifications — try again');
    return ok;
  }

  // Signing out removes only THIS device's row: other devices the same
  // person uses keep working.
  async function pushUnsubscribeThisDevice(){
    if(!pushSupported()) return;
    try{
      // getRegistration(), not .ready: .ready never settles when no service
      // worker is active (private window, blocked SW, first moments after an
      // update), and Logout awaits this — it made the Logout button do
      // nothing at all on such devices. No registration = no subscription.
      const reg = await navigator.serviceWorker.getRegistration();
      if(!reg || !reg.pushManager) return;
      const sub = await reg.pushManager.getSubscription();
      if(!sub) return;
      const endpoint = sub.endpoint;
      try{ await sub.unsubscribe(); }catch(e){}
      if(await ensureCloud()){
        await db.from('push_subscriptions').delete().eq('endpoint', endpoint);
      }
    }catch(e){ /* signing out must never fail because of this */ }
  }

  // Re-subscribes a returning user silently when permission is already
  // granted (endpoints rotate, and a row may have been pruned as dead).
  async function pushInit(){
    pushRenderPrompts();
    if(!pushSupported() || !currentUser) return;
    if(Notification.permission === 'granted') pushSubscribe();
    navigator.serviceWorker.addEventListener('message', (e)=>{
      if(e.data && e.data.type==='push-subscription-changed') pushSubscribe();
    });
  }

  // ---------------------------------------------------------------------
  // Sending
  //
  // Every call is best-effort and deliberately NOT awaited by its caller:
  // a notification failing must never stop the action that triggered it
  // from completing. The audience is resolved server-side (see the Edge
  // Function) — callers name an audience, never a recipient list.
  // ---------------------------------------------------------------------
  async function notifyPush({ audience, customerId, userId, title, message, url, tag }){
    if(!(await ensureCloud())) return;
    try{
      await db.functions.invoke('send-push', {
        body: { audience, customerId, userId, title, message, url, tag }
      });
    }catch(e){ console.warn('notifyPush failed (non-fatal)', e && e.message); }
  }
  function notifyAdmins(title, message, tag){
    notifyPush({ audience:'admins', title, message, tag }).catch(()=>{});
  }
  function notifyCustomer(customerId, title, message, tag){
    if(!customerId) return;
    notifyPush({ audience:'customer', customerId, title, message, tag }).catch(()=>{});
  }
  function notifyUser(userId, title, message, tag){
    if(!userId) return;
    notifyPush({ audience:'user', userId, title, message, tag }).catch(()=>{});
  }
  function notifyTechnicians(title, message, tag){
    notifyPush({ audience:'technicians', title, message, tag }).catch(()=>{});
  }

  // ---------------------------------------------------------------------
  // The three in-app toggles (admin cloud sheet, technician profile,
  // customer profile). One shared handler — the only difference between
  // them is which pair of element ids they render into.
  // ---------------------------------------------------------------------
  const PUSH_TOGGLES = [
    { status:'pushStatusAdmin', btn:'pushEnableAdminBtn' },
    { status:'pushStatusTech',  btn:'pushEnableTechBtn' },
    { status:'pushStatusCust',  btn:'pushEnableCustBtn' }
  ];
  // ---------------------------------------------------------------------
  // Home-screen prompt (technician + customer). Shown only while this
  // device CAN get notifications but hasn't been allowed yet. The Android
  // permission pop-up is only ever triggered by the Turn On tap — never on
  // load — for the reason in pushRequestPermission's comment. "Not now"
  // hides it on this device for PUSH_PROMPT_SNOOZE_DAYS, then it returns.
  // ---------------------------------------------------------------------
  const PUSH_PROMPT_SNOOZE_DAYS = 7;
  function pushPromptSnoozeKey(){ return 'awes-push-prompt-snooze:'+(currentUser ? currentUser.id : ''); }
  function pushPromptSnoozed(){
    try{
      const until = Number(localStorage.getItem(pushPromptSnoozeKey()) || 0);
      return until > Date.now();
    }catch(e){ return false; }
  }
  function pushRenderPrompts(){
    const show = !!currentUser && currentUser.role !== 'admin'
      && pushSupported() && Notification.permission === 'default' && !pushPromptSnoozed();
    const msg = (currentUser && currentUser.role==='customer')
      ? 'Get alerts when your technician is on the way, arrives, or sends you a message.'
      : 'Get alerts for new job orders and messages, even when the app is closed.';
    ['pushPromptTech','pushPromptCust'].forEach(id=>{
      const el = $(id);
      if(!el) return;
      if(!show){ el.style.display = 'none'; el.innerHTML = ''; return; }
      el.innerHTML =
        '<span class="push-prompt-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M18 8a6 6 0 0 0-12 0c0 7-3 9-3 9h18s-3-2-3-9"/><path d="M13.7 21a2 2 0 0 1-3.4 0"/></svg></span>'+
        '<div class="push-prompt-body">'+
          '<p class="push-prompt-title">Turn on notifications</p>'+
          '<p class="push-prompt-text">'+msg+'</p>'+
          '<div class="push-prompt-actions">'+
            '<button type="button" class="btn btn-primary" data-push-on>Turn On</button>'+
            '<button type="button" class="btn push-prompt-later" data-push-later>Not now</button>'+
          '</div>'+
        '</div>';
      el.style.display = '';
      el.querySelector('[data-push-on]').addEventListener('click', async (e)=>{
        e.currentTarget.disabled = true;
        await pushRequestPermission();
        pushRefreshToggles();
      });
      el.querySelector('[data-push-later]').addEventListener('click', ()=>{
        try{ localStorage.setItem(pushPromptSnoozeKey(), String(Date.now() + PUSH_PROMPT_SNOOZE_DAYS*86400000)); }catch(e){}
        pushRenderPrompts();
      });
    });
  }

  function pushRefreshToggles(){
    let label, showBtn = true;
    if(!pushSupported()){ label = 'Not supported on this device'; showBtn = false; }
    else if(Notification.permission === 'granted'){ label = 'On'; showBtn = false; }
    else if(Notification.permission === 'denied'){ label = 'Blocked in browser settings'; showBtn = false; }
    else label = 'Off';
    PUSH_TOGGLES.forEach(t=>{
      const s = $(t.status), b = $(t.btn);
      if(s) s.textContent = label;
      if(b) b.style.display = showBtn ? '' : 'none';
    });
    pushRenderPrompts();
  }
  PUSH_TOGGLES.forEach(t=>{
    const b = $(t.btn);
    if(b) b.addEventListener('click', async ()=>{
      b.disabled = true;
      await pushRequestPermission();
      b.disabled = false;
      pushRefreshToggles();
    });
  });
  pushRefreshToggles();


  // =====================================================================
  // Purchasing — Supplier Database (admin only)
  //
  // Tables (migration 20260923_01_purchasing_suppliers_materials.sql):
  //   suppliers, supplier_contacts, supplier_documents, supplier_materials
  // All admin-only under RLS. Suppliers are never hard-deleted — only
  // deactivated — because requisitions and POs will reference them.
  //
  // Entry point: purchOnShow(key), called by showPurchasingView() in home.js.
  // =====================================================================

  // Shared with the Materials Database (materials.category) — keep in sync.
  const PURCH_CATEGORIES = [
    'Piping', 'Refrigerant', 'Electrical', 'Insulation', 'Consumables',
    'Parts & Components', 'Ducting & Ventilation', 'Plumbing',
    'Fire Protection', 'Hardware', 'Tools & Equipment', 'Others'
  ];
  const SP_DOC_TYPES = ['BIR 2303', 'DTI / SEC', "Mayor's Permit", 'Quotation', 'Price List', 'Other'];
  const SP_DOC_BUCKET = 'supplier-documents';
  const SP_DOC_MAX_BYTES = 10 * 1024 * 1024;
  const SP_PRICE_STALE_DAYS = 60;

  let spCache = [];            // suppliers, each with .contacts (embedded)
  let spEditing = null;        // supplier being edited in the sheet, or null when adding
  let spSheetSupplies = [];    // supplies selection inside the sheet
  let spContactsCache = [];

  // ---------- row <-> object ----------
  function spFromRow(r){
    const bank = r.bank_details || {};
    return {
      id: r.id, code: r.code || '', name: r.name || '', tradeName: r.trade_name || '',
      supplies: Array.isArray(r.supplies) ? r.supplies : [],
      address: r.address || '', city: r.city || '', tin: r.tin || '',
      vatRegistered: (r.vat_registered === true || r.vat_registered === false) ? r.vat_registered : null,
      paymentTerms: r.payment_terms || '', creditLimit: r.credit_limit,
      delivers: !!r.delivers, rating: r.rating || null, remarks: r.remarks || '',
      bank: { bank: bank.bank || '', accountName: bank.account_name || '', accountNo: bank.account_no || '', ewallet: bank.ewallet || '' },
      isActive: r.is_active !== false,
      contacts: Array.isArray(r.supplier_contacts) ? r.supplier_contacts : [],
      updatedAt: r.updated_at
    };
  }
  function spDisplayName(s){ return s.tradeName || s.name; }
  function spPrimaryContact(s){
    const c = s.contacts || [];
    return c.find(x=> x.is_primary) || c[0] || null;
  }
  function spParseMoney(v){
    const t = String(v == null ? '' : v).replace(/[₱,\s]/g, '');
    if(t === '') return null;
    const n = Number(t);
    return isFinite(n) && n >= 0 ? Math.round(n * 100) / 100 : NaN;
  }
  function spMoney(n){
    if(n == null || n === '') return '—';
    return '₱' + Number(n).toLocaleString('en-PH', { minimumFractionDigits:2, maximumFractionDigits:2 });
  }
  function spDaysSince(dateStr){
    if(!dateStr) return null;
    const d = new Date(dateStr + (String(dateStr).length === 10 ? 'T00:00:00' : ''));
    return Math.floor((Date.now() - d.getTime()) / 86400000);
  }

  // ---------- entry ----------
  function purchOnShow(key){
    if(key === 'myRequests'){ if(currentUser) mrtShow(); return; }   // technician screen
    if(key === 'myStock'){ if(currentUser) invShowMyStock(); return; } // storekeeper screen (quantities only)
    if(key === 'myMaterials'){ if(currentUser) invShowMyMaterials(); return; }
    // Movement screens: admins and storekeepers (the database decides who
    // may post for which warehouse)
    if(key === 'receive'){ invShowReceive(); return; }
    if(key === 'issue'){ invShowIssue(); return; }
    if(key === 'returns'){ invShowReturns(); return; }
    if(key === 'transfers'){ invShowTransfers(); return; }
    if(key === 'slips'){ invShowSlips(); return; }
    if(key === 'invReports'){ rpShow(); return; }   // admins + storekeepers (quantities only for storekeepers)
    // Tools & Equipment — the database decides who may do what
    const tlPages = { tlHub: tlShowHub, tlRegister: tlShowRegister, tlIssue: tlShowIssue, tlReturn: tlShowReturn, tlHandover: tlShowHandover,
      tlDefects: tlShowDefects, tlMaint: tlShowMaint, tlSlips: tlShowSlips, tlReports: tlShowReports, myTools: tlShowMine };
    if(tlPages[key]){ tlPages[key](); return; }
    if(!currentUser || currentUser.role !== 'admin') return;
    purchRealtimeStart();
    if(key === 'suppliers') spShow();
    if(key === 'materials') mtShow();
    if(key === 'purchaseOrders') poShow();
    if(key === 'requisitions') mrShow();
    if(key === 'stock') invShowStock();
    if(key === 'warehouses') invShowWarehouses();
    if(key === 'projects') invShowProjects();
  }

  async function spShow(){
    const sel = $('spFilterCategory');
    if(sel.options.length <= 1){
      PURCH_CATEGORIES.forEach(c=>{ const o = document.createElement('option'); o.value = c; o.textContent = c; sel.appendChild(o); });
    }
    if(await spLoad()) spRenderList();
  }

  async function spLoad(opts){
    const silent = !!(opts && opts.silent);
    const list = $('spList');
    if(!silent) list.innerHTML = '<div class="empty-state">Loading…</div>';
    if(!(await ensureCloud())){
      spCache = [];
      list.innerHTML = '<div class="empty-state">Not connected to Shared Cloud — the Supplier Database needs a connection.</div>';
      return false;
    }
    try{
      const { data, error } = await db.from('suppliers')
        .select('*, supplier_contacts(id,name,position,mobile,email,is_primary)')
        .order('name', { ascending: true });
      if(error) throw error;
      spCache = (data || []).map(spFromRow);
      return true;
    }catch(e){
      console.error('load suppliers failed', describeCloudError(e));
      if(silent) return false;   // background refresh: keep what's on screen
      spCache = [];
      const msg = purchIsAuthError(e) ? PURCH_EXPIRED_HTML : /relation .*suppliers.* does not exist|42P01/.test(describeCloudError(e))
        ? 'The suppliers table isn\u2019t in the database yet — run migration 20260923_01_purchasing_suppliers_materials.sql in Supabase first.'
        : 'Couldn\u2019t load suppliers: ' + escapeHtml(describeCloudError(e));
      list.innerHTML = '<div class="empty-state">' + msg + '</div>';
      return false;
    }
  }

  function spFiltered(){
    const q = ($('spSearch').value || '').trim().toLowerCase();
    const cat = $('spFilterCategory').value;
    const showInactive = $('spShowInactive').checked;
    return spCache.filter(s=>{
      if(!showInactive && !s.isActive) return false;
      if(cat && !s.supplies.includes(cat)) return false;
      if(!q) return true;
      const hay = [s.code, s.name, s.tradeName, s.city, s.address, s.tin]
        .concat((s.contacts || []).map(c=> c.name + ' ' + c.mobile + ' ' + c.email))
        .join(' ').toLowerCase();
      return hay.includes(q);
    });
  }

  function spRenderList(){
    const list = $('spList');
    const active = spCache.filter(s=> s.isActive).length;
    $('spCount').textContent = spCache.length ? (active + ' active' + (spCache.length > active ? ' · ' + (spCache.length - active) + ' inactive' : '')) : '';
    const rows = spFiltered();
    const openIds = new Set($$('#spList .user-card').filter(c=> c.querySelector('.user-edit-panel.open')).map(c=> c.dataset.id));
    if(rows.length === 0){
      list.innerHTML = '<div class="empty-state">' + (spCache.length === 0
        ? 'No suppliers yet. Tap <b>+ Add Supplier</b>, or import a CSV.'
        : 'No suppliers match.') + '</div>';
      return;
    }
    list.innerHTML = rows.map(s=>{
      const pc = spPrimaryContact(s);
      const sub = [s.code, s.city, s.paymentTerms, s.delivers ? 'Delivers' : 'Pickup only'].filter(Boolean).join(' · ');
      const tags = s.supplies.map(t=> '<span class="sp-tag">' + escapeHtml(t) + '</span>').join('') +
        (s.isActive ? '' : '<span class="sp-tag danger">Inactive</span>') +
        (s.rating ? '<span class="sp-tag muted">' + '★'.repeat(s.rating) + '</span>' : '');
      const vat = s.vatRegistered === true ? 'VAT-registered' : s.vatRegistered === false ? 'Non-VAT' : 'Unknown';
      const isOpen = openIds.has(s.id) ? ' open' : '';
      return '<div class="user-card' + (s.isActive ? '' : ' inactive') + '" data-id="' + escapeHtml(s.id) + '">' +
        '<div class="user-card-head' + isOpen + '" data-act="toggle" style="cursor:pointer;"><div style="min-width:0;">' +
          '<div class="u-name">' + escapeHtml(spDisplayName(s)) + '</div>' +
          '<div class="u-status">' + escapeHtml(sub) + '</div>' +
          (tags ? '<div class="sp-tags">' + tags + '</div>' : '') +
        '</div><span class="card-caret">▾</span></div>' +
        '<div class="user-edit-panel' + isOpen + '">' +
          (s.tradeName && s.tradeName !== s.name ? '<div class="cust-detail-row"><b>Registered name:</b> ' + escapeHtml(s.name) + '</div>' : '') +
          '<div class="cust-detail-row"><b>Address:</b> ' + escapeHtml([s.address, s.city].filter(Boolean).join(', ') || '—') + '</div>' +
          '<div class="cust-detail-row"><b>Contact:</b> ' + (pc
            ? escapeHtml(pc.name) + (pc.position ? ' (' + escapeHtml(pc.position) + ')' : '') +
              (pc.mobile ? ' · <a href="tel:' + escapeHtml(pc.mobile.replace(/\s/g, '')) + '">' + escapeHtml(pc.mobile) + '</a>' : '')
            : '—') + (s.contacts.length > 1 ? ' <span style="color:var(--text-muted);">+' + (s.contacts.length - 1) + ' more</span>' : '') + '</div>' +
          '<div class="cust-detail-row"><b>TIN / VAT:</b> ' + escapeHtml(s.tin || '—') + ' · ' + vat + '</div>' +
          '<div class="cust-detail-row"><b>Terms:</b> ' + escapeHtml(s.paymentTerms || '—') +
            (s.creditLimit != null ? ' · Credit limit ' + spMoney(s.creditLimit) : '') + '</div>' +
          (s.remarks ? '<div class="cust-detail-row"><b>Remarks:</b> ' + escapeHtml(s.remarks) + '</div>' : '') +
          '<div class="user-card-actions">' +
            '<button type="button" data-act="edit" class="primary">Edit</button>' +
            '<button type="button" data-act="contacts">Contacts</button>' +
            '<button type="button" data-act="docs">Documents</button>' +
            '<button type="button" data-act="prices">Price List</button>' +
            (s.isActive
              ? '<button type="button" data-act="deactivate" class="danger">Deactivate</button>'
              : '<button type="button" data-act="reactivate">Reactivate</button>') +
          '</div>' +
        '</div>' +
      '</div>';
    }).join('');
  }

  $('spSearch').addEventListener('input', spRenderList);
  $('spFilterCategory').addEventListener('change', spRenderList);
  $('spShowInactive').addEventListener('change', spRenderList);
  $('spAddBtn').addEventListener('click', ()=> spOpenSheet(null, 'info'));

  $('spList').addEventListener('click', async (e)=>{
    const btn = e.target.closest('[data-act]');
    if(!btn) return;
    const card = btn.closest('.user-card');
    const s = card && spCache.find(x=> x.id === card.dataset.id);
    if(!s) return;
    const act = btn.dataset.act;
    if(act === 'toggle'){
      card.querySelector('.user-edit-panel').classList.toggle('open');
      card.querySelector('.user-card-head').classList.toggle('open');
      return;
    }
    if(act === 'edit') return spOpenSheet(s, 'info');
    if(act === 'contacts' || act === 'docs' || act === 'prices') return spOpenSheet(s, act);
    if(act === 'deactivate' || act === 'reactivate'){
      const on = act === 'reactivate';
      if(!on && !confirm('Deactivate ' + spDisplayName(s) + '? It will be hidden from pickers but kept for existing records. You can reactivate it any time.')) return;
      if(!(await purchEnsureSession())) return;
      btn.disabled = true;
      try{
        purchMarkOwn(s.id);
        const { error } = await db.from('suppliers').update({ is_active: on }).eq('id', s.id);
        if(error) throw error;
        s.isActive = on;
        toast(spDisplayName(s) + (on ? ' reactivated' : ' deactivated'));
        spRenderList();
      }catch(err){
        btn.disabled = false;
        purchFail('Couldn\u2019t update supplier: ', err);
      }
    }
  });

  // ---------- sheet ----------
  function spRenderSuppliesPick(){
    $('spSuppliesPick').innerHTML = PURCH_CATEGORIES.map(c=>
      '<button type="button" data-cat="' + escapeHtml(c) + '" class="' + (spSheetSupplies.includes(c) ? 'on' : '') + '">' + escapeHtml(c) + '</button>'
    ).join('');
  }
  $('spSuppliesPick').addEventListener('click', (e)=>{
    const b = e.target.closest('[data-cat]');
    if(!b) return;
    const c = b.dataset.cat;
    spSheetSupplies = spSheetSupplies.includes(c) ? spSheetSupplies.filter(x=> x !== c) : spSheetSupplies.concat(c);
    b.classList.toggle('on');
  });

  function spOpenSheet(s, tab){
    spEditing = s;
    $('spStaleNote').style.display = 'none';
    $('spSheetTitle').textContent = s ? spDisplayName(s) : 'Add Supplier';
    $('spCodeLine').style.display = s ? '' : 'none';
    $('spCodeLine').textContent = s ? s.code + (s.isActive ? '' : ' · Inactive') : '';
    $('spName').value = s ? s.name : '';
    $('spTradeName').value = s ? s.tradeName : '';
    spSheetSupplies = s ? s.supplies.slice() : [];
    spRenderSuppliesPick();
    $('spAddress').value = s ? s.address : '';
    $('spCity').value = s ? s.city : '';
    $('spTin').value = s ? s.tin : '';
    $('spVat').value = s && s.vatRegistered !== null ? String(s.vatRegistered) : '';
    $('spTerms').value = s ? s.paymentTerms : 'COD';
    $('spCreditLimit').value = s && s.creditLimit != null ? String(s.creditLimit) : '';
    $('spDelivers').value = s && s.delivers ? 'true' : 'false';
    $('spRating').value = s && s.rating ? String(s.rating) : '';
    $('spBank').value = s ? s.bank.bank : '';
    $('spAcctName').value = s ? s.bank.accountName : '';
    $('spAcctNo').value = s ? s.bank.accountNo : '';
    $('spEwallet').value = s ? s.bank.ewallet : '';
    $('spRemarks').value = s ? s.remarks : '';
    $('spSaveBtn').textContent = s ? 'Save Changes' : 'Save Supplier';
    $('spSaveBtn').disabled = false;
    spResetContactForm();
    const sel = $('spDocType');
    if(!sel.options.length) sel.innerHTML = SP_DOC_TYPES.map(t=> '<option>' + escapeHtml(t) + '</option>').join('');
    spResetDocForm();
    spSetTabsEnabled(!!s);
    spShowTab(s ? tab : 'info');
    $('spSheetOverlay').classList.add('open');
  }
  function spSetTabsEnabled(on){
    $$('#spTabs [data-sp-tab]').forEach(b=>{
      if(b.dataset.spTab !== 'info') b.classList.toggle('sp-seg-disabled', !on);
    });
  }
  function spShowTab(tab){
    $$('#spTabs [data-sp-tab]').forEach(b=> b.classList.toggle('active', b.dataset.spTab === tab));
    $('spPaneInfo').style.display = tab === 'info' ? '' : 'none';
    $('spPaneContacts').style.display = tab === 'contacts' ? '' : 'none';
    $('spPaneDocs').style.display = tab === 'docs' ? '' : 'none';
    $('spPanePrices').style.display = tab === 'prices' ? '' : 'none';
    if(!spEditing) return;
    if(tab === 'contacts') spLoadContacts();
    if(tab === 'docs') spLoadDocs();
    if(tab === 'prices') spLoadPrices();
  }
  $('spTabs').addEventListener('click', (e)=>{
    const b = e.target.closest('[data-sp-tab]');
    if(b && !b.classList.contains('sp-seg-disabled')) spShowTab(b.dataset.spTab);
  });
  function spCloseSheet(){
    $('spSheetOverlay').classList.remove('open');
    spEditing = null;
    spLoad().then(ok=>{ if(ok) spRenderList(); });   // contacts/primary may have changed
  }
  $('spSheetClose').addEventListener('click', spCloseSheet);

  $('spSaveBtn').addEventListener('click', async ()=>{
    const name = $('spName').value.trim();
    if(!name){ toast('Registered business name is required'); $('spName').focus(); return; }
    const credit = spParseMoney($('spCreditLimit').value);
    if(Number.isNaN(credit)){ toast('Credit limit must be a number'); $('spCreditLimit').focus(); return; }
    const dup = spCache.find(x=> x.name.trim().toLowerCase() === name.toLowerCase() && (!spEditing || x.id !== spEditing.id));
    if(dup && !confirm('A supplier named "' + dup.name + '" (' + dup.code + ') already exists. Save anyway?')) return;
    const vat = $('spVat').value;
    const row = {
      name, trade_name: $('spTradeName').value.trim(), supplies: spSheetSupplies.slice(),
      address: $('spAddress').value.trim(), city: $('spCity').value.trim(), tin: $('spTin').value.trim(),
      vat_registered: vat === '' ? null : vat === 'true',
      payment_terms: $('spTerms').value.trim() || 'COD', credit_limit: credit,
      delivers: $('spDelivers').value === 'true',
      rating: $('spRating').value ? Number($('spRating').value) : null,
      bank_details: {
        bank: $('spBank').value.trim(), account_name: $('spAcctName').value.trim(),
        account_no: $('spAcctNo').value.trim(), ewallet: $('spEwallet').value.trim()
      },
      remarks: $('spRemarks').value.trim()
    };
    if(!(await ensureCloud())){ toast('Not connected — can\u2019t save'); return; }
    if(!(await purchEnsureSession())) return;
    const btn = $('spSaveBtn'); btn.disabled = true;
    try{
      let res;
      if(spEditing) res = await db.from('suppliers').update(row).eq('id', spEditing.id).select('*, supplier_contacts(id,name,position,mobile,email,is_primary)').single();
      else res = await db.from('suppliers').insert(row).select('*, supplier_contacts(id,name,position,mobile,email,is_primary)').single();
      if(res.error) throw res.error;
      const saved = spFromRow(res.data);
      purchMarkOwn(saved.id);
      const wasNew = !spEditing;
      const i = spCache.findIndex(x=> x.id === saved.id);
      if(i >= 0) spCache[i] = saved; else spCache.push(saved);
      spCache.sort((a,b)=> a.name.localeCompare(b.name));
      spEditing = saved;
      spRenderList();
      $('spSheetTitle').textContent = spDisplayName(saved);
      $('spCodeLine').style.display = ''; $('spCodeLine').textContent = saved.code;
      btn.textContent = 'Save Changes';
      spSetTabsEnabled(true);
      toast(wasNew ? 'Supplier saved as ' + saved.code + ' — add contacts next' : 'Supplier updated');
      if(wasNew) spShowTab('contacts');
    }catch(e){
      purchFail('Couldn\u2019t save supplier: ', e);
    }finally{ btn.disabled = false; }
  });

  // ---------- contacts ----------
  function spResetContactForm(){
    $('spContactId').value = '';
    ['spContactName','spContactPosition','spContactMobile','spContactEmail'].forEach(id=> $(id).value = '');
    $('spContactPrimary').checked = false;
    $('spContactFormTitle').textContent = 'Add a contact';
    $('spContactCancelBtn').style.display = 'none';
  }
  async function spLoadContacts(opts){
    const list = $('spContactsList');
    if(!(opts && opts.silent)) list.innerHTML = '<div class="empty-state">Loading…</div>';
    try{
      const { data, error } = await db.from('supplier_contacts').select('*')
        .eq('supplier_id', spEditing.id).order('is_primary', { ascending:false }).order('name');
      if(error) throw error;
      spContactsCache = data || [];
      if(!spContactsCache.length){
        list.innerHTML = '<div class="empty-state" style="padding:16px;">No contacts yet.</div>';
        $('spContactPrimary').checked = true;   // first contact defaults to primary
        return;
      }
      list.innerHTML = spContactsCache.map(c=>
        '<div class="sp-row" data-id="' + escapeHtml(c.id) + '"><div class="sp-row-top"><div style="min-width:0;">' +
          '<div class="sp-row-title">' + escapeHtml(c.name) + (c.is_primary ? ' <span class="sp-tag">Primary</span>' : '') + '</div>' +
          '<div class="sp-row-sub">' + [
            c.position ? escapeHtml(c.position) : '',
            c.mobile ? '<a href="tel:' + escapeHtml(c.mobile.replace(/\s/g, '')) + '">' + escapeHtml(c.mobile) + '</a>' : '',
            c.email ? '<a href="mailto:' + escapeHtml(c.email) + '">' + escapeHtml(c.email) + '</a>' : ''
          ].filter(Boolean).join(' · ') + '</div>' +
        '</div></div><div class="user-card-actions">' +
          '<button type="button" data-cact="edit">Edit</button>' +
          (c.is_primary ? '' : '<button type="button" data-cact="primary">Make primary</button>') +
          '<button type="button" data-cact="remove" class="danger">Remove</button>' +
        '</div></div>'
      ).join('');
    }catch(e){
      list.innerHTML = '<div class="empty-state">Couldn\u2019t load contacts: ' + escapeHtml(describeCloudError(e)) + '</div>';
    }
  }
  // The unique "one primary per supplier" index means the old primary must
  // be cleared before a new one is set.
  async function spClearPrimary(exceptId){
    let q = db.from('supplier_contacts').update({ is_primary:false }).eq('supplier_id', spEditing.id).eq('is_primary', true);
    if(exceptId) q = q.neq('id', exceptId);
    const { error } = await q;
    if(error) throw error;
  }
  $('spContactsList').addEventListener('click', async (e)=>{
    const b = e.target.closest('[data-cact]');
    if(!b) return;
    const c = spContactsCache.find(x=> x.id === b.closest('.sp-row').dataset.id);
    if(!c) return;
    const act = b.dataset.cact;
    if(act === 'edit'){
      $('spContactId').value = c.id;
      $('spContactName').value = c.name; $('spContactPosition').value = c.position || '';
      $('spContactMobile').value = c.mobile || ''; $('spContactEmail').value = c.email || '';
      $('spContactPrimary').checked = !!c.is_primary;
      $('spContactFormTitle').textContent = 'Edit contact';
      $('spContactCancelBtn').style.display = '';
      $('spContactName').focus();
      return;
    }
    if(!(await purchEnsureSession())) return;
    b.disabled = true;
    try{
      if(act === 'primary'){
        await spClearPrimary(c.id);
        const { error } = await db.from('supplier_contacts').update({ is_primary:true }).eq('id', c.id);
        if(error) throw error;
        toast(c.name + ' is now the primary contact');
      }else if(act === 'remove'){
        if(!confirm('Remove ' + c.name + ' from this supplier?')){ b.disabled = false; return; }
        const { error } = await db.from('supplier_contacts').delete().eq('id', c.id);
        if(error) throw error;
        toast('Contact removed');
      }
      spLoadContacts();
    }catch(err){
      b.disabled = false;
      purchFail('Couldn\u2019t update contact: ', err);
    }
  });
  $('spContactCancelBtn').addEventListener('click', spResetContactForm);
  $('spContactSaveBtn').addEventListener('click', async ()=>{
    if(!spEditing) return;
    const name = $('spContactName').value.trim();
    if(!name){ toast('Contact name is required'); $('spContactName').focus(); return; }
    const id = $('spContactId').value;
    const primary = $('spContactPrimary').checked;
    const row = {
      name, position: $('spContactPosition').value.trim(),
      mobile: $('spContactMobile').value.trim(), email: $('spContactEmail').value.trim(),
      is_primary: primary
    };
    if(!(await purchEnsureSession())) return;
    const btn = $('spContactSaveBtn'); btn.disabled = true;
    try{
      if(primary) await spClearPrimary(id || null);
      const res = id
        ? await db.from('supplier_contacts').update(row).eq('id', id)
        : await db.from('supplier_contacts').insert(Object.assign({ supplier_id: spEditing.id }, row));
      if(res.error) throw res.error;
      toast(id ? 'Contact updated' : 'Contact added');
      spResetContactForm();
      spLoadContacts();
    }catch(e){
      purchFail('Couldn\u2019t save contact: ', e);
    }finally{ btn.disabled = false; }
  });

  // ---------- documents ----------
  function spResetDocForm(){
    $('spDocTitle').value = ''; $('spDocExpires').value = ''; $('spDocFile').value = '';
    if($('spDocType').options.length) $('spDocType').selectedIndex = 0;
  }
  let spDocsCache = [];
  async function spLoadDocs(opts){
    const list = $('spDocsList');
    if(!(opts && opts.silent)) list.innerHTML = '<div class="empty-state">Loading…</div>';
    try{
      const { data, error } = await db.from('supplier_documents').select('*')
        .eq('supplier_id', spEditing.id).order('created_at', { ascending:false });
      if(error) throw error;
      spDocsCache = data || [];
      if(!spDocsCache.length){
        list.innerHTML = '<div class="empty-state" style="padding:16px;">No documents yet — upload BIR 2303, permits, or quotations below.</div>';
        return;
      }
      const today = new Date().toISOString().slice(0,10);
      list.innerHTML = spDocsCache.map(d=>{
        let exp = '';
        if(d.expires_on){
          const left = -spDaysSince(d.expires_on);
          exp = d.expires_on < today ? '<span class="sp-tag danger">Expired ' + escapeHtml(d.expires_on) + '</span>'
            : left <= 30 ? '<span class="sp-tag warn">Expires ' + escapeHtml(d.expires_on) + '</span>'
            : '<span class="sp-tag muted">Valid until ' + escapeHtml(d.expires_on) + '</span>';
        }
        return '<div class="sp-row" data-id="' + escapeHtml(d.id) + '"><div class="sp-row-top"><div style="min-width:0;">' +
          '<div class="sp-row-title">' + escapeHtml(d.title || d.doc_type) + ' <span class="sp-tag muted">' + escapeHtml(d.doc_type) + '</span> ' + exp + '</div>' +
          '<div class="sp-row-sub">' + escapeHtml(d.file_name || '') + ' · uploaded ' + escapeHtml(String(d.created_at || '').slice(0,10)) + '</div>' +
        '</div></div><div class="user-card-actions">' +
          '<button type="button" data-dact="open" class="primary">Open</button>' +
          '<button type="button" data-dact="remove" class="danger">Delete</button>' +
        '</div></div>';
      }).join('');
    }catch(e){
      list.innerHTML = '<div class="empty-state">Couldn\u2019t load documents: ' + escapeHtml(describeCloudError(e)) + '</div>';
    }
  }
  $('spDocsList').addEventListener('click', async (e)=>{
    const b = e.target.closest('[data-dact]');
    if(!b) return;
    const d = spDocsCache.find(x=> x.id === b.closest('.sp-row').dataset.id);
    if(!d) return;
    if(b.dataset.dact === 'open' && (/^(application\/pdf|image\/)/.test(d.mime_type || '') || /\.(pdf|png|jpe?g|webp|gif)$/i.test(d.file_name || d.storage_path || ''))){
      // PDFs and images open in the app's PDF viewer (Download / Share there).
      b.disabled = true;
      try{
        const { data, error } = await db.storage.from(SP_DOC_BUCKET).download(d.storage_path);
        if(error) throw error;
        const isPdf = (d.mime_type || '') === 'application/pdf' || /\.pdf$/i.test(d.file_name || d.storage_path || '');
        const blob = isPdf ? new Blob([data], { type:'application/pdf' }) : data;
        await openFileInPdfViewer(blob, d.file_name || d.title || 'document', d.title || d.file_name || d.doc_type);
      }catch(err){
        purchFail('Couldn\u2019t open document: ', err);
      }finally{ b.disabled = false; }
      return;
    }
    if(b.dataset.dact === 'open'){
      // Open the tab synchronously (inside the tap) so mobile popup
      // blockers allow it, then point it at the signed URL once we have it.
      const w = window.open('', '_blank');
      try{
        const { data, error } = await db.storage.from(SP_DOC_BUCKET).createSignedUrl(d.storage_path, 600);
        if(error) throw error;
        if(w) w.location.href = data.signedUrl; else window.location.href = data.signedUrl;
      }catch(err){
        if(w) w.close();
        purchFail('Couldn\u2019t open document: ', err);
      }
      return;
    }
    if(!confirm('Delete "' + (d.title || d.file_name || d.doc_type) + '"? This cannot be undone.')) return;
    if(!(await purchEnsureSession())) return;
    b.disabled = true;
    try{
      const { error } = await db.from('supplier_documents').delete().eq('id', d.id);
      if(error) throw error;
      try{ await db.storage.from(SP_DOC_BUCKET).remove([d.storage_path]); }catch(_){}
      toast('Document deleted');
      spLoadDocs();
    }catch(err){
      b.disabled = false;
      purchFail('Couldn\u2019t delete document: ', err);
    }
  });
  $('spDocUploadBtn').addEventListener('click', async ()=>{
    if(!spEditing) return;
    const file = $('spDocFile').files && $('spDocFile').files[0];
    if(!file){ toast('Choose a file first'); return; }
    if(file.size > SP_DOC_MAX_BYTES){ toast('File is over 10 MB'); return; }
    if(!/^(application\/pdf|image\/)/.test(file.type || '')){ toast('Only PDF or image files'); return; }
    if(!(await purchEnsureSession())) return;
    const btn = $('spDocUploadBtn'); btn.disabled = true; btn.textContent = 'Uploading…';
    const safeName = (file.name || 'document').replace(/[^a-zA-Z0-9._-]/g, '_');
    const path = spEditing.id + '/' + Date.now() + '-' + safeName;
    try{
      const up = await db.storage.from(SP_DOC_BUCKET).upload(path, file, { contentType: file.type, upsert:false });
      if(up.error) throw up.error;
      const { error } = await db.from('supplier_documents').insert({
        supplier_id: spEditing.id, doc_type: $('spDocType').value,
        title: $('spDocTitle').value.trim(), storage_path: path,
        file_name: file.name || safeName, mime_type: file.type || '',
        expires_on: $('spDocExpires').value || null
      });
      if(error){
        try{ await db.storage.from(SP_DOC_BUCKET).remove([path]); }catch(_){}
        throw error;
      }
      toast('Document uploaded');
      spResetDocForm();
      spLoadDocs();
    }catch(e){
      purchFail('Upload failed: ', e);
    }finally{ btn.disabled = false; btn.textContent = 'Upload'; }
  });

  // ---------- price list (read-only until the Materials Database is built) ----------
  async function spLoadPrices(opts){
    const list = $('spPricesList');
    if(!(opts && opts.silent)) list.innerHTML = '<div class="empty-state">Loading…</div>';
    try{
      const { data, error } = await db.from('supplier_materials')
        .select('id, supplier_item_code, price, price_unit, price_updated_at, min_order_qty, lead_time_days, is_preferred, is_active, materials(code, name, unit)')
        .eq('supplier_id', spEditing.id);
      if(error) throw error;
      const rows = (data || []).sort((a,b)=> ((a.materials && a.materials.name) || '').localeCompare((b.materials && b.materials.name) || ''));
      if(!rows.length){
        list.innerHTML = '<div class="empty-state" style="padding:16px;">No items priced for this supplier yet.<br>' +
          'Add prices from <b>Purchasing › Materials Database</b> — open an item, then its <b>Supplier Prices</b> tab.</div>';
        return;
      }
      list.innerHTML = '<div class="sp-table-wrap"><table class="sp-table"><thead><tr>' +
        '<th>Item</th><th>Their code</th><th class="num">Price</th><th>Updated</th><th class="num">Lead time</th></tr></thead><tbody>' +
        rows.map(r=>{
          const m = r.materials || {};
          const age = spDaysSince(r.price_updated_at);
          const stale = age != null && age > SP_PRICE_STALE_DAYS;
          return '<tr' + (r.is_active ? '' : ' style="opacity:.55;"') + '><td><b>' + escapeHtml(m.name || '—') + '</b><div class="sp-row-sub">' + escapeHtml(m.code || '') +
              (r.is_preferred ? ' <span class="sp-tag">Preferred</span>' : '') + '</div></td>' +
            '<td>' + escapeHtml(r.supplier_item_code || '—') + '</td>' +
            '<td class="num">' + spMoney(r.price) + '<div class="sp-row-sub">' + escapeHtml(r.price_unit || (m.unit ? 'per ' + m.unit : '')) + '</div></td>' +
            '<td>' + (r.price_updated_at ? escapeHtml(r.price_updated_at) : '—') + (stale ? ' <span class="sp-tag warn">' + age + 'd old</span>' : '') + '</td>' +
            '<td class="num">' + (r.lead_time_days != null ? r.lead_time_days + 'd' : '—') + '</td></tr>';
        }).join('') + '</tbody></table></div>';
    }catch(e){
      list.innerHTML = '<div class="empty-state">Couldn\u2019t load price list: ' + escapeHtml(describeCloudError(e)) + '</div>';
    }
  }

  // ---------- CSV import / export ----------
  // Columns. Bank details are deliberately excluded from both directions.
  const SP_CSV_COLS = ['code','name','trade_name','supplies','address','city','tin','vat_registered',
    'payment_terms','credit_limit','delivers','rating','remarks','is_active',
    'contact_name','contact_position','contact_mobile','contact_email'];

  function spCsvCell(v){
    const t = v == null ? '' : String(v);
    return /[",\r\n]/.test(t) ? '"' + t.replace(/"/g, '""') + '"' : t;
  }
  // RFC 4180-ish parser: quoted fields, escaped quotes, CRLF/LF, embedded newlines.
  // Like Excel, a quote only opens a quoted field when it's the field's first
  // character — so hand-typed inch marks (Copper Tube 3/8" Soft) stay literal
  // instead of swallowing the rest of the row.
  function spParseCsv(text){
    const rows = []; let row = []; let f = ''; let q = false; let atStart = true;
    text = text.replace(/^\uFEFF/, '');
    for(let i = 0; i < text.length; i++){
      const ch = text[i];
      if(q){
        if(ch === '"'){ if(text[i+1] === '"'){ f += '"'; i++; } else q = false; }
        else f += ch;
        continue;
      }
      if(ch === '"' && atStart){ q = true; atStart = false; continue; }
      atStart = false;
      if(ch === ','){ row.push(f); f = ''; atStart = true; }
      else if(ch === '\n' || ch === '\r'){
        if(ch === '\r' && text[i+1] === '\n') i++;
        row.push(f); f = ''; atStart = true;
        if(row.some(c=> c.trim() !== '')) rows.push(row);
        row = [];
      }else f += ch;
    }
    row.push(f);
    if(row.some(c=> c.trim() !== '')) rows.push(row);
    return rows;
  }
  function spCsvBool(v){
    const t = String(v || '').trim().toLowerCase();
    if(['y','yes','true','1','vat','vat-registered','delivers','active'].includes(t)) return true;
    if(['n','no','false','0','non-vat','nonvat','pickup','pickup only','inactive'].includes(t)) return false;
    return null;
  }

  $('spExportBtn').addEventListener('click', ()=>{
    const rows = spFiltered();
    const lines = [SP_CSV_COLS.join(',')].concat(rows.map(s=>{
      const pc = spPrimaryContact(s) || {};
      return [s.code, s.name, s.tradeName, s.supplies.join('; '), s.address, s.city, s.tin,
        s.vatRegistered === null ? '' : (s.vatRegistered ? 'yes' : 'no'),
        s.paymentTerms, s.creditLimit == null ? '' : s.creditLimit, s.delivers ? 'yes' : 'no',
        s.rating || '', s.remarks, s.isActive ? 'yes' : 'no',
        pc.name || '', pc.position || '', pc.mobile || '', pc.email || ''].map(spCsvCell).join(',');
    }));
    // BOM so Excel reads ñ and ₱ correctly
    const blob = new Blob(['\uFEFF' + lines.join('\r\n')], { type:'text/csv;charset=utf-8' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'suppliers-' + new Date().toISOString().slice(0,10) + '.csv';
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(()=> URL.revokeObjectURL(a.href), 2000);
    toast(rows.length ? 'Exported ' + rows.length + ' supplier' + (rows.length === 1 ? '' : 's') : 'Exported a blank template');
  });

  $('spImportBtn').addEventListener('click', ()=>{ $('spImportFile').value = ''; $('spImportFile').click(); });
  $('spImportFile').addEventListener('change', async ()=>{
    const file = $('spImportFile').files && $('spImportFile').files[0];
    if(!file) return;
    if(!(await ensureCloud())){ toast('Not connected — can\u2019t import'); return; }
    if(!(await purchEnsureSession())) return;
    let rows;
    try{ rows = spParseCsv(await file.text()); }catch(e){ toast('Couldn\u2019t read that file'); return; }
    if(rows.length < 2){ toast('The CSV has no data rows'); return; }
    const head = rows[0].map(h=> h.trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, ''));
    if(!head.includes('name')){ toast('CSV needs at least a "name" column'); return; }
    const col = (r, k)=>{ const i = head.indexOf(k); return i < 0 ? undefined : (r[i] || '').trim(); };
    const has = (k)=> head.includes(k);

    const byCode = new Map(spCache.map(s=> [s.code.toLowerCase(), s]));
    const byName = new Map(spCache.map(s=> [s.name.trim().toLowerCase(), s]));
    const inserts = [], updates = [], skipped = [];
    rows.slice(1).forEach((r, idx)=>{
      const name = col(r, 'name');
      if(!name){ skipped.push('row ' + (idx + 2) + ': no name'); return; }
      const row = { name };
      if(has('trade_name')) row.trade_name = col(r, 'trade_name');
      if(has('supplies')){
        const lookup = new Map(PURCH_CATEGORIES.map(c=> [c.toLowerCase(), c]));
        row.supplies = col(r, 'supplies').split(/[;|]/).map(x=> x.trim()).filter(Boolean)
          .map(x=> lookup.get(x.toLowerCase()) || x);
      }
      ['address','city','tin','payment_terms','remarks'].forEach(k=>{ if(has(k)) row[k] = col(r, k); });
      if(has('vat_registered')) row.vat_registered = spCsvBool(col(r, 'vat_registered'));
      if(has('delivers')) row.delivers = spCsvBool(col(r, 'delivers')) === true;
      if(has('is_active') && col(r, 'is_active') !== '') row.is_active = spCsvBool(col(r, 'is_active')) !== false;
      if(has('credit_limit')){
        const n = spParseMoney(col(r, 'credit_limit'));
        if(Number.isNaN(n)){ skipped.push('row ' + (idx + 2) + ': bad credit_limit'); return; }
        row.credit_limit = n;
      }
      if(has('rating')){
        const n = parseInt(col(r, 'rating'), 10);
        row.rating = n >= 1 && n <= 5 ? n : null;
      }
      if(row.payment_terms === '') delete row.payment_terms;
      const code = has('code') ? col(r, 'code') : '';
      const existing = (code && byCode.get(code.toLowerCase())) || byName.get(name.toLowerCase());
      const contact = has('contact_name') && col(r, 'contact_name') ? {
        name: col(r, 'contact_name'), position: col(r, 'contact_position') || '',
        mobile: col(r, 'contact_mobile') || '', email: col(r, 'contact_email') || ''
      } : null;
      if(existing) updates.push({ id: existing.id, row });
      else{
        if(code) row.code = code;
        inserts.push({ row, contact });
      }
    });
    if(!inserts.length && !updates.length){ toast('Nothing to import' + (skipped.length ? ' — ' + skipped[0] : '')); return; }
    if(!confirm('Import ' + file.name + '?\n\n' +
      inserts.length + ' new supplier' + (inserts.length === 1 ? '' : 's') + '\n' +
      updates.length + ' existing supplier' + (updates.length === 1 ? '' : 's') + ' updated (matched by code, then name)\n' +
      (skipped.length ? skipped.length + ' row' + (skipped.length === 1 ? '' : 's') + ' skipped\n' : '') +
      '\nContacts are only added for new suppliers. Bank details are never imported.')) return;

    const btn = $('spImportBtn'); btn.disabled = true; btn.textContent = 'Importing…';
    let okNew = 0, okUpd = 0; const fails = [];
    try{
      if(inserts.length){
        const { data, error } = await db.from('suppliers').insert(inserts.map(x=> x.row)).select('id, name');
        if(error) throw error;
        okNew = (data || []).length;
        const contactRows = [];
        (data || []).forEach(d=>{
          const src = inserts.find(x=> x.row.name === d.name && x.contact);
          if(src) contactRows.push(Object.assign({ supplier_id: d.id, is_primary: true }, src.contact));
        });
        if(contactRows.length){
          const cr = await db.from('supplier_contacts').insert(contactRows);
          if(cr.error) fails.push('contacts: ' + describeCloudError(cr.error));
        }
      }
      for(const u of updates){
        const { error } = await db.from('suppliers').update(u.row).eq('id', u.id);
        if(error) fails.push(u.row.name + ': ' + describeCloudError(error)); else okUpd++;
      }
      toast('Imported: ' + okNew + ' new, ' + okUpd + ' updated' + (fails.length ? ' — ' + fails.length + ' failed (see console)' : ''));
      if(fails.length) console.error('supplier import failures', fails);
    }catch(e){
      purchFail('Import failed: ', e);
    }finally{
      btn.disabled = false; btn.textContent = 'Import CSV';
      if(await spLoad()) spRenderList();
    }
  });

  // =====================================================================
  // Purchasing — Materials Database (admin only)
  //
  // Tables: materials (catalog), supplier_materials (price list; one row
  // per supplier+material, at most one is_preferred per material),
  // supplier_price_history (written by trigger — read-only here).
  // Materials are never hard-deleted, only deactivated. Removing a
  // supplier price also only deactivates the row, so its history is kept.
  // =====================================================================

  const MT_SCOPES = ['Aircon', 'Ventilation', 'General Scope'];
  const MT_CODE_PREFIX = {
    'Piping':'PIP', 'Refrigerant':'REF', 'Electrical':'ELE', 'Insulation':'INS',
    'Consumables':'CON', 'Parts & Components':'PRT', 'Ducting & Ventilation':'DUC',
    'Plumbing':'PLB', 'Fire Protection':'FPR', 'Hardware':'HDW',
    'Tools & Equipment':'TLS', 'Others':'OTH'
  };
  const MT_PAGE = 150;             // rows rendered before "Show more"
  const MT_SELECT = '*, supplier_materials(id, price, price_unit, price_updated_at, is_preferred, is_active, suppliers(id, code, name, trade_name, is_active))';

  let mtCache = [];
  let mtEditing = null;
  let mtSheetScope = [];
  let mtSpecs = [];                // [{k, v}] while the sheet is open
  let mtShowLimit = MT_PAGE;
  let mtSuppliersLite = [];        // for the supplier picker
  let mtPricesCache = [];

  function mtFromRow(r){
    const specs = r.specs && typeof r.specs === 'object' ? r.specs : {};
    return {
      id: r.id, code: r.code || '', name: r.name || '', family: r.family || '',
      category: r.category || 'Others', scope: Array.isArray(r.scope) ? r.scope : [],
      unit: r.unit || '', packUnit: r.pack_unit || '', packQty: r.pack_qty,
      brand: r.brand || '', specs, standardCost: r.standard_cost,
      isActive: r.is_active !== false, notes: r.notes || '',
      prices: Array.isArray(r.supplier_materials) ? r.supplier_materials : []
    };
  }
  // The price to show on the list: preferred active supplier, else the
  // cheapest active one. Returns null when nothing is priced.
  function mtBestPrice(m){
    const live = m.prices.filter(p=> p.is_active && p.price != null && (!p.suppliers || p.suppliers.is_active !== false));
    if(!live.length) return null;
    return live.find(p=> p.is_preferred) || live.slice().sort((a,b)=> Number(a.price) - Number(b.price))[0];
  }
  function mtSupplierLabel(s){ return s ? (s.trade_name || s.name || '') : ''; }
  function mtSpecText(specs){
    return Object.keys(specs || {}).map(k=> k + ': ' + specs[k]).join(' · ');
  }
  function mtNormCode(v){ return String(v || '').trim().toUpperCase().replace(/\s+/g, '-'); }

  async function mtShow(){
    const cat = $('mtFilterCategory');
    if(cat.options.length <= 1){
      PURCH_CATEGORIES.forEach(c=>{ const o = document.createElement('option'); o.value = c; o.textContent = c; cat.appendChild(o); });
      $('mtCategory').innerHTML = PURCH_CATEGORIES.map(c=> '<option>' + escapeHtml(c) + '</option>').join('');
    }
    mtShowLimit = MT_PAGE;
    if(await mtLoad()) mtRenderList();
  }

  async function mtLoad(opts){
    const silent = !!(opts && opts.silent);
    const list = $('mtList');
    if(!silent) list.innerHTML = '<div class="empty-state">Loading…</div>';
    if(!(await ensureCloud())){
      mtCache = [];
      list.innerHTML = '<div class="empty-state">Not connected to Shared Cloud — the Materials Database needs a connection.</div>';
      return false;
    }
    try{
      const { data, error } = await db.from('materials').select(MT_SELECT).order('code', { ascending:true });
      if(error) throw error;
      mtCache = (data || []).map(mtFromRow);
      mtRefreshDatalists();
      return true;
    }catch(e){
      console.error('load materials failed', describeCloudError(e));
      if(silent) return false;
      mtCache = [];
      const msg = purchIsAuthError(e) ? PURCH_EXPIRED_HTML : /42P01|42703|does not exist/.test(describeCloudError(e))
        ? 'The materials table isn\u2019t ready yet — run migration 20260923_01_purchasing_suppliers_materials.sql in Supabase first.'
        : 'Couldn\u2019t load materials: ' + escapeHtml(describeCloudError(e));
      list.innerHTML = '<div class="empty-state">' + msg + '</div>';
      return false;
    }
  }
  function mtRefreshDatalists(){
    const uniq = (arr)=> Array.from(new Set(arr.filter(Boolean))).sort((a,b)=> a.localeCompare(b));
    $('mtFamilyList').innerHTML = uniq(mtCache.map(m=> m.family)).map(f=> '<option value="' + escapeHtml(f) + '">').join('');
    $('mtBrandList').innerHTML = uniq(mtCache.map(m=> m.brand)).map(f=> '<option value="' + escapeHtml(f) + '">').join('');
  }

  function mtFiltered(){
    const q = ($('mtSearch').value || '').trim().toLowerCase();
    const cat = $('mtFilterCategory').value;
    const scope = $('mtFilterScope').value;
    const showInactive = $('mtShowInactive').checked;
    const words = q.split(/\s+/).filter(Boolean);
    return mtCache.filter(m=>{
      if(!showInactive && !m.isActive) return false;
      if(cat && m.category !== cat) return false;
      if(scope && !m.scope.includes(scope)) return false;
      if(!words.length) return true;
      const hay = [m.code, m.name, m.family, m.brand, m.notes, mtSpecText(m.specs)]
        .concat(m.prices.map(p=> mtSupplierLabel(p.suppliers))).join(' ').toLowerCase();
      return words.every(w=> hay.includes(w));   // every word, any order: "3/8 copper" finds "Copper Tube 3/8"
    });
  }

  function mtRenderList(){
    const list = $('mtList');
    const active = mtCache.filter(m=> m.isActive).length;
    $('mtCount').textContent = mtCache.length ? (active + ' active' + (mtCache.length > active ? ' · ' + (mtCache.length - active) + ' inactive' : '')) : '';
    const rows = mtFiltered();
    if(!rows.length){
      list.innerHTML = '<div class="empty-state">' + (mtCache.length === 0
        ? 'No materials yet. Tap <b>+ Add Material</b>, or use <b>Seed from Service Reports</b> to start from what your technicians already use.'
        : 'No materials match.') + '</div>';
      return;
    }
    // Grouped by category (in the standard category order), then family, then name.
    const order = new Map(PURCH_CATEGORIES.map((c,i)=> [c, i]));
    rows.sort((a,b)=> (order.has(a.category) ? order.get(a.category) : 99) - (order.has(b.category) ? order.get(b.category) : 99)
      || (a.family || a.name).localeCompare(b.family || b.name) || a.name.localeCompare(b.name, undefined, { numeric:true }));
    const shown = rows.slice(0, mtShowLimit);
    const counts = rows.reduce((acc, m)=>{ acc[m.category] = (acc[m.category] || 0) + 1; return acc; }, {});
    let html = '', lastCat = null;
    shown.forEach(m=>{
      if(m.category !== lastCat){
        lastCat = m.category;
        html += '<div class="mt-group-head">' + escapeHtml(m.category) + '<span>' + counts[m.category] + '</span></div>';
      }
      const best = mtBestPrice(m);
      const sub = [m.family && m.family !== m.name ? m.family : '', m.brand, mtSpecText(m.specs),
        m.packUnit && m.packQty ? '1 ' + m.packUnit + ' = ' + m.packQty + ' ' + m.unit : ''].filter(Boolean).join(' · ');
      const tags = m.scope.map(s=> '<span class="sp-tag muted">' + escapeHtml(s) + '</span>').join('') +
        (m.isActive ? '' : '<span class="sp-tag danger">Inactive</span>');
      let priceHtml;
      if(best){
        const age = spDaysSince(best.price_updated_at);
        priceHtml = '<div class="mt-row-price">' + spMoney(best.price) +
          '<div class="sp-row-sub">' + escapeHtml(best.price_unit || 'per ' + m.unit) + '</div>' +
          '<div class="sp-row-sub">' + (best.is_preferred ? '<span class="mt-star">★</span> ' : '') + escapeHtml(mtSupplierLabel(best.suppliers)) + '</div>' +
          (age != null && age > SP_PRICE_STALE_DAYS ? '<span class="sp-tag warn">' + age + 'd old</span>' : '') + '</div>';
      }else if(m.standardCost != null){
        priceHtml = '<div class="mt-row-price none">~' + spMoney(m.standardCost) + '<div class="sp-row-sub">std. cost / ' + escapeHtml(m.unit) + '</div></div>';
      }else{
        priceHtml = '<div class="mt-row-price none">No price</div>';
      }
      html += '<button type="button" class="mt-row' + (m.isActive ? '' : ' inactive') + '" data-id="' + escapeHtml(m.id) + '">' +
        '<div class="mt-row-main"><div class="mt-row-title"><span class="mt-code">' + escapeHtml(m.code) + '</span>' + escapeHtml(m.name) + '</div>' +
        '<div class="sp-row-sub">' + escapeHtml(sub || 'Unit: ' + m.unit) + '</div>' +
        (tags ? '<div class="sp-tags">' + tags + '</div>' : '') + '</div>' + priceHtml + '</button>';
    });
    if(rows.length > shown.length){
      html += '<button type="button" class="btn btn-secondary mt-more" id="mtShowMore">Show ' + Math.min(MT_PAGE, rows.length - shown.length) + ' more (' + (rows.length - shown.length) + ' hidden)</button>';
    }
    list.innerHTML = html;
  }

  const mtResetAndRender = ()=>{ mtShowLimit = MT_PAGE; mtRenderList(); };
  $('mtSearch').addEventListener('input', mtResetAndRender);
  $('mtFilterCategory').addEventListener('change', mtResetAndRender);
  $('mtFilterScope').addEventListener('change', mtResetAndRender);
  $('mtShowInactive').addEventListener('change', mtResetAndRender);
  $('mtAddBtn').addEventListener('click', ()=> mtOpenSheet(null, 'info'));
  $('mtList').addEventListener('click', (e)=>{
    if(e.target.closest('#mtShowMore')){ mtShowLimit += MT_PAGE; mtRenderList(); return; }
    const row = e.target.closest('.mt-row');
    const m = row && mtCache.find(x=> x.id === row.dataset.id);
    if(m) mtOpenSheet(m, 'info');
  });

  // ---------- sheet: details ----------
  function mtRenderScopePick(){
    $('mtScopePick').innerHTML = MT_SCOPES.map(s=>
      '<button type="button" data-scope="' + escapeHtml(s) + '" class="' + (mtSheetScope.includes(s) ? 'on' : '') + '">' + escapeHtml(s) + '</button>').join('');
  }
  $('mtScopePick').addEventListener('click', (e)=>{
    const b = e.target.closest('[data-scope]');
    if(!b) return;
    const s = b.dataset.scope;
    mtSheetScope = mtSheetScope.includes(s) ? mtSheetScope.filter(x=> x !== s) : mtSheetScope.concat(s);
    b.classList.toggle('on');
  });

  function mtRenderSpecs(){
    $('mtSpecsList').innerHTML = mtSpecs.map((sp, i)=>
      '<div class="mt-spec-row" data-i="' + i + '">' +
        '<input type="text" data-f="k" value="' + escapeHtml(sp.k) + '" placeholder="e.g. Size" list="mtSpecKeyList">' +
        '<input type="text" data-f="v" value="' + escapeHtml(sp.v) + '" placeholder=\'e.g. 3/8"\'>' +
        '<button type="button" data-rm="1" title="Remove">&minus;</button></div>').join('') +
      '<datalist id="mtSpecKeyList"><option value="Size"><option value="Gauge"><option value="Thickness"><option value="Length"><option value="Rating"><option value="Voltage"><option value="Capacity"><option value="Refrigerant"><option value="Material"><option value="Color"></datalist>';
  }
  $('mtSpecsList').addEventListener('input', (e)=>{
    const row = e.target.closest('.mt-spec-row');
    if(row && e.target.dataset.f) mtSpecs[Number(row.dataset.i)][e.target.dataset.f] = e.target.value;
  });
  $('mtSpecsList').addEventListener('click', (e)=>{
    if(!e.target.closest('[data-rm]')) return;
    mtSpecs.splice(Number(e.target.closest('.mt-spec-row').dataset.i), 1);
    mtRenderSpecs();
  });
  $('mtAddSpec').addEventListener('click', ()=>{
    mtSpecs.push({ k:'', v:'' });
    mtRenderSpecs();
    const inputs = $('mtSpecsList').querySelectorAll('input[data-f=k]');
    if(inputs.length) inputs[inputs.length - 1].focus();
  });

  function mtUpdatePackPreview(){
    const u = $('mtUnit').value.trim(), pu = $('mtPackUnit').value.trim(), q = $('mtPackQty').value.trim();
    $('mtPackPreview').textContent = (u && pu && q) ? '1 ' + pu + ' = ' + q + ' ' + u : '';
  }
  ['mtUnit','mtPackUnit','mtPackQty'].forEach(id=> $(id).addEventListener('input', mtUpdatePackPreview));

  function mtSuggestCodeFor(category){
    const prefix = MT_CODE_PREFIX[category] || 'MAT';
    const re = new RegExp('^' + prefix + '-(\\d+)$');
    let max = 0;
    mtCache.forEach(m=>{ const mm = m.code.match(re); if(mm) max = Math.max(max, Number(mm[1])); });
    return prefix + '-' + String(max + 1).padStart(3, '0');
  }
  $('mtSuggestCode').addEventListener('click', ()=>{ $('mtCode').value = mtSuggestCodeFor($('mtCategory').value); });
  // New item: keep the suggested code in step with the category until the
  // admin types their own.
  $('mtCategory').addEventListener('change', ()=>{
    if(!mtEditing && (!$('mtCode').value || $('mtCode').dataset.auto === '1')){
      $('mtCode').value = mtSuggestCodeFor($('mtCategory').value);
      $('mtCode').dataset.auto = '1';
    }
  });
  $('mtCode').addEventListener('input', ()=>{ $('mtCode').dataset.auto = ''; });

  // prefill: optional {name, unit, category, ...} for new items (seed / duplicate)
  function mtOpenSheet(m, tab, prefill){
    mtEditing = m;
    $('mtStaleNote').style.display = 'none';
    const src = m || prefill || {};
    $('mtSheetTitle').textContent = m ? m.name : (prefill && prefill.duplicateOf ? 'New size of ' + prefill.duplicateOf : 'Add Material');
    $('mtStatusLine').style.display = m ? '' : 'none';
    $('mtStatusLine').textContent = m ? m.code + (m.isActive ? '' : ' · Inactive') : '';
    $('mtCategory').value = src.category || PURCH_CATEGORIES[0];
    $('mtCode').value = m ? m.code : mtSuggestCodeFor($('mtCategory').value);
    $('mtCode').dataset.auto = m ? '' : '1';
    $('mtName').value = src.name || '';
    $('mtFamily').value = src.family || '';
    $('mtBrand').value = src.brand || '';
    mtSheetScope = (src.scope || []).slice();
    mtRenderScopePick();
    $('mtUnit').value = src.unit || '';
    $('mtPackUnit').value = src.packUnit || '';
    $('mtPackQty').value = src.packQty != null ? String(src.packQty) : '';
    $('mtStdCost').value = src.standardCost != null ? String(src.standardCost) : '';
    mtUpdatePackPreview();
    mtSpecs = Object.keys(src.specs || {}).map(k=> ({ k, v: String(src.specs[k]) }));
    mtRenderSpecs();
    $('mtNotes').value = src.notes || '';
    $('mtSaveBtn').textContent = m ? 'Save Changes' : 'Save Material';
    $('mtSaveBtn').disabled = false;
    $('mtSheetActions').style.display = m ? '' : 'none';
    if(m) $('mtToggleActiveBtn').textContent = m.isActive ? 'Deactivate' : 'Reactivate';
    mtResetPriceForm();
    mtSetTabsEnabled(!!m);
    mtShowTab(m ? tab : 'info');
    $('mtSheetOverlay').classList.add('open');
    if(!m) setTimeout(()=> $(src.name ? 'mtUnit' : 'mtName').focus(), 50);
  }
  function mtSetTabsEnabled(on){
    $$('#mtTabs [data-mt-tab]').forEach(b=>{ if(b.dataset.mtTab !== 'info') b.classList.toggle('sp-seg-disabled', !on); });
  }
  function mtShowTab(tab){
    $$('#mtTabs [data-mt-tab]').forEach(b=> b.classList.toggle('active', b.dataset.mtTab === tab));
    $('mtPaneInfo').style.display = tab === 'info' ? '' : 'none';
    $('mtPanePrices').style.display = tab === 'prices' ? '' : 'none';
    $('mtPaneHistory').style.display = tab === 'history' ? '' : 'none';
    if(!mtEditing) return;
    if(tab === 'prices') mtLoadPrices();
    if(tab === 'history') mtLoadHistory();
  }
  $('mtTabs').addEventListener('click', (e)=>{
    const b = e.target.closest('[data-mt-tab]');
    if(b && !b.classList.contains('sp-seg-disabled')) mtShowTab(b.dataset.mtTab);
  });
  $('mtSheetClose').addEventListener('click', async ()=>{
    $('mtSheetOverlay').classList.remove('open');
    mtEditing = null;
    if(await mtLoad()) mtRenderList();
    if($('mtSeedOverlay').classList.contains('open')) mtSeedRender();
  });

  function mtGatherRow(){
    const num = (id)=> spParseMoney($(id).value);
    const specs = {};
    mtSpecs.forEach(sp=>{ const k = sp.k.trim(), v = sp.v.trim(); if(k && v) specs[k] = v; });
    return {
      code: mtNormCode($('mtCode').value), name: $('mtName').value.trim(),
      family: $('mtFamily').value.trim(), category: $('mtCategory').value,
      scope: mtSheetScope.slice(), unit: $('mtUnit').value.trim(),
      pack_unit: $('mtPackUnit').value.trim() || null, pack_qty: num('mtPackQty'),
      brand: $('mtBrand').value.trim(), specs, standard_cost: num('mtStdCost'),
      notes: $('mtNotes').value.trim()
    };
  }

  $('mtSaveBtn').addEventListener('click', async ()=>{
    const row = mtGatherRow();
    if(!row.code){ toast('Code is required'); $('mtCode').focus(); return; }
    if(!/^[A-Z0-9][A-Z0-9._\-/]*$/.test(row.code)){ toast('Code: letters, numbers, - . / only'); $('mtCode').focus(); return; }
    if(!row.name){ toast('Item name is required'); $('mtName').focus(); return; }
    if(!row.unit){ toast('Issue unit is required (e.g. ft, pc, kg)'); $('mtUnit').focus(); return; }
    if(Number.isNaN(row.pack_qty) || row.pack_qty === 0){ toast('Qty per purchase unit must be a positive number'); $('mtPackQty').focus(); return; }
    if(Number.isNaN(row.standard_cost)){ toast('Standard cost must be a number'); $('mtStdCost').focus(); return; }
    if(row.pack_qty != null && !row.pack_unit){ toast('Enter the purchase unit for that quantity (e.g. roll)'); $('mtPackUnit').focus(); return; }
    const clash = mtCache.find(x=> x.code === row.code && (!mtEditing || x.id !== mtEditing.id));
    if(clash){ toast('Code ' + row.code + ' is already used by ' + clash.name); $('mtCode').focus(); return; }
    const twin = mtCache.find(x=> x.name.trim().toLowerCase() === row.name.toLowerCase() && (!mtEditing || x.id !== mtEditing.id));
    if(twin && !confirm('"' + twin.name + '" already exists as ' + twin.code + '. Save another item with the same name?')) return;
    if(!(await ensureCloud())){ toast('Not connected — can\u2019t save'); return; }
    if(!(await purchEnsureSession())) return;
    const btn = $('mtSaveBtn'); btn.disabled = true;
    try{
      const res = mtEditing
        ? await db.from('materials').update(row).eq('id', mtEditing.id).select(MT_SELECT).single()
        : await db.from('materials').insert(row).select(MT_SELECT).single();
      if(res.error) throw res.error;
      const saved = mtFromRow(res.data);
      purchMarkOwn(saved.id);
      const wasNew = !mtEditing;
      const i = mtCache.findIndex(x=> x.id === saved.id);
      if(i >= 0) mtCache[i] = saved; else mtCache.push(saved);
      mtEditing = saved;
      mtRefreshDatalists();
      mtRenderList();
      $('mtSheetTitle').textContent = saved.name;
      $('mtStatusLine').style.display = ''; $('mtStatusLine').textContent = saved.code + (saved.isActive ? '' : ' · Inactive');
      btn.textContent = 'Save Changes';
      $('mtSheetActions').style.display = '';
      $('mtToggleActiveBtn').textContent = saved.isActive ? 'Deactivate' : 'Reactivate';
      mtSetTabsEnabled(true);
      toast(wasNew ? saved.code + ' saved — add supplier prices next' : 'Material updated');
      if(wasNew) mtShowTab('prices');
    }catch(e){
      const msg = describeCloudError(e);
      if(purchIsAuthError(e)){ purchReauth(); return; }
      toast(/23505/.test(msg) ? 'That code is already in use' : 'Couldn\u2019t save material: ' + msg);
    }finally{ btn.disabled = false; }
  });

  $('mtDuplicateBtn').addEventListener('click', ()=>{
    if(!mtEditing) return;
    const m = mtEditing;
    // New size of the same thing: keep category/family/unit/scope/brand, and
    // the spec *names* (Size, Gauge…) with their values cleared.
    const specs = {};
    Object.keys(m.specs || {}).forEach(k=>{ specs[k] = ''; });
    mtOpenSheet(null, 'info', {
      duplicateOf: m.name, category: m.category, family: m.family || m.name, brand: m.brand,
      scope: m.scope, unit: m.unit, packUnit: m.packUnit, packQty: m.packQty, specs, name: m.family || ''
    });
    mtSpecs = Object.keys(specs).map(k=> ({ k, v:'' }));
    mtRenderSpecs();
    $('mtName').focus();
  });

  $('mtToggleActiveBtn').addEventListener('click', async ()=>{
    const m = mtEditing;
    if(!m) return;
    const on = !m.isActive;
    if(!on && !confirm('Deactivate ' + m.code + ' ' + m.name + '? Technicians won\u2019t be able to pick it; existing records keep it.')) return;
    if(!(await purchEnsureSession())) return;
    const btn = $('mtToggleActiveBtn'); btn.disabled = true;
    try{
      purchMarkOwn(m.id);
      const { error } = await db.from('materials').update({ is_active:on }).eq('id', m.id);
      if(error) throw error;
      m.isActive = on;
      btn.textContent = on ? 'Deactivate' : 'Reactivate';
      $('mtStatusLine').textContent = m.code + (on ? '' : ' · Inactive');
      mtRenderList();
      toast(m.code + (on ? ' reactivated' : ' deactivated'));
    }catch(e){ purchFail('Couldn\u2019t update: ', e); }
    finally{ btn.disabled = false; }
  });

  // ---------- sheet: supplier prices ----------
  async function mtLoadSuppliersLite(){
    const { data, error } = await db.from('suppliers').select('id, code, name, trade_name, is_active').order('name');
    if(error) throw error;
    mtSuppliersLite = data || [];
  }
  function mtFillSupplierSelect(keepId){
    const taken = new Set(mtPricesCache.filter(p=> p.is_active).map(p=> p.supplier_id));
    const opts = mtSuppliersLite
      .filter(s=> s.id === keepId || (s.is_active && !taken.has(s.id)))
      .map(s=> '<option value="' + escapeHtml(s.id) + '">' + escapeHtml(mtSupplierLabel(s)) + ' (' + escapeHtml(s.code) + ')</option>');
    $('mtPriceSupplier').innerHTML = opts.length
      ? '<option value="">Choose a supplier…</option>' + opts.join('')
      : '<option value="">' + (mtSuppliersLite.length ? 'Every active supplier already has a price here' : 'No suppliers yet — add them in Supplier Database') + '</option>';
    if(keepId) $('mtPriceSupplier').value = keepId;
    // Nothing left to add (and not editing an existing price): show a note
    // instead of an empty form.
    const nothingToAdd = !opts.length && !keepId;
    $('mtPriceForm').style.display = nothingToAdd ? 'none' : '';
    $('mtPriceAllDone').style.display = nothingToAdd && mtSuppliersLite.length ? '' : 'none';
    if(nothingToAdd && !mtSuppliersLite.length) $('mtPriceForm').style.display = '';
  }
  function mtResetPriceForm(){
    $('mtPriceId').value = '';
    ['mtPriceAmount','mtPriceItemCode','mtPriceMoq','mtPriceLead'].forEach(id=> $(id).value = '');
    $('mtPriceUnit').value = mtEditing && mtEditing.unit ? mtEditing.unit : '';
    $('mtPriceDate').value = new Date().toISOString().slice(0,10);
    $('mtPricePreferred').checked = false;
    $('mtPriceSupplier').disabled = false;
    $('mtPriceFormTitle').textContent = 'Add a supplier price';
    $('mtPriceCancelBtn').style.display = 'none';
  }
  // opts.silent: no "Loading…" flash. opts.keepForm: a background refresh —
  // leave whatever the admin is typing in the price form alone.
  async function mtLoadPrices(opts){
    const silent = !!(opts && opts.silent), keepForm = !!(opts && opts.keepForm);
    const list = $('mtPricesList');
    if(!silent) list.innerHTML = '<div class="empty-state">Loading…</div>';
    try{
      const [pr] = await Promise.all([
        db.from('supplier_materials').select('*, suppliers(id, code, name, trade_name, is_active)').eq('material_id', mtEditing.id),
        mtLoadSuppliersLite()
      ]);
      if(pr.error) throw pr.error;
      mtPricesCache = (pr.data || []).sort((a,b)=> (b.is_active - a.is_active) || (b.is_preferred - a.is_preferred) || (Number(a.price) - Number(b.price)));
      if(keepForm){
        const editingId = $('mtPriceId').value;
        const chosen = $('mtPriceSupplier').value;
        const editing = editingId && mtPricesCache.find(p=> p.id === editingId);
        mtFillSupplierSelect(editing ? editing.supplier_id : undefined);
        if(editing) $('mtPriceSupplier').disabled = true;
        else if(chosen && Array.from($('mtPriceSupplier').options).some(o=> o.value === chosen)) $('mtPriceSupplier').value = chosen;
      }else{
        mtResetPriceForm();
        mtFillSupplierSelect();
      }
      const live = mtPricesCache.filter(p=> p.is_active);
      if(!live.length){
        list.innerHTML = '<div class="empty-state" style="padding:16px;">No supplier prices yet. Add the first one below.</div>';
      }else{
        const cheapest = Math.min.apply(null, live.filter(p=> p.price != null).map(p=> Number(p.price)));
        list.innerHTML = live.map(p=>{
          const age = spDaysSince(p.price_updated_at);
          const meta = [p.supplier_item_code ? 'Their code ' + escapeHtml(p.supplier_item_code) : '',
            p.min_order_qty != null ? 'MOQ ' + escapeHtml(String(p.min_order_qty)) : '',
            p.lead_time_days != null ? escapeHtml(String(p.lead_time_days)) + 'd lead time' : '',
            p.price_updated_at ? 'priced ' + escapeHtml(p.price_updated_at) : ''].filter(Boolean).join(' · ');
          return '<div class="sp-row" data-id="' + escapeHtml(p.id) + '"><div class="sp-row-top"><div style="min-width:0;">' +
              '<div class="sp-row-title">' + (p.is_preferred ? '<span class="mt-star">★</span> ' : '') + escapeHtml(mtSupplierLabel(p.suppliers)) +
                (p.suppliers && p.suppliers.is_active === false ? ' <span class="sp-tag danger">Supplier inactive</span>' : '') +
                (live.length > 1 && Number(p.price) === cheapest ? ' <span class="sp-tag">Lowest</span>' : '') +
                (age != null && age > SP_PRICE_STALE_DAYS ? ' <span class="sp-tag warn">' + age + 'd old</span>' : '') + '</div>' +
              '<div class="sp-row-sub">' + (meta || '&nbsp;') + '</div></div>' +
            '<div class="mt-row-price">' + spMoney(p.price) + '<div class="sp-row-sub">' + escapeHtml(p.price_unit || 'per ' + mtEditing.unit) + '</div></div></div>' +
            '<div class="user-card-actions">' +
              '<button type="button" data-pact="edit" class="primary">Update price</button>' +
              (p.is_preferred ? '<button type="button" data-pact="unpref">Unset preferred</button>' : '<button type="button" data-pact="pref">Make preferred</button>') +
              '<button type="button" data-pact="remove" class="danger">Remove</button>' +
            '</div></div>';
        }).join('');
      }
    }catch(e){
      list.innerHTML = '<div class="empty-state">Couldn\u2019t load prices: ' + escapeHtml(describeCloudError(e)) + '</div>';
    }
  }
  // Unique "one preferred per material" index → clear the old one first.
  async function mtClearPreferred(exceptId){
    let q = db.from('supplier_materials').update({ is_preferred:false }).eq('material_id', mtEditing.id).eq('is_preferred', true);
    if(exceptId) q = q.neq('id', exceptId);
    const { error } = await q;
    if(error) throw error;
  }
  $('mtPricesList').addEventListener('click', async (e)=>{
    const b = e.target.closest('[data-pact]');
    if(!b) return;
    const p = mtPricesCache.find(x=> x.id === b.closest('.sp-row').dataset.id);
    if(!p) return;
    const act = b.dataset.pact;
    if(act === 'edit'){
      mtFillSupplierSelect(p.supplier_id);
      $('mtPriceSupplier').disabled = true;
      $('mtPriceId').value = p.id;
      $('mtPriceAmount').value = p.price != null ? String(p.price) : '';
      $('mtPriceUnit').value = p.price_unit || mtEditing.unit;
      $('mtPriceDate').value = new Date().toISOString().slice(0,10);   // updating = re-quoted today
      $('mtPriceItemCode').value = p.supplier_item_code || '';
      $('mtPriceMoq').value = p.min_order_qty != null ? String(p.min_order_qty) : '';
      $('mtPriceLead').value = p.lead_time_days != null ? String(p.lead_time_days) : '';
      $('mtPricePreferred').checked = !!p.is_preferred;
      $('mtPriceFormTitle').textContent = 'Update price — ' + mtSupplierLabel(p.suppliers);
      $('mtPriceCancelBtn').style.display = '';
      $('mtPriceAmount').focus();
      return;
    }
    if(!(await purchEnsureSession())) return;
    b.disabled = true;
    try{
      if(act === 'pref'){
        await mtClearPreferred(p.id);
        const { error } = await db.from('supplier_materials').update({ is_preferred:true }).eq('id', p.id);
        if(error) throw error;
        toast(mtSupplierLabel(p.suppliers) + ' is now preferred');
      }else if(act === 'unpref'){
        const { error } = await db.from('supplier_materials').update({ is_preferred:false }).eq('id', p.id);
        if(error) throw error;
      }else if(act === 'remove'){
        if(!confirm('Remove ' + mtSupplierLabel(p.suppliers) + '\u2019s price for this item? Its price history is kept.')){ b.disabled = false; return; }
        const { error } = await db.from('supplier_materials').update({ is_active:false, is_preferred:false }).eq('id', p.id);
        if(error) throw error;
        toast('Price removed');
      }
      mtLoadPrices();
    }catch(err){
      b.disabled = false;
      purchFail('Couldn\u2019t update price: ', err);
    }
  });
  $('mtPriceCancelBtn').addEventListener('click', ()=>{ mtResetPriceForm(); mtFillSupplierSelect(); });
  $('mtPriceSaveBtn').addEventListener('click', async ()=>{
    if(!mtEditing) return;
    const id = $('mtPriceId').value;
    const supplierId = $('mtPriceSupplier').value;
    if(!supplierId){ toast('Choose a supplier'); return; }
    const price = spParseMoney($('mtPriceAmount').value);
    if(price == null || Number.isNaN(price)){ toast('Enter a valid price'); $('mtPriceAmount').focus(); return; }
    const moq = spParseMoney($('mtPriceMoq').value);
    const leadRaw = $('mtPriceLead').value.trim();
    const lead = leadRaw === '' ? null : parseInt(leadRaw, 10);
    if(Number.isNaN(moq) || moq === 0){ toast('Min. order qty must be a positive number'); return; }
    if(leadRaw !== '' && (Number.isNaN(lead) || lead < 0)){ toast('Lead time must be whole days'); return; }
    const preferred = $('mtPricePreferred').checked;
    const unitTxt = $('mtPriceUnit').value.trim();
    const row = {
      price, price_unit: unitTxt ? (/^per\s/i.test(unitTxt) ? unitTxt : 'per ' + unitTxt) : null,
      price_updated_at: $('mtPriceDate').value || new Date().toISOString().slice(0,10),
      supplier_item_code: $('mtPriceItemCode').value.trim(), min_order_qty: moq,
      lead_time_days: lead, is_preferred: preferred, is_active: true
    };
    if(!(await purchEnsureSession())) return;
    const btn = $('mtPriceSaveBtn'); btn.disabled = true;
    try{
      if(preferred) await mtClearPreferred(id || null);
      // A supplier removed earlier still has its (inactive) row — the
      // supplier+material pair is unique — so revive it instead of inserting.
      const existing = id ? { id } : mtPricesCache.find(p=> p.supplier_id === supplierId);
      const res = existing
        ? await db.from('supplier_materials').update(row).eq('id', existing.id)
        : await db.from('supplier_materials').insert(Object.assign({ supplier_id: supplierId, material_id: mtEditing.id }, row));
      if(res.error) throw res.error;
      toast(id ? 'Price updated' : 'Price added');
      mtLoadPrices();
    }catch(e){
      purchFail('Couldn\u2019t save price: ', e);
    }finally{ btn.disabled = false; }
  });

  // ---------- sheet: price history ----------
  async function mtLoadHistory(opts){
    const list = $('mtHistoryList');
    if(!(opts && opts.silent)) list.innerHTML = '<div class="empty-state">Loading…</div>';
    try{
      const sm = await db.from('supplier_materials').select('id, suppliers(code, name, trade_name)').eq('material_id', mtEditing.id);
      if(sm.error) throw sm.error;
      const ids = (sm.data || []).map(r=> r.id);
      if(!ids.length){ list.innerHTML = '<div class="empty-state" style="padding:16px;">No price changes recorded yet.</div>'; return; }
      const names = new Map((sm.data || []).map(r=> [r.id, mtSupplierLabel(r.suppliers)]));
      const { data, error } = await db.from('supplier_price_history').select('*')
        .in('supplier_material_id', ids).order('changed_at', { ascending:false }).limit(200);
      if(error) throw error;
      const rows = data || [];
      if(!rows.length){ list.innerHTML = '<div class="empty-state" style="padding:16px;">No price changes recorded yet.</div>'; return; }
      // change vs. the previous entry for the same supplier
      const prevBySupplier = {};
      const withDelta = rows.slice().reverse().map(r=>{
        const prev = prevBySupplier[r.supplier_material_id];
        prevBySupplier[r.supplier_material_id] = r;
        return Object.assign({ delta: prev && prev.price != null && r.price != null ? Number(r.price) - Number(prev.price) : null, first: !prev }, r);
      }).reverse();
      list.innerHTML = '<p style="font-size:12px; color:var(--text-muted); margin-top:0;">Every price change is logged automatically. Newest first.</p>' +
        '<div class="sp-table-wrap"><table class="sp-table"><thead><tr><th>Date</th><th>Supplier</th><th class="num">Price</th><th class="num">Change</th></tr></thead><tbody>' +
        withDelta.map(r=>{
          const d = r.delta;
          const chg = r.first ? '<span class="sp-tag muted">first</span>'
            : d == null || d === 0 ? '—'
            : '<span style="color:' + (d > 0 ? 'var(--danger)' : 'var(--green-dark)') + '; font-weight:700;">' + (d > 0 ? '+' : '−') + spMoney(Math.abs(d)).replace('₱', '₱') + '</span>';
          return '<tr><td>' + escapeHtml(String(r.changed_at || '').slice(0,10)) + '</td><td>' + escapeHtml(names.get(r.supplier_material_id) || '—') + '</td>' +
            '<td class="num">' + spMoney(r.price) + '<div class="sp-row-sub">' + escapeHtml(r.price_unit || '') + '</div></td><td class="num">' + chg + '</td></tr>';
        }).join('') + '</tbody></table></div>';
    }catch(e){
      list.innerHTML = '<div class="empty-state">Couldn\u2019t load price history: ' + escapeHtml(describeCloudError(e)) + '</div>';
    }
  }

  // ---------- seed from Service Reports ----------
  let mtSeedItems = [];   // [{name, unit, count}]
  function mtNormName(s){ return String(s || '').trim().replace(/\s+/g, ' ').toLowerCase(); }
  $('mtSeedBtn').addEventListener('click', async ()=>{
    $('mtSeedOverlay').classList.add('open');
    $('mtSeedSearch').value = '';
    const list = $('mtSeedList');
    list.innerHTML = '<div class="empty-state">Reading Service Reports…</div>';
    if(!(await ensureCloud())){ list.innerHTML = '<div class="empty-state">Not connected.</div>'; return; }
    try{
      const agg = new Map();
      const PAGE = 1000;
      for(let from = 0; from < 20000; from += PAGE){
        const { data, error } = await db.from('service_reports').select('materials').range(from, from + PAGE - 1);
        if(error) throw error;
        (data || []).forEach(r=> (Array.isArray(r.materials) ? r.materials : []).forEach(it=>{
          const raw = String((it && (it.description || it.details)) || '').trim().replace(/\s+/g, ' ');
          if(!raw) return;
          const key = raw.toLowerCase();
          const e = agg.get(key) || { name: raw, units: {}, count: 0 };
          e.count++;
          const u = String((it && it.unit) || '').trim();
          if(u) e.units[u] = (e.units[u] || 0) + 1;
          agg.set(key, e);
        }));
        if(!data || data.length < PAGE) break;
      }
      mtSeedItems = Array.from(agg.values()).map(e=>({
        name: e.name, count: e.count,
        unit: Object.keys(e.units).sort((a,b)=> e.units[b] - e.units[a])[0] || ''
      })).sort((a,b)=> b.count - a.count || a.name.localeCompare(b.name));
      mtSeedRender();
    }catch(e){
      list.innerHTML = '<div class="empty-state">Couldn\u2019t read Service Reports: ' + escapeHtml(describeCloudError(e)) + '</div>';
    }
  });
  function mtSeedRender(){
    const known = new Set(mtCache.map(m=> mtNormName(m.name)));
    const q = mtNormName($('mtSeedSearch').value);
    const items = mtSeedItems.filter(it=> !known.has(mtNormName(it.name)) && (!q || mtNormName(it.name).includes(q)));
    const list = $('mtSeedList');
    if(!mtSeedItems.length){ list.innerHTML = '<div class="empty-state">No materials found on any Service Report yet.</div>'; return; }
    if(!items.length){ list.innerHTML = '<div class="empty-state">' + (q ? 'No matches.' : 'Everything from your Service Reports is already in the catalog. 🎉') + '</div>'; return; }
    list.innerHTML = items.slice(0, 300).map(it=>
      '<div class="mt-seed-row" data-name="' + escapeHtml(it.name) + '" data-unit="' + escapeHtml(it.unit) + '">' +
        '<div class="mt-seed-main">' + escapeHtml(it.name) + (it.unit ? ' <span class="sp-tag muted">' + escapeHtml(it.unit) + '</span>' : '') + '</div>' +
        '<div class="mt-seed-count">used ' + it.count + '×</div>' +
        '<button type="button">Add</button></div>').join('') +
      (items.length > 300 ? '<div class="empty-state">Showing the 300 most used — filter to find others.</div>' : '');
  }
  $('mtSeedSearch').addEventListener('input', mtSeedRender);
  $('mtSeedList').addEventListener('click', (e)=>{
    const b = e.target.closest('button');
    if(!b) return;
    const row = b.closest('.mt-seed-row');
    // Clean up the typed name a little: Title Case words that were typed all
    // lower-case, keep sizes/codes (3/8", R32, AWG) untouched.
    const name = row.dataset.name.replace(/\b([a-z])([a-z]{2,})\b/g, (m, a, rest)=> a.toUpperCase() + rest);
    mtOpenSheet(null, 'info', { name, unit: row.dataset.unit });
  });
  $('mtSeedClose').addEventListener('click', ()=> $('mtSeedOverlay').classList.remove('open'));

  // ---------- CSV import / export ----------
  const MT_CSV_COLS = ['code','name','family','category','scope','unit','pack_unit','pack_qty','brand','specs','standard_cost','notes','is_active'];
  // specs travel as "Size=3/8""; Gauge=22"
  function mtSpecsToCsv(specs){ return Object.keys(specs || {}).map(k=> k + '=' + specs[k]).join('; '); }
  function mtSpecsFromCsv(txt){
    const o = {};
    String(txt || '').split(';').forEach(part=>{
      const i = part.indexOf('=');
      if(i > 0){ const k = part.slice(0, i).trim(), v = part.slice(i + 1).trim(); if(k && v) o[k] = v; }
    });
    return o;
  }
  $('mtExportBtn').addEventListener('click', ()=>{
    const rows = mtFiltered();
    const lines = [MT_CSV_COLS.join(',')].concat(rows.map(m=> [
      m.code, m.name, m.family, m.category, m.scope.join('; '), m.unit, m.packUnit, m.packQty == null ? '' : m.packQty,
      m.brand, mtSpecsToCsv(m.specs), m.standardCost == null ? '' : m.standardCost, m.notes, m.isActive ? 'yes' : 'no'
    ].map(spCsvCell).join(',')));
    const blob = new Blob(['\uFEFF' + lines.join('\r\n')], { type:'text/csv;charset=utf-8' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'materials-' + new Date().toISOString().slice(0,10) + '.csv';
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(()=> URL.revokeObjectURL(a.href), 2000);
    toast(rows.length ? 'Exported ' + rows.length + ' item' + (rows.length === 1 ? '' : 's') : 'Exported a blank template');
  });
  $('mtImportBtn').addEventListener('click', ()=>{ $('mtImportFile').value = ''; $('mtImportFile').click(); });
  $('mtImportFile').addEventListener('change', async ()=>{
    const file = $('mtImportFile').files && $('mtImportFile').files[0];
    if(!file) return;
    if(!(await ensureCloud())){ toast('Not connected — can\u2019t import'); return; }
    if(!(await purchEnsureSession())) return;
    let rows;
    try{ rows = spParseCsv(await file.text()); }catch(e){ toast('Couldn\u2019t read that file'); return; }
    if(rows.length < 2){ toast('The CSV has no data rows'); return; }
    const head = rows[0].map(h=> h.trim().toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, ''));
    const missing = ['name','unit'].filter(k=> !head.includes(k));
    if(missing.length){ toast('CSV needs columns: ' + missing.join(', ')); return; }
    const col = (r, k)=>{ const i = head.indexOf(k); return i < 0 ? undefined : (r[i] || '').trim(); };
    const has = (k)=> head.includes(k);
    const catLookup = new Map(PURCH_CATEGORIES.map(c=> [c.toLowerCase(), c]));
    const scopeLookup = new Map(MT_SCOPES.map(s=> [s.toLowerCase(), s]));
    const byCode = new Map(mtCache.map(m=> [m.code, m]));
    const usedCodes = new Set(mtCache.map(m=> m.code));
    const nextCode = (cat)=>{   // auto-code rows without one, avoiding clashes within this file too
      const prefix = MT_CODE_PREFIX[cat] || 'MAT';
      let n = 1; const re = new RegExp('^' + prefix + '-(\\d+)$');
      usedCodes.forEach(c=>{ const mm = c.match(re); if(mm) n = Math.max(n, Number(mm[1]) + 1); });
      const code = prefix + '-' + String(n).padStart(3, '0'); usedCodes.add(code); return code;
    };
    const inserts = [], updates = [], skipped = [];
    rows.slice(1).forEach((r, idx)=>{
      const line = 'row ' + (idx + 2);
      const name = col(r, 'name'), unit = col(r, 'unit');
      if(!name || !unit){ skipped.push(line + ': needs name and unit'); return; }
      const category = has('category') ? (catLookup.get((col(r, 'category') || '').toLowerCase()) || 'Others') : 'Others';
      const row = { name, unit, category };
      ['family','brand','notes'].forEach(k=>{ if(has(k)) row[k] = col(r, k); });
      if(has('pack_unit')) row.pack_unit = col(r, 'pack_unit') || null;
      if(has('scope')) row.scope = col(r, 'scope').split(/[;|,]/).map(x=> scopeLookup.get(x.trim().toLowerCase())).filter(Boolean);
      if(has('specs')) row.specs = mtSpecsFromCsv(col(r, 'specs'));
      if(has('is_active') && col(r, 'is_active') !== '') row.is_active = spCsvBool(col(r, 'is_active')) !== false;
      for(const k of ['pack_qty', 'standard_cost']){
        if(!has(k)) continue;
        const n = spParseMoney(col(r, k));
        if(Number.isNaN(n) || (k === 'pack_qty' && n === 0)){ skipped.push(line + ': bad ' + k); return; }
        row[k] = n;
      }
      const code = has('code') ? mtNormCode(col(r, 'code')) : '';
      if(code && byCode.has(code)) updates.push({ id: byCode.get(code).id, row });
      else{ row.code = code || nextCode(category); usedCodes.add(row.code); inserts.push(row); }
    });
    if(!inserts.length && !updates.length){ toast('Nothing to import' + (skipped.length ? ' — ' + skipped[0] : '')); return; }
    if(!confirm('Import ' + file.name + '?\n\n' +
      inserts.length + ' new item' + (inserts.length === 1 ? '' : 's') + ' (rows without a code get one automatically)\n' +
      updates.length + ' existing item' + (updates.length === 1 ? '' : 's') + ' updated (matched by code)\n' +
      (skipped.length ? skipped.length + ' row' + (skipped.length === 1 ? '' : 's') + ' skipped — ' + skipped.slice(0, 3).join('; ') + '\n' : '') +
      '\nSupplier prices aren\u2019t part of this file.')) return;
    const btn = $('mtImportBtn'); btn.disabled = true; btn.textContent = 'Importing…';
    let okNew = 0, okUpd = 0; const fails = [];
    try{
      for(let i = 0; i < inserts.length; i += 200){
        const { data, error } = await db.from('materials').insert(inserts.slice(i, i + 200)).select('id');
        if(error) throw error;
        okNew += (data || []).length;
      }
      for(const u of updates){
        const { error } = await db.from('materials').update(u.row).eq('id', u.id);
        if(error) fails.push(u.row.name + ': ' + describeCloudError(error)); else okUpd++;
      }
      toast('Imported: ' + okNew + ' new, ' + okUpd + ' updated' + (fails.length ? ' — ' + fails.length + ' failed (see console)' : ''));
      if(fails.length) console.error('material import failures', fails);
    }catch(e){
      const msg = describeCloudError(e);
      if(purchIsAuthError(e)){ purchReauth(); return; }
      toast(/23505/.test(msg) ? 'Import stopped: a code in the file is already used' : 'Import failed: ' + msg);
    }finally{
      btn.disabled = false; btn.textContent = 'Import CSV';
      if(await mtLoad()) mtRenderList();
    }
  });


  // =====================================================================
  // Purchasing — live updates (Supabase Realtime)
  //
  // One channel for all purchasing tables (published by migration
  // 20260923_02_purchasing_realtime.sql). Any insert/update/delete —
  // from this device or another admin's — queues a short-debounced,
  // silent refresh of just the parts that are on screen:
  //   * the Supplier / Materials lists (expanded cards stay expanded)
  //   * an open sheet's Contacts / Documents / Prices / History tab
  //   * the supplier picker in "Add a supplier price" (without wiping what's
  //     being typed)
  // Forms are never overwritten. If the supplier/material open in a sheet is
  // changed elsewhere, a notice offers to reload it instead.
  // Missed events (socket dropped, phone asleep) are covered by a refresh
  // when the app regains focus or the connection comes back.
  // =====================================================================
  const PURCH_RT_TABLES = ['suppliers', 'supplier_contacts', 'supplier_documents', 'materials', 'supplier_materials',
    'purchase_orders', 'purchase_order_items', 'po_signatories', 'po_settings',
    'material_requisitions', 'material_requisition_items',
    'warehouses', 'warehouse_storekeepers', 'projects', 'project_job_orders', 'stock_balances', 'stock_movements',
    'stock_receipts', 'issue_slips', 'return_slips', 'stock_transfers'];
  let purchChannel = null;
  let purchPending = new Set();
  let purchPendingIds = new Set();
  let purchTimer = null;
  const purchOwn = new Map();      // id -> time of our own write

  function purchMarkOwn(id){ if(id) purchOwn.set(id, Date.now()); }
  function purchIsOwn(id){ const t = purchOwn.get(id); return !!t && Date.now() - t < 5000; }
  function purchVisible(panel){
    return $('purchasingView').style.display !== 'none' && $('purchPanel_' + panel).style.display !== 'none';
  }
  function purchSheetTab(prefix){   // active tab of an open sheet, else null
    if(!$(prefix + 'SheetOverlay').classList.contains('open')) return null;
    const b = document.querySelector('#' + prefix + 'Tabs .seg-tab.active');
    return b ? (b.dataset.spTab || b.dataset.mtTab) : null;
  }
  function purchSetLive(state){
    $$('.purch-live').forEach(el=>{
      el.className = 'purch-live ' + state;
      el.textContent = state === 'on' ? 'Live' : state === 'off' ? 'Offline' : 'Connecting…';
      el.title = state === 'on' ? 'Updates appear automatically'
        : state === 'off' ? 'Live updates paused — will refresh when the connection is back' : '';
    });
  }

  function purchRealtimeStart(){
    if(purchChannel || !db || typeof db.channel !== 'function') return;
    purchSetLive('connecting');
    let ch = db.channel('purchasing-admin-' + (currentUser && currentUser.id || 'x'));
    PURCH_RT_TABLES.forEach(t=>{
      ch = ch.on('postgres_changes', { event:'*', schema:'public', table:t }, (payload)=> purchQueue(t, payload));
    });
    purchChannel = ch.subscribe((status)=>{
      if(status === 'SUBSCRIBED'){
        // (Re)connected: catch up on anything missed while we were down.
        const wasOff = document.querySelector('.purch-live.off');
        purchSetLive('on');
        if(wasOff) purchQueueAll();
      }else if(status === 'CHANNEL_ERROR' || status === 'TIMED_OUT' || status === 'CLOSED'){
        purchSetLive('off');
      }
    });
  }
  function purchRealtimeTeardown(){
    clearTimeout(purchTimer); purchTimer = null;
    purchPending.clear(); purchPendingIds.clear();
    if(purchChannel && db){ try{ db.removeChannel(purchChannel); }catch(e){} }
    purchChannel = null;
  }

  function purchQueue(table, payload){
    purchPending.add(table);
    const row = payload && (payload.new && payload.new.id ? payload.new : payload.old);
    if(row && row.id && (table === 'suppliers' || table === 'materials') && !purchIsOwn(row.id)){
      purchPendingIds.add(table + ':' + row.id);
    }
    // A PO changed elsewhere: header events carry the PO id, item events its po_id.
    const poId = row && (table === 'purchase_orders' ? row.id : table === 'purchase_order_items' ? row.po_id : null);
    if(poId && !purchIsOwn(poId)) purchPendingIds.add('po:' + poId);
    const mrId = row && (table === 'material_requisitions' ? row.id : table === 'material_requisition_items' ? row.mr_id : null);
    if(mrId && !purchIsOwn(mrId)) purchPendingIds.add('mr:' + mrId);
    clearTimeout(purchTimer);
    // Debounced: a CSV import fires hundreds of events — refresh once.
    purchTimer = setTimeout(purchApply, 400);
  }
  function purchQueueAll(){ PURCH_RT_TABLES.forEach(t=> purchPending.add(t)); clearTimeout(purchTimer); purchTimer = setTimeout(purchApply, 50); }

  async function purchApply(){
    const t = purchPending; purchPending = new Set();
    const ids = purchPendingIds; purchPendingIds = new Set();
    if(!currentUser || currentUser.role !== 'admin') return;
    const has = (...names)=> names.some(n=> t.has(n));
    const jobs = [];

    // Supplier Database
    if(has('suppliers', 'supplier_contacts') && purchVisible('suppliers')){
      jobs.push(spLoad({ silent:true }).then(ok=>{ if(ok) spRenderList(); }));
    }
    const spTab = purchSheetTab('sp');
    if(spTab && spEditing){
      if(spTab === 'contacts' && has('supplier_contacts')) jobs.push(spLoadContacts({ silent:true }));
      if(spTab === 'docs' && has('supplier_documents')) jobs.push(spLoadDocs({ silent:true }));
      if(spTab === 'prices' && has('supplier_materials', 'materials')) jobs.push(spLoadPrices({ silent:true }));
      if(ids.has('suppliers:' + spEditing.id)) $('spStaleNote').style.display = '';
    }

    // Materials Database (its rows also show supplier names, so supplier
    // renames/deactivations refresh it too)
    if(has('materials', 'supplier_materials', 'suppliers') && purchVisible('materials')){
      jobs.push(mtLoad({ silent:true }).then(ok=>{
        if(!ok) return;
        mtRenderList();
        if($('mtSeedOverlay').classList.contains('open')) mtSeedRender();
      }));
    }
    const mtTab = purchSheetTab('mt');
    if(mtTab && mtEditing){
      if(mtTab === 'prices' && has('supplier_materials', 'suppliers')) jobs.push(mtLoadPrices({ silent:true, keepForm:true }));
      if(mtTab === 'history' && has('supplier_materials')) jobs.push(mtLoadHistory({ silent:true }));
      if(ids.has('materials:' + mtEditing.id)) $('mtStaleNote').style.display = '';
    }
    // Purchase Orders
    if(typeof poLoadList === 'function' && has('purchase_orders', 'purchase_order_items', 'suppliers') && purchVisible('purchaseOrders')){
      jobs.push(poLoadList({ silent:true }).then(ok=>{ if(ok) poRenderList(); }));
    }
    if(typeof poEditorVisible === 'function' && poEditorVisible()){
      if(poEditing && ids.has('po:' + poEditing.id)) $('poStaleNote').style.display = '';
      if(has('po_signatories')) jobs.push(poLoadSignatories().then(()=>{ poFillSignatorySelects(); poRenderSigHint(); }).catch(()=>{}));
      if(has('suppliers', 'supplier_contacts')) jobs.push(poLoadSuppliers().then(()=>{
        const cur = $('poSupplier').value; poFillSupplierSelect(cur); $('poSupplier').value = cur; poRenderSupplierInfo();
        $('poSupplier').disabled = poReadOnly;
      }).catch(()=>{}));
      if(has('materials', 'supplier_materials') && !purchVisible('materials')) jobs.push(mtLoad({ silent:true }));
    }
    if($('poSettingsOverlay').classList.contains('open')){
      if(has('po_signatories')) jobs.push(poLoadSignatories().then(poRenderSigList).catch(()=>{}));
    }
    // Material Requisitions (a PO being issued/cancelled/deleted changes
    // fulfilment too, so PO events refresh an open request)
    if(typeof mrLoadList === 'function' && purchVisible('requisitions')){
      if(has('material_requisitions', 'material_requisition_items')) jobs.push(mrLoadList({ silent:true }).then(ok=>{ if(ok && !mrDetailVisible()) mrRenderList(); }));
      if(mrDetailVisible() && mrOpenRow){
        if(ids.has('mr:' + mrOpenRow.id) && mrOpenRow.status === 'submitted') $('mrStaleNote').style.display = '';
        else if(ids.has('mr:' + mrOpenRow.id) || has('purchase_orders')) jobs.push(mrOpen(mrOpenRow.id));
      }
    }
    // Inventory
    if(typeof invShowStock === 'function'){
      if(purchVisible('stock') && has('stock_balances', 'stock_movements', 'warehouses', 'materials')){
        if($('invOpeningView').style.display === 'none') jobs.push(invLoadStock({ silent:true }).then(ok=>{ if(ok && invItemOpen) return invRenderItem(); }));
      }
      if(purchVisible('warehouses') && has('warehouses', 'warehouse_storekeepers', 'stock_balances')) jobs.push(invShowWarehouses({ silent:true }));
      if(purchVisible('projects') && has('projects', 'project_job_orders', 'stock_movements') && $('invPrjEditView').style.display === 'none') jobs.push(invShowProjects({ silent:true }));
      if(purchVisible('slips') && has('stock_receipts', 'issue_slips', 'return_slips', 'stock_transfers') && $('invSlipView').style.display === 'none') jobs.push(invShowSlips({ silent:true }));
    }
    try{ await Promise.all(jobs); }catch(e){ console.error('purchasing live refresh failed', e); }
  }

  // Reload the open item from the latest data (after the stale notice).
  $('spStaleReload').addEventListener('click', ()=>{
    const cur = spEditing && spCache.find(x=> x.id === spEditing.id);
    const tab = purchSheetTab('sp') || 'info';
    if(cur) spOpenSheet(cur, tab);
  });
  $('mtStaleReload').addEventListener('click', ()=>{
    const cur = mtEditing && mtCache.find(x=> x.id === mtEditing.id);
    const tab = purchSheetTab('mt') || 'info';
    if(cur) mtOpenSheet(cur, tab);
  });

  // Catch-up when the tab/app comes back or the network returns.
  function purchCatchUp(){
    if(!purchChannel || !currentUser || currentUser.role !== 'admin') return;
    if($('purchasingView').style.display === 'none') return;
    purchQueueAll();
  }
  document.addEventListener('visibilitychange', ()=>{ if(document.visibilityState === 'visible') purchCatchUp(); });
  window.addEventListener('online', purchCatchUp);


  // =====================================================================
  // Purchasing — expired sign-in handling
  //
  // The app restores `currentUser` from localStorage, which can outlive the
  // real Supabase Auth session (expired refresh token, long-idle tab,
  // signed out elsewhere, admin password changed). Requests then go out as
  // `anon`, which every purchasing table refuses (42501 "permission denied
  // … TO anon"). Instead of that raw error:
  //   * each write first checks for a live session (purchEnsureSession);
  //   * if it's gone, a small "Sign in again" box asks for the admin
  //     password — the sheet and anything typed in it stay as they are —
  //     and the write then carries on by itself;
  //   * any request that still fails that way opens the same box.
  // =====================================================================
  const PURCH_EXPIRED_HTML = 'Your admin sign-in has expired, so the database can\u2019t be read. ' +
    '<button type="button" class="btn btn-primary mt-small-btn" data-purch-reauth="1" style="margin-top:10px;">Sign in again</button>';
  let purchReauthWaiters = [];

  // Reads the raw error fields (the "TO anon" part lives in .hint), so it
  // doesn't depend on how describeCloudError formats things.
  function purchErrText(e){
    if(!e) return '';
    return [e.code, e.message, e.details, e.hint, e.error_description, e.name].filter(Boolean).join(' | ') || String(e);
  }
  function purchIsAuthError(e){
    const m = purchErrText(e);
    return (/42501/.test(m) && /\banon\b/i.test(m)) || /PGRST30[123]|JWT expired|invalid JWT|jwt malformed/i.test(m);
  }
  // "permission denied" (42501, not an RLS row check) should never happen to
  // a signed-in admin on these tables — if the hint didn't say so, confirm
  // by checking whether the session is actually still alive.
  function purchIsPermissionDenied(e){
    const m = purchErrText(e);
    return /42501/.test(m) && /permission denied/i.test(m);
  }
  async function purchFail(prefix, e){
    if(purchIsAuthError(e)){ purchReauth(); return; }
    if(purchIsPermissionDenied(e) && !(await cloudAuthUid())){ purchReauth(); return; }
    toast(prefix + describeCloudError(e));
  }
  async function purchEnsureSession(){
    const uid = await cloudAuthUid();
    if(uid) return true;
    return purchReauth();
  }
  // Resolves true once signed back in, false if the admin backs out.
  function purchReauth(){
    return new Promise((resolve)=>{
      purchReauthWaiters.push(resolve);
      if($('purchReauthOverlay').classList.contains('open')) return;
      $('purchReauthPw').value = '';
      $('purchReauthErr').textContent = '';
      $('purchReauthBtn').disabled = false;
      $('purchReauthOverlay').classList.add('open');
      setTimeout(()=> $('purchReauthPw').focus(), 50);
    });
  }
  function purchReauthDone(ok){
    $('purchReauthOverlay').classList.remove('open');
    const w = purchReauthWaiters; purchReauthWaiters = [];
    w.forEach(r=> r(ok));
  }
  async function purchReauthSubmit(){
    const pw = $('purchReauthPw').value;
    if(!pw){ $('purchReauthErr').textContent = 'Enter the admin password.'; return; }
    const btn = $('purchReauthBtn'); btn.disabled = true; btn.textContent = 'Signing in…';
    try{
      const { data, error } = await db.auth.signInWithPassword({ email: ADMIN_EMAIL, password: pw });
      if(error) throw error;
      if(!data || !data.user || (data.user.email || '').toLowerCase() !== ADMIN_EMAIL.toLowerCase()) throw new Error('Not the admin account');
      toast('Signed in again');
      purchReauthDone(true);
      purchQueueAll();   // re-read everything now that the database will answer
    }catch(e){
      const m = describeCloudError(e);
      $('purchReauthErr').textContent = /invalid login|invalid_credentials|400/i.test(m) ? 'Wrong password — try again.' : 'Couldn\u2019t sign in: ' + m;
    }finally{ btn.disabled = false; btn.textContent = 'Sign in'; }
  }
  $('purchReauthBtn').addEventListener('click', purchReauthSubmit);
  $('purchReauthPw').addEventListener('keydown', (e)=>{ if(e.key === 'Enter') purchReauthSubmit(); });
  $('purchReauthClose').addEventListener('click', ()=> purchReauthDone(false));
  $('purchReauthLogout').addEventListener('click', ()=>{ purchReauthDone(false); doLogout(); });
  // "Sign in again" button inside a list's error message
  ['spList', 'mtList'].forEach(id=> $(id).addEventListener('click', (e)=>{
    if(!e.target.closest('[data-purch-reauth]')) return;
    e.stopPropagation();
    purchReauth().then(ok=>{
      if(!ok) return;
      if(id === 'spList') spLoad().then(ok=>{ if(ok) spRenderList(); }); else mtLoad().then(ok=>{ if(ok) mtRenderList(); });
    });
  }, true));


  // =====================================================================
  // Purchasing — Purchase Orders (admin only)
  //
  // Tables (migration 20260923_03_purchase_orders.sql): purchase_orders,
  // purchase_order_items, po_signatories, po_settings; storage bucket
  // 'purchasing-assets' (logo/…, signatures/…).
  //
  // The DATABASE owns the rules: PO numbers, totals, draft→issued→cancelled,
  // locking, and the snapshots taken at issue. This screen mirrors the math
  // for display and reads everything back after each save.
  //
  // PDF: jsPDF + autotable (same libs as the Service Report). Viewed through
  // the shared preview overlay (renderPdfPreview) and downloaded/shared via
  // shareOrDownloadPdf — both in pdf.js.
  // =====================================================================

  const PO_BUCKET = 'purchasing-assets';
  const PO_VAT_RATE = 0.12;
  const PO_LIST_SELECT = 'id, po_no, status, po_date, total, ewt_amount, net_payable, reference, supplier_id, supplier_snapshot, updated_at, suppliers(name, trade_name), purchase_order_items(count)';

  let poCache = [];
  let poEditing = null;      // header row from the DB, or null for a new unsaved PO
  let poItems = [];          // [{key, id, material_id, code, description, specs, unit, qty, unit_price}]
  // Specs text the supplier needs to fill the order (size, rating, brand…),
  // built from the Materials Database entry. Same format the database uses
  // (material_spec_text in 20260924_01) so both paths read the same.
  function poSpecText(m){
    if(!m) return '';
    const parts = [];
    if(String(m.brand || '').trim()) parts.push('Brand: ' + String(m.brand).trim());
    Object.keys(m.specs || {}).forEach(k=>{ const v = String(m.specs[k] == null ? '' : m.specs[k]).trim(); if(v) parts.push(k + ': ' + v); });
    return parts.join('; ');
  }
  let poSettingsData = null; // po_settings.data
  let poSignatories = [];
  let poSuppliers = [];      // suppliers with their contacts, for the picker + PDF
  let poReadOnly = false;
  let poKeySeq = 0;
  const poImgCache = new Map();  // storage path -> {dataUrl, w, h}

  function poUuid(){
    if(window.crypto && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c=>{
      const r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 0x3 | 0x8)).toString(16);
    });
  }
  function poRound2(n){ return Math.round((Number(n) + Number.EPSILON) * 100) / 100; }
  function poNum(v){ const n = spParseMoney(v); return n == null || Number.isNaN(n) ? null : n; }
  function poFmt(n){ return Number(n || 0).toLocaleString('en-PH', { minimumFractionDigits:2, maximumFractionDigits:2 }); }
  function poQtyFmt(n){ return Number(n || 0).toLocaleString('en-PH', { maximumFractionDigits:3 }); }
  function poToday(){
    // Manila date, whatever the device clock's zone is
    return new Date(Date.now() + 8 * 3600e3).toISOString().slice(0, 10);
  }
  function poDateLong(d){
    if(!d) return '—';
    const dt = new Date(d + 'T00:00:00');
    return isNaN(dt) ? d : dt.toLocaleDateString('en-PH', { year:'numeric', month:'long', day:'numeric' });
  }
  function poSupplierName(s){ return s ? (s.trade_name || s.name || '') : ''; }

  // Same math as the database (po_compute_totals) — display only.
  // EWT is computed on the amount net of VAT (vatable) and deducted:
  // net payable = total − EWT.
  function poCalc(items, vatMode, discount, ewtRate){
    const subtotal = poRound2(items.reduce((a, it)=> a + poRound2((Number(it.qty) || 0) * (Number(it.unit_price) || 0)), 0));
    const net = Math.max(poRound2(subtotal - (Number(discount) || 0)), 0);
    let vat = 0, total = net, vatable = net;
    if(vatMode === 'exclusive'){ vat = poRound2(net * PO_VAT_RATE); total = poRound2(net + vat); }
    else if(vatMode === 'inclusive'){ vat = poRound2(net - net / (1 + PO_VAT_RATE)); vatable = poRound2(net - vat); }
    const rate = Number(ewtRate) || 0;
    const ewt = poRound2(vatable * rate);
    return { subtotal, discount: Number(discount) || 0, net, vat, vatable, total, ewtRate: rate, ewt, netPayable: poRound2(total - ewt) };
  }
  function poEwtLabel(rate){
    const pct = Math.round(Number(rate) * 10000) / 100;
    return 'Less: EWT ' + pct + '%' + (Number(rate) === 0.01 ? ' (goods)' : Number(rate) === 0.02 ? ' (services)' : '');
  }

  // "Six Thousand Three Hundred Twenty-Nine Pesos and 12/100 Only"
  function poAmountInWords(amount){
    const ones = ['', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten', 'Eleven',
      'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen', 'Seventeen', 'Eighteen', 'Nineteen'];
    const tens = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety'];
    const under1000 = (n)=>{
      let s = '';
      if(n >= 100){ s += ones[Math.floor(n / 100)] + ' Hundred'; n %= 100; if(n) s += ' '; }
      if(n >= 20){ s += tens[Math.floor(n / 10)]; if(n % 10) s += '-' + ones[n % 10]; }
      else if(n > 0) s += ones[n];
      return s;
    };
    const total = poRound2(Math.abs(Number(amount) || 0));
    let pesos = Math.floor(total);
    const cents = Math.round((total - pesos) * 100);
    if(pesos === 0) return 'Zero Pesos and ' + String(cents).padStart(2, '0') + '/100 Only';
    const scales = ['', ' Thousand', ' Million', ' Billion'];
    const parts = [];
    for(let i = 0; pesos > 0 && i < scales.length; i++){
      const chunk = pesos % 1000;
      if(chunk) parts.unshift(under1000(chunk) + scales[i]);
      pesos = Math.floor(pesos / 1000);
    }
    const whole = Math.floor(total);
    return parts.join(' ') + (whole === 1 ? ' Peso' : ' Pesos') + ' and ' + String(cents).padStart(2, '0') + '/100 Only';
  }

  // ---------- reference data ----------
  async function poLoadSettings(){
    const { data, error } = await db.from('po_settings').select('data').eq('id', 1);
    if(error) throw error;
    poSettingsData = (data && data[0] && data[0].data) || {};
    return poSettingsData;
  }
  async function poLoadSignatories(){
    const { data, error } = await db.from('po_signatories').select('*').order('name');
    if(error) throw error;
    poSignatories = data || [];
    return poSignatories;
  }
  async function poLoadSuppliers(){
    const { data, error } = await db.from('suppliers')
      .select('id, code, name, trade_name, address, city, tin, payment_terms, is_active, supplier_contacts(name, position, mobile, email, is_primary)')
      .order('name');
    if(error) throw error;
    poSuppliers = data || [];
    return poSuppliers;
  }
  async function poEnsureRefs(){
    const jobs = [poLoadSettings(), poLoadSignatories(), poLoadSuppliers()];
    if(!mtCache.length) jobs.push(mtLoad({ silent:true }));
    await Promise.all(jobs);
  }

  // ---------- list ----------
  async function poShow(){
    // Sidebar "Purchase Orders" while a PO is open: back to the list,
    // unless there are unsaved changes the admin wants to keep.
    if(poEditorVisible()){
      if(!poConfirmLeave()) return;
      poShowListView();
    }
    if(await poLoadList()) poRenderList();
  }
  async function poLoadList(opts){
    const silent = !!(opts && opts.silent);
    const list = $('poList');
    if(!silent) list.innerHTML = '<div class="empty-state">Loading…</div>';
    if(!(await ensureCloud())){
      if(!silent) list.innerHTML = '<div class="empty-state">Not connected to Shared Cloud — Purchase Orders need a connection.</div>';
      return false;
    }
    try{
      const { data, error } = await db.from('purchase_orders').select(PO_LIST_SELECT)
        .order('po_date', { ascending:false }).order('po_no', { ascending:false });
      if(error) throw error;
      poCache = data || [];
      return true;
    }catch(e){
      console.error('load purchase orders failed', describeCloudError(e));
      if(silent) return false;
      const msg = purchIsAuthError(e) ? PURCH_EXPIRED_HTML
        : /42P01|does not exist/.test(describeCloudError(e))
          ? 'The purchase order tables aren\u2019t in the database yet — run migration 20260923_03_purchase_orders.sql in Supabase first.'
          : 'Couldn\u2019t load purchase orders: ' + escapeHtml(describeCloudError(e));
      list.innerHTML = '<div class="empty-state">' + msg + '</div>';
      return false;
    }
  }
  function poListSupplier(r){
    return poSupplierName(r.suppliers) || poSupplierName(r.supplier_snapshot) || '— no supplier yet —';
  }
  function poRenderList(){
    const q = ($('poSearch').value || '').trim().toLowerCase();
    const st = $('poFilterStatus').value;
    const counts = poCache.reduce((a, r)=>{ a[r.status] = (a[r.status] || 0) + 1; return a; }, {});
    $('poCount').textContent = poCache.length
      ? [counts.draft ? counts.draft + ' draft' + (counts.draft > 1 ? 's' : '') : '', counts.issued ? counts.issued + ' issued' : ''].filter(Boolean).join(' · ')
      : '';
    const rows = poCache.filter(r=>{
      if(st && r.status !== st) return false;
      if(!q) return true;
      return [r.po_no, poListSupplier(r), r.reference].join(' ').toLowerCase().includes(q);
    });
    const list = $('poList');
    if(!rows.length){
      list.innerHTML = '<div class="empty-state">' + (poCache.length ? 'No purchase orders match.'
        : 'No purchase orders yet. Tap <b>+ New Purchase Order</b> to create one.') + '</div>';
      return;
    }
    list.innerHTML = rows.map(r=>{
      const n = Array.isArray(r.purchase_order_items) && r.purchase_order_items[0] ? r.purchase_order_items[0].count : 0;
      return '<button type="button" class="mt-row' + (r.status === 'cancelled' ? ' inactive' : '') + '" data-id="' + escapeHtml(r.id) + '">' +
        '<div class="mt-row-main"><div class="mt-row-title"><span class="mt-code">' + escapeHtml(r.po_no || '—') + '</span>' +
          escapeHtml(poListSupplier(r)) + ' <span class="po-status ' + escapeHtml(r.status) + '">' + escapeHtml(r.status) + '</span></div>' +
          '<div class="sp-row-sub">' + escapeHtml([poDateLong(r.po_date), n + ' item' + (n === 1 ? '' : 's'), r.reference].filter(Boolean).join(' · ')) + '</div></div>' +
        '<div class="mt-row-price">₱' + poFmt(Number(r.ewt_amount) > 0 ? r.net_payable : r.total) +
          (Number(r.ewt_amount) > 0 ? '<div class="sp-row-sub">net of EWT</div>' : '') + '</div></button>';
    }).join('');
  }
  $('poSearch').addEventListener('input', poRenderList);
  $('poFilterStatus').addEventListener('change', poRenderList);
  $('poList').addEventListener('click', (e)=>{
    if(e.target.closest('[data-purch-reauth]')){
      purchReauth().then(ok=>{ if(ok) poShow(); });
      return;
    }
    const row = e.target.closest('.mt-row');
    if(row) poOpen(row.dataset.id);
  });
  $('poAddBtn').addEventListener('click', ()=> poOpen(null));

  // ---------- in-page views ----------
  let poDirty = false;
  function poEditorVisible(){ return $('poEditorView').style.display !== 'none'; }
  function poShowEditorView(){
    $('poListView').style.display = 'none';
    $('poEditorView').style.display = '';
    $('purchasingView').classList.add('po-wide');
    window.scrollTo({ top: 0 });
  }
  function poShowListView(){
    $('poEditorView').style.display = 'none';
    $('poListView').style.display = '';
    $('purchasingView').classList.remove('po-wide');
    poEditing = null; poDirty = false;
    window.scrollTo({ top: 0 });
  }
  // Leaving an edited draft asks first.
  function poConfirmLeave(){
    return !poDirty || poReadOnly || confirm('Discard the changes you haven\u2019t saved?');
  }
  $('poEditorView').addEventListener('input', (e)=>{ if(!e.target.closest('.po-actions')) poDirty = true; });
  $('poEditorView').addEventListener('change', (e)=>{ if(!e.target.closest('.po-actions')) poDirty = true; });
  $('poBackBtn').addEventListener('click', ()=>{ if(poConfirmLeave()) poClose(); });
  $('poEditTermsBtn').addEventListener('click', ()=> $('poSettingsBtn').click());

  // ---------- editor ----------
  async function poOpen(id, prefill){
    if(!(await ensureCloud())){ toast('Not connected'); return; }
    try{
      await poEnsureRefs();
      let header = null, items = [];
      if(id){
        const h = await db.from('purchase_orders').select('*').eq('id', id);
        if(h.error) throw h.error;
        header = h.data && h.data[0];
        if(!header){ toast('That PO no longer exists'); poShow(); return; }
        const it = await db.from('purchase_order_items').select('*').eq('po_id', id).order('line_no');
        if(it.error) throw it.error;
        items = it.data || [];
      }
      poEditing = header;
      poItems = (prefill ? prefill.items : items).map(r=> ({
        key: ++poKeySeq, id: prefill ? null : r.id, material_id: r.material_id || null, code: r.code || '',
        description: r.description || '', unit: r.unit || '', qty: r.qty, unit_price: r.unit_price,
        // NULL = line saved before specs existed: fill from the catalog on
        // drafts; an issued PO shows exactly what was issued.
        specs: r.specs != null ? r.specs
          : ((!header || header.status === 'draft') && r.material_id ? poSpecText(mtCache.find(x=> x.id === r.material_id)) : '')
      }));
      const src = header || (prefill && prefill.header) || {};
      const set = poSettingsData || {};
      poFillSupplierSelect(src.supplier_id);
      $('poSupplier').value = src.supplier_id || '';
      $('poReference').value = src.reference || '';
      $('poDate').value = header ? header.po_date : poToday();
      $('poDeliveryDate').value = src.delivery_date || '';
      $('poTerms').value = src.payment_terms != null ? src.payment_terms : '';
      $('poVatMode').value = src.vat_mode || set.vat_mode || 'exclusive';
      $('poDeliverTo').value = src.deliver_to != null && (header || prefill) ? src.deliver_to : (set.deliver_to || '');
      $('poDiscount').value = src.discount ? String(src.discount) : '';
      $('poEwt').value = String(Number(src.ewt_rate) || 0);
      if(!$('poEwt').value) $('poEwt').value = '0';
      poFillSignatorySelects(src.prepared_by_id, src.approved_by_id);
      $('poPreparedBy').value = src.prepared_by_id || '';
      $('poApprovedBy').value = src.approved_by_id || '';
      if(!poItems.length) poItems.push(poBlankItem());
      $('poStaleNote').style.display = 'none';
      poApplyMode();
      poRenderItems();
      poRenderTotals();
      poRenderSupplierInfo();
      poRenderSigHint();
      poShowEditorView();
      poDirty = !!prefill;   // a duplicate isn't saved yet
    }catch(e){
      purchFail('Couldn\u2019t open the PO: ', e);
    }
  }
  function poBlankItem(){ return { key: ++poKeySeq, id: null, material_id: null, code: '', description: '', specs: '', unit: '', qty: '', unit_price: '' }; }

  function poApplyMode(){
    const st = poEditing ? poEditing.status : 'draft';
    poReadOnly = st !== 'draft';
    $('poSheetTitle').textContent = poEditing ? poEditing.po_no : 'New Purchase Order';
    $('poSheetStatus').className = 'po-status ' + st;
    $('poSheetStatus').textContent = poEditing ? st : 'unsaved';
    const note = $('poLockedNote');
    if(st === 'issued'){
      note.className = 'po-locked-note';
      note.textContent = 'Issued ' + (poEditing.issued_at ? new Date(poEditing.issued_at).toLocaleString('en-PH') : '') +
        ' — locked. It can be viewed, downloaded, duplicated or cancelled, but not edited.';
      note.style.display = '';
    }else if(st === 'cancelled'){
      note.className = 'po-locked-note cancelled';
      note.textContent = 'Cancelled ' + (poEditing.cancelled_at ? new Date(poEditing.cancelled_at).toLocaleString('en-PH') : '') +
        (poEditing.cancel_reason ? ' — Reason: ' + poEditing.cancel_reason : '');
      note.style.display = '';
    }else note.style.display = 'none';
    $$('#poEditorView input, #poEditorView select, #poEditorView textarea').forEach(el=>{ el.disabled = poReadOnly; });
    $('poAddItem').style.display = poReadOnly ? 'none' : '';
    poRenderActions();
  }
  function poRenderActions(){
    const st = poEditing ? poEditing.status : 'draft';
    const b = (id, label, cls)=> '<button type="button" class="btn ' + (cls || 'btn-secondary') + '" data-po-act="' + id + '">' + label + '</button>';
    let html = '';
    if(st === 'draft'){
      html = b('save', 'Save Draft') + b('preview', 'Preview PDF') + b('issue', 'Issue PO', 'btn-primary');
      if(poEditing) html += b('duplicate', 'Duplicate') + b('delete', 'Delete Draft', 'danger');
    }else{
      html = b('preview', 'View PDF', 'btn-primary') + b('duplicate', 'Duplicate');
      if(st === 'issued') html += b('cancel', 'Cancel PO', 'danger');
    }
    $('poActions').innerHTML = html;
  }

  function poFillSupplierSelect(keepId){
    const opts = poSuppliers.filter(s=> s.is_active !== false || s.id === keepId)
      .map(s=> '<option value="' + escapeHtml(s.id) + '">' + escapeHtml(poSupplierName(s)) + (s.is_active === false ? ' (inactive)' : '') + '</option>');
    $('poSupplier').innerHTML = '<option value="">' + (poSuppliers.length ? 'Choose a supplier…' : 'No suppliers yet — add them in Supplier Database') + '</option>' + opts.join('');
  }
  function poFillSignatorySelects(keepPrep, keepAppr){
    const mk = (keep)=> '<option value="">— none —</option>' + poSignatories
      .filter(s=> s.is_active || s.id === keep)
      .map(s=> '<option value="' + escapeHtml(s.id) + '">' + escapeHtml(s.name) + (s.position ? ' — ' + escapeHtml(s.position) : '') + (s.signature_path ? '' : ' (no signature)') + '</option>').join('');
    const pv = $('poPreparedBy').value, av = $('poApprovedBy').value;
    $('poPreparedBy').innerHTML = mk(keepPrep || pv);
    $('poApprovedBy').innerHTML = mk(keepAppr || av);
    if(!keepPrep && pv) $('poPreparedBy').value = pv;
    if(!keepAppr && av) $('poApprovedBy').value = av;
  }
  function poRenderSigHint(){
    if(!poSignatories.length){
      $('poSigHint').innerHTML = 'No signatories yet — add them (with their e-signature) in <b>PO Settings, Logo &amp; Signatures</b>.';
      return;
    }
    const missing = [$('poPreparedBy').value, $('poApprovedBy').value].map(id=> poSignatories.find(s=> s.id === id)).filter(s=> s && !s.signature_path);
    $('poSigHint').textContent = missing.length ? missing.map(s=> s.name).join(', ') + ' has no uploaded signature yet — the PDF will show a blank signature line.' : '';
  }
  $('poPreparedBy').addEventListener('change', poRenderSigHint);
  $('poApprovedBy').addEventListener('change', poRenderSigHint);

  function poCurrentSupplier(){ return poSuppliers.find(s=> s.id === $('poSupplier').value) || null; }
  function poRenderSupplierInfo(){
    const s = poCurrentSupplier();
    if(!s){ $('poSupplierInfo').textContent = ''; return; }
    const c = (s.supplier_contacts || []).slice().sort((a, b)=> (b.is_primary ? 1 : 0) - (a.is_primary ? 1 : 0))[0];
    $('poSupplierInfo').innerHTML = [
      escapeHtml([s.address, s.city].filter(Boolean).join(', ')),
      s.tin ? 'TIN ' + escapeHtml(s.tin) : '',
      c ? escapeHtml(c.name + (c.mobile ? ' · ' + c.mobile : '')) : ''
    ].filter(Boolean).join('<br>');
  }
  let poLastSupplierTerms = '';
  $('poSupplier').addEventListener('focus', ()=>{ const s = poCurrentSupplier(); poLastSupplierTerms = s ? (s.payment_terms || '') : ''; });
  $('poSupplier').addEventListener('change', ()=>{
    const s = poCurrentSupplier();
    poRenderSupplierInfo();
    // Take the supplier's usual terms unless the admin typed their own.
    const cur = $('poTerms').value.trim();
    if(s && (!cur || cur === poLastSupplierTerms)) $('poTerms').value = s.payment_terms || '';
    poLastSupplierTerms = s ? (s.payment_terms || '') : '';
    // Offer to re-price catalog items from the new supplier's price list.
    if(!s) return;
    const changes = poItems.filter(it=> it.material_id).map(it=>{
      const p = poPriceFor(it.material_id, s.id);
      return p && p.price != null && Number(p.price) !== Number(it.unit_price) ? { it, p } : null;
    }).filter(Boolean);
    if(changes.length && confirm('Update ' + changes.length + ' item price' + (changes.length > 1 ? 's' : '') + ' from ' + poSupplierName(s) + '\u2019s price list?')){
      changes.forEach(({ it, p })=>{ it.unit_price = p.price; if(p.unitFromPrice) it.unit = p.unitFromPrice; });
      poRenderItems(); poRenderTotals();
    }
  });

  // Price of a catalog item for a supplier: that supplier's active price,
  // else the preferred/cheapest from anyone, else the standard cost.
  function poPriceFor(materialId, supplierId){
    const m = mtCache.find(x=> x.id === materialId);
    if(!m) return null;
    const live = m.prices.filter(p=> p.is_active && p.price != null);
    const mine = supplierId && live.find(p=> p.suppliers && p.suppliers.id === supplierId);
    const pick = mine || null;
    const unitFromPrice = (pr)=> pr && pr.price_unit ? pr.price_unit.replace(/^per\s+/i, '').trim() : '';
    if(pick) return { price: Number(pick.price), unitFromPrice: unitFromPrice(pick), source: 'supplier' };
    const best = mtBestPrice(m);
    if(best) return { price: Number(best.price), unitFromPrice: unitFromPrice(best), source: 'other' };
    if(m.standardCost != null) return { price: Number(m.standardCost), unitFromPrice: '', source: 'standard' };
    return null;
  }

  // ---------- items ----------
  function poRenderItems(){
    const wrap = $('poItems');
    wrap.innerHTML = poItems.map((it, i)=>{
      const amt = poRound2((Number(it.qty) || 0) * (Number(it.unit_price) || 0));
      const dis = poReadOnly ? ' disabled' : '';
      return '<div class="po-item" data-key="' + it.key + '">' +
        '<div class="po-no">' + (i + 1) + '</div>' +
        '<div class="po-item-desc"><input type="text" data-f="description" value="' + escapeHtml(it.description) + '" placeholder="' + (i === 0 ? 'Type an item name or code…' : 'Item') + '" autocomplete="off"' + dis + '>' +
          '<div class="po-item-code' + (!it.material_id && it.description ? ' po-need-cat' : '') + '">' + poCodeCell(it) + '</div>' +
          ((it.material_id || it.specs) ? (poReadOnly
            ? (it.specs ? '<div class="po-item-specs-ro">' + escapeHtml(it.specs) + '</div>' : '')
            : '<textarea class="po-item-specs" data-f="specs" rows="2" placeholder="Specs for the supplier — size, rating, model, colour…">' + escapeHtml(it.specs || '') + '</textarea>') : '') +
        '</div>' +
        '<input type="text" class="num po-qty" data-f="qty" inputmode="decimal" value="' + escapeHtml(it.qty === '' || it.qty == null ? '' : String(it.qty)) + '" placeholder="Qty"' + dis + '>' +
        '<input type="text" class="po-unit" data-f="unit" list="mtUnitList" value="' + escapeHtml(it.unit) + '" placeholder="Unit"' + dis + '>' +
        '<input type="text" class="num po-price" data-f="unit_price" inputmode="decimal" value="' + escapeHtml(it.unit_price === '' || it.unit_price == null ? '' : String(it.unit_price)) + '" placeholder="Unit price"' + dis + '>' +
        '<div class="po-amt">₱' + poFmt(amt) + '</div>' +
        (poReadOnly ? '<span></span>' : '<button type="button" class="po-rm" data-rm="1" title="Remove item">&minus;</button>') +
      '</div>';
    }).join('');
  }
  function poItemByEl(el){
    const row = el.closest('.po-item');
    return row ? poItems.find(x=> String(x.key) === row.dataset.key) : null;
  }
  $('poItems').addEventListener('input', (e)=>{
    const it = poItemByEl(e.target);
    const f = e.target.dataset.f;
    if(!it || !f) return;
    if(f === 'qty' || f === 'unit_price'){
      it[f] = e.target.value.trim() === '' ? '' : (poNum(e.target.value) == null ? e.target.value : poNum(e.target.value));
      const row = e.target.closest('.po-item');
      row.querySelector('.po-amt').textContent = '₱' + poFmt(poRound2((Number(it.qty) || 0) * (Number(it.unit_price) || 0)));
      poRenderTotals();
    }else if(f === 'description'){
      it.description = e.target.value;
      // Edited away from the catalog name → becomes a free-text line.
      if(it.material_id){
        const m = mtCache.find(x=> x.id === it.material_id);
        if(!m || m.name !== it.description){ it.material_id = null; it.code = ''; }
      }
      { const cc = e.target.closest('.po-item').querySelector('.po-item-code'); cc.innerHTML = poCodeCell(it); cc.classList.toggle('po-need-cat', !it.material_id && !!it.description); }
      poSuggest(e.target, it);
    }else it[f] = e.target.value;
  });
  $('poItems').addEventListener('click', (e)=>{
    const pick = e.target.closest('[data-pick]');
    if(pick){ poPickMaterial(poItemByEl(pick), pick.dataset.pick); return; }
    if(e.target.closest('[data-rm]')){
      const it = poItemByEl(e.target);
      poItems = poItems.filter(x=> x !== it);
      if(!poItems.length) poItems.push(poBlankItem());
      poRenderItems(); poRenderTotals();
    }
  });
  $('poItems').addEventListener('keydown', (e)=>{
    const box = e.target.closest('.po-item-desc') && e.target.closest('.po-item-desc').querySelector('.po-suggest');
    if(!box) return;
    const btns = Array.from(box.querySelectorAll('[data-pick]'));
    let i = btns.findIndex(b=> b.classList.contains('hl'));
    if(e.key === 'ArrowDown' || e.key === 'ArrowUp'){
      e.preventDefault();
      if(i >= 0) btns[i].classList.remove('hl');
      i = e.key === 'ArrowDown' ? Math.min(btns.length - 1, i + 1) : Math.max(0, i - 1);
      if(btns[i]){ btns[i].classList.add('hl'); btns[i].scrollIntoView({ block:'nearest' }); }
    }else if(e.key === 'Enter' && i >= 0){
      e.preventDefault(); poPickMaterial(poItemByEl(e.target), btns[i].dataset.pick);
    }else if(e.key === 'Escape'){ box.remove(); }
  });
  $('poItems').addEventListener('focusout', (e)=>{
    // let a click on a suggestion land first
    setTimeout(()=>{
      const d = e.target.closest && e.target.closest('.po-item-desc');
      if(d && !d.contains(document.activeElement)){ const b = d.querySelector('.po-suggest'); if(b) b.remove(); }
    }, 180);
  });
  function poSuggest(input, it){
    const host = input.closest('.po-item-desc');
    let box = host.querySelector('.po-suggest');
    const words = input.value.trim().toLowerCase().split(/\s+/).filter(Boolean);
    if(!words.length){ if(box) box.remove(); return; }
    const sup = $('poSupplier').value;
    const hits = mtCache.filter(m=> m.isActive).filter(m=>{
      const hay = [m.code, m.name, m.family, m.brand, mtSpecText(m.specs)].join(' ').toLowerCase();
      return words.every(w=> hay.includes(w));
    }).slice(0, 8);
    if(!hits.length){ if(box) box.remove(); return; }
    if(!box){ box = document.createElement('div'); box.className = 'po-suggest'; host.appendChild(box); }
    box.innerHTML = hits.map((m, i)=>{
      const p = poPriceFor(m.id, sup);
      return '<button type="button" data-pick="' + escapeHtml(m.id) + '"' + (i === 0 ? ' class="hl"' : '') + '><span><b>' + escapeHtml(m.code) + '</b> ' + escapeHtml(m.name) + '</span>' +
        '<span class="s-price">' + (p ? '₱' + poFmt(p.price) + (p.source === 'supplier' ? '' : p.source === 'standard' ? ' std.' : ' other') : 'no price') + '</span></button>';
    }).join('');
  }
  // Every PO line must be a Materials Database item. A typed line that
  // isn't picked shows this prompt — pick it from the list, or add it to
  // the catalog right here without leaving the PO.
  function poCodeCell(it){
    if(it.material_id) return escapeHtml(it.code);
    if(!it.description) return '';
    return 'Not in the Materials Database — pick it from the list' + (poReadOnly ? '' : ' or <button type="button" class="po-link" data-qa="1">+ Add to catalog</button>');
  }
  $('poItems').addEventListener('click', (e)=>{
    if(!e.target.closest('[data-qa]')) return;
    const it = poItemByEl(e.target); if(!it) return;
    const row = e.target.closest('.po-item');
    if(row.nextElementSibling && row.nextElementSibling.classList.contains('po-qa')){ row.nextElementSibling.remove(); return; }
    const box = document.createElement('div'); box.className = 'po-qa'; box.dataset.key = it.key;
    const cat = PURCH_CATEGORIES.map(c=> '<option>' + escapeHtml(c) + '</option>').join('');
    box.innerHTML = '<div class="po-qa-title">Add “' + escapeHtml(it.description) + '” to the Materials Database</div>' +
      '<div class="po-qa-grid"><input type="text" data-q="name" value="' + escapeHtml(it.description) + '" placeholder="Item name">' +
      '<select data-q="category">' + cat + '</select><input type="text" data-q="unit" list="mtUnitList" value="' + escapeHtml(it.unit || '') + '" placeholder="Unit (ft, pc…)">' +
      '<input type="text" data-q="code" placeholder="Code"></div>' +
      '<div class="po-qa-actions"><button type="button" class="btn btn-primary mt-small-btn" data-q-save="1">Add &amp; use</button><button type="button" class="btn btn-secondary mt-small-btn" data-q-cancel="1">Cancel</button>' +
      '<span class="po-hint" style="margin:0;">You can fill in sizes, brand and supplier prices later in the Materials Database.</span></div>';
    row.after(box);
    const code = box.querySelector('[data-q=code]'), catSel = box.querySelector('[data-q=category]');
    const sugg = ()=>{ if(code.dataset.typed !== '1') code.value = mtSuggestCodeFor(catSel.value); };
    catSel.addEventListener('change', sugg); code.addEventListener('input', ()=>{ code.dataset.typed = '1'; });
    mtLoad({ silent:true }).then(sugg, sugg);
    box.querySelector('[data-q=name]').focus();
  });
  $('poItems').addEventListener('click', async (e)=>{
    const box = e.target.closest('.po-qa'); if(!box) return;
    if(e.target.closest('[data-q-cancel]')){ box.remove(); return; }
    if(!e.target.closest('[data-q-save]')) return;
    const it = poItems.find(x=> String(x.key) === box.dataset.key); if(!it) return;
    const v = (k)=> box.querySelector('[data-q=' + k + ']').value.trim();
    const row = { code: mtNormCode(v('code')), name: v('name'), family:'', category: v('category'), scope:[], unit: v('unit'),
      pack_unit:null, pack_qty:null, brand:'', specs:{}, standard_cost:null, notes:'Added from a Purchase Order' };
    if(!row.name){ toast('Enter the item name'); return; }
    if(!row.unit){ toast('Enter the unit (e.g. ft, pc, kg)'); return; }
    if(!/^[A-Z0-9][A-Z0-9._\-/]*$/.test(row.code)){ toast('Code: letters, numbers, - . / only'); return; }
    await mtLoad({ silent:true }).catch(()=>{});
    const clash = mtCache.find(x=> x.code === row.code);
    if(clash){ toast('Code ' + row.code + ' is already used by ' + clash.name); return; }
    const twin = mtCache.find(x=> x.name.trim().toLowerCase() === row.name.toLowerCase() && x.isActive);
    if(twin && confirm('“' + twin.name + '” is already in the catalog as ' + twin.code + '. Use that one instead?')){ box.remove(); poPickMaterial(it, twin.id); return; }
    if(!(await purchEnsureSession())) return;
    const btn = e.target.closest('[data-q-save]'); btn.disabled = true;
    try{
      const { data, error } = await db.from('materials').insert(row).select('id').single();
      if(error) throw error;
      await mtLoad({ silent:true });
      box.remove();
      poPickMaterial(it, data.id);
      toast(row.code + ' added to the Materials Database');
    }catch(err){ purchFail('Couldn\u2019t add the item: ', err); }
    finally{ btn.disabled = false; }
  });
  function poPickMaterial(it, materialId){
    const m = mtCache.find(x=> x.id === materialId);
    if(!it || !m) return;
    const p = poPriceFor(m.id, $('poSupplier').value);
    it.material_id = m.id; it.code = m.code; it.description = m.name;
    it.specs = poSpecText(m);   // admin can add order-specific details after
    it.unit = (p && p.unitFromPrice) || m.unit;
    if(p) it.unit_price = p.price;
    poRenderItems(); poRenderTotals();
    const row = $('poItems').querySelector('.po-item[data-key="' + it.key + '"] [data-f="qty"]');
    if(row) row.focus();
  }
  $('poAddItem').addEventListener('click', ()=>{
    poItems.push(poBlankItem());
    poRenderItems();
    const inputs = $('poItems').querySelectorAll('[data-f="description"]');
    if(inputs.length) inputs[inputs.length - 1].focus();
  });

  function poRenderTotals(){
    const vm = $('poVatMode').value;
    const t = poCalc(poCleanItems(), vm, poNum($('poDiscount').value) || 0, Number($('poEwt').value) || 0);
    $('poTotSub').textContent = '₱' + poFmt(t.subtotal);
    const row = (l, v)=> '<div class="row"><span>' + l + '</span><span>' + v + '</span></div>';
    $('poTotVatRows').innerHTML = vm === 'exclusive' ? row('Add: VAT 12%', '₱' + poFmt(t.vat))
      : vm === 'inclusive' ? row('VATable sales', '₱' + poFmt(t.vatable)) + row('VAT 12% (included)', '₱' + poFmt(t.vat))
      : row('VAT', 'Non-VAT');
    $('poTotTotal').textContent = '₱' + poFmt(t.total);
    $('poTotEwtRow').style.display = t.ewt ? '' : 'none';
    $('poTotEwtLabel').textContent = 'Withheld: ' + (Math.round(t.ewtRate * 10000) / 100) + '% of ₱' + poFmt(t.vatable) + ' (net of VAT)';
    $('poTotEwt').textContent = '(₱' + poFmt(t.ewt) + ')';
    $('poTotNetLabel').textContent = t.ewtRate ? 'Net Amount Payable' : 'Total Amount';
    $('poTotNet').textContent = '₱' + poFmt(t.netPayable);
  }
  $('poVatMode').addEventListener('change', poRenderTotals);
  $('poDiscount').addEventListener('input', poRenderTotals);
  $('poEwt').addEventListener('change', poRenderTotals);

  // Items with anything typed in them (fully blank rows are ignored), with
  // qty/price coerced to numbers — used for totals and saving.
  function poCleanItems(){
    return poItems.filter(it=> String(it.description || '').trim() || (it.qty !== '' && it.qty != null) || (it.unit_price !== '' && it.unit_price != null))
      .map(it=> Object.assign({}, it, { qty: Number(it.qty) || 0, unit_price: Number(it.unit_price) || 0 }));
  }
  function poValidate(){
    const items = poItems.filter(it=> String(it.description || '').trim() || (it.qty !== '' && it.qty != null) || (it.unit_price !== '' && it.unit_price != null));
    for(let i = 0; i < items.length; i++){
      const it = items[i], n = i + 1;
      if(!String(it.description || '').trim()) return 'Item ' + n + ': pick an item from the Materials Database';
      if(!it.material_id) return 'Item ' + n + ' (' + it.description + '): pick it from the Materials Database list, or tap “+ Add to catalog”';
      const q = Number(it.qty);
      if(it.qty === '' || !isFinite(q) || q <= 0) return 'Item ' + n + ' (' + it.description + '): enter a quantity above 0';
      const p = Number(it.unit_price);
      if(it.unit_price === '' || !isFinite(p) || p < 0) return 'Item ' + n + ' (' + it.description + '): enter a unit price (0 is allowed)';
    }
    const d = spParseMoney($('poDiscount').value);
    if(Number.isNaN(d)) return 'Discount must be a number';
    return null;
  }
  function poGatherHeader(){
    return {
      supplier_id: $('poSupplier').value || null,
      po_date: $('poDate').value || poToday(),
      delivery_date: $('poDeliveryDate').value || null,
      deliver_to: $('poDeliverTo').value.trim(),
      payment_terms: $('poTerms').value.trim(),
      reference: $('poReference').value.trim(),
      vat_mode: $('poVatMode').value,
      discount: poNum($('poDiscount').value) || 0,
      ewt_rate: Number($('poEwt').value) || 0,
      prepared_by_id: $('poPreparedBy').value || null,
      approved_by_id: $('poApprovedBy').value || null
    };
  }

  // Saves header + items. Items are upserted by id, then any removed rows
  // are deleted — so a failure midway never leaves the draft with fewer
  // items than it had. Returns the fresh header row, or null.
  async function poSave(opts){
    const quiet = !!(opts && opts.quiet);
    const err = poValidate();
    if(err){ toast(err); return null; }
    if(!(await ensureCloud())){ toast('Not connected — can\u2019t save'); return null; }
    if(!(await purchEnsureSession())) return null;
    const header = poGatherHeader();
    try{
      let id = poEditing && poEditing.id;
      if(id){
        purchMarkOwn(id);
        const { error } = await db.from('purchase_orders').update(header).eq('id', id);
        if(error) throw error;
      }else{
        const { data, error } = await db.from('purchase_orders').insert(header).select('*').single();
        if(error) throw error;
        id = data.id; purchMarkOwn(id);
        poEditing = data;
      }
      const clean = poItems.filter(it=> String(it.description || '').trim());
      clean.forEach(it=>{ if(!it.id) it.id = poUuid(); });
      purchMarkOwn(id);
      if(clean.length){
        const rows = clean.map((it, i)=> ({
          id: it.id, po_id: id, line_no: i + 1, material_id: it.material_id || null, code: it.code || '',
          description: it.description.trim(), specs: String(it.specs || '').trim(), unit: (it.unit || '').trim(), qty: Number(it.qty), unit_price: Number(it.unit_price)
        }));
        const { error } = await db.from('purchase_order_items').upsert(rows, { onConflict: 'id' });
        if(error) throw error;
      }
      let del = db.from('purchase_order_items').delete().eq('po_id', id);
      if(clean.length) del = del.not('id', 'in', '(' + clean.map(it=> it.id).join(',') + ')');
      const dr = await del;
      if(dr.error) throw dr.error;
      const h = await db.from('purchase_orders').select('*').eq('id', id);
      if(h.error) throw h.error;
      poEditing = h.data[0];
      poApplyMode();
      poDirty = false;
      if(!quiet) toast(poEditing.po_no + ' saved');
      poLoadList({ silent:true }).then(ok=>{ if(ok) poRenderList(); });
      return poEditing;
    }catch(e){
      purchFail('Couldn\u2019t save the PO: ', e);
      return null;
    }
  }

  $('poActions').addEventListener('click', async (e)=>{
    const b = e.target.closest('[data-po-act]');
    if(!b) return;
    const act = b.dataset.poAct;
    const lock = (on)=> $$('#poActions .btn').forEach(x=>{ x.disabled = on; });
    lock(true);
    try{
      if(act === 'save') await poSave();
      else if(act === 'preview') await poShowPdf('view');
      else if(act === 'duplicate') poDuplicate();
      else if(act === 'issue') await poIssue();
      else if(act === 'cancel') await poCancel();
      else if(act === 'delete') await poDeleteDraft();
    }finally{ lock(false); }
  });

  async function poIssue(){
    const err = poValidate();
    if(err){ toast(err); return; }
    if(!$('poSupplier').value){ toast('Choose a supplier before issuing'); return; }
    if(!poCleanItems().filter(it=> it.description.trim()).length){ toast('Add at least one item before issuing'); return; }
    if(!$('poApprovedBy').value){ toast('Choose who approves this PO before issuing'); $('poApprovedBy').focus(); return; }
    const t = poCalc(poCleanItems(), $('poVatMode').value, poNum($('poDiscount').value) || 0, Number($('poEwt').value) || 0);
    const s = poCurrentSupplier();
    if(!confirm('Issue this PO to ' + poSupplierName(s) + ' for ₱' + poFmt(t.total) + (t.ewt ? ' (net payable ₱' + poFmt(t.netPayable) + ' after EWT)' : '') + '?\n\nOnce issued it is locked: it can be viewed, downloaded or cancelled, but not edited.')) return;
    const saved = await poSave({ quiet:true });
    if(!saved) return;
    try{
      purchMarkOwn(saved.id);
      const { error } = await db.from('purchase_orders').update({ status:'issued' }).eq('id', saved.id);
      if(error) throw error;
      const h = await db.from('purchase_orders').select('*').eq('id', saved.id);
      if(h.error) throw h.error;
      poEditing = h.data[0];
      poApplyMode(); poRenderItems();
      toast(poEditing.po_no + ' issued');
      poLoadList({ silent:true }).then(ok=>{ if(ok) poRenderList(); });
      await poShowPdf('view');
    }catch(e){ purchFail('Couldn\u2019t issue the PO: ', e); }
  }
  async function poCancel(){
    if(!poEditing) return;
    const reason = prompt('Cancel ' + poEditing.po_no + '?\n\nThe PO stays on record, marked CANCELLED. Enter the reason:');
    if(reason === null) return;
    if(!reason.trim()){ toast('A reason is required to cancel'); return; }
    if(!(await purchEnsureSession())) return;
    try{
      purchMarkOwn(poEditing.id);
      const { error } = await db.from('purchase_orders').update({ status:'cancelled', cancel_reason: reason.trim() }).eq('id', poEditing.id);
      if(error) throw error;
      const h = await db.from('purchase_orders').select('*').eq('id', poEditing.id);
      if(h.error) throw h.error;
      poEditing = h.data[0];
      poApplyMode(); poRenderItems();
      toast(poEditing.po_no + ' cancelled');
      poLoadList({ silent:true }).then(ok=>{ if(ok) poRenderList(); });
    }catch(e){ purchFail('Couldn\u2019t cancel the PO: ', e); }
  }
  async function poDeleteDraft(){
    if(!poEditing) return;
    if(!confirm('Delete draft ' + poEditing.po_no + '? This can\u2019t be undone.')) return;
    poDirty = false;
    if(!(await purchEnsureSession())) return;
    try{
      purchMarkOwn(poEditing.id);
      const { error } = await db.from('purchase_orders').delete().eq('id', poEditing.id);
      if(error) throw error;
      toast('Draft deleted');
      poClose();
    }catch(e){ purchFail('Couldn\u2019t delete the draft: ', e); }
  }
  function poDuplicate(){
    if(!poConfirmLeave()) return;
    const header = poGatherHeader();
    const items = poCleanItems().filter(it=> it.description.trim());
    poEditing = null;
    poOpen(null, { header, items }).then(()=> toast('Copied into a new draft — review and save'));
  }
  function poClose(){
    poShowListView();
    poShow();
  }
  $('poStaleReload').addEventListener('click', ()=>{ if(poEditing) poOpen(poEditing.id); });

  // ---------- images from storage (logo / signatures) ----------
  function poBlobToDataUrl(blob){
    return new Promise((res, rej)=>{ const r = new FileReader(); r.onload = ()=> res(r.result); r.onerror = rej; r.readAsDataURL(blob); });
  }
  function poImageSize(dataUrl){
    return new Promise((res)=>{ const im = new Image(); im.onload = ()=> res({ w: im.naturalWidth, h: im.naturalHeight }); im.onerror = ()=> res({ w: 0, h: 0 }); im.src = dataUrl; });
  }
  async function poLoadImage(path){
    if(!path) return null;
    if(poImgCache.has(path)) return poImgCache.get(path);
    try{
      const { data, error } = await db.storage.from(PO_BUCKET).download(path);
      if(error || !data) throw error || new Error('no data');
      const dataUrl = await poBlobToDataUrl(data);
      const size = await poImageSize(dataUrl);
      const out = { dataUrl, w: size.w, h: size.h };
      poImgCache.set(path, out);
      return out;
    }catch(e){ console.warn('image load failed', path, e); return null; }
  }
  // The built-in AWES logo is white artwork (made for the green band).
  // For the white header it's recoloured to the brand green: every pixel
  // takes the green, keeping its transparency — so edges stay smooth.
  const poLogoCache = {};
  async function poDefaultLogo(style){
    const key = style === 'green' ? 'green-band' : 'white';
    if(poLogoCache[key]) return poLogoCache[key];
    const size = await poImageSize(AWES_LOGO_B64);
    if(key === 'green-band') return (poLogoCache[key] = { dataUrl: AWES_LOGO_B64, w: size.w, h: size.h });
    const im = new Image(); im.src = AWES_LOGO_B64; await im.decode();
    const c = document.createElement('canvas'); c.width = im.naturalWidth; c.height = im.naturalHeight;
    const ctx = c.getContext('2d');
    ctx.drawImage(im, 0, 0);
    ctx.globalCompositeOperation = 'source-in';   // paint only where the logo is
    ctx.fillStyle = 'rgb(21,77,52)';
    ctx.fillRect(0, 0, c.width, c.height);
    return (poLogoCache[key] = { dataUrl: c.toDataURL('image/png'), w: c.width, h: c.height });
  }

  // Uploaded logo → how it appears in the header: all-white on the green
  // band (shape kept via its transparency), original colours on white.
  const poTintCache = new Map();
  async function poLogoForStyle(img, style){
    if(!img || style !== 'green') return img;
    const key = img.dataUrl.length + ':' + img.dataUrl.slice(-40);
    if(poTintCache.has(key)) return poTintCache.get(key);
    const im = new Image(); im.src = img.dataUrl; await im.decode();
    const c = document.createElement('canvas'); c.width = im.naturalWidth; c.height = im.naturalHeight;
    const ctx = c.getContext('2d');
    ctx.drawImage(im, 0, 0);
    ctx.globalCompositeOperation = 'source-in';
    ctx.fillStyle = '#fff';
    ctx.fillRect(0, 0, c.width, c.height);
    const out = { dataUrl: c.toDataURL('image/png'), w: c.width, h: c.height };
    poTintCache.set(key, out);
    return out;
  }
  // A logo saved as JPG / on a white or coloured box has no transparency, so
  // turning it white would give a solid white rectangle. Remove a uniform
  // background (sampled from the corners) and crop to the artwork.
  function poPrepareLogo(src){
    const c = document.createElement('canvas'); c.width = src.width; c.height = src.height;
    const ctx = c.getContext('2d'); ctx.drawImage(src, 0, 0);
    const img = ctx.getImageData(0, 0, c.width, c.height), px = img.data, W = c.width, H = c.height;
    const at = (x, y)=> (y * W + x) * 4;
    const corners = [at(0, 0), at(W - 1, 0), at(0, H - 1), at(W - 1, H - 1)];
    const opaque = corners.every(i=> px[i + 3] > 245);
    if(opaque){
      const bg = [0, 1, 2].map(k=> corners.reduce((a, i)=> a + px[i + k], 0) / 4);
      const lo = 22, hi = 70;   // colour distance: ≤lo → background, ≥hi → artwork
      for(let i = 0; i < px.length; i += 4){
        const d = Math.sqrt((px[i] - bg[0]) ** 2 + (px[i + 1] - bg[1]) ** 2 + (px[i + 2] - bg[2]) ** 2);
        const a = d <= lo ? 0 : d >= hi ? 255 : Math.round(255 * (d - lo) / (hi - lo));
        px[i + 3] = Math.min(px[i + 3], a);
      }
      ctx.putImageData(img, 0, 0);
    }
    let x0 = W, y0 = H, x1 = -1, y1 = -1;
    for(let y = 0; y < H; y++) for(let x = 0; x < W; x++){
      if(px[at(x, y) + 3] > 24){ if(x < x0) x0 = x; if(x > x1) x1 = x; if(y < y0) y0 = y; if(y > y1) y1 = y; }
    }
    if(x1 < 0) return c;
    const pad = 4;
    x0 = Math.max(0, x0 - pad); y0 = Math.max(0, y0 - pad); x1 = Math.min(W - 1, x1 + pad); y1 = Math.min(H - 1, y1 + pad);
    const out = document.createElement('canvas'); out.width = x1 - x0 + 1; out.height = y1 - y0 + 1;
    out.getContext('2d').drawImage(c, x0, y0, out.width, out.height, 0, 0, out.width, out.height);
    return out;
  }

  // ---------- PDF ----------
  // What goes on the PDF. Issued/cancelled POs print ONLY their snapshots,
  // so the document the supplier received never changes. Drafts use live
  // data (and the current form contents, even before saving).
  async function poPdfData(){
    const live = !poEditing || poEditing.status === 'draft';
    const header = live ? Object.assign({}, poEditing || {}, poGatherHeader()) : poEditing;
    const items = live ? poCleanItems().filter(it=> it.description.trim()) : poItems.map(it=> Object.assign({}, it, { qty: Number(it.qty), unit_price: Number(it.unit_price) }));
    let company, supplier, prepared, approved;
    if(live){
      company = poSettingsData || {};
      const s = poSuppliers.find(x=> x.id === header.supplier_id);
      const c = s ? (s.supplier_contacts || []).slice().sort((a, b)=> (b.is_primary ? 1 : 0) - (a.is_primary ? 1 : 0))[0] : null;
      supplier = s ? { name: s.name, trade_name: s.trade_name, address: s.address, city: s.city, tin: s.tin,
        contact_name: c ? c.name : '', contact_mobile: c ? c.mobile : '', contact_email: c ? c.email : '' } : null;
      const sig = (id)=>{ const x = poSignatories.find(s2=> s2.id === id); return x ? { name: x.name, position: x.position, signature_path: x.signature_path } : null; };
      prepared = sig(header.prepared_by_id); approved = sig(header.approved_by_id);
    }else{
      company = header.company_snapshot || poSettingsData || {};
      supplier = header.supplier_snapshot; prepared = header.prepared_snapshot; approved = header.approved_snapshot;
    }
    const style = company.header_style || 'green';
    const [logo, prepSig, apprSig] = await Promise.all([
      company.logo_path ? poLoadImage(company.logo_path).then(img=> poLogoForStyle(img, style)) : poDefaultLogo(style),
      prepared && prepared.signature_path ? poLoadImage(prepared.signature_path) : null,
      approved && approved.signature_path ? poLoadImage(approved.signature_path) : null
    ]);
    return { header, items, company, supplier, prepared, approved, logo: logo || await poDefaultLogo(style), prepSig, apprSig,
      totals: poCalc(items, header.vat_mode, header.discount, header.ewt_rate), status: header.status || 'draft',
      terms: company.terms || '' };
  }

  // ---- PDF typeface ----
  // Inter (SIL Open Font Licence — fonts/Inter-LICENSE.txt), subset to Latin
  // + punctuation + ₱, ~25 KB per weight. Loaded on first PDF only and
  // precached by the service worker for offline use. If it can't load, the
  // PDF falls back to jsPDF's built-in Helvetica (which has no ₱ glyph, so
  // amounts then print as "PHP").
  const PO_FONT_FILES = { regular:'fonts/Inter-Regular.ttf', semibold:'fonts/Inter-SemiBold.ttf', bold:'fonts/Inter-Bold.ttf' };
  let poFontData = null, poFontTried = false;
  async function poLoadFonts(){
    if(poFontData || poFontTried) return poFontData;
    poFontTried = true;
    try{
      const out = {};
      for(const [k, url] of Object.entries(PO_FONT_FILES)){
        const r = await fetch(url);
        if(!r.ok) throw new Error(url + ' ' + r.status);
        const bytes = new Uint8Array(await r.arrayBuffer());
        let bin = '';
        for(let i = 0; i < bytes.length; i += 0x8000) bin += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
        out[k] = btoa(bin);
      }
      poFontData = out;
    }catch(e){ console.warn('PO font unavailable, using Helvetica', e); poFontTried = false; }
    return poFontData;
  }

  async function poBuildPdf(d){
    await loadAwesScript('jspdf', awesLibs.jspdf);
    await loadAwesScript('autotable', awesLibs.autotable);
    const fonts = await poLoadFonts();
    const { jsPDF } = window.jspdf;
    // compress: deflate page content + fonts. Images below also use 'FAST'
    // (lossless deflate) — jsPDF's default stores them raw, which made a
    // one-page PO with a logo + two signatures about 1.7 MB.
    const doc = new jsPDF({ orientation:'p', unit:'pt', format:'a4', compress:true });
    let F = 'helvetica', FS = ['helvetica', 'bold'], FB = ['helvetica', 'bold'];
    if(fonts){
      try{
        doc.addFileToVFS('Inter-Regular.ttf', fonts.regular);   doc.addFont('Inter-Regular.ttf', 'Inter', 'normal');
        doc.addFileToVFS('Inter-SemiBold.ttf', fonts.semibold); doc.addFont('Inter-SemiBold.ttf', 'Inter', 'bold');
        doc.addFileToVFS('Inter-Bold.ttf', fonts.bold);         doc.addFont('Inter-Bold.ttf', 'InterBold', 'normal');
        F = 'Inter'; FS = ['Inter', 'bold']; FB = ['InterBold', 'normal'];
      }catch(e){ console.warn('PO font registration failed', e); }
    }
    const peso = F === 'Inter' ? '\u20B1' : 'PHP ';
    const reg = (size)=>{ doc.setFont(F, 'normal'); if(size) doc.setFontSize(size); };
    const semi = (size)=>{ doc.setFont(FS[0], FS[1]); if(size) doc.setFontSize(size); };
    const bold = (size)=>{ doc.setFont(FB[0], FB[1]); if(size) doc.setFontSize(size); };
    const caps = (txt, x, yy, color, opts)=>{   // small spaced capitals for labels
      semi(6.8); doc.setTextColor(...color); doc.setCharSpace(0.6);
      doc.text(String(txt).toUpperCase(), x, yy, opts || {}); doc.setCharSpace(0);
    };

    const W = doc.internal.pageSize.getWidth(), H = doc.internal.pageSize.getHeight();
    const M = 36;
    const G = [21, 77, 52], G2 = [31, 122, 80], MINT = [233, 243, 237], MINT_TXT = [197, 229, 210];
    const INK = [28, 34, 30], SUB = [96, 108, 101], LINE = [216, 223, 219];
    const co = d.company || {}, h = d.header, t = d.totals;
    const green = co.header_style !== 'white';          // default: green band
    const fitImg = (img, maxW, maxH)=>{
      if(!img || !img.w || !img.h) return { w: maxW, h: maxH };
      const r = Math.min(maxW / img.w, maxH / img.h);
      return { w: img.w * r, h: img.h * r };
    };
    const imgFmt = (url)=> /^data:image\/jpe?g/i.test(url) ? 'JPEG' : 'PNG';
    const money = (n)=> peso + poFmt(n);

    // ---- header (original layout): green band; logo with the company
    // details stacked under it on the left, title block on the right ----
    const headH = 118;
    const ink = green ? [255, 255, 255] : INK;
    const soft = green ? [255, 255, 255] : SUB;     // on the green band everything is white
    if(green){ doc.setFillColor(...G); doc.rect(0, 0, W, headH, 'F'); }
    else{ doc.setFillColor(...G); doc.rect(0, headH - 4, W, 4, 'F'); }
    const lg = fitImg(d.logo, 150, 44);
    try{ doc.addImage(d.logo.dataUrl, imgFmt(d.logo.dataUrl), M, 16, lg.w, lg.h, 'po-logo', 'FAST'); }catch(e){}
    let hy = 16 + lg.h + 14;
    semi(9.5); doc.setTextColor(...(green ? ink : G));
    doc.text(co.company_name || '', M, hy); hy += 11;
    reg(7.8); doc.setTextColor(...soft);
    if(co.tagline){ doc.text(co.tagline, M, hy); hy += 10; }
    reg(7.2); doc.setTextColor(...ink);
    doc.splitTextToSize(co.address || '', 310).slice(0, 2).forEach(line=>{ doc.text(line, M, hy); hy += 9; });
    const contact = [co.phone, co.email, co.tin ? 'TIN ' + co.tin : ''].filter(Boolean).join('   •   ');
    if(contact) doc.splitTextToSize(contact, 330).slice(0, 2).forEach(line=>{ doc.text(line, M, hy); hy += 9; });
    bold(18); doc.setTextColor(...(green ? ink : G));
    doc.text('PURCHASE ORDER', W - M, 36, { align:'right' });
    semi(10.5); doc.setTextColor(...ink);
    doc.text(h.po_no || 'DRAFT — not yet saved', W - M, 54, { align:'right' });
    reg(8.8); doc.setTextColor(...ink);
    doc.text('Date: ' + poDateLong(h.po_date), W - M, 68, { align:'right' });
    if(d.status !== 'issued'){ semi(8.8); doc.text('Status: ' + d.status.toUpperCase(), W - M, 82, { align:'right' }); }
    let y = Math.max(headH, hy + 6) + 16;

    // ---- supplier / delivery ----
    const colW = (W - M * 2 - 14) / 2, pad = 11, labW = 58;
    const block = (x, title, rows)=>{
      const lines = [];
      rows.forEach(([label, value, strong])=>{
        if(!value) return;
        reg(8.4);
        lines.push({ label, strong, wrapped: doc.splitTextToSize(String(value), colW - pad * 2 - (label ? labW : 0)) });
      });
      const hgt = 24 + lines.reduce((a, l)=> a + l.wrapped.length * 10.8 + 2.5, 0) + 8;
      return { hgt, draw: (hh)=>{
        doc.setFillColor(247, 250, 248); doc.setDrawColor(...LINE); doc.setLineWidth(0.5);
        doc.roundedRect(x, y, colW, hh, 3, 3, 'FD');
        doc.setFillColor(...G2); doc.rect(x, y, 3, hh, 'F');                 // accent edge
        caps(title, x + pad + 2, y + 14, G);
        let yy = y + 28;
        lines.forEach(l=>{
          if(l.label){ reg(7.6); doc.setTextColor(...SUB); doc.text(l.label, x + pad + 2, yy); }
          if(l.strong) semi(9.4); else reg(8.4);
          doc.setTextColor(...INK);
          doc.text(l.wrapped, x + pad + 2 + (l.label ? labW : 0), yy);
          yy += l.wrapped.length * 10.8 + 2.5;
        });
      } };
    };
    const s = d.supplier || {};
    const left = block(M, 'Supplier', [
      ['', s.name || '(no supplier selected)', true],
      ['', s.trade_name && s.trade_name !== s.name ? s.trade_name : ''],
      ['', [s.address, s.city].filter(Boolean).join(', ')],
      ['TIN', s.tin],
      ['Contact', [s.contact_name, s.contact_mobile].filter(Boolean).join(' · ')],
      ['Email', s.contact_email]
    ]);
    const right = block(M + colW + 14, 'Delivery & Terms', [
      ['Deliver to', h.deliver_to || '—'],
      ['Delivery', h.delivery_date ? poDateLong(h.delivery_date) : 'As soon as possible'],
      ['Terms', h.payment_terms || '—'],
      ['Reference', h.reference]
    ]);
    const boxH = Math.max(left.hgt, right.hgt, 84);
    left.draw(boxH); right.draw(boxH);
    y += boxH + 16;

    // ---- items ----
    doc.autoTable({
      startY: y, margin: { left: M, right: M, top: 40, bottom: 60 },
      rowPageBreak: 'avoid',   // specs are drawn by hand — never split a line across pages
      head: [['#', 'Item Code', 'Description', 'Qty', 'Unit', 'Unit Price', 'Amount']],
      body: d.items.map((it, i)=> [String(i + 1), it.code || '', it.description + (String(it.specs || '').trim() ? '\n' + String(it.specs).trim() : ''), poQtyFmt(it.qty), it.unit || '', poFmt(it.unit_price), poFmt(poRound2(it.qty * it.unit_price))]),
      theme: 'plain',
      styles: { font: F, fontStyle:'normal', fontSize: 8.4, cellPadding: { top: 5.5, bottom: 5.5, left: 6, right: 6 }, textColor: INK, valign:'middle', lineColor: LINE, lineWidth: { bottom: 0.5 } },
      headStyles: { font: F, fontStyle:'bold', fillColor: G, textColor: 255, fontSize: 7.8, halign:'center', lineWidth: 0 },
      alternateRowStyles: { fillColor: [247, 250, 248] },
      columnStyles: {
        0: { halign:'center', cellWidth: 24, textColor: SUB }, 1: { cellWidth: 62, fontSize: 7.4, textColor: SUB }, 2: { cellWidth: 'auto' },
        3: { halign:'right', cellWidth: 46 }, 4: { halign:'center', cellWidth: 42 },
        5: { halign:'right', cellWidth: 70 }, 6: { halign:'right', cellWidth: 80, fontStyle:'bold' }
      },
      didParseCell: (c)=>{
        if(c.section === 'head' && (c.column.index === 3 || c.column.index === 5 || c.column.index === 6)) c.cell.styles.halign = 'right';
        if(c.section === 'head' && c.column.index === 2) c.cell.styles.halign = 'left';
        // Description cell with specs: keep the height for both lines but
        // draw them ourselves (name in normal ink, specs smaller and grey).
        if(c.section === 'body' && c.column.index === 2){
          const it = d.items[c.row.index];
          if(it && String(it.specs || '').trim()){
            c.cell.styles.valign = 'top';
            c.cell.poSpec = { name: it.description, specs: String(it.specs).trim() };
          }
        }
      },
      willDrawCell: (c)=>{
        if(c.section === 'body' && c.column.index === 2 && c.cell.poSpec){
          c.cell.poSpecText = c.cell.text; c.cell.text = [];   // background/borders only
        }
      },
      didDrawCell: (c)=>{
        const sp = c.cell.poSpec;
        if(!(c.section === 'body' && c.column.index === 2 && sp)) return;
        const pad = c.cell.padding('left'), w = c.cell.width - pad - c.cell.padding('right');
        let ty = c.cell.y + c.cell.padding('top') + 7;
        doc.setFont(F, 'normal'); doc.setFontSize(8.4); doc.setTextColor(...INK);
        const nameLines = doc.splitTextToSize(sp.name, w);
        doc.text(nameLines, c.cell.x + pad, ty); ty += nameLines.length * 10.2 + 1;
        doc.setFontSize(7.4); doc.setTextColor(...SUB);
        doc.text(doc.splitTextToSize(sp.specs, w), c.cell.x + pad, ty);
        doc.setTextColor(...INK);
      }
    });
    y = doc.lastAutoTable.finalY + 14;

    // ---- totals (right) + amount in words (left) ----
    const rows = [['Subtotal', money(t.subtotal)]];
    if(t.discount) rows.push(['Less: Discount', '(' + money(t.discount) + ')']);
    if(h.vat_mode === 'exclusive') rows.push(['Add: VAT 12%', money(t.vat)]);
    else if(h.vat_mode === 'inclusive'){ rows.push(['VATable Sales', money(t.vatable)]); rows.push(['VAT 12% (included)', money(t.vat)]); }
    else rows.push(['VAT', 'Non-VAT']);
    if(t.ewt){
      rows.push(['Total Amount', money(t.total), true]);
      rows.push([poEwtLabel(t.ewtRate), '(' + money(t.ewt) + ')']);
    }
    const bandLabel = t.ewt ? 'NET AMOUNT PAYABLE' : 'TOTAL AMOUNT';
    const bandValue = t.ewt ? t.netPayable : t.total;
    const tw = 212, tx = W - M - tw;
    if(y + rows.length * 15 + 40 > H - 190){ doc.addPage(); y = 50; }
    rows.forEach(([l, v, strong], i)=>{
      if(strong){ doc.setDrawColor(...LINE); doc.setLineWidth(0.5); doc.line(tx + 10, y + i * 15, W - M - 10, y + i * 15); }
      if(strong) semi(8.6); else reg(8.6);
      doc.setTextColor(...(strong ? INK : SUB)); doc.text(l, tx + 10, y + 10 + i * 15);
      doc.setTextColor(...INK); doc.text(v, W - M - 10, y + 10 + i * 15, { align:'right' });
    });
    const ty = y + rows.length * 15 + 2;
    doc.setFillColor(...G); doc.roundedRect(tx, ty, tw, 26, 3, 3, 'F');
    semi(t.ewt ? 8 : 9); doc.setTextColor(...MINT_TXT); doc.text(bandLabel, tx + 10, ty + 16.5);
    bold(12.5); doc.setTextColor(255, 255, 255); doc.text(money(bandValue), W - M - 10, ty + 17.5, { align:'right' });
    caps('Amount in words', M, y + 10, G);
    reg(8.6); doc.setTextColor(...INK);
    const words = doc.splitTextToSize(poAmountInWords(bandValue), tx - M - 16);
    doc.text(words, M, y + 24);
    y = Math.max(ty + 26, y + 24 + words.length * 11) + 20;

    // ---- terms ----
    const termsText = d.terms || '';
    if(termsText){
      reg(7.8);
      const LH = 10.2, full = W - M * 2;
      const paras = termsText.split(/\r?\n/).map(line=>{
        const m = /^\s*(\d+[.)]|[-•*])\s+(.*)$/.exec(line);
        if(!m) return { num: '', lines: line.trim() ? doc.splitTextToSize(line.trim(), full) : [''] };
        const indent = Math.max(14, doc.getTextWidth(m[1]) + 6);
        return { num: m[1], indent, lines: doc.splitTextToSize(m[2], full - indent) };
      });
      const needed = paras.reduce((a, p)=> a + p.lines.length * LH + 2, 0);
      if(y + 18 + needed > H - 175){ doc.addPage(); y = 50; }
      caps('Terms & Conditions', M, y, G); y += 13;
      reg(7.8); doc.setTextColor(...SUB);
      paras.forEach(p=>{
        if(p.num){ doc.text(p.num, M, y); doc.text(p.lines, M + p.indent, y); }
        else doc.text(p.lines, M, y);
        y += p.lines.length * LH + 2;
      });
      y += 10;
    }

    // ---- signatures: pinned to the bottom of the LAST page ----
    const sigH = 96, sigTop = H - 46 - sigH;
    if(y > sigTop - 10) doc.addPage();
    y = sigTop;
    doc.setDrawColor(...LINE); doc.setLineWidth(0.5); doc.line(M, y - 12, W - M, y - 12);
    const gap = 18, sw = (W - M * 2 - gap * 2) / 3;
    const sigBlock = (x, caption, person, img, fallback)=>{
      caps(caption, x, y + 6, SUB);
      const lineY = y + 62;
      if(img && img.dataUrl){
        const f = fitImg(img, sw - 16, 44);
        try{ doc.addImage(img.dataUrl, imgFmt(img.dataUrl), x + (sw - f.w) / 2, lineY - f.h + 5, f.w, f.h, undefined, 'FAST'); }catch(e){}
      }
      doc.setDrawColor(70, 76, 72); doc.setLineWidth(0.6); doc.line(x, lineY, x + sw, lineY);
      if(person && person.name){
        semi(8.8); doc.setTextColor(...INK); doc.text(person.name.toUpperCase(), x + sw / 2, lineY + 12, { align:'center' });
        if(person.position){ reg(7.6); doc.setTextColor(...SUB); doc.text(person.position, x + sw / 2, lineY + 23, { align:'center' }); }
      }else{
        reg(7.6); doc.setTextColor(...SUB); doc.text(fallback, x + sw / 2, lineY + 12, { align:'center' });
      }
    };
    sigBlock(M, 'Prepared by', d.prepared, d.prepSig, 'Signature over printed name');
    sigBlock(M + sw + gap, 'Approved by', d.approved, d.apprSig, 'Signature over printed name');
    sigBlock(M + (sw + gap) * 2, 'Conforme — Supplier', null, null, 'Signature over printed name / Date');

    // ---- every page: watermark + footer ----
    const pages = doc.internal.getNumberOfPages();
    for(let pn = 1; pn <= pages; pn++){
      doc.setPage(pn);
      if(d.status !== 'issued'){
        try{
          doc.saveGraphicsState();
          doc.setGState(new doc.GState({ opacity: d.status === 'cancelled' ? 0.14 : 0.07 }));
          doc.setTextColor(...(d.status === 'cancelled' ? [200, 30, 30] : [40, 40, 40]));
          bold(92);
          doc.text(d.status === 'cancelled' ? 'CANCELLED' : 'DRAFT', W / 2, H / 2 + 70, { align:'center', angle: 35 });
          doc.restoreGraphicsState();
        }catch(e){}
      }
      doc.setDrawColor(...LINE); doc.setLineWidth(0.5); doc.line(M, H - 32, W - M, H - 32);
      reg(7); doc.setTextColor(...SUB);
      doc.text([h.po_no || 'Draft PO', co.company_name].filter(Boolean).join('   •   ') +
        (d.status === 'cancelled' && h.cancel_reason ? '   •   Cancelled: ' + h.cancel_reason : ''), M, H - 20);
      doc.text('Page ' + pn + ' of ' + pages, W - M, H - 20, { align:'right' });
    }
    doc.setTextColor(0, 0, 0);
    return doc;
  }

  // Preview overlay sits under the PO sheet by default (z-index 50) —
  // lift it while a PO is shown, drop it back when it closes.
  new MutationObserver(()=>{
    if(!$('previewOverlay').classList.contains('open')) $('previewOverlay').style.zIndex = '';
  }).observe($('previewOverlay'), { attributes:true, attributeFilter:['class'] });

  async function poShowPdf(mode){
    try{
      const d = await poPdfData();
      if(!d.items.length){ toast('Add at least one item first'); return; }
      const doc = await poBuildPdf(d);
      const supplierPart = d.supplier ? '-' + String(poSupplierName(d.supplier)).replace(/[^A-Za-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 30) : '';
      const filename = (d.header.po_no || 'Draft-PO') + supplierPart + (d.status === 'issued' ? '' : '-' + d.status.toUpperCase()) + '.pdf';
      const title = 'Purchase Order ' + (d.header.po_no || '(draft)');
      $('previewOverlay').querySelector('h3').textContent = title;
      $('previewOkBtn').textContent = 'Close';
      $('previewOverlay').style.zIndex = '99';
      $('previewOverlay').classList.add('open');
      await renderPdfPreview(doc, filename, title);
    }catch(e){
      console.error('PO pdf failed', e);
      toast('Couldn\u2019t build the PDF: ' + (e && e.message ? e.message : e));
    }
  }

  // ---------- PO settings: company + logo ----------
  function poSetTab(tab){
    $$('#poSetTabs [data-po-tab]').forEach(b=> b.classList.toggle('active', b.dataset.poTab === tab));
    $('poSetPaneCompany').style.display = tab === 'company' ? '' : 'none';
    $('poSetPaneSignatories').style.display = tab === 'signatories' ? '' : 'none';
    if(tab === 'signatories') poRenderSigList();
  }
  $('poSetTabs').addEventListener('click', (e)=>{ const b = e.target.closest('[data-po-tab]'); if(b) poSetTab(b.dataset.poTab); });
  $('poSettingsBtn').addEventListener('click', async ()=>{
    if(!(await ensureCloud())){ toast('Not connected'); return; }
    try{ await Promise.all([poLoadSettings(), poLoadSignatories()]); }
    catch(e){ purchFail('Couldn\u2019t load PO settings: ', e); return; }
    poFillSettingsForm();
    poResetSigForm();
    poSetTab('company');
    $('poSettingsOverlay').classList.add('open');
  });
  $('poSettingsClose').addEventListener('click', ()=>{
    $('poSettingsOverlay').classList.remove('open');
    // an open PO editor picks up new signatories / defaults
    if(poEditorVisible()){ poFillSignatorySelects(); poRenderSigHint(); }
  });
  function poFillSettingsForm(){
    const d = poSettingsData || {};
    $('poCoName').value = d.company_name || ''; $('poCoTagline').value = d.tagline || '';
    $('poCoAddress').value = d.address || ''; $('poCoPhone').value = d.phone || '';
    $('poCoEmail').value = d.email || ''; $('poCoTin').value = d.tin || '';
    $('poCoVat').value = d.vat_mode || 'exclusive'; $('poCoDeliverTo').value = d.deliver_to || '';
    $('poCoTerms').value = d.terms || ''; $('poHeaderStyle').value = d.header_style || 'green';
    poRenderLogoPreview();
  }
  async function poRenderLogoPreview(){
    const d = poSettingsData || {};
    const box = $('poLogoPreview');
    const style = $('poHeaderStyle').value || 'green';
    box.classList.toggle('green', style === 'green');
    const img = d.logo_path ? await poLogoForStyle(await poLoadImage(d.logo_path), style) : await poDefaultLogo(style);
    box.innerHTML = img ? '<img alt="Logo" src="' + img.dataUrl + '">' : '<span style="font-size:12px;color:var(--text-muted);">Logo unavailable</span>';
    $('poLogoResetBtn').style.display = d.logo_path ? '' : 'none';
  }
  $('poHeaderStyle').addEventListener('change', poRenderLogoPreview);
  async function poSaveSettings(patch, msg){
    if(!(await purchEnsureSession())) return false;
    const data = Object.assign({}, poSettingsData || {}, patch);
    try{
      const { error } = await db.from('po_settings').upsert({ id: 1, data }, { onConflict: 'id' });
      if(error) throw error;
      poSettingsData = data;
      if(msg) toast(msg);
      return true;
    }catch(e){ purchFail('Couldn\u2019t save PO settings: ', e); return false; }
  }
  $('poSettingsSaveBtn').addEventListener('click', async ()=>{
    const btn = $('poSettingsSaveBtn'); btn.disabled = true;
    try{
      await poSaveSettings({
        company_name: $('poCoName').value.trim(), tagline: $('poCoTagline').value.trim(),
        address: $('poCoAddress').value.trim(), phone: $('poCoPhone').value.trim(),
        email: $('poCoEmail').value.trim(), tin: $('poCoTin').value.trim(),
        vat_mode: $('poCoVat').value, deliver_to: $('poCoDeliverTo').value.trim(),
        terms: $('poCoTerms').value.trim(), header_style: $('poHeaderStyle').value
      }, 'PO settings saved');
    }finally{ btn.disabled = false; }
  });

  // Draws an uploaded image onto a canvas (downscaled) and returns a PNG blob.
  function poLoadFileImage(file){
    return new Promise((res, rej)=>{
      const url = URL.createObjectURL(file);
      const im = new Image();
      im.onload = ()=>{ URL.revokeObjectURL(url); res(im); };
      im.onerror = ()=>{ URL.revokeObjectURL(url); rej(new Error('That file isn\u2019t a readable image')); };
      im.src = url;
    });
  }
  function poCanvasToBlob(c){ return new Promise(res=> c.toBlob(res, 'image/png')); }
  async function poImageToPng(file, maxW, maxH){
    const im = await poLoadFileImage(file);
    const r = Math.min(1, maxW / im.naturalWidth, maxH / im.naturalHeight);
    const c = document.createElement('canvas');
    c.width = Math.max(1, Math.round(im.naturalWidth * r)); c.height = Math.max(1, Math.round(im.naturalHeight * r));
    c.getContext('2d').drawImage(im, 0, 0, c.width, c.height);
    return c;
  }
  async function poUploadPng(canvas, folder){
    const blob = await poCanvasToBlob(canvas);
    const path = folder + '/' + Date.now() + '-' + Math.random().toString(36).slice(2, 8) + '.png';
    const { error } = await db.storage.from(PO_BUCKET).upload(path, blob, { contentType:'image/png', upsert:false });
    if(error) throw error;
    const dataUrl = canvas.toDataURL('image/png');
    poImgCache.set(path, { dataUrl, w: canvas.width, h: canvas.height });
    return path;
  }
  $('poLogoUploadBtn').addEventListener('click', ()=>{ $('poLogoFile').value = ''; $('poLogoFile').click(); });
  $('poLogoFile').addEventListener('change', async ()=>{
    const file = $('poLogoFile').files && $('poLogoFile').files[0];
    if(!file) return;
    if(file.size > 8 * 1024 * 1024){ toast('Logo file is over 8 MB'); return; }
    if(!(await purchEnsureSession())) return;
    const btn = $('poLogoUploadBtn'); btn.disabled = true; btn.textContent = 'Uploading…';
    try{
      const canvas = poPrepareLogo(await poImageToPng(file, 900, 320));
      const path = await poUploadPng(canvas, 'logo');
      // The old file is kept on purpose: issued POs still point at it.
      if(await poSaveSettings({ logo_path: path }, 'Logo updated')) poRenderLogoPreview();
    }catch(e){ purchFail('Logo upload failed: ', e); }
    finally{ btn.disabled = false; btn.textContent = 'Upload logo'; }
  });
  $('poLogoResetBtn').addEventListener('click', async ()=>{
    if(!confirm('Go back to the default AWES logo? (Issued POs keep the logo they were issued with.)')) return;
    if(await poSaveSettings({ logo_path: '' }, 'Using the default AWES logo')) poRenderLogoPreview();
  });

  // ---------- signatories ----------
  let poSigCanvas = null;          // processed signature waiting to be saved
  const poSigThumbs = new Map();   // path -> dataUrl (list thumbnails)

  // Turns a photo/scan of a signature into a clean PNG: paper → transparent,
  // then crops to the ink. Background level comes from the brighter pixels
  // so shadows/grey paper in phone photos are handled.
  function poCleanSignature(src){
    const c = document.createElement('canvas');
    c.width = src.width; c.height = src.height;
    const ctx = c.getContext('2d');
    ctx.drawImage(src, 0, 0);
    const img = ctx.getImageData(0, 0, c.width, c.height);
    const px = img.data;
    const lums = [];
    for(let i = 0; i < px.length; i += 16) lums.push(0.299 * px[i] + 0.587 * px[i + 1] + 0.114 * px[i + 2]);
    lums.sort((a, b)=> a - b);
    const bg = lums[Math.floor(lums.length * 0.9)] || 255;
    const cut = bg * 0.78, soft = bg * 0.55;
    let minX = c.width, minY = c.height, maxX = -1, maxY = -1;
    for(let y = 0; y < c.height; y++){
      for(let x = 0; x < c.width; x++){
        const i = (y * c.width + x) * 4;
        if(px[i + 3] === 0) continue;
        const l = 0.299 * px[i] + 0.587 * px[i + 1] + 0.114 * px[i + 2];
        let a;
        if(l >= cut) a = 0;
        else if(l <= soft) a = 255;
        else a = Math.round(255 * (cut - l) / (cut - soft));
        px[i + 3] = Math.min(px[i + 3], a);
        if(px[i + 3] > 40){ if(x < minX) minX = x; if(x > maxX) maxX = x; if(y < minY) minY = y; if(y > maxY) maxY = y; }
      }
    }
    ctx.putImageData(img, 0, 0);
    if(maxX < 0) return null;   // nothing but paper
    const pad = 8;
    minX = Math.max(0, minX - pad); minY = Math.max(0, minY - pad);
    maxX = Math.min(c.width - 1, maxX + pad); maxY = Math.min(c.height - 1, maxY + pad);
    const out = document.createElement('canvas');
    out.width = maxX - minX + 1; out.height = maxY - minY + 1;
    out.getContext('2d').drawImage(c, minX, minY, out.width, out.height, 0, 0, out.width, out.height);
    return out;
  }
  async function poProcessSigFile(){
    const file = $('poSigFile').files && $('poSigFile').files[0];
    poSigCanvas = null;
    if(!file){ poShowSigPreview(null); return; }
    if(file.size > 10 * 1024 * 1024){ toast('Signature image is over 10 MB'); $('poSigFile').value = ''; return; }
    try{
      let c = await poImageToPng(file, 1200, 600);
      if($('poSigClean').checked){
        const cleaned = poCleanSignature(c);
        if(!cleaned){ toast('No signature found in that image — try a darker pen or better light'); poShowSigPreview(null); return; }
        c = cleaned;
      }
      poSigCanvas = c;
      poShowSigPreview(c.toDataURL('image/png'));
    }catch(e){ toast(e.message || 'Couldn\u2019t read that image'); }
  }
  $('poSigFile').addEventListener('change', poProcessSigFile);
  $('poSigClean').addEventListener('change', poProcessSigFile);
  function poShowSigPreview(url){
    $('poSigPreview').innerHTML = url ? '<img alt="Signature" src="' + url + '">' : '<span>Signature preview</span>';
  }
  function poResetSigForm(){
    $('poSigId').value = ''; $('poSigName').value = ''; $('poSigPosition').value = '';
    $('poSigFile').value = ''; poSigCanvas = null; poShowSigPreview(null);
    $('poSigFormTitle').textContent = 'Add a signatory';
    $('poSigCancelBtn').style.display = 'none';
  }
  async function poRenderSigList(){
    const list = $('poSigList');
    if(!poSignatories.length){ list.innerHTML = '<div class="empty-state" style="padding:14px;">No signatories yet — add the people who prepare and approve POs below.</div>'; return; }
    list.innerHTML = poSignatories.map(s=>
      '<div class="sp-row" data-id="' + escapeHtml(s.id) + '"' + (s.is_active ? '' : ' style="opacity:.55;"') + '><div class="sp-row-top"><div style="min-width:0;">' +
        '<div class="sp-row-title">' + escapeHtml(s.name) + (s.is_active ? '' : ' <span class="sp-tag danger">Inactive</span>') + (s.signature_path ? '' : ' <span class="sp-tag warn">No signature</span>') + '</div>' +
        '<div class="sp-row-sub">' + escapeHtml(s.position || '') + '</div></div>' +
        '<div data-thumb="' + escapeHtml(s.signature_path || '') + '"></div></div>' +
      '<div class="user-card-actions"><button type="button" data-sact="edit" class="primary">Edit / New signature</button>' +
        '<button type="button" data-sact="toggle">' + (s.is_active ? 'Deactivate' : 'Reactivate') + '</button></div></div>'
    ).join('');
    for(const el of list.querySelectorAll('[data-thumb]')){
      const path = el.dataset.thumb;
      if(!path) continue;
      const img = await poLoadImage(path);
      if(img && el.isConnected) el.innerHTML = '<img class="po-sig-thumb" alt="" src="' + img.dataUrl + '">';
    }
  }
  $('poSigList').addEventListener('click', async (e)=>{
    const b = e.target.closest('[data-sact]');
    if(!b) return;
    const s = poSignatories.find(x=> x.id === b.closest('.sp-row').dataset.id);
    if(!s) return;
    if(b.dataset.sact === 'edit'){
      $('poSigId').value = s.id; $('poSigName').value = s.name; $('poSigPosition').value = s.position || '';
      $('poSigFile').value = ''; poSigCanvas = null;
      const img = s.signature_path ? await poLoadImage(s.signature_path) : null;
      poShowSigPreview(img ? img.dataUrl : null);
      $('poSigFormTitle').textContent = 'Edit ' + s.name + ' — upload a new file to replace the signature';
      $('poSigCancelBtn').style.display = '';
      $('poSigName').focus();
      return;
    }
    if(!(await purchEnsureSession())) return;
    b.disabled = true;
    try{
      const { error } = await db.from('po_signatories').update({ is_active: !s.is_active }).eq('id', s.id);
      if(error) throw error;
      await poLoadSignatories(); poRenderSigList();
    }catch(err){ b.disabled = false; purchFail('Couldn\u2019t update signatory: ', err); }
  });
  $('poSigCancelBtn').addEventListener('click', poResetSigForm);
  $('poSigSaveBtn').addEventListener('click', async ()=>{
    const name = $('poSigName').value.trim();
    if(!name){ toast('Enter the signatory\u2019s name'); $('poSigName').focus(); return; }
    const id = $('poSigId').value;
    if(!id && !poSigCanvas && !confirm('Save ' + name + ' without a signature? The PDF will show a blank line until one is uploaded.')) return;
    if(!(await purchEnsureSession())) return;
    const btn = $('poSigSaveBtn'); btn.disabled = true; btn.textContent = 'Saving…';
    try{
      const row = { name, position: $('poSigPosition').value.trim() };
      // A new file always gets a new path — issued POs keep pointing at the old one.
      if(poSigCanvas) row.signature_path = await poUploadPng(poSigCanvas, 'signatures');
      const res = id ? await db.from('po_signatories').update(row).eq('id', id)
                     : await db.from('po_signatories').insert(row);
      if(res.error) throw res.error;
      toast(id ? 'Signatory updated' : 'Signatory added');
      poResetSigForm();
      await poLoadSignatories(); poRenderSigList();
    }catch(e){ purchFail('Couldn\u2019t save signatory: ', e); }
    finally{ btn.disabled = false; btn.textContent = 'Save Signatory'; }
  });


  // =====================================================================
  // Purchasing — Material Requisition (MRF)
  //
  // Technician side (purchPanel_myRequests): create / edit / submit own
  // requests for their job orders.  Admin side (purchPanel_requisitions):
  // review (approve with adjusted qty, return, reject), then fulfil
  // approved lines via Purchase Orders or "tech buys".
  //
  // The DATABASE enforces who may do what (migration
  // 20260923_06_material_requisitions.sql): numbering, ownership, job-order
  // assignment, locking, and the automatic approved⇄fulfilled switch.
  // =====================================================================

  const MR_URGENCY = { normal:'Normal', urgent:'Urgent', emergency:'Emergency' };
  const MR_STATUS_LABEL = { draft:'Draft', submitted:'Submitted', returned:'Returned', approved:'Approved', rejected:'Rejected', cancelled:'Cancelled', fulfilled:'Fulfilled' };
  const MR_PHOTO_BUCKET = 'requisition-photos';

  function mrDate(d){ return d ? poDateLong(String(d).slice(0, 10)) : '—'; }
  function mrWhen(ts){ return ts ? new Date(ts).toLocaleString('en-PH', { month:'short', day:'numeric', hour:'numeric', minute:'2-digit' }) : ''; }
  function mrQty(n){ return n == null || n === '' ? '—' : poQtyFmt(n); }
  function mrLineCovered(it){
    if(Number(it.qty_approved) === 0 && it.qty_approved !== null) return true;
    if(it.fulfilled_by === 'tech_buy') return true;
    if(it.fulfilled_by === 'stock') return true;   // set by the database once fully issued
    return !!(it.po_id && it.purchase_orders && it.purchase_orders.status !== 'cancelled');
  }
  // Techs don't need the admin's price list — just the active catalog.
  let mrCatalog = [];
  async function mrLoadCatalog(){
    if(currentUser && currentUser.role === 'admin' && typeof mtCache !== 'undefined' && mtCache.length){ mrCatalog = mtCache.filter(m=> m.isActive); return; }
    const { data, error } = await db.from('materials').select('id, code, name, family, unit, brand, specs, category').eq('is_active', true).order('name');
    if(error) throw error;
    mrCatalog = (data || []).map(r=> ({ id:r.id, code:r.code, name:r.name, family:r.family || '', unit:r.unit, brand:r.brand || '', specs:r.specs || {}, category:r.category }));
  }
  // Shared item-name autocomplete (technician form)
  function mrSuggest(input, onPick){
    const host = input.closest('.po-item-desc');
    let box = host.querySelector('.po-suggest');
    const words = input.value.trim().toLowerCase().split(/\s+/).filter(Boolean);
    if(!words.length){ if(box) box.remove(); return; }
    const hits = mrCatalog.filter(m=>{
      const hay = [m.code, m.name, m.family, m.brand, mtSpecText(m.specs)].join(' ').toLowerCase();
      return words.every(w=> hay.includes(w));
    }).slice(0, 8);
    if(!hits.length){ if(box) box.remove(); return; }
    if(!box){ box = document.createElement('div'); box.className = 'po-suggest'; host.appendChild(box); }
    box.innerHTML = hits.map((m, i)=> '<button type="button" data-pick="' + escapeHtml(m.id) + '"' + (i === 0 ? ' class="hl"' : '') + '><span><b>' +
      escapeHtml(m.code) + '</b> ' + escapeHtml(m.name) + '</span><span class="s-price">' + escapeHtml(m.unit) + '</span></button>').join('');
    box.onclick = (e)=>{ const b = e.target.closest('[data-pick]'); if(b) onPick(b.dataset.pick); };
  }

  // =====================================================================
  // TECHNICIAN
  // =====================================================================
  let mrtCache = [];
  let mrtEditing = null;     // header row, or null for a new request
  let mrtItems = [];
  let mrtJobs = [];
  let mrtUrgency = 'normal';
  let mrtPhotoFile = null;
  let mrtDirty = false;
  let mrtKey = 0;
  let mrtChannel = null;

  async function mrtShow(){
    if(mrtFormVisible()){
      if(mrtDirty && !confirm('Discard the changes you haven\u2019t saved?')) return;
      mrtShowList();
    }
    mrtRealtimeStart();
    await mrtLoadList();
  }
  function mrtFormVisible(){ return $('mrtFormView').style.display !== 'none'; }
  function mrtShowList(){ $('mrtFormView').style.display = 'none'; $('mrtListView').style.display = ''; mrtEditing = null; mrtDirty = false; window.scrollTo({ top:0 }); }
  function mrtShowForm(){ $('mrtListView').style.display = 'none'; $('mrtFormView').style.display = ''; window.scrollTo({ top:0 }); }

  async function mrtLoadList(opts){
    const silent = !!(opts && opts.silent);
    const list = $('mrtList');
    if(!silent) list.innerHTML = '<div class="empty-state">Loading…</div>';
    if(!(await ensureCloud())){ if(!silent) list.innerHTML = '<div class="empty-state">Not connected — requests need a connection.</div>'; return false; }
    try{
      const { data, error } = await db.from('material_requisitions')
        .select('id, mrf_no, status, urgency, job_order, needed_by, created_at, review_note, material_requisition_items(count)')
        .eq('requested_by', currentUser.id).order('created_at', { ascending:false });
      if(error) throw error;
      mrtCache = data || [];
      mrtRenderList();
      return true;
    }catch(e){
      console.error('load my requests failed', describeCloudError(e));
      if(!silent) list.innerHTML = '<div class="empty-state">' + (purchIsAuthError(e) ? PURCH_EXPIRED_HTML : 'Couldn\u2019t load your requests: ' + escapeHtml(describeCloudError(e))) + '</div>';
      return false;
    }
  }
  function mrtRenderList(){
    const list = $('mrtList');
    if(!mrtCache.length){ list.innerHTML = '<div class="empty-state">No requests yet. Tap <b>+ New Material Request</b>.</div>'; return; }
    list.innerHTML = mrtCache.map(r=>{
      const n = r.material_requisition_items && r.material_requisition_items[0] ? r.material_requisition_items[0].count : 0;
      const jo = r.job_order ? r.job_order.id + (r.job_order.custName ? ' · ' + r.job_order.custName : '') : 'No job order';
      return '<button type="button" class="mt-row" data-id="' + escapeHtml(r.id) + '"><div class="mt-row-main">' +
        '<div class="mt-row-title"><span class="mt-code">' + escapeHtml(r.mrf_no) + '</span><span class="po-status ' + r.status + '">' + escapeHtml(MR_STATUS_LABEL[r.status] || r.status) + '</span>' +
        (r.urgency !== 'normal' ? ' <span class="mr-urg ' + r.urgency + '">' + escapeHtml(MR_URGENCY[r.urgency]) + '</span>' : '') + '</div>' +
        '<div class="sp-row-sub">' + escapeHtml(jo) + ' · ' + n + ' item' + (n === 1 ? '' : 's') + (r.needed_by ? ' · needed ' + escapeHtml(mrDate(r.needed_by)) : '') + '</div>' +
        (r.status === 'returned' || r.status === 'rejected' ? '<div class="sp-row-sub" style="color:#9A6212;">Admin: ' + escapeHtml(r.review_note) + '</div>' : '') +
        '</div></button>';
    }).join('');
  }
  $('mrtList').addEventListener('click', (e)=>{
    if(e.target.closest('[data-purch-reauth]')){ purchReauth().then(ok=>{ if(ok) mrtLoadList(); }); return; }
    const row = e.target.closest('.mt-row'); if(row) mrtOpen(row.dataset.id);
  });
  $('mrtNewBtn').addEventListener('click', ()=> mrtOpen(null));
  $('mrtBackBtn').addEventListener('click', ()=>{
    if(mrtDirty && !confirm('Discard the changes you haven\u2019t saved?')) return;
    mrtShowList(); mrtLoadList();
  });

  async function mrtOpen(id){
    if(!(await ensureCloud())){ toast('Not connected'); return; }
    try{
      const jobsP = (typeof dtListForWorker === 'function' ? dtListForWorker(currentUser.id) : Promise.resolve([])).catch(()=> []);
      await mrLoadCatalog();
      let h = null, items = [];
      if(id){
        const r = await db.from('material_requisitions').select('*').eq('id', id);
        if(r.error) throw r.error;
        h = r.data && r.data[0];
        if(!h){ toast('That request no longer exists'); mrtLoadList(); return; }
        const it = await db.from('material_requisition_items').select('*').eq('mr_id', id).order('line_no');
        if(it.error) throw it.error;
        items = it.data || [];
      }
      const jobs = await jobsP;
      mrtJobs = jobs.filter(j=> !(typeof dtIsTerminal === 'function' && dtIsTerminal(j)));
      mrtEditing = h;
      mrtItems = items.map(r=> ({ key: ++mrtKey, id: r.id, material_id: r.material_id, code: r.code, description: r.description, unit: r.unit, qty: r.qty_requested, qty_approved: r.qty_approved }));
      if(!mrtItems.length) mrtItems.push(mrtBlank());
      const keepJob = h && h.job_order_id;
      $('mrtJob').innerHTML = '<option value="">No job order (office / stock)</option>' +
        mrtJobs.map(j=> '<option value="' + escapeHtml(j.id) + '">' + escapeHtml(j.id + (j.custName ? ' — ' + j.custName : '')) + '</option>').join('') +
        (keepJob && !mrtJobs.some(j=> j.id === keepJob) ? '<option value="' + escapeHtml(keepJob) + '">' + escapeHtml(keepJob + (h.job_order && h.job_order.custName ? ' — ' + h.job_order.custName : '')) + '</option>' : '');
      $('mrtJob').value = keepJob || (mrtJobs.length === 1 && !h ? mrtJobs[0].id : '');
      $('mrtNeeded').value = h && h.needed_by ? h.needed_by : '';
      mrtUrgency = h ? h.urgency : 'normal';
      $$('#mrtUrgency [data-u]').forEach(b=> b.classList.toggle('on', b.dataset.u === mrtUrgency));
      $('mrtDeliver').value = h && h.deliver_to ? h.deliver_to : 'Job site';
      $('mrtPurpose').value = h ? h.purpose : '';
      $('mrtPhoto').value = ''; mrtPhotoFile = null;
      $('mrtPhotoPreview').innerHTML = '';
      if(h && h.photo_path){
        db.storage.from(MR_PHOTO_BUCKET).download(h.photo_path).then(async ({ data })=>{
          if(data) $('mrtPhotoPreview').innerHTML = '<img alt="Photo" src="' + await poBlobToDataUrl(data) + '">';
        }).catch(()=>{});
      }
      mrtApplyMode();
      mrtRenderItems();
      mrtRenderJobInfo();
      mrtDirty = false;
      mrtShowForm();
    }catch(e){ purchFail('Couldn\u2019t open the request: ', e); }
  }
  function mrtBlank(){ return { key: ++mrtKey, id: null, material_id: null, code: '', description: '', unit: '', qty: '', qty_approved: null }; }
  function mrtEditable(){ return !mrtEditing || mrtEditing.status === 'draft' || mrtEditing.status === 'returned'; }
  function mrtApplyMode(){
    const h = mrtEditing, st = h ? h.status : 'draft', ed = mrtEditable();
    $('mrtTitle').textContent = h ? h.mrf_no : 'New Request';
    $('mrtStatus').className = 'po-status ' + st;
    $('mrtStatus').textContent = h ? (MR_STATUS_LABEL[st] || st) : 'unsaved';
    const note = $('mrtNote');
    const msg = !h ? '' : st === 'returned' ? 'Returned for changes — Admin: ' + h.review_note + '. Edit and submit again.'
      : st === 'rejected' ? 'Rejected — Admin: ' + h.review_note
      : st === 'submitted' ? 'Submitted ' + mrWhen(h.submitted_at) + ' — waiting for admin review.'
      : st === 'approved' ? 'Approved by ' + (h.reviewer_name || 'admin') + ' ' + mrWhen(h.reviewed_at) + '. Quantities below are what was approved.'
      : st === 'fulfilled' ? 'Fulfilled — all approved items are being purchased.'
      : st === 'cancelled' ? 'Cancelled.' : '';
    note.textContent = msg;
    note.className = 'po-locked-note' + (st === 'rejected' || st === 'cancelled' ? ' cancelled' : '');
    note.style.display = msg ? '' : 'none';
    $$('#mrtFormView input, #mrtFormView select, #mrtFormView textarea').forEach(el=>{ el.disabled = !ed; });
    $$('#mrtUrgency button').forEach(b=>{ b.disabled = !ed; });
    $('mrtAddItem').style.display = ed ? '' : 'none';
    const b = (a, l, c)=> '<button type="button" class="btn ' + (c || 'btn-secondary') + '" data-mrt="' + a + '">' + l + '</button>';
    let html = '';
    if(ed) html = b('save', 'Save Draft') + b('submit', st === 'returned' ? 'Submit Again' : 'Submit Request', 'btn-primary');
    if(h && ['draft', 'submitted', 'returned'].includes(st)) html += b(st === 'draft' ? 'delete' : 'cancel', st === 'draft' ? 'Delete Draft' : 'Cancel Request', 'danger');
    $('mrtActions').innerHTML = html;
    $('mrtActions').style.display = html ? '' : 'none';
  }
  function mrtRenderJobInfo(){
    const j = mrtJobs.find(x=> x.id === $('mrtJob').value) || (mrtEditing && mrtEditing.job_order && mrtEditing.job_order.id === $('mrtJob').value ? mrtEditing.job_order : null);
    $('mrtJobInfo').textContent = j ? [j.custName, j.siteAddress].filter(Boolean).join(' · ') : (mrtJobs.length ? '' : 'You have no active job orders — you can still request for the office or stock.');
  }
  $('mrtJob').addEventListener('change', mrtRenderJobInfo);
  $('mrtUrgency').addEventListener('click', (e)=>{
    const b = e.target.closest('[data-u]'); if(!b || b.disabled) return;
    mrtUrgency = b.dataset.u; mrtDirty = true;
    $$('#mrtUrgency [data-u]').forEach(x=> x.classList.toggle('on', x === b));
  });
  $('mrtFormView').addEventListener('input', ()=>{ mrtDirty = true; });

  function mrtRenderItems(){
    const ed = mrtEditable(), dis = ed ? '' : ' disabled';
    const reviewed = mrtEditing && ['approved', 'fulfilled'].includes(mrtEditing.status);
    $('mrtItems').innerHTML = mrtItems.map((it, i)=>{
      const cut = reviewed && it.qty_approved != null && Number(it.qty_approved) !== Number(it.qty);
      return '<div class="mr-item" data-key="' + it.key + '"><div class="po-no">' + (i + 1) + '</div>' +
        '<div class="po-item-desc"><input type="text" data-f="description" value="' + escapeHtml(it.description) + '" placeholder="' + (i === 0 ? 'e.g. copper tube 3/8' : 'Item') + '" autocomplete="off"' + dis + '>' +
        '<div class="po-item-code">' + (it.material_id ? escapeHtml(it.code) : (it.description ? 'not in list' : '')) + '</div></div>' +
        '<input type="text" class="num mrq" data-f="qty" inputmode="decimal" placeholder="Qty" value="' + escapeHtml(it.qty === '' || it.qty == null ? '' : String(it.qty)) + '"' + dis + '>' +
        '<input type="text" class="mru" data-f="unit" list="mtUnitList" placeholder="Unit" value="' + escapeHtml(it.unit || '') + '"' + dis + '>' +
        (ed ? '<button type="button" class="po-rm" data-rm="1" title="Remove">&minus;</button>' : '<span></span>') +
        (reviewed ? '<div class="mr-appr' + (cut ? ' reduced' : '') + '">Approved: ' + mrQty(it.qty_approved) + ' ' + escapeHtml(it.unit || '') + (cut ? ' (you asked for ' + mrQty(it.qty) + ')' : '') + '</div>' : '') +
      '</div>';
    }).join('');
  }
  function mrtItemByEl(el){ const r = el.closest('.mr-item'); return r ? mrtItems.find(x=> String(x.key) === r.dataset.key) : null; }
  $('mrtItems').addEventListener('input', (e)=>{
    const it = mrtItemByEl(e.target), f = e.target.dataset.f;
    if(!it || !f) return;
    if(f === 'description'){
      it.description = e.target.value;
      if(it.material_id){ const m = mrCatalog.find(x=> x.id === it.material_id); if(!m || m.name !== it.description){ it.material_id = null; it.code = ''; } }
      e.target.closest('.mr-item').querySelector('.po-item-code').textContent = it.material_id ? it.code : (it.description ? 'not in list' : '');
      mrSuggest(e.target, (mid)=>{
        const m = mrCatalog.find(x=> x.id === mid); if(!m) return;
        Object.assign(it, { material_id: m.id, code: m.code, description: m.name, unit: m.unit });
        mrtRenderItems();
        const q = $('mrtItems').querySelector('.mr-item[data-key="' + it.key + '"] [data-f="qty"]'); if(q) q.focus();
      });
    }else if(f === 'qty') it.qty = e.target.value.trim() === '' ? '' : (poNum(e.target.value) == null ? e.target.value : poNum(e.target.value));
    else it[f] = e.target.value;
  });
  $('mrtItems').addEventListener('keydown', (e)=>{
    const box = e.target.closest('.po-item-desc') && e.target.closest('.po-item-desc').querySelector('.po-suggest');
    if(!box) return;
    const btns = Array.from(box.querySelectorAll('[data-pick]'));
    let i = btns.findIndex(b=> b.classList.contains('hl'));
    if(e.key === 'ArrowDown' || e.key === 'ArrowUp'){ e.preventDefault(); if(i >= 0) btns[i].classList.remove('hl'); i = e.key === 'ArrowDown' ? Math.min(btns.length - 1, i + 1) : Math.max(0, i - 1); if(btns[i]) btns[i].classList.add('hl'); }
    else if(e.key === 'Enter' && i >= 0){ e.preventDefault(); btns[i].click(); }
    else if(e.key === 'Escape') box.remove();
  });
  $('mrtItems').addEventListener('focusout', (e)=>{
    setTimeout(()=>{ const d = e.target.closest && e.target.closest('.po-item-desc'); if(d && !d.contains(document.activeElement)){ const b = d.querySelector('.po-suggest'); if(b) b.remove(); } }, 180);
  });
  $('mrtItems').addEventListener('click', (e)=>{
    if(!e.target.closest('[data-rm]')) return;
    const it = mrtItemByEl(e.target);
    mrtItems = mrtItems.filter(x=> x !== it);
    if(!mrtItems.length) mrtItems.push(mrtBlank());
    mrtDirty = true; mrtRenderItems();
  });
  $('mrtAddItem').addEventListener('click', ()=>{
    mrtItems.push(mrtBlank()); mrtRenderItems();
    const all = $('mrtItems').querySelectorAll('[data-f="description"]'); if(all.length) all[all.length - 1].focus();
  });
  $('mrtPhoto').addEventListener('change', async ()=>{
    const f = $('mrtPhoto').files && $('mrtPhoto').files[0];
    mrtPhotoFile = null; $('mrtPhotoPreview').innerHTML = '';
    if(!f) return;
    try{
      const c = await poImageToPng(f, 1400, 1400);        // shrink big phone photos
      mrtPhotoFile = await new Promise(res=> c.toBlob(res, 'image/jpeg', 0.82));
      $('mrtPhotoPreview').innerHTML = '<img alt="Photo" src="' + c.toDataURL('image/jpeg', 0.7) + '">';
      mrtDirty = true;
    }catch(e){ toast(e.message || 'Couldn\u2019t read that photo'); }
  });

  function mrtValidate(forSubmit){
    const rows = mrtItems.filter(it=> String(it.description || '').trim() || (it.qty !== '' && it.qty != null));
    for(let i = 0; i < rows.length; i++){
      const it = rows[i];
      if(!String(it.description || '').trim()) return 'Item ' + (i + 1) + ': what do you need?';
      const q = Number(it.qty);
      if(it.qty === '' || !isFinite(q) || q <= 0) return 'Item ' + (i + 1) + ' (' + it.description + '): enter how many';
    }
    if(forSubmit && !rows.length) return 'Add at least one item';
    return null;
  }
  async function mrtSave(submit){
    const err = mrtValidate(submit);
    if(err){ toast(err); return null; }
    if(!(await ensureCloud())){ toast('Not connected — can\u2019t save'); return null; }
    if(!(await purchEnsureSession())) return null;
    const header = {
      job_order_id: $('mrtJob').value || null, needed_by: $('mrtNeeded').value || null, urgency: mrtUrgency,
      deliver_to: $('mrtDeliver').value, purpose: $('mrtPurpose').value.trim()
    };
    try{
      let id = mrtEditing && mrtEditing.id;
      if(mrtPhotoFile){
        const path = currentUser.id + '/' + Date.now() + '.jpg';
        const up = await db.storage.from(MR_PHOTO_BUCKET).upload(path, mrtPhotoFile, { contentType:'image/jpeg', upsert:false });
        if(up.error) throw up.error;
        header.photo_path = path;
      }
      if(id){
        purchMarkOwn(id);
        const { error } = await db.from('material_requisitions').update(header).eq('id', id);
        if(error) throw error;
      }else{
        const { data, error } = await db.from('material_requisitions').insert(header).select('*').single();
        if(error) throw error;
        id = data.id; mrtEditing = data; purchMarkOwn(id);
      }
      const clean = mrtItems.filter(it=> String(it.description || '').trim());
      clean.forEach(it=>{ if(!it.id) it.id = poUuid(); });
      if(clean.length){
        const { error } = await db.from('material_requisition_items').upsert(clean.map((it, i)=> ({
          id: it.id, mr_id: id, line_no: i + 1, material_id: it.material_id || null, code: it.code || '',
          description: it.description.trim(), unit: (it.unit || '').trim(), qty_requested: Number(it.qty)
        })), { onConflict:'id' });
        if(error) throw error;
      }
      let del = db.from('material_requisition_items').delete().eq('mr_id', id);
      if(clean.length) del = del.not('id', 'in', '(' + clean.map(it=> it.id).join(',') + ')');
      const dr = await del; if(dr.error) throw dr.error;
      if(submit){
        purchMarkOwn(id);
        const { error } = await db.from('material_requisitions').update({ status:'submitted' }).eq('id', id);
        if(error) throw error;
      }
      const h = await db.from('material_requisitions').select('*').eq('id', id);
      if(h.error) throw h.error;
      mrtEditing = h.data[0];
      mrtPhotoFile = null; mrtDirty = false;
      if(submit){
        const who = currentUser.name || 'A technician';
        notifyAdmins('New material request', mrtEditing.mrf_no + ' from ' + who + ' — ' + clean.length + ' item' + (clean.length === 1 ? '' : 's') +
          (mrtEditing.urgency !== 'normal' ? ' (' + MR_URGENCY[mrtEditing.urgency].toUpperCase() + ')' : ''), 'mrf-' + mrtEditing.id);
        toast(mrtEditing.mrf_no + ' submitted — admin has been notified');
        mrtShowList(); mrtLoadList();
      }else{
        toast(mrtEditing.mrf_no + ' saved as draft');
        mrtApplyMode(); mrtRenderItems();
      }
      return mrtEditing;
    }catch(e){ purchFail('Couldn\u2019t save the request: ', e); return null; }
  }
  $('mrtActions').addEventListener('click', async (e)=>{
    const b = e.target.closest('[data-mrt]'); if(!b) return;
    const act = b.dataset.mrt;
    $$('#mrtActions .btn').forEach(x=>{ x.disabled = true; });
    try{
      if(act === 'save') await mrtSave(false);
      else if(act === 'submit'){ if(confirm('Submit this request to the admin? You can\u2019t edit it after submitting unless it\u2019s returned to you.')) await mrtSave(true); }
      else if(act === 'cancel' || act === 'delete'){
        if(!confirm(act === 'delete' ? 'Delete this draft?' : 'Cancel ' + mrtEditing.mrf_no + '?')) return;
        if(!(await purchEnsureSession())) return;
        purchMarkOwn(mrtEditing.id);
        const q = act === 'delete' ? db.from('material_requisitions').delete().eq('id', mrtEditing.id)
                                   : db.from('material_requisitions').update({ status:'cancelled' }).eq('id', mrtEditing.id);
        const { error } = await q; if(error) throw error;
        toast(act === 'delete' ? 'Draft deleted' : 'Request cancelled');
        mrtShowList(); mrtLoadList();
      }
    }catch(err){ purchFail('Couldn\u2019t update the request: ', err); }
    finally{ $$('#mrtActions .btn').forEach(x=>{ x.disabled = false; }); }
  });

  // Live status for the technician (own requests only — RLS + filter).
  function mrtRealtimeStart(){
    if(mrtChannel || !db || typeof db.channel !== 'function' || !currentUser) return;
    purchSetLive('connecting');
    mrtChannel = db.channel('mrf-tech-' + currentUser.id)
      .on('postgres_changes', { event:'*', schema:'public', table:'material_requisitions', filter:'requested_by=eq.' + currentUser.id }, (p)=>{
        const row = p && (p.new && p.new.id ? p.new : p.old);
        if(row && purchIsOwn(row.id)) return;
        clearTimeout(mrtChannel._t);
        mrtChannel._t = setTimeout(async ()=>{
          if($('purchPanel_myRequests').style.display === 'none') return;
          if(mrtFormVisible()){
            // reopen read-only views; never overwrite what the tech is typing
            if(mrtEditing && row && row.id === mrtEditing.id && !mrtDirty) mrtOpen(mrtEditing.id);
          }else mrtLoadList({ silent:true });
        }, 400);
      })
      .subscribe((st)=>{ purchSetLive(st === 'SUBSCRIBED' ? 'on' : (st === 'CHANNEL_ERROR' || st === 'TIMED_OUT' || st === 'CLOSED') ? 'off' : 'connecting'); });
  }
  function mrtRealtimeTeardown(){
    if(mrtChannel && db){ try{ db.removeChannel(mrtChannel); }catch(e){} }
    mrtChannel = null;
  }

  // =====================================================================
  // ADMIN
  // =====================================================================
  let mrCache = [];
  let mrOpenRow = null;      // header being reviewed
  let mrOpenItems = [];
  let mrQtyDraft = {};       // item id -> adjusted qty while reviewing
  let mrSelected = new Set();

  function mrDetailVisible(){ return $('mrDetailView').style.display !== 'none'; }
  async function mrShow(){
    if(mrDetailVisible()) mrShowListView();
    if(await mrLoadList()) mrRenderList();
  }
  function mrShowListView(){ $('mrDetailView').style.display = 'none'; $('mrListView').style.display = ''; $('purchasingView').classList.remove('po-wide'); mrOpenRow = null; }
  function mrShowDetailView(){ $('mrListView').style.display = 'none'; $('mrDetailView').style.display = ''; $('purchasingView').classList.add('po-wide'); window.scrollTo({ top:0 }); }

  async function mrLoadList(opts){
    const silent = !!(opts && opts.silent);
    const list = $('mrList');
    if(!silent) list.innerHTML = '<div class="empty-state">Loading…</div>';
    if(!(await ensureCloud())){ if(!silent) list.innerHTML = '<div class="empty-state">Not connected.</div>'; return false; }
    try{
      const { data, error } = await db.from('material_requisitions')
        .select('id, mrf_no, status, urgency, requester_name, job_order, needed_by, submitted_at, created_at, material_requisition_items(count)')
        .neq('status', 'draft').order('created_at', { ascending:false });
      if(error) throw error;
      mrCache = data || [];
      return true;
    }catch(e){
      console.error('load requisitions failed', describeCloudError(e));
      if(silent) return false;
      list.innerHTML = '<div class="empty-state">' + (purchIsAuthError(e) ? PURCH_EXPIRED_HTML
        : /42P01|does not exist/.test(describeCloudError(e)) ? 'The requisition tables aren\u2019t in the database yet — run migration 20260923_06_material_requisitions.sql first.'
        : 'Couldn\u2019t load requisitions: ' + escapeHtml(describeCloudError(e))) + '</div>';
      return false;
    }
  }
  function mrRenderList(){
    const f = $('mrFilterStatus').value, q = ($('mrSearch').value || '').trim().toLowerCase();
    const counts = mrCache.reduce((a, r)=>{ a[r.status] = (a[r.status] || 0) + 1; return a; }, {});
    $('mrCount').textContent = [counts.submitted ? counts.submitted + ' to review' : '', counts.approved ? counts.approved + ' to fulfil' : ''].filter(Boolean).join(' · ');
    const urgRank = { emergency:0, urgent:1, normal:2 };
    const rows = mrCache.filter(r=>{
      if(f === 'open' && !['submitted', 'approved'].includes(r.status)) return false;
      if(f && f !== 'open' && r.status !== f) return false;
      if(!q) return true;
      return [r.mrf_no, r.requester_name, r.job_order && r.job_order.id, r.job_order && r.job_order.custName].join(' ').toLowerCase().includes(q);
    }).sort((a, b)=> (a.status === 'submitted' ? 0 : 1) - (b.status === 'submitted' ? 0 : 1) || urgRank[a.urgency] - urgRank[b.urgency] || String(b.submitted_at || b.created_at).localeCompare(String(a.submitted_at || a.created_at)));
    const list = $('mrList');
    if(!rows.length){ list.innerHTML = '<div class="empty-state">' + (mrCache.length ? 'Nothing here.' : 'No requests yet. Technicians create them from their home screen.') + '</div>'; return; }
    list.innerHTML = rows.map(r=>{
      const n = r.material_requisition_items && r.material_requisition_items[0] ? r.material_requisition_items[0].count : 0;
      const jo = r.job_order ? r.job_order.id + (r.job_order.custName ? ' · ' + r.job_order.custName : '') : 'No job order';
      return '<button type="button" class="mt-row" data-id="' + escapeHtml(r.id) + '"><div class="mt-row-main">' +
        '<div class="mt-row-title"><span class="mt-code">' + escapeHtml(r.mrf_no) + '</span>' + escapeHtml(r.requester_name || 'Technician') +
        ' <span class="po-status ' + r.status + '">' + escapeHtml(MR_STATUS_LABEL[r.status]) + '</span>' +
        (r.urgency !== 'normal' ? ' <span class="mr-urg ' + r.urgency + '">' + escapeHtml(MR_URGENCY[r.urgency]) + '</span>' : '') + '</div>' +
        '<div class="sp-row-sub">' + escapeHtml(jo) + ' · ' + n + ' item' + (n === 1 ? '' : 's') + (r.needed_by ? ' · needed ' + escapeHtml(mrDate(r.needed_by)) : '') +
        (r.submitted_at ? ' · sent ' + escapeHtml(mrWhen(r.submitted_at)) : '') + '</div></div></button>';
    }).join('');
  }
  $('mrSearch').addEventListener('input', mrRenderList);
  $('mrFilterStatus').addEventListener('change', mrRenderList);
  $('mrList').addEventListener('click', (e)=>{
    if(e.target.closest('[data-purch-reauth]')){ purchReauth().then(ok=>{ if(ok) mrShow(); }); return; }
    const row = e.target.closest('.mt-row'); if(row) mrOpen(row.dataset.id);
  });
  $('mrBackBtn').addEventListener('click', ()=>{ mrShowListView(); mrShow(); });
  $('mrStaleReload').addEventListener('click', ()=>{ if(mrOpenRow) mrOpen(mrOpenRow.id); });

  async function mrOpen(id){
    try{
      if(!mtCache.length) await mtLoad({ silent:true }).catch(()=>{});
      const [h, it] = await Promise.all([
        db.from('material_requisitions').select('*').eq('id', id),
        db.from('material_requisition_items').select('*, purchase_orders(id, po_no, status)').eq('mr_id', id).order('line_no')
      ]);
      if(h.error) throw h.error; if(it.error) throw it.error;
      mrOpenRow = h.data && h.data[0];
      if(!mrOpenRow){ toast('That request no longer exists'); mrShow(); return; }
      mrOpenItems = it.data || [];
      mrQtyDraft = {}; mrSelected = new Set();
      $('mrStaleNote').style.display = 'none';
      mrRenderDetail();
      mrShowDetailView();
    }catch(e){ purchFail('Couldn\u2019t open the request: ', e); }
  }
  function mrRenderDetail(){
    const h = mrOpenRow, st = h.status;
    $('mrTitle').textContent = h.mrf_no;
    $('mrStatus').className = 'po-status ' + st; $('mrStatus').textContent = MR_STATUS_LABEL[st];
    $('mrUrgency').className = 'mr-urg ' + h.urgency; $('mrUrgency').textContent = h.urgency !== 'normal' ? MR_URGENCY[h.urgency] : '';
    const jo = h.job_order;
    const kv = (k, v, wide)=> '<div' + (wide ? ' class="wide"' : '') + '><div class="k">' + k + '</div><div class="v">' + (v || '—') + '</div></div>';
    $('mrInfo').innerHTML =
      kv('Requested by', escapeHtml(h.requester_name || 'Technician') + (h.submitted_at ? '<div class="sp-row-sub">' + escapeHtml(mrWhen(h.submitted_at)) + '</div>' : '')) +
      kv('Job order', jo ? '<b>' + escapeHtml(jo.id) + '</b><div class="sp-row-sub">' + escapeHtml([jo.custName, jo.siteAddress].filter(Boolean).join(' · ')) + '</div>' : 'None — office / stock') +
      kv('Needed by', escapeHtml(mrDate(h.needed_by))) +
      kv('Deliver to', escapeHtml(h.deliver_to)) +
      (h.purpose ? kv('Purpose / notes', escapeHtml(h.purpose), true) : '') +
      (h.review_note ? kv(st === 'rejected' ? 'Rejected — reason' : st === 'returned' ? 'Returned — reason' : 'Admin note', escapeHtml(h.review_note), true) : '') +
      (h.reviewed_at ? kv('Reviewed', escapeHtml((h.reviewer_name || 'Admin') + ' · ' + mrWhen(h.reviewed_at))) : '') +
      (h.photo_path ? '<div class="wide"><div class="k">Photo</div><div class="mr-photo" id="mrPhotoBox">Loading photo…</div></div>' : '');
    if(h.photo_path){
      db.storage.from(MR_PHOTO_BUCKET).download(h.photo_path).then(async ({ data })=>{
        const box = document.getElementById('mrPhotoBox'); if(box)   // re-created per open, so not via the cached $()
        box.innerHTML = data ? '<img alt="Photo" src="' + await poBlobToDataUrl(data) + '">' : 'Photo unavailable';
      }).catch(()=>{});
    }
    const reviewing = st === 'submitted';
    const fulfilling = st === 'approved' || st === 'fulfilled';
    const head = '<thead><tr>' + (fulfilling ? '<th style="width:28px;"><input type="checkbox" id="mrSelAll" title="Select all open lines"></th>' : '') +
      '<th>#</th><th>Item</th><th class="num">Requested</th><th class="num">' + (reviewing ? 'Approve' : 'Approved') + '</th><th>Unit</th>' + (fulfilling ? '<th>Fulfilment</th>' : '') + '</tr></thead>';
    const body = mrOpenItems.map((it, i)=>{
      const covered = mrLineCovered(it);
      const appr = it.qty_approved;
      const cut = appr != null && Number(appr) !== Number(it.qty_requested);
      let cov = '';
      if(fulfilling){
        if(Number(appr) === 0) cov = '<span class="cov ok">Not needed</span>';
        else if(it.fulfilled_by === 'tech_buy') cov = '<span class="cov ok">Tech buys</span>';
        else if(it.fulfilled_by === 'stock') cov = '<span class="cov ok">Issued from stock</span>';
        else if(Number(it.qty_issued) > 0) cov = '<span class="cov open">' + mrQty(it.qty_issued) + ' of ' + mrQty(appr) + ' issued from stock</span>';
        else if(it.po_id && it.purchase_orders) cov = '<span class="cov ' + (it.purchase_orders.status === 'cancelled' ? 'open' : 'ok') + '"><a data-open-po="' + escapeHtml(it.po_id) + '">' +
          escapeHtml(it.purchase_orders.po_no) + '</a> ' + escapeHtml(it.purchase_orders.status) + (it.purchase_orders.status === 'cancelled' ? ' — needs a new PO' : '') + '</span>';
        else cov = '<span class="cov open">Not yet</span>';
      }
      return '<tr data-id="' + escapeHtml(it.id) + '">' +
        (fulfilling ? '<td>' + (covered ? '' : '<input type="checkbox" class="mr-sel"' + (mrSelected.has(it.id) ? ' checked' : '') + '>') + '</td>' : '') +
        '<td>' + (i + 1) + '</td><td><b>' + escapeHtml(it.description) + '</b><div class="sp-row-sub">' + (it.material_id ? escapeHtml(it.code) : 'typed by the technician — not linked to the catalog') + (it.note ? ' · ' + escapeHtml(it.note) : '') + '</div>' +
          (!it.material_id && ['submitted', 'approved'].includes(st) && !it.po_id ? '<div class="po-item-desc mr-link"><input type="text" data-link="1" placeholder="Link to catalog item…" autocomplete="off"></div>' : '') + '</td>' +
        '<td class="num">' + mrQty(it.qty_requested) + '</td>' +
        '<td class="num">' + (reviewing
          ? '<input type="text" class="mr-qty" inputmode="decimal" value="' + escapeHtml(String(mrQtyDraft[it.id] != null ? mrQtyDraft[it.id] : (appr != null ? appr : it.qty_requested))) + '">'
          : '<span class="' + (cut ? 'reduced' : '') + '">' + mrQty(appr) + '</span>') + '</td>' +
        '<td>' + escapeHtml(it.unit || '') + '</td>' + (fulfilling ? '<td>' + cov + '</td>' : '') + '</tr>';
    }).join('');
    $('mrItemsTable').innerHTML = head + '<tbody>' + body + '</tbody>';
    $('mrItemsHint').textContent = reviewing ? 'Lower a quantity to approve less than requested, or set it to 0 if the item isn\u2019t needed.'
      : fulfilling ? (mrOpenItems.some(it=> !mrLineCovered(it)) ? 'Tick the open lines, then create Purchase Orders for them or mark them as bought by the technician.' : 'Every approved line is covered.') : '';
    const b = (a, l, c)=> '<button type="button" class="btn ' + (c || 'btn-secondary') + '" data-mr="' + a + '">' + l + '</button>';
    let html = '';
    if(reviewing) html = b('return', 'Return for Changes') + b('reject', 'Reject', 'danger') + b('approve', 'Approve', 'btn-primary');
    else if(fulfilling){
      if(mrOpenItems.some(it=> !mrLineCovered(it))) html = b('techbuy', 'Mark: Tech Buys') + b('createpo', 'Create PO(s)', 'btn-primary');
      html += b('pdf', 'View PDF');
      if(st === 'approved') html += b('cancel', 'Cancel Request', 'danger');
    }else html = b('pdf', 'View PDF');
    $('mrActions').innerHTML = html;
  }
  // Link a technician's typed line to a Materials Database item (needed
  // before it can go on a Purchase Order, which accepts catalog items only)
  // keyboard for the link box: ↑/↓ to move, Enter to pick, Esc to close
  $('mrItemsTable').addEventListener('keydown', (e)=>{
    if(!e.target.dataset || !e.target.dataset.link) return;
    const box = e.target.closest('.po-item-desc').querySelector('.po-suggest'); if(!box) return;
    const btns = Array.from(box.querySelectorAll('[data-pick]')); let i = btns.findIndex(b=> b.classList.contains('hl'));
    if(e.key === 'ArrowDown' || e.key === 'ArrowUp'){ e.preventDefault(); if(i >= 0) btns[i].classList.remove('hl'); i = e.key === 'ArrowDown' ? Math.min(btns.length - 1, i + 1) : Math.max(0, i - 1); if(btns[i]) btns[i].classList.add('hl'); }
    else if(e.key === 'Enter' && i >= 0){ e.preventDefault(); btns[i].click(); }
    else if(e.key === 'Escape') box.remove();
  });
  $('mrItemsTable').addEventListener('input', (e)=>{
    if(!e.target.dataset.link) return;
    const id = e.target.closest('tr').dataset.id;
    mrCatalog = mtCache.filter(m=> m.isActive);
    mrSuggest(e.target, async (mid)=>{
      const m = mtCache.find(x=> x.id === mid); if(!m) return;
      if(!(await purchEnsureSession())) return;
      const { error } = await db.from('material_requisition_items').update({ material_id: m.id, code: m.code }).eq('id', id);
      if(error){ purchFail('Couldn\u2019t link it: ', error); return; }
      toast('Linked to ' + m.code + ' ' + m.name);
      mrOpen(mrOpenRow.id);
    });
  });
  $('mrItemsTable').addEventListener('input', (e)=>{
    if(!e.target.classList.contains('mr-qty')) return;
    mrQtyDraft[e.target.closest('tr').dataset.id] = e.target.value;
  });
  $('mrItemsTable').addEventListener('change', (e)=>{
    if(e.target.id === 'mrSelAll'){
      mrOpenItems.filter(it=> !mrLineCovered(it)).forEach(it=>{ if(e.target.checked) mrSelected.add(it.id); else mrSelected.delete(it.id); });
      $$('#mrItemsTable .mr-sel').forEach(x=>{ x.checked = e.target.checked; });
    }else if(e.target.classList.contains('mr-sel')){
      const id = e.target.closest('tr').dataset.id;
      if(e.target.checked) mrSelected.add(id); else mrSelected.delete(id);
    }
  });
  $('mrItemsTable').addEventListener('click', (e)=>{
    const a = e.target.closest('[data-open-po]'); if(!a) return;
    const poId = a.dataset.openPo;
    showPurchasingView('purchaseOrders');
    setTimeout(()=> poOpen(poId), 50);
  });

  $('mrActions').addEventListener('click', async (e)=>{
    const b = e.target.closest('[data-mr]'); if(!b) return;
    const act = b.dataset.mr;
    $$('#mrActions .btn').forEach(x=>{ x.disabled = true; });
    try{
      if(act === 'approve') await mrApprove();
      else if(act === 'return' || act === 'reject') await mrReturnOrReject(act);
      else if(act === 'techbuy') await mrMarkTechBuy();
      else if(act === 'createpo') await mrCreatePos();
      else if(act === 'pdf') await mrShowPdf();
      else if(act === 'cancel'){
        if(!confirm('Cancel ' + mrOpenRow.mrf_no + '? Lines already on Purchase Orders stay on them.')) return;
        await mrSetStatus({ status:'cancelled' }, 'Request cancelled');
      }
    }finally{ $$('#mrActions .btn').forEach(x=>{ x.disabled = false; }); }
  });
  async function mrSetStatus(patch, msg){
    if(!(await purchEnsureSession())) return false;
    try{
      purchMarkOwn(mrOpenRow.id);
      const { error } = await db.from('material_requisitions').update(patch).eq('id', mrOpenRow.id);
      if(error) throw error;
      toast(msg);
      await mrOpen(mrOpenRow.id);
      mrLoadList({ silent:true }).then(ok=>{ if(ok) mrRenderList(); });
      return true;
    }catch(err){ purchFail('Couldn\u2019t update the request: ', err); return false; }
  }
  async function mrApprove(){
    // validate adjusted quantities
    const updates = [];
    for(const it of mrOpenItems){
      const raw = mrQtyDraft[it.id];
      if(raw == null) continue;
      const n = spParseMoney(raw);
      if(n == null || Number.isNaN(n)){ toast(it.description + ': enter a quantity (0 = not needed)'); return; }
      if(n > Number(it.qty_requested)){ toast(it.description + ': can\u2019t approve more than requested (' + mrQty(it.qty_requested) + ')'); return; }
      if(n !== Number(it.qty_approved != null ? it.qty_approved : it.qty_requested)) updates.push({ id: it.id, qty_approved: n });
    }
    const reduced = updates.filter(u=> u.qty_approved < Number(mrOpenItems.find(x=> x.id === u.id).qty_requested)).length;
    if(!confirm('Approve ' + mrOpenRow.mrf_no + (reduced ? ' with ' + reduced + ' reduced quantit' + (reduced === 1 ? 'y' : 'ies') : ' as requested') + '? The technician will be notified.')) return;
    if(!(await purchEnsureSession())) return;
    try{
      for(const u of updates){
        const { error } = await db.from('material_requisition_items').update({ qty_approved: u.qty_approved }).eq('id', u.id);
        if(error) throw error;
      }
    }catch(err){ purchFail('Couldn\u2019t save the quantities: ', err); return; }
    if(await mrSetStatus({ status:'approved' }, mrOpenRow.mrf_no + ' approved')){
      notifyUser(mrOpenRow.requested_by, 'Material request approved', mrOpenRow.mrf_no + (reduced ? ' was approved with some quantities reduced.' : ' was approved.'), 'mrf-' + mrOpenRow.id);
    }
  }
  async function mrReturnOrReject(kind){
    const reason = prompt(kind === 'reject' ? 'Reject ' + mrOpenRow.mrf_no + '. Reason (the technician will see this):' : 'Return ' + mrOpenRow.mrf_no + ' to the technician for changes. What should they change?');
    if(reason === null) return;
    if(!reason.trim()){ toast('Please give a reason'); return; }
    const ok = await mrSetStatus({ status: kind === 'reject' ? 'rejected' : 'returned', review_note: reason.trim() }, mrOpenRow.mrf_no + (kind === 'reject' ? ' rejected' : ' returned to the technician'));
    if(ok) notifyUser(mrOpenRow.requested_by, kind === 'reject' ? 'Material request rejected' : 'Material request needs changes', mrOpenRow.mrf_no + ': ' + reason.trim(), 'mrf-' + mrOpenRow.id);
  }
  function mrSelectedOpen(){ return mrOpenItems.filter(it=> mrSelected.has(it.id) && !mrLineCovered(it)); }
  async function mrMarkTechBuy(){
    const sel = mrSelectedOpen();
    if(!sel.length){ toast('Tick the lines the technician will buy'); return; }
    if(!confirm('Mark ' + sel.length + ' line' + (sel.length === 1 ? '' : 's') + ' as bought by ' + (mrOpenRow.requester_name || 'the technician') + ' (cash advance)?')) return;
    if(!(await purchEnsureSession())) return;
    try{
      purchMarkOwn(mrOpenRow.id);
      const { error } = await db.from('material_requisition_items').update({ fulfilled_by:'tech_buy' }).in('id', sel.map(it=> it.id));
      if(error) throw error;
      toast('Marked as tech buys');
      notifyUser(mrOpenRow.requested_by, 'Materials: please purchase', mrOpenRow.mrf_no + ': ' + sel.length + ' item' + (sel.length === 1 ? '' : 's') + ' approved for you to buy (cash advance).', 'mrf-' + mrOpenRow.id);
      await mrOpen(mrOpenRow.id);
    }catch(err){ purchFail('Couldn\u2019t update the lines: ', err); }
  }

  // Groups the ticked lines by each catalog item's PREFERRED supplier and
  // creates one draft PO per supplier. Free-text lines, or items with no
  // preferred supplier, go on one extra draft with no supplier chosen yet.
  async function mrCreatePos(){
    const sel = mrSelectedOpen();
    if(!sel.length){ toast('Tick the lines to put on Purchase Orders'); return; }
    const unlinked = sel.filter(it=> !it.material_id);
    if(unlinked.length){ toast('Link ' + unlinked.map(it=> '“' + it.description + '”').join(', ') + ' to a catalog item first (the box under each line)'); return; }
    if(!(await ensureCloud())){ toast('Not connected'); return; }
    try{ await Promise.all([mtLoad({ silent:true }), poLoadSettings(), poLoadSuppliers()]); }
    catch(e){ purchFail('Couldn\u2019t load suppliers / prices: ', e); return; }
    const groups = new Map();   // supplierId|'' -> lines
    sel.forEach(it=>{
      const m = it.material_id && mtCache.find(x=> x.id === it.material_id);
      const pref = m && m.prices.find(p=> p.is_preferred && p.is_active && p.suppliers && p.suppliers.is_active !== false);
      const key = pref ? pref.suppliers.id : '';
      if(!groups.has(key)) groups.set(key, []);
      groups.get(key).push(it);
    });
    const names = Array.from(groups.keys()).map(k=> (k ? poSupplierName(poSuppliers.find(s=> s.id === k)) : 'No preferred supplier (choose in the PO)') + ': ' + groups.get(k).length + ' line' + (groups.get(k).length === 1 ? '' : 's'));
    if(!confirm('Create ' + groups.size + ' draft Purchase Order' + (groups.size === 1 ? '' : 's') + '?\n\n' + names.join('\n') + '\n\nThey open as drafts so you can check prices before issuing.')) return;
    if(!(await purchEnsureSession())) return;
    const set = poSettingsData || {};
    const jo = mrOpenRow.job_order;
    const deliverTo = mrOpenRow.deliver_to === 'Job site' && jo && jo.siteAddress ? jo.siteAddress + (jo.custName ? ' (' + jo.custName + ')' : '') : (set.deliver_to || '');
    const created = [];
    try{
      for(const [supplierId, lines] of groups){
        const sup = poSuppliers.find(s=> s.id === supplierId);
        const header = {
          supplier_id: supplierId || null, reference: mrOpenRow.mrf_no + (jo ? ' / ' + jo.id + (jo.custName ? ' — ' + jo.custName : '') : ''),
          deliver_to: deliverTo, payment_terms: sup ? (sup.payment_terms || '') : '', vat_mode: set.vat_mode || 'exclusive',
          delivery_date: mrOpenRow.needed_by || null
        };
        const { data: po, error } = await db.from('purchase_orders').insert(header).select('id, po_no').single();
        if(error) throw error;
        const rows = lines.map((it, i)=>{
          const p = it.material_id ? poPriceFor(it.material_id, supplierId || null) : null;
          return { id: poUuid(), po_id: po.id, line_no: i + 1, material_id: it.material_id || null, code: it.code || '', description: it.description,
            unit: (p && p.unitFromPrice) || it.unit || '',
            // only what hasn't already been issued from stock
            qty: Number(it.qty_approved != null ? it.qty_approved : it.qty_requested) - Number(it.qty_issued || 0), unit_price: p ? p.price : 0 };
        });
        const ir = await db.from('purchase_order_items').insert(rows); if(ir.error) throw ir.error;
        purchMarkOwn(mrOpenRow.id);
        const lr = await db.from('material_requisition_items').update({ fulfilled_by:'po', po_id: po.id }).in('id', lines.map(it=> it.id));
        if(lr.error) throw lr.error;
        created.push(po.po_no);
      }
      toast('Created ' + created.join(', ') + ' — open them from the Fulfilment column');
      await mrOpen(mrOpenRow.id);
    }catch(err){
      purchFail('Couldn\u2019t create the Purchase Orders' + (created.length ? ' (made ' + created.join(', ') + ' before the error)' : '') + ': ', err);
      if(created.length) mrOpen(mrOpenRow.id);
    }
  }

  // ---------- MRF PDF (same look as the PO) ----------
  async function mrShowPdf(){
    try{
      await loadAwesScript('jspdf', awesLibs.jspdf);
      await loadAwesScript('autotable', awesLibs.autotable);
      await poLoadSettings().catch(()=>{});
      const co = poSettingsData || {};
      const style = co.header_style || 'green';
      const logo = co.logo_path ? await poLoadImage(co.logo_path).then(img=> poLogoForStyle(img, style)) : await poDefaultLogo(style);
      const fonts = await poLoadFonts();
      const { jsPDF } = window.jspdf;
      const doc = new jsPDF({ orientation:'p', unit:'pt', format:'a4', compress:true });
      let F = 'helvetica', FS = ['helvetica', 'bold'], FB = ['helvetica', 'bold'];
      if(fonts){ try{
        doc.addFileToVFS('Inter-Regular.ttf', fonts.regular); doc.addFont('Inter-Regular.ttf', 'Inter', 'normal');
        doc.addFileToVFS('Inter-SemiBold.ttf', fonts.semibold); doc.addFont('Inter-SemiBold.ttf', 'Inter', 'bold');
        doc.addFileToVFS('Inter-Bold.ttf', fonts.bold); doc.addFont('Inter-Bold.ttf', 'InterBold', 'normal');
        F = 'Inter'; FS = ['Inter', 'bold']; FB = ['InterBold', 'normal'];
      }catch(e){} }
      const reg = (s)=>{ doc.setFont(F, 'normal'); doc.setFontSize(s); };
      const semi = (s)=>{ doc.setFont(FS[0], FS[1]); doc.setFontSize(s); };
      const bold = (s)=>{ doc.setFont(FB[0], FB[1]); doc.setFontSize(s); };
      const W = doc.internal.pageSize.getWidth(), H = doc.internal.pageSize.getHeight(), M = 36;
      const G = [21, 77, 52], SUB = [96, 108, 101], INK = [28, 34, 30], LINE = [216, 223, 219];
      const green = style !== 'white', ink = green ? [255, 255, 255] : INK;
      const h = mrOpenRow, jo = h.job_order;
      const headH = 104;
      if(green){ doc.setFillColor(...G); doc.rect(0, 0, W, headH, 'F'); } else { doc.setFillColor(...G); doc.rect(0, headH - 4, W, 4, 'F'); }
      if(logo && logo.w){ const r = Math.min(150 / logo.w, 44 / logo.h); try{ doc.addImage(logo.dataUrl, 'PNG', M, 16, logo.w * r, logo.h * r, 'mr-logo', 'FAST'); }catch(e){} }
      semi(9.5); doc.setTextColor(...ink); doc.text(co.company_name || '', M, 78);
      reg(7.4); doc.text(doc.splitTextToSize(co.address || '', 320).slice(0, 1), M, 90);
      bold(16); doc.text('MATERIAL REQUISITION', W - M, 36, { align:'right' });
      semi(10.5); doc.text(h.mrf_no, W - M, 54, { align:'right' });
      reg(8.8); doc.text('Status: ' + MR_STATUS_LABEL[h.status].toUpperCase() + (h.urgency !== 'normal' ? '   •   ' + MR_URGENCY[h.urgency].toUpperCase() : ''), W - M, 68, { align:'right' });
      let y = headH + 20;
      const info = [['Requested by', (h.requester_name || '') + (h.submitted_at ? '  (' + mrWhen(h.submitted_at) + ')' : '')],
        ['Job order', jo ? jo.id + (jo.custName ? ' — ' + jo.custName : '') : 'None (office / stock)'], ['Site', jo && jo.siteAddress],
        ['Needed by', h.needed_by ? mrDate(h.needed_by) : 'Not specified'], ['Deliver to', h.deliver_to], ['Purpose', h.purpose]].filter(r=> r[1]);
      info.forEach(([k, v])=>{
        reg(7.8); doc.setTextColor(...SUB); doc.text(k, M, y);
        reg(9); doc.setTextColor(...INK); const lines = doc.splitTextToSize(String(v), W - M * 2 - 90); doc.text(lines, M + 90, y);
        y += lines.length * 11 + 3;
      });
      const showFul = h.status === 'approved' || h.status === 'fulfilled';
      doc.autoTable({
        startY: y + 8, margin: { left:M, right:M, bottom:60 },
        head: [['#', 'Item', 'Code', 'Requested', 'Approved', 'Unit'].concat(showFul ? ['Fulfilment'] : [])],
        body: mrOpenItems.map((it, i)=> [String(i + 1), it.description, it.code || '', mrQty(it.qty_requested), mrQty(it.qty_approved), it.unit || '']
          .concat(showFul ? [Number(it.qty_approved) === 0 ? 'Not needed' : it.fulfilled_by === 'tech_buy' ? 'Tech buys' : it.fulfilled_by === 'stock' ? 'Issued from stock' : it.purchase_orders ? it.purchase_orders.po_no + (it.purchase_orders.status === 'cancelled' ? ' (cancelled)' : '') : 'Open'] : [])),
        theme:'plain',
        styles: { font:F, fontSize:8.4, cellPadding:{ top:5, bottom:5, left:6, right:6 }, textColor:INK, lineColor:LINE, lineWidth:{ bottom:0.5 } },
        headStyles: { font:F, fontStyle:'bold', fillColor:G, textColor:255, fontSize:7.8 },
        alternateRowStyles: { fillColor:[247, 250, 248] },
        columnStyles: { 0:{ cellWidth:22, halign:'center' }, 2:{ cellWidth:60, textColor:SUB, fontSize:7.4 }, 3:{ halign:'right', cellWidth:60 }, 4:{ halign:'right', cellWidth:60 }, 5:{ halign:'center', cellWidth:40 } }
      });
      // signatures pinned at the bottom
      const sigTop = H - 46 - 80, sw = (W - M * 2 - 36) / 3;
      if(doc.lastAutoTable.finalY > sigTop - 10) doc.addPage();
      [['Requested by', h.requester_name], ['Reviewed / approved by', h.reviewer_name], ['Received by', '']].forEach(([cap, name], i)=>{
        const x = M + i * (sw + 18);
        semi(6.8); doc.setTextColor(...SUB); doc.text(cap.toUpperCase(), x, sigTop);
        doc.setDrawColor(70, 76, 72); doc.setLineWidth(0.6); doc.line(x, sigTop + 50, x + sw, sigTop + 50);
        semi(8.6); doc.setTextColor(...INK); doc.text(name ? name.toUpperCase() : 'Signature over printed name / Date', x + sw / 2, sigTop + 62, { align:'center' });
      });
      const pages = doc.internal.getNumberOfPages();
      for(let p = 1; p <= pages; p++){
        doc.setPage(p); reg(7); doc.setTextColor(...SUB);
        doc.text(h.mrf_no + '   •   ' + (co.company_name || ''), M, H - 20);
        doc.text('Page ' + p + ' of ' + pages, W - M, H - 20, { align:'right' });
      }
      const filename = h.mrf_no + '.pdf', title = 'Material Requisition ' + h.mrf_no;
      $('previewOverlay').querySelector('h3').textContent = title;
      $('previewOkBtn').textContent = 'Close';
      $('previewOverlay').style.zIndex = '99';
      $('previewOverlay').classList.add('open');
      await renderPdfPreview(doc, filename, title);
    }catch(e){ console.error('MRF pdf failed', e); toast('Couldn\u2019t build the PDF: ' + (e && e.message ? e.message : e)); }
  }


  // =====================================================================
  // Inventory — Phase 1 (migration 20260923_07_inventory_foundation.sql)
  //
  //   Stock on Hand   admin: qty + average cost + value per warehouse,
  //                   opening balances, item history, count adjustments
  //   Warehouses      admin: add / edit / deactivate
  //   Projects        admin: big jobs grouping job orders; material cost
  //   Warehouse Stock storekeeper: quantities only, own warehouses only
  //   Users & Roles   the Storekeeper setting = warehouse assignments
  //
  // The DATABASE keeps balances and average cost (trigger on every
  // stock_movements insert), refuses negative stock, and never lets a
  // movement be edited or deleted. Storekeepers read *_qty views that
  // carry no money at all.
  // =====================================================================

  const INV_TYPE_LABEL = { opening:'Opening', adjustment:'Adjustment', receipt:'Received', issue:'Issued', 'return':'Returned',
    transfer_out:'Transfer out', transfer_in:'Transfer in', write_off:'Written off' };
  const INV_PRJ_STATUS = { planning:'Planning', active:'Active', on_hold:'On hold', completed:'Completed', cancelled:'Cancelled' };

  let invWarehouses = [];
  let invBalances = [];          // stock_balances rows
  let invProfileNames = new Map();

  function invMoney(n){ return '₱' + poFmt(n); }
  function invQty(n){ return poQtyFmt(n); }
  function invWh(id){ return invWarehouses.find(w=> w.id === id); }
  function invWhLabel(id){ const w = invWh(id); return w ? w.code + ' · ' + w.name : '—'; }
  function invMissingTables(e){ return /42P01|does not exist|schema cache/.test(describeCloudError(e)); }
  const INV_MIGRATION_MSG = 'The inventory tables aren\u2019t in the database yet — run migration 20260923_07_inventory_foundation.sql in Supabase first.';

  async function invLoadWarehouses(){
    const { data, error } = await db.from('warehouses').select('*').order('code');
    if(error) throw error;
    invWarehouses = data || [];
    return invWarehouses;
  }
  async function invLoadNames(ids){
    const need = Array.from(new Set(ids.filter(id=> id && !invProfileNames.has(id))));
    if(!need.length) return;
    try{
      const { data } = await db.from('profiles').select('id, name').in('id', need);
      (data || []).forEach(p=> invProfileNames.set(p.id, p.name || ''));
    }catch(e){}
  }

  // =====================================================================
  // STOCK ON HAND (admin)
  // =====================================================================
  let invItemOpen = null;   // material being viewed
  function invStockView(which){
    $('invStockListView').style.display = which === 'list' ? '' : 'none';
    $('invOpeningView').style.display = which === 'opening' ? '' : 'none';
    $('invItemView').style.display = which === 'item' ? '' : 'none';
    $('purchasingView').classList.toggle('po-wide', which !== 'list');
    if(which !== 'item') invItemOpen = null;
    window.scrollTo({ top:0 });
  }
  async function invShowStock(){
    invStockView('list');
    await invLoadStock();
  }
  async function invLoadStock(opts){
    const silent = !!(opts && opts.silent);
    const list = $('invStockList');
    if(!silent) list.innerHTML = '<div class="empty-state">Loading…</div>';
    if(!(await ensureCloud())){ if(!silent) list.innerHTML = '<div class="empty-state">Not connected.</div>'; return false; }
    try{
      const [, b] = await Promise.all([invLoadWarehouses(), db.from('stock_balances').select('*'), mtLoad({ silent:true })]);
      if(b.error) throw b.error;
      invBalances = b.data || [];
      const whSel = $('invStockWh'), keep = whSel.value;
      whSel.innerHTML = '<option value="">All warehouses</option>' + invWarehouses.map(w=> '<option value="' + escapeHtml(w.id) + '">' + escapeHtml(w.code + ' · ' + w.name) + (w.is_active ? '' : ' (inactive)') + '</option>').join('');
      whSel.value = keep;
      const cat = $('invStockCat');
      if(cat.options.length <= 1) PURCH_CATEGORIES.forEach(c=>{ const o = document.createElement('option'); o.value = c; o.textContent = c; cat.appendChild(o); });
      invRenderStock();
      return true;
    }catch(e){
      console.error('load stock failed', describeCloudError(e));
      if(!silent) list.innerHTML = '<div class="empty-state">' + (purchIsAuthError(e) ? PURCH_EXPIRED_HTML : invMissingTables(e) ? INV_MIGRATION_MSG : 'Couldn\u2019t load stock: ' + escapeHtml(describeCloudError(e))) + '</div>';
      return false;
    }
  }
  function invStockRows(){
    const wh = $('invStockWh').value, cat = $('invStockCat').value, showZero = $('invStockZero').checked;
    const words = ($('invStockSearch').value || '').trim().toLowerCase().split(/\s+/).filter(Boolean);
    const byMat = new Map();
    invBalances.forEach(b=>{
      if(wh && b.warehouse_id !== wh) return;
      const e = byMat.get(b.material_id) || { qty:0, value:0, per:[] };
      const q = Number(b.qty_on_hand), v = q * Number(b.avg_cost);
      e.qty += q; e.value += v; e.per.push(b);
      byMat.set(b.material_id, e);
    });
    const mats = showZero ? mtCache.filter(m=> m.isActive || byMat.has(m.id)) : mtCache.filter(m=> byMat.has(m.id) && byMat.get(m.id).qty > 0);
    return mats.filter(m=>{
      if(cat && m.category !== cat) return false;
      if(!words.length) return true;
      const hay = [m.code, m.name, m.family, m.brand, mtSpecText(m.specs)].join(' ').toLowerCase();
      return words.every(w=> hay.includes(w));
    }).map(m=> ({ m, s: byMat.get(m.id) || { qty:0, value:0, per:[] } }))
      .sort((a, b)=> a.m.category.localeCompare(b.m.category) || a.m.name.localeCompare(b.m.name, undefined, { numeric:true }));
  }
  function invRenderStock(){
    const rows = invStockRows();
    const wh = $('invStockWh').value;
    const inStock = rows.filter(r=> r.s.qty > 0);
    const value = rows.reduce((a, r)=> a + r.s.value, 0);
    $('invStockSummary').innerHTML =
      '<div class="tile"><div class="k">Items in stock</div><div class="v">' + inStock.length + '</div></div>' +
      '<div class="tile"><div class="k">Stock value' + (wh ? ' — ' + escapeHtml(invWh(wh) ? invWh(wh).code : '') : '') + '</div><div class="v">' + invMoney(value) + '</div></div>' +
      '<div class="tile"><div class="k">Warehouses</div><div class="v">' + invWarehouses.filter(w=> w.is_active).length + '</div></div>';
    $('invStockCount').textContent = inStock.length ? inStock.length + ' items · ' + invMoney(value) : '';
    const list = $('invStockList');
    if(!invWarehouses.length){ list.innerHTML = '<div class="empty-state">Add a warehouse first — <b>Inventory › Warehouses</b>.</div>'; return; }
    if(!rows.length){ list.innerHTML = '<div class="empty-state">' + (invBalances.length ? 'Nothing matches.' : 'No stock recorded yet. Tap <b>+ Opening Balance</b> to enter what you have now.') + '</div>'; return; }
    let html = '', lastCat = null;
    rows.forEach(({ m, s })=>{
      if(m.category !== lastCat){ lastCat = m.category; html += '<div class="mt-group-head">' + escapeHtml(m.category) + '</div>'; }
      const chips = !wh && s.per.length > 1 ? '<div class="inv-wh-chips">' + s.per.filter(b=> Number(b.qty_on_hand) > 0).map(b=>
        '<span class="sp-tag muted">' + escapeHtml(invWh(b.warehouse_id) ? invWh(b.warehouse_id).code : '?') + ': ' + invQty(b.qty_on_hand) + '</span>').join('') + '</div>' : '';
      const avg = s.qty > 0 ? s.value / s.qty : 0;
      html += '<button type="button" class="mt-row" data-id="' + escapeHtml(m.id) + '"><div class="mt-row-main">' +
        '<div class="mt-row-title"><span class="mt-code">' + escapeHtml(m.code) + '</span>' + escapeHtml(m.name) + '</div>' +
        '<div class="sp-row-sub">' + (s.qty > 0 ? 'avg ' + invMoney(avg) + ' / ' + escapeHtml(m.unit) : 'no stock') + '</div>' + chips + '</div>' +
        '<div class="mt-row-price"><span class="inv-qty' + (s.qty > 0 ? '' : ' zero') + '">' + invQty(s.qty) + ' ' + escapeHtml(m.unit) + '</span>' +
        '<div class="sp-row-sub">' + invMoney(s.value) + '</div></div></button>';
    });
    list.innerHTML = html;
  }
  ['invStockSearch'].forEach(id=> $(id).addEventListener('input', invRenderStock));
  ['invStockWh', 'invStockCat', 'invStockZero'].forEach(id=> $(id).addEventListener('change', invRenderStock));
  $('invStockList').addEventListener('click', (e)=>{
    if(e.target.closest('[data-purch-reauth]')){ purchReauth().then(ok=>{ if(ok) invShowStock(); }); return; }
    const r = e.target.closest('.mt-row'); if(r) invOpenItem(r.dataset.id);
  });
  $('invStockExportBtn').addEventListener('click', ()=>{
    const wh = $('invStockWh').value;
    const lines = [['warehouse','code','item','unit','qty_on_hand','avg_cost','value'].join(',')];
    invBalances.filter(b=> (!wh || b.warehouse_id === wh) && Number(b.qty_on_hand) !== 0).forEach(b=>{
      const m = mtCache.find(x=> x.id === b.material_id) || {};
      lines.push([invWh(b.warehouse_id) ? invWh(b.warehouse_id).code : '', m.code, m.name, m.unit, Number(b.qty_on_hand), Number(b.avg_cost), (Number(b.qty_on_hand) * Number(b.avg_cost)).toFixed(2)].map(spCsvCell).join(','));
    });
    const blob = new Blob(['\uFEFF' + lines.join('\r\n')], { type:'text/csv;charset=utf-8' });
    const a = document.createElement('a'); a.href = URL.createObjectURL(blob);
    a.download = 'stock-on-hand-' + poToday() + '.csv'; document.body.appendChild(a); a.click(); a.remove();
    setTimeout(()=> URL.revokeObjectURL(a.href), 2000);
    toast('Exported ' + (lines.length - 1) + ' stock line' + (lines.length === 2 ? '' : 's'));
  });

  // ---------- item detail: per-warehouse + history + adjust ----------
  async function invOpenItem(materialId){
    const m = mtCache.find(x=> x.id === materialId);
    if(!m) return;
    invItemOpen = m;
    $('invItemTitle').innerHTML = '<span class="mt-code">' + escapeHtml(m.code) + '</span> ' + escapeHtml(m.name);
    invStockView('item');
    invItemOpen = m;
    await invRenderItem();
  }
  async function invRenderItem(){
    const m = invItemOpen; if(!m) return;
    const bal = invBalances.filter(b=> b.material_id === m.id);
    $('invItemCards').innerHTML = invWarehouses.filter(w=> w.is_active || bal.some(b=> b.warehouse_id === w.id)).map(w=>{
      const b = bal.find(x=> x.warehouse_id === w.id) || { qty_on_hand:0, avg_cost:0 };
      const q = Number(b.qty_on_hand);
      return '<div class="tile"><div class="k">' + escapeHtml(w.code + ' · ' + w.name) + '</div>' +
        '<div class="v">' + invQty(q) + ' ' + escapeHtml(m.unit) + '</div>' +
        '<div class="s">' + (q ? 'avg ' + invMoney(b.avg_cost) + ' · ' + invMoney(q * Number(b.avg_cost)) : 'none') + '</div>' +
        '<button type="button" class="btn btn-secondary mt-small-btn" style="margin-top:8px;" data-adjust="' + escapeHtml(w.id) + '">Adjust count</button></div>';
    }).join('');
    const hist = $('invItemHistory');
    hist.innerHTML = '<tbody><tr><td>Loading…</td></tr></tbody>';
    try{
      const { data, error } = await db.from('stock_movements').select('*').eq('material_id', m.id).order('created_at', { ascending:false }).limit(300);
      if(error) throw error;
      const rows = data || [];
      await invLoadNames(rows.map(r=> r.created_by).concat(rows.map(r=> r.worker_id)));
      if(!rows.length){ hist.innerHTML = '<tbody><tr><td style="color:var(--text-muted);">No movements yet.</td></tr></tbody>'; return; }
      hist.innerHTML = '<thead><tr><th>When</th><th>Warehouse</th><th>Type</th><th>Reference</th><th class="num">Qty</th><th class="num">Balance</th><th class="num">Unit cost</th><th class="num">Value</th><th>By</th></tr></thead><tbody>' +
        rows.map(r=> '<tr><td>' + escapeHtml(mrWhen(r.created_at)) + '</td><td>' + escapeHtml(invWh(r.warehouse_id) ? invWh(r.warehouse_id).code : '') + '</td>' +
          '<td>' + escapeHtml(INV_TYPE_LABEL[r.doc_type] || r.doc_type) + '</td><td>' + escapeHtml([r.doc_ref, r.note].filter(Boolean).join(' — ')) + '</td>' +
          '<td class="num ' + (Number(r.qty) > 0 ? 'inv-in' : 'inv-out') + '">' + (Number(r.qty) > 0 ? '+' : '−') + invQty(Math.abs(r.qty)) + '</td>' +
          '<td class="num">' + invQty(r.balance_after) + '</td><td class="num">' + invMoney(r.unit_cost) + '</td><td class="num">' + invMoney(r.value) + '</td>' +
          '<td>' + escapeHtml(invProfileNames.get(r.created_by) || '') + '</td></tr>').join('') + '</tbody>';
    }catch(e){ hist.innerHTML = '<tbody><tr><td>Couldn\u2019t load history: ' + escapeHtml(describeCloudError(e)) + '</td></tr></tbody>'; }
  }
  $('invItemBack').addEventListener('click', ()=>{ invStockView('list'); invRenderStock(); });
  $('invItemCards').addEventListener('click', async (e)=>{
    const b = e.target.closest('[data-adjust]'); if(!b || !invItemOpen) return;
    const w = invWh(b.dataset.adjust), m = invItemOpen;
    const bal = invBalances.find(x=> x.material_id === m.id && x.warehouse_id === w.id);
    const cur = bal ? Number(bal.qty_on_hand) : 0;
    const raw = prompt('Physical count of ' + m.name + ' in ' + w.code + '\n\nSystem shows ' + invQty(cur) + ' ' + m.unit + '. Enter the actual quantity counted:', String(cur));
    if(raw === null) return;
    const counted = spParseMoney(raw);
    if(counted == null || Number.isNaN(counted)){ toast('Enter a number'); return; }
    const diff = Math.round((counted - cur) * 1000) / 1000;
    if(diff === 0){ toast('No change — count matches'); return; }
    const reason = prompt('Reason for the ' + (diff > 0 ? '+' : '−') + invQty(Math.abs(diff)) + ' ' + m.unit + ' adjustment (e.g. recount, damaged, found):');
    if(reason === null) return;
    if(!reason.trim()){ toast('A reason is required'); return; }
    if(!(await purchEnsureSession())) return;
    try{
      const { error } = await db.from('stock_movements').insert({ doc_type:'adjustment', doc_ref:'Count ' + poToday(), warehouse_id: w.id, material_id: m.id, qty: diff, note: reason.trim() });
      if(error) throw error;
      toast('Adjusted ' + m.code + ' in ' + w.code + ' to ' + invQty(counted) + ' ' + m.unit);
      await invLoadStock({ silent:true });
      await invRenderItem();
    }catch(err){ purchFail('Couldn\u2019t post the adjustment: ', err); }
  });

  // ---------- opening balance ----------
  let invOpLines = [], invOpKey = 0;
  function invOpBlank(){ return { key: ++invOpKey, material_id:null, code:'', description:'', unit:'', qty:'', unit_cost:'' }; }
  $('invOpeningBtn').addEventListener('click', async ()=>{
    if(!invWarehouses.filter(w=> w.is_active).length){ toast('Add a warehouse first'); return; }
    $('invOpWh').innerHTML = invWarehouses.filter(w=> w.is_active).map(w=> '<option value="' + escapeHtml(w.id) + '">' + escapeHtml(w.code + ' · ' + w.name) + '</option>').join('');
    if($('invStockWh').value && invWh($('invStockWh').value) && invWh($('invStockWh').value).is_active) $('invOpWh').value = $('invStockWh').value;
    $('invOpNote').value = '';
    invOpLines = [invOpBlank()];
    invRenderOpLines();
    invStockView('opening');
  });
  $('invOpeningBack').addEventListener('click', ()=>{
    if(invOpLines.some(l=> l.material_id) && !confirm('Discard this opening balance?')) return;
    invStockView('list'); invRenderStock();
  });
  function invRenderOpLines(){
    $('invOpItems').innerHTML = invOpLines.map((l, i)=>{
      const val = poRound2((Number(l.qty) || 0) * (Number(l.unit_cost) || 0));
      return '<div class="po-item inv-op-item" data-key="' + l.key + '"><div class="po-no">' + (i + 1) + '</div>' +
        '<div class="po-item-desc"><input type="text" data-f="description" value="' + escapeHtml(l.description) + '" placeholder="Search the materials list…" autocomplete="off">' +
        '<div class="po-item-code">' + (l.material_id ? escapeHtml(l.code) : (l.description ? 'pick an item from the list' : '')) + '</div></div>' +
        '<input type="text" class="num po-qty" data-f="qty" inputmode="decimal" placeholder="Qty" value="' + escapeHtml(String(l.qty)) + '">' +
        '<input type="text" class="po-unit" value="' + escapeHtml(l.unit) + '" disabled placeholder="Unit">' +
        '<input type="text" class="num po-price" data-f="unit_cost" inputmode="decimal" placeholder="Unit cost" value="' + escapeHtml(String(l.unit_cost)) + '">' +
        '<div class="po-amt">' + invMoney(val) + '</div>' +
        '<button type="button" class="po-rm" data-rm="1" title="Remove">&minus;</button></div>';
    }).join('');
    invOpTotal();
  }
  function invOpTotal(){
    const t = invOpLines.reduce((a, l)=> a + poRound2((Number(l.qty) || 0) * (Number(l.unit_cost) || 0)), 0);
    const n = invOpLines.filter(l=> l.material_id).length;
    $('invOpTotal').textContent = n ? n + ' item' + (n === 1 ? '' : 's') + ' · total value ' + invMoney(t) : '';
  }
  function invOpLine(el){ const r = el.closest('.po-item'); return r ? invOpLines.find(x=> String(x.key) === r.dataset.key) : null; }
  $('invOpItems').addEventListener('input', (e)=>{
    const l = invOpLine(e.target), f = e.target.dataset.f; if(!l || !f) return;
    if(f === 'description'){
      l.description = e.target.value;
      if(l.material_id){ const m = mtCache.find(x=> x.id === l.material_id); if(!m || m.name !== l.description){ l.material_id = null; l.code = ''; l.unit = ''; } }
      mrCatalog = mtCache.filter(m=> m.isActive);
      mrSuggest(e.target, (mid)=>{
        const m = mtCache.find(x=> x.id === mid); if(!m) return;
        if(invOpLines.some(x=> x !== l && x.material_id === m.id)){ toast(m.code + ' is already on this list'); return; }
        Object.assign(l, { material_id:m.id, code:m.code, description:m.name, unit:m.unit, unit_cost: m.standardCost != null ? m.standardCost : '' });
        invRenderOpLines();
        const q = $('invOpItems').querySelector('.po-item[data-key="' + l.key + '"] [data-f="qty"]'); if(q) q.focus();
      });
    }else{
      l[f] = e.target.value.trim();
      const row = e.target.closest('.po-item');
      row.querySelector('.po-amt').textContent = invMoney(poRound2((Number(l.qty) || 0) * (Number(l.unit_cost) || 0)));
      invOpTotal();
    }
  });
  $('invOpItems').addEventListener('click', (e)=>{
    if(!e.target.closest('[data-rm]')) return;
    const l = invOpLine(e.target);
    invOpLines = invOpLines.filter(x=> x !== l);
    if(!invOpLines.length) invOpLines.push(invOpBlank());
    invRenderOpLines();
  });
  // keyboard: ↑/↓ to move through suggestions, Enter to pick, Esc to close
  $('invOpItems').addEventListener('keydown', (e)=>{
    const box = e.target.closest('.po-item-desc') && e.target.closest('.po-item-desc').querySelector('.po-suggest');
    if(!box) return;
    const btns = Array.from(box.querySelectorAll('[data-pick]'));
    let i = btns.findIndex(b=> b.classList.contains('hl'));
    if(e.key === 'ArrowDown' || e.key === 'ArrowUp'){ e.preventDefault(); if(i >= 0) btns[i].classList.remove('hl'); i = e.key === 'ArrowDown' ? Math.min(btns.length - 1, i + 1) : Math.max(0, i - 1); if(btns[i]) btns[i].classList.add('hl'); }
    else if(e.key === 'Enter' && i >= 0){ e.preventDefault(); btns[i].click(); }
    else if(e.key === 'Escape') box.remove();
  });
  $('invOpItems').addEventListener('focusout', (e)=>{
    setTimeout(()=>{ const d = e.target.closest && e.target.closest('.po-item-desc'); if(d && !d.contains(document.activeElement)){ const b = d.querySelector('.po-suggest'); if(b) b.remove(); } }, 180);
  });
  $('invOpAdd').addEventListener('click', ()=>{
    invOpLines.push(invOpBlank()); invRenderOpLines();
    const all = $('invOpItems').querySelectorAll('[data-f="description"]'); if(all.length) all[all.length - 1].focus();
  });
  $('invOpImport').addEventListener('click', ()=>{ $('invOpFile').value = ''; $('invOpFile').click(); });
  $('invOpFile').addEventListener('change', async ()=>{
    const f = $('invOpFile').files && $('invOpFile').files[0]; if(!f) return;
    const rows = spParseCsv(await f.text());
    if(rows.length < 2){ toast('The CSV has no data rows'); return; }
    const head = rows[0].map(h=> h.trim().toLowerCase().replace(/[^a-z0-9]+/g, '_'));
    const ci = (k)=> head.indexOf(k);
    if(ci('code') < 0 || ci('qty') < 0){ toast('CSV needs columns: code, qty (and optionally unit_cost)'); return; }
    const skipped = [];
    const lines = [];
    rows.slice(1).forEach((r, i)=>{
      const code = mtNormCode(r[ci('code')]), m = mtCache.find(x=> x.code === code);
      const qty = spParseMoney(r[ci('qty')]);
      const cost = ci('unit_cost') >= 0 && String(r[ci('unit_cost')] || '').trim() !== '' ? spParseMoney(r[ci('unit_cost')]) : (m && m.standardCost != null ? m.standardCost : null);
      if(!m){ skipped.push('row ' + (i + 2) + ': unknown code ' + code); return; }
      if(qty == null || Number.isNaN(qty) || qty <= 0){ skipped.push('row ' + (i + 2) + ': bad qty'); return; }
      if(cost == null || Number.isNaN(cost)){ skipped.push('row ' + (i + 2) + ': no unit cost'); return; }
      if(lines.some(l=> l.material_id === m.id)){ skipped.push('row ' + (i + 2) + ': ' + code + ' repeated'); return; }
      lines.push({ key: ++invOpKey, material_id:m.id, code:m.code, description:m.name, unit:m.unit, qty, unit_cost:cost });
    });
    invOpLines = lines.length ? lines : [invOpBlank()];
    invRenderOpLines();
    toast('Loaded ' + lines.length + ' item' + (lines.length === 1 ? '' : 's') + (skipped.length ? ' — skipped ' + skipped.length + ': ' + skipped.slice(0, 2).join('; ') : ''));
  });
  $('invOpPost').addEventListener('click', async ()=>{
    const wh = invWh($('invOpWh').value);
    if(!wh){ toast('Choose a warehouse'); return; }
    const lines = invOpLines.filter(l=> l.material_id || String(l.description || '').trim());
    if(!lines.length){ toast('Add at least one item'); return; }
    for(let i = 0; i < lines.length; i++){
      const l = lines[i];
      if(!l.material_id){ toast('Item ' + (i + 1) + ': pick it from the materials list'); return; }
      const q = spParseMoney(l.qty), c = spParseMoney(l.unit_cost);
      if(q == null || Number.isNaN(q) || q <= 0){ toast(l.code + ': enter a quantity above 0'); return; }
      if(c == null || Number.isNaN(c)){ toast(l.code + ': enter the unit cost (0 is allowed)'); return; }
    }
    const total = lines.reduce((a, l)=> a + poRound2(spParseMoney(l.qty) * spParseMoney(l.unit_cost)), 0);
    if(!confirm('Post opening balance to ' + wh.code + ' · ' + wh.name + '?\n\n' + lines.length + ' item' + (lines.length === 1 ? '' : 's') + ', total value ' + invMoney(total) +
      '\n\nStock movements can\u2019t be edited afterwards — mistakes are corrected with an adjustment.')) return;
    if(!(await purchEnsureSession())) return;
    const btn = $('invOpPost'); btn.disabled = true;
    try{
      const ref = 'Opening ' + poToday();
      const { error } = await db.from('stock_movements').insert(lines.map(l=> ({
        doc_type:'opening', doc_ref: ref, warehouse_id: wh.id, material_id: l.material_id,
        qty: spParseMoney(l.qty), unit_cost: spParseMoney(l.unit_cost), note: $('invOpNote').value.trim()
      })));
      if(error) throw error;
      toast('Opening balance posted to ' + wh.code);
      invOpLines = [];
      await invShowStock();
    }catch(e){ purchFail('Couldn\u2019t post the opening balance: ', e); }
    finally{ btn.disabled = false; }
  });

  // =====================================================================
  // WAREHOUSES (admin)
  // =====================================================================
  async function invShowWarehouses(opts){
    const list = $('invWhList');
    if(!(opts && opts.silent)) list.innerHTML = '<div class="empty-state">Loading…</div>';
    if(!(await ensureCloud())){ list.innerHTML = '<div class="empty-state">Not connected.</div>'; return; }
    try{
      const [, k, b] = await Promise.all([invLoadWarehouses(), db.from('warehouse_storekeepers').select('*'), db.from('stock_balances').select('warehouse_id, qty_on_hand, avg_cost')]);
      if(k.error) throw k.error; if(b.error) throw b.error;
      await invLoadNames((k.data || []).map(x=> x.user_id));
      if(!invWarehouses.length){ list.innerHTML = '<div class="empty-state">No warehouses yet. Tap <b>+ Add Warehouse</b>.</div>'; return; }
      list.innerHTML = invWarehouses.map(w=>{
        const keepers = (k.data || []).filter(x=> x.warehouse_id === w.id).map(x=> invProfileNames.get(x.user_id) || 'Staff');
        const bs = (b.data || []).filter(x=> x.warehouse_id === w.id && Number(x.qty_on_hand) > 0);
        const val = bs.reduce((a, x)=> a + Number(x.qty_on_hand) * Number(x.avg_cost), 0);
        return '<div class="sp-row' + (w.is_active ? '' : ' inactive') + '" data-id="' + escapeHtml(w.id) + '"' + (w.is_active ? '' : ' style="opacity:.6;"') + '><div class="sp-row-top"><div style="min-width:0;">' +
          '<div class="sp-row-title"><span class="mt-code">' + escapeHtml(w.code) + '</span> ' + escapeHtml(w.name) + (w.is_active ? '' : ' <span class="sp-tag danger">Inactive</span>') + '</div>' +
          '<div class="sp-row-sub">' + escapeHtml(w.address || 'No address') + '</div>' +
          '<div class="sp-row-sub">Storekeeper' + (keepers.length === 1 ? '' : 's') + ': ' + (keepers.length ? escapeHtml(keepers.join(', ')) : '<span style="color:#9A6212;">none assigned</span>') + '</div></div>' +
          '<div class="mt-row-price">' + invMoney(val) + '<div class="sp-row-sub">' + bs.length + ' item' + (bs.length === 1 ? '' : 's') + ' in stock</div></div></div>' +
          '<div class="user-card-actions"><button type="button" class="primary" data-wh-edit="1">Edit</button></div></div>';
      }).join('');
    }catch(e){
      list.innerHTML = '<div class="empty-state">' + (purchIsAuthError(e) ? PURCH_EXPIRED_HTML : invMissingTables(e) ? INV_MIGRATION_MSG : 'Couldn\u2019t load warehouses: ' + escapeHtml(describeCloudError(e))) + '</div>';
    }
  }
  function invWhOpenForm(w){
    $('invWhForm').style.display = '';
    $('invWhFormTitle').textContent = w ? 'Edit ' + w.code : 'New Warehouse';
    $('invWhId').value = w ? w.id : '';
    $('invWhCode').value = w ? w.code : 'WH-' + String(invWarehouses.length + 1).padStart(2, '0');
    $('invWhName').value = w ? w.name : '';
    $('invWhAddress').value = w ? w.address : '';
    $('invWhActive').value = w ? String(w.is_active) : 'true';
    $('invWhName').focus();
  }
  $('invWhAddBtn').addEventListener('click', ()=> invWhOpenForm(null));
  $('invWhCancel').addEventListener('click', ()=>{ $('invWhForm').style.display = 'none'; });
  $('invWhList').addEventListener('click', (e)=>{
    if(e.target.closest('[data-purch-reauth]')){ purchReauth().then(ok=>{ if(ok) invShowWarehouses(); }); return; }
    if(!e.target.closest('[data-wh-edit]')) return;
    invWhOpenForm(invWh(e.target.closest('.sp-row').dataset.id));
    window.scrollTo({ top:0 });
  });
  $('invWhSave').addEventListener('click', async ()=>{
    const id = $('invWhId').value;
    const row = { code: mtNormCode($('invWhCode').value), name: $('invWhName').value.trim(), address: $('invWhAddress').value.trim(), is_active: $('invWhActive').value === 'true' };
    if(!row.code){ toast('Enter a code, e.g. WH-01'); return; }
    if(!row.name){ toast('Enter the warehouse name'); return; }
    if(invWarehouses.some(w=> w.code === row.code && w.id !== id)){ toast('Code ' + row.code + ' is already used'); return; }
    if(!(await purchEnsureSession())) return;
    try{
      const res = id ? await db.from('warehouses').update(row).eq('id', id) : await db.from('warehouses').insert(row);
      if(res.error) throw res.error;
      toast(id ? 'Warehouse updated' : row.code + ' added');
      $('invWhForm').style.display = 'none';
      invShowWarehouses();
    }catch(e){ purchFail('Couldn\u2019t save the warehouse: ', e); }
  });

  // =====================================================================
  // PROJECTS (admin)
  // =====================================================================
  let invProjects = [], invPrjLinks = [], invPrjOpen = null, invJobsAll = [];
  function invPrjView(which){
    $('invPrjListView').style.display = which === 'list' ? '' : 'none';
    $('invPrjEditView').style.display = which === 'edit' ? '' : 'none';
    $('purchasingView').classList.toggle('po-wide', which === 'edit');
    if(which === 'list') invPrjOpen = null;
    window.scrollTo({ top:0 });
  }
  // Material cost per project: issues minus returns (and write-offs), for
  // the project itself or any of its job orders. Movement values are
  // negative when stock goes out, so cost = −sum(value).
  function invProjectCost(p, moves){
    const jobs = new Set(invPrjLinks.filter(l=> l.project_id === p.id).map(l=> l.job_order_id));
    return moves.filter(m=> m.project_id === p.id || (m.job_order_id && jobs.has(m.job_order_id)))
      .reduce((a, m)=> a - Number(m.value || 0), 0);
  }
  let invPrjMoves = [];
  async function invShowProjects(opts){
    if(!(opts && opts.keepView)) invPrjView('list');
    const list = $('invPrjList');
    if(!(opts && opts.silent)) list.innerHTML = '<div class="empty-state">Loading…</div>';
    if(!(await ensureCloud())){ list.innerHTML = '<div class="empty-state">Not connected.</div>'; return; }
    try{
      const [p, l, mv] = await Promise.all([
        db.from('projects').select('*').order('created_at', { ascending:false }),
        db.from('project_job_orders').select('*'),
        db.from('stock_movements').select('project_id, job_order_id, value, doc_type').in('doc_type', ['issue', 'return', 'write_off'])
      ]);
      if(p.error) throw p.error; if(l.error) throw l.error; if(mv.error) throw mv.error;
      invProjects = p.data || []; invPrjLinks = l.data || []; invPrjMoves = mv.data || [];
      invRenderProjects();
    }catch(e){
      list.innerHTML = '<div class="empty-state">' + (purchIsAuthError(e) ? PURCH_EXPIRED_HTML : invMissingTables(e) ? INV_MIGRATION_MSG : 'Couldn\u2019t load projects: ' + escapeHtml(describeCloudError(e))) + '</div>';
    }
  }
  function invRenderProjects(){
    const st = $('invPrjStatus').value, q = ($('invPrjSearch').value || '').trim().toLowerCase();
    const rows = invProjects.filter(p=> (st === 'open' ? ['planning', 'active', 'on_hold'].includes(p.status) : !st || p.status === st) &&
      (!q || [p.project_no, p.name, p.customer_name, p.site_address].join(' ').toLowerCase().includes(q)));
    const active = invProjects.filter(p=> p.status === 'active').length;
    $('invPrjCount').textContent = active ? active + ' active' : '';
    const list = $('invPrjList');
    if(!rows.length){ list.innerHTML = '<div class="empty-state">' + (invProjects.length ? 'Nothing matches.' : 'No projects yet. Tap <b>+ New Project</b>.') + '</div>'; return; }
    list.innerHTML = rows.map(p=>{
      const jobs = invPrjLinks.filter(l=> l.project_id === p.id).length;
      const cost = invProjectCost(p, invPrjMoves);
      const pct = p.budget ? Math.round(cost / Number(p.budget) * 100) : null;
      return '<button type="button" class="mt-row' + (p.status === 'cancelled' ? ' inactive' : '') + '" data-id="' + escapeHtml(p.id) + '"><div class="mt-row-main">' +
        '<div class="mt-row-title"><span class="mt-code">' + escapeHtml(p.project_no) + '</span>' + escapeHtml(p.name) + ' <span class="po-status ' + (p.status === 'active' ? 'approved' : p.status === 'completed' ? 'fulfilled' : p.status === 'cancelled' ? 'rejected' : 'draft') + '">' + escapeHtml(INV_PRJ_STATUS[p.status]) + '</span></div>' +
        '<div class="sp-row-sub">' + escapeHtml([p.customer_name, p.site_address].filter(Boolean).join(' · ') || 'No customer set') + ' · ' + jobs + ' job order' + (jobs === 1 ? '' : 's') + '</div></div>' +
        '<div class="mt-row-price">' + invMoney(cost) + '<div class="sp-row-sub">' + (p.budget ? pct + '% of ' + invMoney(p.budget) : 'material cost') + '</div></div></button>';
    }).join('');
  }
  $('invPrjSearch').addEventListener('input', invRenderProjects);
  $('invPrjStatus').addEventListener('change', invRenderProjects);
  $('invPrjList').addEventListener('click', (e)=>{
    if(e.target.closest('[data-purch-reauth]')){ purchReauth().then(ok=>{ if(ok) invShowProjects(); }); return; }
    const r = e.target.closest('.mt-row'); if(r) invOpenProject(invProjects.find(p=> p.id === r.dataset.id));
  });
  $('invPrjAddBtn').addEventListener('click', ()=> invOpenProject(null));
  $('invPrjBack').addEventListener('click', ()=>{ invPrjView('list'); invRenderProjects(); });

  async function invOpenProject(p){
    invPrjOpen = p;
    $('invPrjTitle').textContent = p ? p.project_no : 'New Project';
    $('invPrjStatusPill').className = 'po-status ' + (p ? (p.status === 'active' ? 'approved' : p.status === 'completed' ? 'fulfilled' : p.status === 'cancelled' ? 'rejected' : 'draft') : 'draft');
    $('invPrjStatusPill').textContent = p ? INV_PRJ_STATUS[p.status] : 'unsaved';
    $('invPrjName').value = p ? p.name : ''; $('invPrjCustomer').value = p ? p.customer_name : '';
    $('invPrjSite').value = p ? p.site_address : ''; $('invPrjBudget').value = p && p.budget != null ? String(p.budget) : '';
    $('invPrjStart').value = p && p.start_date ? p.start_date : ''; $('invPrjEnd').value = p && p.end_date ? p.end_date : '';
    $('invPrjStatusSel').value = p ? p.status : 'active'; $('invPrjNotes').value = p ? p.notes : '';
    $('invPrjJobsSec').style.display = p ? '' : 'none';
    $('invPrjCostSec').style.display = p ? '' : 'none';
    invPrjView('edit');
    invPrjOpen = p;
    if(p){ invRenderPrjCost(); await invRenderPrjJobs(); }
  }
  function invRenderPrjCost(){
    const p = invPrjOpen; if(!p) return;
    const cost = invProjectCost(p, invPrjMoves);
    const budget = p.budget != null ? Number(p.budget) : null;
    const pct = budget ? cost / budget * 100 : 0;
    $('invPrjCost').innerHTML = '<div class="inv-summary">' +
      '<div class="tile"><div class="k">Materials issued (net of returns)</div><div class="v">' + invMoney(cost) + '</div></div>' +
      (budget != null ? '<div class="tile"><div class="k">Budget</div><div class="v">' + invMoney(budget) + '</div></div>' +
        '<div class="tile"><div class="k">Remaining</div><div class="v" style="color:' + (budget - cost < 0 ? 'var(--danger)' : 'var(--green-dark)') + ';">' + invMoney(budget - cost) + '</div></div>' : '') + '</div>' +
      (budget ? '<div class="inv-budget-bar' + (pct >= 100 ? ' over' : pct >= 80 ? ' warn' : '') + '"><span style="width:' + Math.min(100, pct).toFixed(1) + '%"></span></div><div class="po-hint">' + pct.toFixed(1) + '% of budget used</div>' : '') +
      (cost === 0 ? '<div class="po-hint">No materials issued yet. Issue slips (next phase) will add up here automatically — for the project and all its job orders.</div>' : '');
  }
  async function invRenderPrjJobs(){
    const p = invPrjOpen; if(!p) return;
    if(!invJobsAll.length && typeof dtListAll === 'function'){ try{ invJobsAll = await dtListAll(); }catch(e){ invJobsAll = []; } }
    const mine = invPrjLinks.filter(l=> l.project_id === p.id);
    const jobInfo = (id)=> invJobsAll.find(j=> j.id === id);
    $('invPrjJobs').innerHTML = mine.length ? mine.map(l=>{
      const j = jobInfo(l.job_order_id);
      return '<div class="sp-row" data-jo="' + escapeHtml(l.job_order_id) + '"><div class="sp-row-top"><div><div class="sp-row-title">' + escapeHtml(l.job_order_id) + '</div>' +
        '<div class="sp-row-sub">' + escapeHtml(j ? [j.custName, j.siteAddress].filter(Boolean).join(' · ') : '') + '</div></div>' +
        '<div class="user-card-actions" style="margin:0;"><button type="button" class="danger" data-jo-rm="1">Remove</button></div></div></div>';
    }).join('') : '<div class="empty-state" style="padding:12px;">No job orders linked yet.</div>';
    const taken = new Set(invPrjLinks.map(l=> l.job_order_id));
    const free = invJobsAll.filter(j=> !taken.has(j.id)).slice(0, 300);
    $('invPrjJobPick').innerHTML = '<option value="">' + (free.length ? 'Choose a job order to add…' : 'No unlinked job orders') + '</option>' +
      free.map(j=> '<option value="' + escapeHtml(j.id) + '">' + escapeHtml(j.id + (j.custName ? ' — ' + j.custName : '')) + '</option>').join('');
  }
  $('invPrjJobAdd').addEventListener('click', async ()=>{
    const jo = $('invPrjJobPick').value; if(!jo || !invPrjOpen) return;
    if(!(await purchEnsureSession())) return;
    try{
      const { error } = await db.from('project_job_orders').insert({ project_id: invPrjOpen.id, job_order_id: jo });
      if(error) throw error;
      invPrjLinks.push({ project_id: invPrjOpen.id, job_order_id: jo });
      toast(jo + ' added to ' + invPrjOpen.project_no);
      invRenderPrjJobs(); invRenderPrjCost();
    }catch(e){ purchFail(/23505/.test(describeCloudError(e)) ? 'That job order is already in another project: ' : 'Couldn\u2019t add the job order: ', e); }
  });
  $('invPrjJobs').addEventListener('click', async (e)=>{
    if(!e.target.closest('[data-jo-rm]') || !invPrjOpen) return;
    const jo = e.target.closest('[data-jo]').dataset.jo;
    if(!confirm('Remove ' + jo + ' from ' + invPrjOpen.project_no + '? Its material cost will no longer count toward this project.')) return;
    try{
      const { error } = await db.from('project_job_orders').delete().eq('project_id', invPrjOpen.id).eq('job_order_id', jo);
      if(error) throw error;
      invPrjLinks = invPrjLinks.filter(l=> !(l.project_id === invPrjOpen.id && l.job_order_id === jo));
      invRenderPrjJobs(); invRenderPrjCost();
    }catch(err){ purchFail('Couldn\u2019t remove it: ', err); }
  });
  $('invPrjSave').addEventListener('click', async ()=>{
    const budget = spParseMoney($('invPrjBudget').value);
    if(Number.isNaN(budget)){ toast('Budget must be a number'); return; }
    const row = { name: $('invPrjName').value.trim(), customer_name: $('invPrjCustomer').value.trim(), site_address: $('invPrjSite').value.trim(),
      budget, start_date: $('invPrjStart').value || null, end_date: $('invPrjEnd').value || null, status: $('invPrjStatusSel').value, notes: $('invPrjNotes').value.trim() };
    if(!row.name){ toast('Enter the project name'); $('invPrjName').focus(); return; }
    if(row.start_date && row.end_date && row.end_date < row.start_date){ toast('Target end is before the start'); return; }
    if(!(await purchEnsureSession())) return;
    const btn = $('invPrjSave'); btn.disabled = true;
    try{
      const res = invPrjOpen ? await db.from('projects').update(row).eq('id', invPrjOpen.id).select('*').single()
                             : await db.from('projects').insert(row).select('*').single();
      if(res.error) throw res.error;
      const saved = res.data, wasNew = !invPrjOpen;
      const i = invProjects.findIndex(p=> p.id === saved.id);
      if(i >= 0) invProjects[i] = saved; else invProjects.unshift(saved);
      toast(wasNew ? saved.project_no + ' created — add its job orders below' : 'Project saved');
      await invOpenProject(saved);
    }catch(e){ purchFail('Couldn\u2019t save the project: ', e); }
    finally{ btn.disabled = false; }
  });

  // =====================================================================
  // STOREKEEPER: Warehouse Stock (quantities only)
  // =====================================================================
  let invMyWh = [], invMyStock = [], invMyMats = [];
  let invSkCheckedAt = 0, invSkIs = false;
  // Show the home tile only to staff with at least one warehouse assigned.
  async function invRefreshStorekeeperTile(){
    const tile = document.getElementById('techQaStock');
    if(!tile || !currentUser || currentUser.role === 'admin' || currentUser.role === 'customer'){ if(tile) tile.style.display = 'none'; return; }
    if(Date.now() - invSkCheckedAt < 60000){ tile.style.display = invSkIs ? '' : 'none'; return; }
    try{
      if(!(await ensureCloud())) return;
      const { data, error } = await db.from('warehouse_storekeepers').select('warehouse_id').eq('user_id', currentUser.id);
      if(error) throw error;
      invSkIs = !!(data && data.length); invSkCheckedAt = Date.now();
    }catch(e){ invSkIs = false; }
    tile.style.display = invSkIs ? '' : 'none';
  }
  async function invShowMyStock(){
    $('invMyItemView').style.display = 'none'; $('invMyListView').style.display = '';
    const list = $('invMyList');
    list.innerHTML = '<div class="empty-state">Loading…</div>';
    if(!(await ensureCloud())){ list.innerHTML = '<div class="empty-state">Not connected.</div>'; return; }
    try{
      const k = await db.from('warehouse_storekeepers').select('warehouse_id').eq('user_id', currentUser.id);
      if(k.error) throw k.error;
      const ids = (k.data || []).map(x=> x.warehouse_id);
      if(!ids.length){ list.innerHTML = '<div class="empty-state">You aren\u2019t assigned to a warehouse. Ask the admin to set you as a Storekeeper in Users &amp; Roles.</div>'; return; }
      const [w, s, m] = await Promise.all([
        db.from('warehouses').select('*').in('id', ids).order('code'),
        db.from('stock_on_hand_qty').select('*').in('warehouse_id', ids),
        db.from('materials').select('id, code, name, unit, category, family, specs, brand').eq('is_active', true)
      ]);
      if(w.error) throw w.error; if(s.error) throw s.error; if(m.error) throw m.error;
      invMyWh = w.data || []; invMyStock = s.data || []; invMyMats = m.data || [];
      const sel = $('invMyWh'), keep = sel.value;
      sel.innerHTML = invMyWh.map(x=> '<option value="' + escapeHtml(x.id) + '">' + escapeHtml(x.code + ' · ' + x.name) + '</option>').join('');
      if(keep && invMyWh.some(x=> x.id === keep)) sel.value = keep;
      sel.style.display = invMyWh.length > 1 ? '' : 'none';
      invRenderMyStock();
    }catch(e){
      list.innerHTML = '<div class="empty-state">' + (purchIsAuthError(e) ? PURCH_EXPIRED_HTML : invMissingTables(e) ? 'Inventory isn\u2019t set up yet.' : 'Couldn\u2019t load stock: ' + escapeHtml(describeCloudError(e))) + '</div>';
    }
  }
  function invRenderMyStock(){
    const wh = $('invMyWh').value || (invMyWh[0] && invMyWh[0].id);
    const words = ($('invMySearch').value || '').trim().toLowerCase().split(/\s+/).filter(Boolean);
    const rows = invMyStock.filter(s=> s.warehouse_id === wh && Number(s.qty_on_hand) > 0).map(s=> ({ s, m: invMyMats.find(x=> x.id === s.material_id) }))
      .filter(r=> r.m && (!words.length || words.every(w=> [r.m.code, r.m.name, r.m.family].join(' ').toLowerCase().includes(w))))
      .sort((a, b)=> a.m.name.localeCompare(b.m.name, undefined, { numeric:true }));
    $('invMyList').innerHTML = rows.length ? rows.map(({ s, m })=>
      '<button type="button" class="mt-row" data-id="' + escapeHtml(m.id) + '"><div class="mt-row-main"><div class="mt-row-title"><span class="mt-code">' + escapeHtml(m.code) + '</span>' + escapeHtml(m.name) + '</div>' +
      '<div class="sp-row-sub">' + escapeHtml(m.category) + '</div></div><div class="mt-row-price"><span class="inv-qty">' + invQty(s.qty_on_hand) + ' ' + escapeHtml(m.unit) + '</span></div></button>').join('')
      : '<div class="empty-state">' + (invMyStock.some(s=> s.warehouse_id === wh) ? 'Nothing matches.' : 'No stock recorded in this warehouse yet.') + '</div>';
  }
  $('invMySearch').addEventListener('input', invRenderMyStock);
  $('invMyWh').addEventListener('change', invRenderMyStock);
  $('invMyList').addEventListener('click', async (e)=>{
    if(e.target.closest('[data-purch-reauth]')){ purchReauth().then(ok=>{ if(ok) invShowMyStock(); }); return; }
    const r = e.target.closest('.mt-row'); if(!r) return;
    const m = invMyMats.find(x=> x.id === r.dataset.id), wh = $('invMyWh').value || invMyWh[0].id;
    $('invMyItemTitle').innerHTML = '<span class="mt-code">' + escapeHtml(m.code) + '</span> ' + escapeHtml(m.name);
    $('invMyListView').style.display = 'none'; $('invMyItemView').style.display = '';
    const t = $('invMyItemHistory');
    t.innerHTML = '<tbody><tr><td>Loading…</td></tr></tbody>';
    try{
      const { data, error } = await db.from('stock_movements_qty').select('*').eq('material_id', m.id).eq('warehouse_id', wh).order('created_at', { ascending:false }).limit(200);
      if(error) throw error;
      t.innerHTML = (data || []).length ? '<thead><tr><th>When</th><th>Type</th><th>Reference</th><th class="num">Qty</th><th class="num">Balance</th></tr></thead><tbody>' +
        data.map(x=> '<tr><td>' + escapeHtml(mrWhen(x.created_at)) + '</td><td>' + escapeHtml(INV_TYPE_LABEL[x.doc_type] || x.doc_type) + '</td><td>' + escapeHtml([x.doc_ref, x.note].filter(Boolean).join(' — ')) + '</td>' +
          '<td class="num ' + (Number(x.qty) > 0 ? 'inv-in' : 'inv-out') + '">' + (Number(x.qty) > 0 ? '+' : '−') + invQty(Math.abs(x.qty)) + '</td><td class="num">' + invQty(x.balance_after) + '</td></tr>').join('') + '</tbody>'
        : '<tbody><tr><td>No movements yet.</td></tr></tbody>';
    }catch(err){ t.innerHTML = '<tbody><tr><td>Couldn\u2019t load history.</td></tr></tbody>'; }
  });
  $('invMyItemBack').addEventListener('click', ()=>{ $('invMyItemView').style.display = 'none'; $('invMyListView').style.display = ''; });
  $('techQaStock').addEventListener('click', ()=> showPurchasingView('myStock'));

  // =====================================================================
  // USERS & ROLES hooks — the Storekeeper setting (called from admin.js)
  // =====================================================================
  // Returns null when the inventory tables aren't installed yet, so Users &
  // Roles keeps working exactly as before.
  async function invLoadUsersContext(){
    try{
      const [w, k] = await Promise.all([db.from('warehouses').select('id, code, name, is_active').order('code'), db.from('warehouse_storekeepers').select('*')]);
      if(w.error || k.error) return null;
      const byUser = new Map();
      (k.data || []).forEach(x=>{ if(!byUser.has(x.user_id)) byUser.set(x.user_id, new Set()); byUser.get(x.user_id).add(x.warehouse_id); });
      return { warehouses: w.data || [], byUser };
    }catch(e){ return null; }
  }
  function invUserStatusLine(ctx, userId){
    if(!ctx) return '';
    const mine = ctx.byUser.get(userId);
    if(!mine || !mine.size) return '';
    return '<div class="u-status" style="color:var(--green-dark); font-weight:700;">Storekeeper: ' +
      escapeHtml(ctx.warehouses.filter(w=> mine.has(w.id)).map(w=> w.code).join(', ')) + '</div>';
  }
  function invUserPanelHtml(ctx, userId){
    if(!ctx) return '';
    const mine = ctx.byUser.get(userId) || new Set();
    const body = ctx.warehouses.length ? ctx.warehouses.filter(w=> w.is_active || mine.has(w.id)).map(w=>
      '<label class="restrict-row"><input type="checkbox" data-inv-wh="' + escapeHtml(w.id) + '"' + (mine.has(w.id) ? ' checked' : '') + '>' +
      '<span class="rtxt"><span class="rt-title">' + escapeHtml(w.code + ' · ' + w.name) + '</span></span></label>').join('')
      : '<div style="padding:6px 0; font-size:11.5px; color:var(--text-muted);">Add a warehouse first in <b>Inventory › Warehouses</b>.</div>';
    return '<div class="restrict-group inv-sk-group"><h5>Storekeeper</h5>' +
      '<div style="margin:-2px 0 6px; font-size:11.5px; color:var(--text-muted); line-height:1.4;">Tick the warehouses this person keeps. They\u2019ll see those warehouses\u2019 stock (quantities only — no costs) and, in the next phase, issue and receive for them.</div>' + body + '</div>';
  }
  function invUserPanelReset(ctx, userId, panel){
    if(!ctx) return;
    const mine = ctx.byUser.get(userId) || new Set();
    panel.querySelectorAll('[data-inv-wh]').forEach(c=>{ c.checked = mine.has(c.dataset.invWh); });
  }
  async function invSaveUserWarehouses(ctx, userId, panel){
    if(!ctx) return true;
    const want = new Set(Array.from(panel.querySelectorAll('[data-inv-wh]')).filter(c=> c.checked).map(c=> c.dataset.invWh));
    const have = ctx.byUser.get(userId) || new Set();
    const add = Array.from(want).filter(id=> !have.has(id)), del = Array.from(have).filter(id=> !want.has(id));
    try{
      if(add.length){ const r = await db.from('warehouse_storekeepers').insert(add.map(id=> ({ warehouse_id:id, user_id:userId }))); if(r.error) throw r.error; }
      for(const id of del){ const r = await db.from('warehouse_storekeepers').delete().eq('warehouse_id', id).eq('user_id', userId); if(r.error) throw r.error; }
      return true;
    }catch(e){ console.error('storekeeper save failed', describeCloudError(e)); return false; }
  }


  // =====================================================================
  // Inventory — Phase 2 screens (migration 20260923_08_inventory_movements.sql)
  //
  //   Receive / Issue / Return / Transfer — admins (sidebar) and
  //   storekeepers (Warehouse Stock hub). Every post is ONE call to an
  //   inv_post_* database function, which validates, costs and writes the
  //   document + ledger atomically. The screens send quantities only.
  //   Slips & History — every document, with PDF.
  //   My Materials — technicians: slips to sign for, and what they hold.
  // =====================================================================

  const INV_SLIP_KIND = {
    rcv: { label:'Receipt', title:'RECEIVING REPORT', table:'stock_receipts', items:'stock_receipt_items', fk:'receipt_id', no:'receipt_no' },
    iss: { label:'Issue', title:'MATERIALS ISSUE SLIP', table:'issue_slips', items:'issue_slip_items', fk:'slip_id', no:'slip_no' },
    ret: { label:'Return', title:'MATERIALS RETURN SLIP', table:'return_slips', items:'return_slip_items', fk:'return_id', no:'return_no' },
    trf: { label:'Transfer', title:'STOCK TRANSFER', table:'stock_transfers', items:'stock_transfer_items', fk:'transfer_id', no:'transfer_no' }
  };
  const invX = { cat:[], catById:new Map(), whs:[], mine:[], avail:new Map(), workers:[], projects:[], jobs:[], isAdmin:false };
  const invAvailKey = (wh, m)=> wh + '|' + m;
  function invAvail(wh, m){ return invX.avail.get(invAvailKey(wh, m)) || 0; }
  function invIsAdmin(){ return !!(currentUser && currentUser.role === 'admin'); }

  // One load of everything the movement screens need. Quantities only —
  // stock_on_hand_qty works the same for admins and storekeepers.
  async function invLoadCtx(){
    invX.isAdmin = invIsAdmin();
    const [cat, whs, keep, av, wk, pr, jobs] = await Promise.all([
      db.from('materials').select('id, code, name, unit, pack_unit, pack_qty, category, family, specs, brand').eq('is_active', true).order('name'),
      db.from('warehouses').select('*').order('code'),
      invX.isAdmin ? Promise.resolve({ data:null }) : db.from('warehouse_storekeepers').select('warehouse_id').eq('user_id', currentUser.id),
      db.from('stock_on_hand_qty').select('*'),
      db.from('profiles').select('id, name').eq('role', 'technician').eq('active', true).order('name'),
      db.from('projects').select('id, project_no, name, status').in('status', ['planning', 'active', 'on_hold']).order('project_no', { ascending:false }),
      db.rpc('inv_open_job_orders')
    ]);
    for(const r of [cat, whs, av, wk, pr]) if(r.error) throw r.error;
    invX.cat = (cat.data || []).map(m=> Object.assign({}, m, { specs: m.specs || {} }));
    invX.catById = new Map(invX.cat.map(m=> [m.id, m]));
    invX.whs = whs.data || [];
    const keepIds = keep.data ? new Set(keep.data.map(k=> k.warehouse_id)) : null;
    invX.mine = invX.whs.filter(w=> w.is_active && (!keepIds || keepIds.has(w.id)));
    invX.avail = new Map((av.data || []).map(b=> [invAvailKey(b.warehouse_id, b.material_id), Number(b.qty_on_hand)]));
    invX.workers = wk.data || [];
    invX.projects = pr.data || [];
    invX.jobs = jobs.error ? [] : (jobs.data || []);
  }
  function invOpts(list, val, label, empty){
    return (empty != null ? '<option value="">' + escapeHtml(empty) + '</option>' : '') + list.map(x=> '<option value="' + escapeHtml(val(x)) + '">' + escapeHtml(label(x)) + '</option>').join('');
  }
  function invFillCommon(prefix){
    const whOpts = invOpts(invX.mine, w=> w.id, w=> w.code + ' · ' + w.name);
    return whOpts;
  }
  function invFillProjJob(projSel, jobSel){
    $(projSel).innerHTML = invOpts(invX.projects, p=> p.id, p=> p.project_no + ' — ' + p.name, '— none —');
    $(jobSel).innerHTML = invOpts(invX.jobs, j=> j.id, j=> j.id + (j.cust_name ? ' — ' + j.cust_name : ''), '— none —');
  }
  async function invEnter(render){
    const host = $('purchasingView');
    if(!(await ensureCloud())){ toast('Not connected'); return false; }
    try{ await invLoadCtx(); }
    catch(e){
      purchFail(invMissingTables(e) ? 'Run migration 20260923_08_inventory_movements.sql first: ' : 'Couldn\u2019t load inventory: ', e);
      return false;
    }
    if(!invX.mine.length){ toast(invX.isAdmin ? 'Add an active warehouse first' : 'You aren\u2019t assigned to a warehouse'); return false; }
    host.classList.add('po-wide');
    render();
    return true;
  }
  // storekeeper hub navigation
  $('purchasingView').addEventListener('click', (e)=>{
    const go = e.target.closest('[data-inv-go]');
    if(go){ showPurchasingView(go.dataset.invGo); return; }
    if(e.target.closest('[data-inv-hub]')) showPurchasingView('myStock');
  });

  // ---------------------------------------------------------------------
  // Shared line editor (issue / transfer / receive-without-PO)
  //   lines: {key, material_id, qty, unit_cost, mr_item_id, max, locked}
  // ---------------------------------------------------------------------
  const invLE = {};
  let invLEKey = 0;
  function invLEBlank(){ return { key: ++invLEKey, material_id:null, qty:'', unit_cost:'', mr_item_id:null, max:null, locked:false, text:'' }; }
  function invLERender(id){
    const st = invLE[id], m = (x)=> x.material_id ? invX.catById.get(x.material_id) : null;
    const wh = st.wh ? $(st.wh).value : '';
    const lastCol = st.cost ? 'Unit cost (₱)' : st.avail ? 'On hand' : '';
    $(st.host).innerHTML = '<div class="inv-ln-head"><span>#</span><span>Item</span><span>Qty</span><span>Unit</span><span>' + lastCol + '</span><span></span></div>' +
      st.lines.map((l, i)=>{
        const it = m(l), have = it && wh ? invAvail(wh, it.id) : null;
        const low = st.avail && it && Number(l.qty) > have;
        const last = st.cost ? '<input type="text" class="num" data-f="unit_cost" inputmode="decimal" placeholder="avg" value="' + escapeHtml(String(l.unit_cost)) + '">'
          : st.avail ? '<div class="inv-av' + (low ? ' low' : '') + '">' + (it ? invQty(have) + (low ? ' — short' : '') : '') + '</div>' : '<span></span>';
        return '<div class="inv-ln" data-key="' + l.key + '"><div class="po-no">' + (i + 1) + '</div>' +
          '<div class="po-item-desc"><input type="text" data-f="text" value="' + escapeHtml(it ? it.name : l.text) + '" placeholder="Search item…" autocomplete="off"' + (l.locked ? ' disabled' : '') + '>' +
          '<div class="po-item-code">' + (it ? escapeHtml(it.code) : '') + (l.max != null ? ' · up to ' + invQty(l.max) : '') + '</div></div>' +
          '<input type="text" class="num inv-q" data-f="qty" inputmode="decimal" placeholder="Qty" value="' + escapeHtml(String(l.qty)) + '">' +
          '<div class="inv-unit">' + escapeHtml(it ? it.unit : '') + '</div>' + last +
          (l.locked ? '<span></span>' : '<button type="button" class="po-rm" data-rm="1" title="Remove">&minus;</button>') + '</div>';
      }).join('');
  }
  function invLEBind(id, host, opts){
    invLE[id] = Object.assign({ host, lines:[invLEBlank()] }, opts);
    const el = $(host);
    const lineOf = (t)=>{ const r = t.closest('.inv-ln'); return r ? invLE[id].lines.find(x=> String(x.key) === r.dataset.key) : null; };
    el.addEventListener('input', (e)=>{
      const l = lineOf(e.target), f = e.target.dataset.f; if(!l || !f) return;
      if(f === 'text'){
        l.text = e.target.value; l.material_id = null;
        e.target.closest('.inv-ln').querySelector('.po-item-code').textContent = '';
        mrCatalog = invX.cat;
        mrSuggest(e.target, (mid)=>{
          if(invLE[id].lines.some(x=> x !== l && x.material_id === mid)){ toast('That item is already on the list'); return; }
          l.material_id = mid; l.text = '';
          invLERender(id);
          const q = el.querySelector('.inv-ln[data-key="' + l.key + '"] [data-f="qty"]'); if(q) q.focus();
        });
      }else{
        l[f] = e.target.value.trim();
        if(f === 'qty' && invLE[id].avail) invLEAvailCell(id, l);
      }
    });
    el.addEventListener('keydown', (e)=>{
      const box = e.target.closest('.po-item-desc') && e.target.closest('.po-item-desc').querySelector('.po-suggest');
      if(!box) return;
      const btns = Array.from(box.querySelectorAll('[data-pick]')); let i = btns.findIndex(b=> b.classList.contains('hl'));
      if(e.key === 'ArrowDown' || e.key === 'ArrowUp'){ e.preventDefault(); if(i >= 0) btns[i].classList.remove('hl'); i = e.key === 'ArrowDown' ? Math.min(btns.length - 1, i + 1) : Math.max(0, i - 1); if(btns[i]) btns[i].classList.add('hl'); }
      else if(e.key === 'Enter' && i >= 0){ e.preventDefault(); btns[i].click(); }
      else if(e.key === 'Escape') box.remove();
    });
    el.addEventListener('focusout', (e)=>{ setTimeout(()=>{ const d = e.target.closest && e.target.closest('.po-item-desc'); if(d && !d.contains(document.activeElement)){ const b = d.querySelector('.po-suggest'); if(b) b.remove(); } }, 180); });
    el.addEventListener('click', (e)=>{
      if(!e.target.closest('[data-rm]')) return;
      const l = lineOf(e.target); invLE[id].lines = invLE[id].lines.filter(x=> x !== l);
      if(!invLE[id].lines.length) invLE[id].lines.push(invLEBlank());
      invLERender(id);
    });
  }
  function invLEAvailCell(id, l){
    const st = invLE[id], it = invX.catById.get(l.material_id), row = $(st.host).querySelector('.inv-ln[data-key="' + l.key + '"] .inv-av');
    if(!row || !it) return;
    const have = invAvail($(st.wh).value, it.id), low = Number(l.qty) > have;
    row.className = 'inv-av' + (low ? ' low' : ''); row.textContent = invQty(have) + (low ? ' — short' : '');
  }
  // validated payload lines, or a message
  function invLECollect(id, needCostIgnored){
    const out = [];
    const lines = invLE[id].lines.filter(l=> l.material_id || String(l.text || '').trim() || String(l.qty).trim());
    for(let i = 0; i < lines.length; i++){
      const l = lines[i];
      if(!l.material_id) return 'Line ' + (i + 1) + ': pick the item from the list';
      const q = spParseMoney(l.qty);
      if(q == null || Number.isNaN(q) || q <= 0) return invX.catById.get(l.material_id).code + ': enter a quantity above 0';
      if(l.max != null && q > l.max) return invX.catById.get(l.material_id).code + ': at most ' + invQty(l.max) + ' on this request';
      const row = { material_id: l.material_id, qty: q };
      if(l.mr_item_id) row.mr_item_id = l.mr_item_id;
      if(invLE[id].cost && String(l.unit_cost).trim() !== ''){
        const c = spParseMoney(l.unit_cost);
        if(Number.isNaN(c)) return invX.catById.get(l.material_id).code + ': unit cost must be a number';
        row.unit_cost = c;
      }
      out.push(row);
    }
    if(!out.length) return 'Add at least one item';
    return out;
  }
  async function invRpc(fn, payload){
    if(!(await purchEnsureSession())) return null;
    const { data, error } = await db.rpc(fn, { p: payload });
    if(error) throw error;
    return data;
  }

  // =====================================================================
  // RECEIVE
  // =====================================================================
  let invRcvMode = 'po', invRcvPos = [], invRcvPoLines = [];
  async function invShowReceive(){
    await invEnter(async ()=>{
      $('invRcvWh').innerHTML = invFillCommon();
      let sup = await db.from('suppliers_directory').select('id, display_name').order('display_name');
      $('invRcvSupplier').innerHTML = invOpts(sup.data || [], s=> s.id, s=> s.display_name, '— not specified —');
      invFillProjJob('invRcvProject', 'invRcvJob');
      $('invRcvRef').value = ''; $('invRcvNote').value = ''; $('invRcvDirect').checked = false;
      invLEBind('rcv', 'invRcvLines', { cost: invX.isAdmin, avail:false, wh:'invRcvWh' });
      await invRcvLoadPos();
      invRcvSetMode('po');
    });
  }
  async function invRcvLoadPos(){
    const { data, error } = await db.rpc('inv_pos_to_receive');
    invRcvPos = error ? [] : (data || []);
    $('invRcvPo').innerHTML = '<option value="">' + (invRcvPos.length ? 'Choose an issued PO…' : 'No issued POs waiting for delivery') + '</option>' +
      invRcvPos.map(p=> '<option value="' + escapeHtml(p.id) + '">' + escapeHtml(p.po_no + ' — ' + (p.supplier || 'no supplier') + (p.reference ? ' · ' + p.reference : '')) + '</option>').join('');
  }
  function invRcvSetMode(m){
    invRcvMode = m;
    $$('#invRcvMode [data-m]').forEach(b=> b.classList.toggle('on', b.dataset.m === m));
    $('invRcvPoWrap').style.display = m === 'po' ? '' : 'none';
    $('invRcvSupWrap').style.display = m === 'free' ? '' : 'none';
    $('invRcvAdd').style.display = m === 'free' ? '' : 'none';
    $('invRcvHint').textContent = m === 'free'
      ? (invX.isAdmin ? 'Leave unit cost blank to value it at the current average cost.' : 'Received stock is valued at the current average cost (admins can set a cost).')
      : 'Enter what arrived now. Partial deliveries are fine — the rest stays open on the PO.';
    if(m === 'po') invRcvRenderPo(); else { invLE.rcv.lines = [invLEBlank()]; invLERender('rcv'); }
  }
  $('invRcvMode').addEventListener('click', (e)=>{ const b = e.target.closest('[data-m]'); if(b) invRcvSetMode(b.dataset.m); });
  $('invRcvAdd').addEventListener('click', ()=>{ invLE.rcv.lines.push(invLEBlank()); invLERender('rcv'); });
  $('invRcvPo').addEventListener('change', invRcvRenderPo);
  $('invRcvDirect').addEventListener('change', ()=>{
    const on = $('invRcvDirect').checked;
    $('invRcvProjWrap').style.display = on ? '' : 'none'; $('invRcvJobWrap').style.display = on ? '' : 'none';
  });
  function invRcvRenderPo(){
    if(invRcvMode !== 'po') return;
    const po = invRcvPos.find(p=> p.id === $('invRcvPo').value);
    if(!po){ $('invRcvLines').innerHTML = '<div class="empty-state" style="padding:12px;">Choose the PO this delivery is for.</div>'; invRcvPoLines = []; return; }
    invRcvPoLines = (po.items || []).filter(i=> Number(i.qty_received) < Number(i.qty)).map(i=> Object.assign({ now:'', map:i.material_id }, i));
    $('invRcvLines').innerHTML = '<div class="inv-ln-head"><span>#</span><span>Item</span><span>Receive now</span><span>Unit</span><span>Ordered / in</span><span></span></div>' +
      invRcvPoLines.map((i, n)=>{
        const m = i.map ? invX.catById.get(i.map) : null;
        const remaining = Number(i.qty) - Number(i.qty_received);
        const mapper = i.material_id ? '' : '<select data-map="1" style="margin-top:4px;"><option value="">Which catalog item is this?</option>' +
          invX.cat.map(c=> '<option value="' + escapeHtml(c.id) + '"' + (i.map === c.id ? ' selected' : '') + '>' + escapeHtml(c.code + ' — ' + c.name) + '</option>').join('') + '</select>';
        return '<div class="inv-ln" data-poi="' + escapeHtml(i.id) + '"><div class="po-no">' + (n + 1) + '</div>' +
          '<div class="inv-desc"><b>' + escapeHtml(i.description) + '</b><div class="po-item-code">' + escapeHtml(i.code || (m ? m.code : 'not in catalog')) + '</div>' + mapper + '</div>' +
          '<input type="text" class="num inv-q" data-poq="1" inputmode="decimal" placeholder="' + escapeHtml(invQty(remaining)) + '">' +
          '<div class="inv-unit">' + escapeHtml(i.unit) + '</div>' +
          '<div class="inv-av">' + invQty(i.qty) + ' / ' + invQty(i.qty_received) + '</div><span></span>' +
          '<div class="inv-conv" data-conv="1"></div></div>';
      }).join('') +
      '<button type="button" class="btn btn-secondary mt-small-btn" id="invRcvAll" style="margin-top:8px;">Fill in: everything remaining</button>';
  }
  function invRcvConv(i, qty){
    const m = invX.catById.get(i.map);
    if(!m || !(Number(m.pack_qty) > 0) || String(i.unit).trim().toLowerCase() !== String(m.pack_unit || '').trim().toLowerCase()) return '';
    return qty ? '= ' + invQty(qty * Number(m.pack_qty)) + ' ' + m.unit + ' into stock' : '1 ' + i.unit + ' = ' + invQty(m.pack_qty) + ' ' + m.unit;
  }
  $('invRcvLines').addEventListener('input', (e)=>{
    if(!e.target.dataset.poq) return;
    const row = e.target.closest('[data-poi]'), i = invRcvPoLines.find(x=> x.id === row.dataset.poi);
    i.now = e.target.value.trim();
    row.querySelector('[data-conv]').textContent = invRcvConv(i, spParseMoney(i.now));
  });
  $('invRcvLines').addEventListener('change', (e)=>{
    if(!e.target.dataset.map) return;
    const row = e.target.closest('[data-poi]'), i = invRcvPoLines.find(x=> x.id === row.dataset.poi);
    i.map = e.target.value || null;
    row.querySelector('[data-conv]').textContent = invRcvConv(i, spParseMoney(i.now));
  });
  $('invRcvLines').addEventListener('click', (e)=>{
    if(e.target.id !== 'invRcvAll') return;
    invRcvPoLines.forEach(i=>{ i.now = String(Number(i.qty) - Number(i.qty_received)); });
    $$('#invRcvLines [data-poi]').forEach(row=>{
      const i = invRcvPoLines.find(x=> x.id === row.dataset.poi);
      row.querySelector('[data-poq]').value = i.now; row.querySelector('[data-conv]').textContent = invRcvConv(i, Number(i.now));
    });
  });
  $('invRcvPost').addEventListener('click', async ()=>{
    const wh = invX.mine.find(w=> w.id === $('invRcvWh').value);
    const payload = { warehouse_id: wh.id, supplier_ref: $('invRcvRef').value.trim(), note: $('invRcvNote').value.trim() };
    let summary;
    if(invRcvMode === 'po'){
      const po = invRcvPos.find(p=> p.id === $('invRcvPo').value);
      if(!po){ toast('Choose the PO'); return; }
      const lines = [];
      for(const i of invRcvPoLines){
        if(!String(i.now).trim()) continue;
        const q = spParseMoney(i.now), rem = Number(i.qty) - Number(i.qty_received);
        if(q == null || Number.isNaN(q) || q <= 0){ toast(i.description + ': enter a quantity above 0'); return; }
        if(q > rem){ toast(i.description + ': only ' + invQty(rem) + ' ' + i.unit + ' left on ' + po.po_no); return; }
        if(!i.map){ toast(i.description + ': choose which catalog item it is'); return; }
        lines.push(Object.assign({ po_item_id: i.id, qty: q }, i.material_id ? {} : { material_id: i.map }));
      }
      if(!lines.length){ toast('Enter what was received'); return; }
      Object.assign(payload, { po_id: po.id, lines });
      summary = lines.length + ' line' + (lines.length === 1 ? '' : 's') + ' from ' + po.po_no;
    }else{
      const lines = invLECollect('rcv');
      if(typeof lines === 'string'){ toast(lines); return; }
      Object.assign(payload, { supplier_id: $('invRcvSupplier').value || null, lines });
      summary = lines.length + ' item' + (lines.length === 1 ? '' : 's') + ' without a PO';
    }
    const direct = invX.isAdmin && $('invRcvDirect').checked;
    if(direct){
      payload.direct_project_id = $('invRcvProject').value || null; payload.direct_job_order_id = $('invRcvJob').value || null;
      if(!payload.direct_project_id && !payload.direct_job_order_id){ toast('Choose the project or job order it was delivered to'); return; }
    }
    if(!confirm('Receive ' + summary + ' into ' + wh.code + '?' + (direct ? '\n\nDelivered straight to site: charged to the project, not kept in stock.' : ''))) return;
    const btn = $('invRcvPost'); btn.disabled = true;
    try{
      const r = await invRpc('inv_post_receipt', payload); if(!r) return;
      toast(r.receipt_no + ' posted');
      invAfterPost('rcv', r.id);
    }catch(e){ purchFail('Couldn\u2019t post the receipt: ', e); }
    finally{ btn.disabled = false; }
  });

  // =====================================================================
  // ISSUE
  // =====================================================================
  let invIssMode = 'mrf', invIssMrs = [];
  async function invShowIssue(){
    await invEnter(async ()=>{
      $('invIssWh').innerHTML = invFillCommon();
      $('invIssWorker').innerHTML = invOpts(invX.workers, w=> w.id, w=> w.name, 'Choose a person…');
      invFillProjJob('invIssProject', 'invIssJob');
      $('invIssNote').value = '';
      invLEBind('iss', 'invIssLines', { cost:false, avail:true, wh:'invIssWh' });
      const r = await db.from('material_requisitions').select('id, mrf_no, requested_by, requester_name, job_order_id, job_order, urgency, material_requisition_items(*)')
        .eq('status', 'approved').order('created_at', { ascending:false });
      invIssMrs = (r.data || []).map(m=> Object.assign(m, { open: (m.material_requisition_items || []).filter(i=>
        i.material_id && !i.po_id && i.fulfilled_by !== 'tech_buy' && Number(i.qty_approved != null ? i.qty_approved : i.qty_requested) - Number(i.qty_issued || 0) > 0) })).filter(m=> m.open.length);
      $('invIssMr').innerHTML = '<option value="">' + (invIssMrs.length ? 'Choose an approved request…' : 'No approved requests with items to issue') + '</option>' +
        invIssMrs.map(m=> '<option value="' + escapeHtml(m.id) + '">' + escapeHtml(m.mrf_no + ' — ' + (m.requester_name || '') + (m.job_order ? ' · ' + m.job_order.id : '') + ' · ' + m.open.length + ' item' + (m.open.length === 1 ? '' : 's')) + '</option>').join('');
      invIssSetMode(invIssMrs.length ? 'mrf' : 'free');
    });
  }
  function invIssSetMode(m){
    invIssMode = m;
    $$('#invIssMode [data-m]').forEach(b=> b.classList.toggle('on', b.dataset.m === m));
    $('invIssMrWrap').style.display = m === 'mrf' ? '' : 'none';
    $('invIssAdd').style.display = m === 'free' ? '' : 'none';
    invLE.iss.lines = [invLEBlank()];
    if(m === 'mrf') invIssFromMr(); else invLERender('iss');
  }
  $('invIssMode').addEventListener('click', (e)=>{ const b = e.target.closest('[data-m]'); if(b) invIssSetMode(b.dataset.m); });
  $('invIssAdd').addEventListener('click', ()=>{ invLE.iss.lines.push(invLEBlank()); invLERender('iss'); });
  $('invIssMr').addEventListener('change', invIssFromMr);
  $('invIssWh').addEventListener('change', ()=> invLERender('iss'));
  function invIssFromMr(){
    const m = invIssMrs.find(x=> x.id === $('invIssMr').value);
    if(!m){ invLE.iss.lines = [invLEBlank()]; invLERender('iss'); return; }
    $('invIssWorker').value = m.requested_by || '';
    $('invIssJob').value = m.job_order_id && invX.jobs.some(j=> j.id === m.job_order_id) ? m.job_order_id : '';
    invLE.iss.lines = m.open.map(i=>{
      const left = Number(i.qty_approved != null ? i.qty_approved : i.qty_requested) - Number(i.qty_issued || 0);
      return { key: ++invLEKey, material_id: i.material_id, qty: String(left), unit_cost:'', mr_item_id: i.id, max: left, locked:true, text:'' };
    });
    invLERender('iss');
  }
  $('invIssPost').addEventListener('click', async ()=>{
    const wh = invX.mine.find(w=> w.id === $('invIssWh').value), worker = invX.workers.find(w=> w.id === $('invIssWorker').value);
    if(!worker){ toast('Choose who the materials are issued to'); return; }
    const lines = invLECollect('iss');
    if(typeof lines === 'string'){ toast(lines); return; }
    const short = lines.filter(l=> l.qty > invAvail(wh.id, l.material_id));
    if(short.length){ toast('Not enough stock in ' + wh.code + ' for ' + short.map(l=> invX.catById.get(l.material_id).code).join(', ')); return; }
    const mr = invIssMode === 'mrf' ? invIssMrs.find(x=> x.id === $('invIssMr').value) : null;
    if(invIssMode === 'mrf' && !mr){ toast('Choose the request'); return; }
    if(!confirm('Issue ' + lines.length + ' item' + (lines.length === 1 ? '' : 's') + ' from ' + wh.code + ' to ' + worker.name + (mr ? ' for ' + mr.mrf_no : '') + '?')) return;
    const btn = $('invIssPost'); btn.disabled = true;
    try{
      const r = await invRpc('inv_post_issue', { warehouse_id: wh.id, worker_id: worker.id, mr_id: mr ? mr.id : null,
        project_id: $('invIssProject').value || null, job_order_id: $('invIssJob').value || null, note: $('invIssNote').value.trim(), lines });
      if(!r) return;
      notifyUser(worker.id, 'Materials issued to you', r.slip_no + ' — ' + lines.length + ' item' + (lines.length === 1 ? '' : 's') + '. Please open My Materials and sign to acknowledge.', 'iss-' + r.id);
      toast(r.slip_no + ' posted — ' + worker.name + ' has been asked to acknowledge');
      invAfterPost('iss', r.id);
    }catch(e){ purchFail('Couldn\u2019t post the issue: ', e); }
    finally{ btn.disabled = false; }
  });

  // =====================================================================
  // RETURN — from what the worker currently holds
  // =====================================================================
  let invRetHold = [];
  async function invShowReturns(){
    await invEnter(()=>{
      $('invRetWh').innerHTML = invFillCommon();
      $('invRetWorker').innerHTML = invOpts(invX.workers, w=> w.id, w=> w.name, 'Choose a person…');
      $('invRetNote').value = ''; invRetHold = [];
      $('invRetLines').innerHTML = '<div class="empty-state" style="padding:12px;">Choose who is returning materials.</div>';
    });
  }
  function invPrjLabel(pid, job){
    const p = invX.projects.find(x=> x.id === pid);
    return [p ? p.project_no + ' — ' + p.name : '', job].filter(Boolean).join(' · ') || 'No project / job order';
  }
  $('invRetWorker').addEventListener('change', async ()=>{
    const wid = $('invRetWorker').value; invRetHold = [];
    if(!wid){ $('invRetLines').innerHTML = ''; return; }
    try{
      const { data, error } = await db.rpc('inv_worker_holdings', { p_worker: wid });
      if(error) throw error;
      invRetHold = (data || []).map(h=> Object.assign({ ret:'', cond:'good' }, h));
    }catch(e){ purchFail('Couldn\u2019t load what they hold: ', e); return; }
    if(!invRetHold.length){ $('invRetLines').innerHTML = '<div class="empty-state" style="padding:12px;">This person isn\u2019t holding any issued materials.</div>'; return; }
    let html = '', last = null;
    invRetHold.forEach((h, n)=>{
      const g = (h.project_id || '') + '|' + (h.job_order_id || '');
      if(g !== last){ last = g; html += '<div class="inv-hold-grp">' + escapeHtml(invPrjLabel(h.project_id, h.job_order_id)) + '</div>'; }
      const m = invX.catById.get(h.material_id) || { code:'?', name:'(inactive item)', unit:'' };
      html += '<div class="inv-ln" data-h="' + n + '"><div class="po-no">' + (n + 1) + '</div>' +
        '<div class="inv-desc"><b>' + escapeHtml(m.name) + '</b><div class="po-item-code">' + escapeHtml(m.code) + ' · holding ' + invQty(h.holding) + ' ' + escapeHtml(m.unit) + '</div></div>' +
        '<input type="text" class="num inv-q" data-rq="1" inputmode="decimal" placeholder="0">' +
        '<div class="inv-unit">' + escapeHtml(m.unit) + '</div>' +
        '<select data-rc="1"><option value="good">Good</option><option value="damaged">Damaged</option></select><span></span></div>';
    });
    $('invRetLines').innerHTML = html;
  });
  $('invRetLines').addEventListener('input', (e)=>{ if(e.target.dataset.rq) invRetHold[Number(e.target.closest('[data-h]').dataset.h)].ret = e.target.value.trim(); });
  $('invRetLines').addEventListener('change', (e)=>{ if(e.target.dataset.rc) invRetHold[Number(e.target.closest('[data-h]').dataset.h)].cond = e.target.value; });
  $('invRetPost').addEventListener('click', async ()=>{
    const wh = invX.mine.find(w=> w.id === $('invRetWh').value), wid = $('invRetWorker').value;
    if(!wid){ toast('Choose who is returning'); return; }
    const picked = [];
    for(const h of invRetHold){
      if(!String(h.ret).trim()) continue;
      const q = spParseMoney(h.ret), m = invX.catById.get(h.material_id);
      if(q == null || Number.isNaN(q) || q <= 0){ toast((m ? m.code : 'Item') + ': enter a quantity above 0'); return; }
      if(q > Number(h.holding)){ toast((m ? m.code : 'Item') + ': they only hold ' + invQty(h.holding)); return; }
      picked.push(Object.assign({}, h, { q }));
    }
    if(!picked.length){ toast('Enter what is being returned'); return; }
    // one return slip per project / job order, so each is credited correctly
    const groups = new Map();
    picked.forEach(h=>{ const k = (h.project_id || '') + '|' + (h.job_order_id || ''); if(!groups.has(k)) groups.set(k, []); groups.get(k).push(h); });
    const dmg = picked.filter(h=> h.cond === 'damaged').length;
    if(!confirm('Post ' + groups.size + ' return slip' + (groups.size === 1 ? '' : 's') + ' into ' + wh.code + '?' + (dmg ? '\n\n' + dmg + ' damaged line' + (dmg === 1 ? '' : 's') + ' will be recorded but not restocked.' : ''))) return;
    const btn = $('invRetPost'); btn.disabled = true;
    const done = [];
    try{
      for(const [, hs] of groups){
        const r = await invRpc('inv_post_return', { warehouse_id: wh.id, worker_id: wid, project_id: hs[0].project_id, job_order_id: hs[0].job_order_id,
          note: $('invRetNote').value.trim(), lines: hs.map(h=> ({ material_id: h.material_id, qty: h.q, condition: h.cond })) });
        if(!r) return;
        done.push(r);
      }
      toast(done.map(r=> r.return_no).join(', ') + ' posted');
      invAfterPost('ret', done[0].id);
    }catch(e){ purchFail('Couldn\u2019t post the return' + (done.length ? ' (posted ' + done.map(r=> r.return_no).join(', ') + ' before the error)' : '') + ': ', e); }
    finally{ btn.disabled = false; }
  });

  // =====================================================================
  // TRANSFER
  // =====================================================================
  async function invShowTransfers(){
    await invEnter(()=>{
      $('invTrfFrom').innerHTML = invFillCommon();
      invTrfFillTo();
      $('invTrfNote').value = '';
      invLEBind('trf', 'invTrfLines', { cost:false, avail:true, wh:'invTrfFrom' });
      invLERender('trf');
    });
  }
  function invTrfFillTo(){
    const from = $('invTrfFrom').value;
    $('invTrfTo').innerHTML = invOpts(invX.whs.filter(w=> w.is_active && w.id !== from), w=> w.id, w=> w.code + ' · ' + w.name, 'Choose destination…');
  }
  $('invTrfFrom').addEventListener('change', ()=>{ invTrfFillTo(); invLERender('trf'); });
  $('invTrfAdd').addEventListener('click', ()=>{ invLE.trf.lines.push(invLEBlank()); invLERender('trf'); });
  $('invTrfPost').addEventListener('click', async ()=>{
    const from = invX.mine.find(w=> w.id === $('invTrfFrom').value), to = invX.whs.find(w=> w.id === $('invTrfTo').value);
    if(!to){ toast('Choose where it\u2019s going'); return; }
    const lines = invLECollect('trf');
    if(typeof lines === 'string'){ toast(lines); return; }
    const short = lines.filter(l=> l.qty > invAvail(from.id, l.material_id));
    if(short.length){ toast('Not enough stock in ' + from.code + ' for ' + short.map(l=> invX.catById.get(l.material_id).code).join(', ')); return; }
    if(!confirm('Transfer ' + lines.length + ' item' + (lines.length === 1 ? '' : 's') + ' from ' + from.code + ' to ' + to.code + '?')) return;
    const btn = $('invTrfPost'); btn.disabled = true;
    try{
      const r = await invRpc('inv_post_transfer', { from_warehouse_id: from.id, to_warehouse_id: to.id, note: $('invTrfNote').value.trim(), lines });
      if(!r) return;
      toast(r.transfer_no + ' posted');
      invAfterPost('trf', r.id);
    }catch(e){ purchFail('Couldn\u2019t post the transfer: ', e); }
    finally{ btn.disabled = false; }
  });

  // after any post: open the new slip (with its PDF) in Slips & History
  async function invAfterPost(kind, id){
    showPurchasingView('slips');
    setTimeout(()=> invOpenSlip(kind, id), 60);
  }

  // =====================================================================
  // SLIPS & HISTORY
  // =====================================================================
  let invSlips = [];
  async function invShowSlips(opts){
    if(!(opts && opts.silent)){ $('invSlipView').style.display = 'none'; $('invSlipListView').style.display = ''; $('invSlipList').innerHTML = '<div class="empty-state">Loading…</div>'; }
    if(!(await ensureCloud())) return;
    try{
      await invLoadCtx();
      const [a, b, c, d] = await Promise.all(['rcv', 'iss', 'ret', 'trf'].map(k=> db.from(INV_SLIP_KIND[k].table).select('*').order('created_at', { ascending:false }).limit(300)));
      for(const r of [a, b, c, d]) if(r.error) throw r.error;
      invSlips = [].concat((a.data || []).map(x=> Object.assign({ kind:'rcv' }, x)), (b.data || []).map(x=> Object.assign({ kind:'iss' }, x)),
        (c.data || []).map(x=> Object.assign({ kind:'ret' }, x)), (d.data || []).map(x=> Object.assign({ kind:'trf' }, x)))
        .sort((x, y)=> String(y.created_at).localeCompare(String(x.created_at)));
      $('invSlipWh').innerHTML = '<option value="">All warehouses</option>' + invX.whs.map(w=> '<option value="' + escapeHtml(w.id) + '">' + escapeHtml(w.code) + '</option>').join('');
      invRenderSlips();
    }catch(e){
      $('invSlipList').innerHTML = '<div class="empty-state">' + (purchIsAuthError(e) ? PURCH_EXPIRED_HTML : invMissingTables(e) ? 'Run migration 20260923_08_inventory_movements.sql first.' : 'Couldn\u2019t load slips: ' + escapeHtml(describeCloudError(e))) + '</div>';
    }
  }
  function invSlipNo(s){ return s[INV_SLIP_KIND[s.kind].no]; }
  function invSlipWhs(s){ return s.kind === 'trf' ? [s.from_warehouse_id, s.to_warehouse_id] : [s.warehouse_id]; }
  function invSlipParty(s){
    const wh = (id)=> { const w = invX.whs.find(x=> x.id === id); return w ? w.code : ''; };
    if(s.kind === 'rcv') return (s.po_id ? 'Against PO' : 'No PO') + (s.supplier_ref ? ' · ' + s.supplier_ref : '') + (s.direct_project_id || s.direct_job_order_id ? ' · direct to site' : '');
    if(s.kind === 'iss') return 'To ' + (s.worker_name || '');
    if(s.kind === 'ret') return 'From ' + (s.worker_name || '');
    return wh(s.from_warehouse_id) + ' → ' + wh(s.to_warehouse_id);
  }
  function invRenderSlips(){
    const t = $('invSlipType').value, wh = $('invSlipWh').value, pend = $('invSlipPending').checked;
    const q = ($('invSlipSearch').value || '').trim().toLowerCase();
    const rows = invSlips.filter(s=> (!t || s.kind === t) && (!wh || invSlipWhs(s).includes(wh)) && (!pend || (s.kind === 'iss' && s.status === 'issued')) &&
      (!q || [invSlipNo(s), invSlipParty(s), s.job_order_id, s.note, invPrjLabel(s.project_id || s.direct_project_id, '')].join(' ').toLowerCase().includes(q)));
    $('invSlipList').innerHTML = rows.length ? rows.slice(0, 300).map(s=>
      '<button type="button" class="mt-row" data-kind="' + s.kind + '" data-id="' + escapeHtml(s.id) + '"><div class="mt-row-main">' +
      '<div class="mt-row-title"><span class="mt-code">' + escapeHtml(invSlipNo(s)) + '</span>' + escapeHtml(INV_SLIP_KIND[s.kind].label) +
      (s.kind === 'iss' ? ' <span class="po-status ' + (s.status === 'acknowledged' ? 'fulfilled' : 'returned') + '">' + (s.status === 'acknowledged' ? 'signed' : 'awaiting signature') + '</span>' : '') + '</div>' +
      '<div class="sp-row-sub">' + escapeHtml([mrWhen(s.created_at), invSlipParty(s), s.job_order_id || s.direct_job_order_id, (s.project_id || s.direct_project_id) ? invPrjLabel(s.project_id || s.direct_project_id, '') : ''].filter(Boolean).join(' · ')) + '</div></div>' +
      '<div class="mt-row-price none">' + escapeHtml(invSlipWhs(s).map(id=> (invX.whs.find(w=> w.id === id) || {}).code || '').join(' → ')) + '</div></button>').join('')
      : '<div class="empty-state">' + (invSlips.length ? 'Nothing matches.' : 'No stock movements yet.') + '</div>';
  }
  ['invSlipSearch'].forEach(id=> $(id).addEventListener('input', invRenderSlips));
  ['invSlipType', 'invSlipWh', 'invSlipPending'].forEach(id=> $(id).addEventListener('change', invRenderSlips));
  $('invSlipList').addEventListener('click', (e)=>{
    if(e.target.closest('[data-purch-reauth]')){ purchReauth().then(ok=>{ if(ok) invShowSlips(); }); return; }
    const r = e.target.closest('.mt-row'); if(r) invOpenSlip(r.dataset.kind, r.dataset.id);
  });
  $('invSlipBack').addEventListener('click', ()=>{ $('invSlipView').style.display = 'none'; $('invSlipListView').style.display = ''; invRenderSlips(); });

  let invSlipOpen = null;
  async function invLoadSlip(kind, id){
    const K = INV_SLIP_KIND[kind];
    const [h, it] = await Promise.all([db.from(K.table).select('*').eq('id', id), db.from(K.items).select('*').eq(K.fk, id).order('line_no')]);
    if(h.error) throw h.error; if(it.error) throw it.error;
    if(!h.data || !h.data[0]) throw new Error('Slip not found');
    return { kind, h: h.data[0], items: it.data || [] };
  }
  async function invOpenSlip(kind, id){
    try{
      if(!invX.whs.length) await invLoadCtx();
      invSlipOpen = await invLoadSlip(kind, id);
      invRenderSlipDetail(invSlipOpen, 'invSlip');
      $('invSlipListView').style.display = 'none'; $('invSlipView').style.display = '';
      window.scrollTo({ top:0 });
    }catch(e){ purchFail('Couldn\u2019t open the slip: ', e); }
  }
  function invRenderSlipDetail(d, pre){
    const K = INV_SLIP_KIND[d.kind], h = d.h;
    const wh = (id)=>{ const w = invX.whs.find(x=> x.id === id); return w ? w.code + ' · ' + w.name : ''; };
    $(pre + 'Title').innerHTML = '<span class="mt-code">' + escapeHtml(h[K.no]) + '</span> ' + escapeHtml(K.label) +
      (d.kind === 'iss' ? ' <span class="po-status ' + (h.status === 'acknowledged' ? 'fulfilled' : 'returned') + '">' + (h.status === 'acknowledged' ? 'signed' : 'awaiting signature') + '</span>' : '');
    const kv = (k, v)=> v ? '<div><div class="k">' + k + '</div><div class="v">' + v + '</div></div>' : '';
    $(pre + 'Info').innerHTML = kv('Date', escapeHtml(mrWhen(h.created_at))) +
      (d.kind === 'trf' ? kv('From', escapeHtml(wh(h.from_warehouse_id))) + kv('To', escapeHtml(wh(h.to_warehouse_id))) : kv('Warehouse', escapeHtml(wh(h.warehouse_id)))) +
      (d.kind === 'iss' ? kv('Issued to', escapeHtml(h.worker_name)) + kv('Issued by', escapeHtml(h.issued_by_name)) + (h.ack_at ? kv('Signed', escapeHtml(mrWhen(h.ack_at))) : '') : '') +
      (d.kind === 'ret' ? kv('Returned by', escapeHtml(h.worker_name)) + kv('Received by', escapeHtml(h.received_by_name)) : '') +
      (d.kind === 'rcv' ? kv('Received by', escapeHtml(h.received_by_name)) + kv('DR / invoice', escapeHtml(h.supplier_ref)) + ((h.direct_project_id || h.direct_job_order_id) ? kv('Delivered to site', escapeHtml(invPrjLabel(h.direct_project_id, h.direct_job_order_id))) : '') : '') +
      (d.kind === 'trf' ? kv('By', escapeHtml(h.created_by_name)) : '') +
      ((h.project_id || h.job_order_id) ? kv('Project / job', escapeHtml(invPrjLabel(h.project_id, h.job_order_id))) : '') + kv('Note', escapeHtml(h.note));
    const name = (id)=> invX.catById.get(id) || { code:'', name:'(inactive item)', unit:'' };
    $(pre + 'Items').innerHTML = '<thead><tr><th>#</th><th>Item</th><th class="num">Qty</th><th>Unit</th>' + (d.kind === 'ret' ? '<th>Condition</th>' : d.kind === 'rcv' ? '<th>As on PO</th>' : '') + '</tr></thead><tbody>' +
      d.items.map((it, i)=>{ const m = name(it.material_id);
        return '<tr><td>' + (i + 1) + '</td><td><b>' + escapeHtml(m.name) + '</b><div class="sp-row-sub">' + escapeHtml(m.code) + '</div></td><td class="num">' + invQty(it.qty) + '</td><td>' + escapeHtml(m.unit) + '</td>' +
          (d.kind === 'ret' ? '<td>' + (it.condition === 'damaged' ? '<span class="sp-tag danger">Damaged</span>' : 'Good') + '</td>' : d.kind === 'rcv' ? '<td>' + (it.qty_po_units ? invQty(it.qty_po_units) + ' ' + escapeHtml(it.po_unit) : '—') + '</td>' : '') + '</tr>';
      }).join('') + '</tbody>';
  }
  $('invSlipPdf').addEventListener('click', ()=>{ if(invSlipOpen) invSlipPdf(invSlipOpen); });

  // ---------- slip PDF (same look as the PO) ----------
  async function invSlipPdf(d){
    try{
      await loadAwesScript('jspdf', awesLibs.jspdf); await loadAwesScript('autotable', awesLibs.autotable);
      await poLoadSettings().catch(()=>{});
      const co = poSettingsData || {}, style = co.header_style || 'green';
      const logo = co.logo_path ? await poLoadImage(co.logo_path).then(img=> poLogoForStyle(img, style)) : await poDefaultLogo(style);
      const fonts = await poLoadFonts();
      const { jsPDF } = window.jspdf;
      const doc = new jsPDF({ orientation:'p', unit:'pt', format:'a4', compress:true });
      let F = 'helvetica', FS = ['helvetica', 'bold'], FB = ['helvetica', 'bold'];
      if(fonts){ try{
        doc.addFileToVFS('Inter-Regular.ttf', fonts.regular); doc.addFont('Inter-Regular.ttf', 'Inter', 'normal');
        doc.addFileToVFS('Inter-SemiBold.ttf', fonts.semibold); doc.addFont('Inter-SemiBold.ttf', 'Inter', 'bold');
        doc.addFileToVFS('Inter-Bold.ttf', fonts.bold); doc.addFont('Inter-Bold.ttf', 'InterBold', 'normal');
        F = 'Inter'; FS = ['Inter', 'bold']; FB = ['InterBold', 'normal'];
      }catch(e){} }
      const reg = (s)=>{ doc.setFont(F, 'normal'); doc.setFontSize(s); }, semi = (s)=>{ doc.setFont(FS[0], FS[1]); doc.setFontSize(s); }, bold = (s)=>{ doc.setFont(FB[0], FB[1]); doc.setFontSize(s); };
      const W = doc.internal.pageSize.getWidth(), H = doc.internal.pageSize.getHeight(), M = 36;
      const G = [21, 77, 52], SUB = [96, 108, 101], INK = [28, 34, 30], LINE = [216, 223, 219];
      const green = style !== 'white', ink = green ? [255, 255, 255] : INK;
      const K = INV_SLIP_KIND[d.kind], h = d.h, headH = 104;
      if(green){ doc.setFillColor(...G); doc.rect(0, 0, W, headH, 'F'); } else { doc.setFillColor(...G); doc.rect(0, headH - 4, W, 4, 'F'); }
      if(logo && logo.w){ const r = Math.min(150 / logo.w, 44 / logo.h); try{ doc.addImage(logo.dataUrl, 'PNG', M, 16, logo.w * r, logo.h * r, 'inv-logo', 'FAST'); }catch(e){} }
      semi(9.5); doc.setTextColor(...ink); doc.text(co.company_name || '', M, 78);
      reg(7.4); doc.text(doc.splitTextToSize(co.address || '', 320).slice(0, 1), M, 90);
      bold(16); doc.text(K.title, W - M, 36, { align:'right' });
      semi(10.5); doc.text(h[K.no], W - M, 54, { align:'right' });
      reg(8.8); doc.text(mrWhen(h.created_at), W - M, 68, { align:'right' });
      let y = headH + 20;
      const wh = (id)=>{ const w = invX.whs.find(x=> x.id === id); return w ? w.code + ' — ' + w.name : ''; };
      const info = [].concat(
        d.kind === 'trf' ? [['From', wh(h.from_warehouse_id)], ['To', wh(h.to_warehouse_id)]] : [['Warehouse', wh(h.warehouse_id)]],
        d.kind === 'iss' ? [['Issued to', h.worker_name]] : [], d.kind === 'ret' ? [['Returned by', h.worker_name]] : [],
        d.kind === 'rcv' ? [['DR / invoice', h.supplier_ref], ['Delivered to site', (h.direct_project_id || h.direct_job_order_id) ? invPrjLabel(h.direct_project_id, h.direct_job_order_id) : '']] : [],
        [['Project / job', (h.project_id || h.job_order_id) ? invPrjLabel(h.project_id, h.job_order_id) : ''], ['Note', h.note]]).filter(r=> r[1]);
      info.forEach(([k, v])=>{
        reg(7.8); doc.setTextColor(...SUB); doc.text(k, M, y);
        reg(9); doc.setTextColor(...INK); const ls = doc.splitTextToSize(String(v), W - M * 2 - 90); doc.text(ls, M + 90, y); y += ls.length * 11 + 3;
      });
      const name = (id)=> invX.catById.get(id) || { code:'', name:'(inactive item)', unit:'' };
      doc.autoTable({
        startY: y + 8, margin: { left:M, right:M, bottom:60 },
        head: [['#', 'Code', 'Item', 'Qty', 'Unit'].concat(d.kind === 'ret' ? ['Condition'] : d.kind === 'rcv' ? ['As on PO'] : [])],
        body: d.items.map((it, i)=>{ const m = name(it.material_id);
          return [String(i + 1), m.code, m.name, invQty(it.qty), m.unit].concat(d.kind === 'ret' ? [it.condition === 'damaged' ? 'Damaged' : 'Good'] : d.kind === 'rcv' ? [it.qty_po_units ? invQty(it.qty_po_units) + ' ' + it.po_unit : ''] : []); }),
        theme:'plain',
        styles: { font:F, fontSize:8.6, cellPadding:{ top:5, bottom:5, left:6, right:6 }, textColor:INK, lineColor:LINE, lineWidth:{ bottom:0.5 } },
        headStyles: { font:F, fontStyle:'bold', fillColor:G, textColor:255, fontSize:7.8 },
        alternateRowStyles: { fillColor:[247, 250, 248] },
        columnStyles: { 0:{ cellWidth:22, halign:'center' }, 1:{ cellWidth:64, textColor:SUB, fontSize:7.6 }, 3:{ halign:'right', cellWidth:56 }, 4:{ halign:'center', cellWidth:44 } }
      });
      // signatures at the bottom
      let sig = null;
      if(d.kind === 'iss' && h.ack_signature_path){
        try{ const r = await db.storage.from('inventory-signatures').download(h.ack_signature_path); if(r.data){ const url = await poBlobToDataUrl(r.data); const sz = await poImageSize(url); sig = { dataUrl:url, w:sz.w, h:sz.h }; } }catch(e){}
      }
      const blocks = d.kind === 'iss' ? [['Issued by', h.issued_by_name, null], ['Received by', h.worker_name, sig]]
        : d.kind === 'ret' ? [['Returned by', h.worker_name, null], ['Received by', h.received_by_name, null]]
        : d.kind === 'rcv' ? [['Delivered by (supplier)', '', null], ['Received by', h.received_by_name, null]]
        : [['Released by', h.created_by_name, null], ['Received by', '', null]];
      const sigTop = H - 46 - 90, sw = (W - M * 2 - 40) / 2;
      if(doc.lastAutoTable.finalY > sigTop - 10) doc.addPage();
      blocks.forEach(([cap, nm, img], i)=>{
        const x = M + i * (sw + 40);
        semi(6.8); doc.setTextColor(...SUB); doc.text(cap.toUpperCase(), x, sigTop);
        if(img && img.w){ const r = Math.min((sw - 20) / img.w, 44 / img.h); try{ doc.addImage(img.dataUrl, 'PNG', x + (sw - img.w * r) / 2, sigTop + 56 - img.h * r, img.w * r, img.h * r, undefined, 'FAST'); }catch(e){} }
        doc.setDrawColor(70, 76, 72); doc.setLineWidth(0.6); doc.line(x, sigTop + 58, x + sw, sigTop + 58);
        semi(8.6); doc.setTextColor(...INK); doc.text(nm ? nm.toUpperCase() : 'Signature over printed name / Date', x + sw / 2, sigTop + 70, { align:'center' });
        if(i === 1 && d.kind === 'iss' && h.ack_at){ reg(7.4); doc.setTextColor(...SUB); doc.text('Acknowledged ' + mrWhen(h.ack_at), x + sw / 2, sigTop + 81, { align:'center' }); }
      });
      const pages = doc.internal.getNumberOfPages();
      for(let p = 1; p <= pages; p++){ doc.setPage(p); reg(7); doc.setTextColor(...SUB); doc.text(h[K.no] + '   •   ' + (co.company_name || ''), M, H - 20); doc.text('Page ' + p + ' of ' + pages, W - M, H - 20, { align:'right' }); }
      const title = K.label + ' ' + h[K.no];
      $('previewOverlay').querySelector('h3').textContent = title;
      $('previewOkBtn').textContent = 'Close';
      $('previewOverlay').style.zIndex = '99';
      $('previewOverlay').classList.add('open');
      await renderPdfPreview(doc, h[K.no] + '.pdf', title);
    }catch(e){ console.error('slip pdf failed', e); toast('Couldn\u2019t build the PDF: ' + (e && e.message ? e.message : e)); }
  }

  // =====================================================================
  // MY MATERIALS (technician): sign for issue slips; what I hold
  // =====================================================================
  let invMine = [], invMineOpen = null, invSigPad = null;
  async function invShowMyMaterials(){
    $('invMineSlipView').style.display = 'none'; $('invMineListView').style.display = '';
    $('invMinePending').innerHTML = '<div class="empty-state">Loading…</div>';
    if(!(await ensureCloud())){ $('invMinePending').innerHTML = '<div class="empty-state">Not connected.</div>'; return; }
    try{
      const [s, hold, cat, pr] = await Promise.all([
        db.from('issue_slips').select('*, issue_slip_items(count)').eq('worker_id', currentUser.id).order('created_at', { ascending:false }).limit(100),
        db.rpc('inv_worker_holdings', { p_worker: currentUser.id }),
        db.from('materials').select('id, code, name, unit').eq('is_active', true),
        db.from('projects').select('id, project_no, name')
      ]);
      if(s.error) throw s.error;
      invMine = s.data || [];
      invX.catById = new Map((cat.data || []).map(m=> [m.id, m]));
      invX.projects = pr.data || [];
      const pend = invMine.filter(x=> x.status === 'issued');
      const row = (x)=> '<button type="button" class="mt-row" data-id="' + escapeHtml(x.id) + '"><div class="mt-row-main"><div class="mt-row-title"><span class="mt-code">' + escapeHtml(x.slip_no) + '</span>' +
        (x.status === 'issued' ? '<span class="po-status returned">sign now</span>' : '<span class="po-status fulfilled">signed</span>') + '</div>' +
        '<div class="sp-row-sub">' + escapeHtml([mrWhen(x.created_at), (x.issue_slip_items && x.issue_slip_items[0] ? x.issue_slip_items[0].count : 0) + ' item(s)', 'by ' + x.issued_by_name, x.job_order_id].filter(Boolean).join(' · ')) + '</div></div></button>';
      $('invMinePending').innerHTML = pend.length ? pend.map(row).join('') : '<div class="empty-state" style="padding:12px;">Nothing to sign. 👍</div>';
      $('invMineRecent').innerHTML = invMine.filter(x=> x.status !== 'issued').slice(0, 20).map(row).join('') || '<div class="empty-state" style="padding:12px;">No slips yet.</div>';
      const hs = hold.error ? [] : (hold.data || []);
      let html = '', last = null;
      hs.forEach(hh=>{
        const g = (hh.project_id || '') + '|' + (hh.job_order_id || '');
        if(g !== last){ last = g; html += '<div class="inv-hold-grp">' + escapeHtml(invPrjLabel(hh.project_id, hh.job_order_id)) + '</div>'; }
        const m = invX.catById.get(hh.material_id) || { code:'', name:'(item)', unit:'' };
        html += '<div class="sp-row"><div class="sp-row-top"><div><div class="sp-row-title">' + escapeHtml(m.name) + '</div><div class="sp-row-sub">' + escapeHtml(m.code) + '</div></div>' +
          '<div class="mt-row-price"><span class="inv-qty">' + invQty(hh.holding) + ' ' + escapeHtml(m.unit) + '</span></div></div></div>';
      });
      $('invMineHold').innerHTML = html || '<div class="empty-state" style="padding:12px;">You\u2019re not holding any issued materials.</div>';
      invSetMineBadge(pend.length);
    }catch(e){
      $('invMinePending').innerHTML = '<div class="empty-state">' + (purchIsAuthError(e) ? PURCH_EXPIRED_HTML : invMissingTables(e) ? 'Inventory isn\u2019t set up yet.' : 'Couldn\u2019t load: ' + escapeHtml(describeCloudError(e))) + '</div>';
    }
  }
  function invSetMineBadge(n){
    const b = document.getElementById('techQaMyMatBadge'); if(!b) return;
    b.textContent = n ? n + ' to sign' : ''; b.style.display = n ? '' : 'none';
  }
  // cheap check on the home screen so the tile shows how many slips need signing
  async function invRefreshMineBadge(){
    if(!currentUser || currentUser.role === 'admin' || currentUser.role === 'customer') return;
    try{
      const { data, error } = await db.from('issue_slips').select('id').eq('worker_id', currentUser.id).eq('status', 'issued');
      if(!error) invSetMineBadge((data || []).length);
    }catch(e){}
  }
  ['invMinePending', 'invMineRecent'].forEach(id=> $(id).addEventListener('click', (e)=>{
    if(e.target.closest('[data-purch-reauth]')){ purchReauth().then(ok=>{ if(ok) invShowMyMaterials(); }); return; }
    const r = e.target.closest('.mt-row'); if(r) invOpenMineSlip(r.dataset.id);
  }));
  $('invMineBack').addEventListener('click', ()=>{ $('invMineSlipView').style.display = 'none'; $('invMineListView').style.display = ''; invShowMyMaterials(); });
  $('techQaMyMaterials').addEventListener('click', ()=> showPurchasingView('myMaterials'));
  async function invOpenMineSlip(id){
    try{
      const whs = await db.from('warehouses').select('*'); invX.whs = whs.data || [];
      invMineOpen = await invLoadSlip('iss', id);
      invRenderSlipDetail(invMineOpen, 'invMine');
      const signed = invMineOpen.h.status === 'acknowledged';
      $('invMineSignSec').style.display = signed ? 'none' : '';
      $('invMineActions').style.display = signed ? 'none' : '';
      $('invMineListView').style.display = 'none'; $('invMineSlipView').style.display = '';
      window.scrollTo({ top:0 });
      if(!signed){
        await loadAwesScript('signature', awesLibs.signature);
        invSigPad = new SignaturePad($('invMineSig'), { penColor:'#1C2621', backgroundColor:'rgba(255,255,255,0)' });
        invSigFit();
      }
    }catch(e){ purchFail('Couldn\u2019t open the slip: ', e); }
  }
  // Size the canvas to its box (sharp on high-DPI phones). Re-run on resize
  // / rotation, redrawing what was already signed so it isn't squashed.
  function invSigFit(){
    const c = $('invMineSig');
    if(!invSigPad || !c.offsetWidth) return;
    const data = invSigPad.toData(), ratio = Math.max(window.devicePixelRatio || 1, 1);
    c.width = c.offsetWidth * ratio; c.height = c.offsetHeight * ratio;
    c.getContext('2d').scale(ratio, ratio);
    invSigPad.clear();
    if(data && data.length) invSigPad.fromData(data);
  }
  window.addEventListener('resize', ()=>{ if($('invMineSlipView').style.display !== 'none') invSigFit(); });
  $('invMineSigClear').addEventListener('click', ()=>{ if(invSigPad) invSigPad.clear(); });
  $('invMineAck').addEventListener('click', async ()=>{
    if(!invMineOpen) return;
    if(!invSigPad || invSigPad.isEmpty()){ toast('Please sign in the box first'); return; }
    if(!(await purchEnsureSession())) return;
    const btn = $('invMineAck'); btn.disabled = true;
    try{
      // crop to the ink (the signing box is mostly empty) so it prints large
      // and crisp on the slip — same routine as the PO e-signatures
      const cropped = poCleanSignature($('invMineSig')) || $('invMineSig');
      const blob = await new Promise(res=> cropped.toBlob(res, 'image/png'));
      const path = currentUser.id + '/' + invMineOpen.h.id + '-' + Date.now() + '.png';
      const up = await db.storage.from('inventory-signatures').upload(path, blob, { contentType:'image/png', upsert:false });
      if(up.error) throw up.error;
      const { error } = await db.rpc('inv_ack_issue', { p_slip: invMineOpen.h.id, p_signature_path: path });
      if(error) throw error;
      toast(invMineOpen.h.slip_no + ' acknowledged — thank you');
      $('invMineSlipView').style.display = 'none'; $('invMineListView').style.display = '';
      invShowMyMaterials();
    }catch(e){ purchFail('Couldn\u2019t acknowledge: ', e); }
    finally{ btn.disabled = false; }
  });


  // =====================================================================
  // Inventory — Reports (migration 20260923_09_inventory_reports.sql)
  //
  // Every figure comes from a database function computed from the stock
  // ledger (Philippine-time months). Storekeepers get their own warehouses
  // and quantities only — the functions return NULL for every value, and
  // this screen simply hides value columns when there are none.
  //
  // Each report builds one "model" { title, subtitle, sheets:[{name, head,
  // rows, money[], totalRow}] } that drives the on-screen table, the PDF
  // and the Excel file, so all three always show the same numbers.
  // =====================================================================

  let rpTab = 'balance', rpModel = null, rpProjectsAll = [], rpReorderRows = [];
  const RP_MONTH = (d)=> new Date(String(d).slice(0, 10) + 'T00:00:00').toLocaleDateString('en-PH', { month:'long', year:'numeric' });
  function rpMoney(){ return invIsAdmin(); }
  function rpMonthRange(){
    const f = $('rpFrom').value, t = $('rpTo').value || f;
    const first = f + '-01';
    const [y, m] = t.split('-').map(Number);
    const last = new Date(Date.UTC(y, m, 0)).toISOString().slice(0, 10);   // last day of the To month
    return { first, last, label: f === t ? RP_MONTH(first) : RP_MONTH(first) + ' – ' + RP_MONTH(t + '-01') };
  }
  const rpItem = (id)=> invX.catById.get(id) || { code:'', name:'(inactive item)', unit:'', category:'' };
  const rpWhCode = (id)=> (invX.whs.find(w=> w.id === id) || {}).code || '';
  function rpPrj(pid, job){
    const p = rpProjectsAll.find(x=> x.id === pid) || invX.projects.find(x=> x.id === pid);
    return [p ? p.project_no + ' ' + p.name : '', job].filter(Boolean).join(' · ') || '—';
  }
  function rpMatchItem(id){
    const m = rpItem(id), cat = $('rpCat').value;
    if(cat && m.category !== cat) return false;
    return true;
  }
  function rpSearchOk(text){
    const words = ($('rpSearch').value || '').trim().toLowerCase().split(/\s+/).filter(Boolean);
    return !words.length || words.every(w=> String(text).toLowerCase().includes(w));
  }

  async function rpShow(){
    if(!(await ensureCloud())){ toast('Not connected'); return; }
    try{
      await invLoadCtx();
      if(invIsAdmin()){ const r = await db.from('projects').select('id, project_no, name, budget, status'); rpProjectsAll = r.data || []; }
    }catch(e){ purchFail('Couldn\u2019t load inventory: ', e); return; }
    $('purchasingView').classList.add('po-wide');
    if(!$('rpFrom').value){
      const now = poToday().slice(0, 7);
      $('rpFrom').value = now; $('rpTo').value = now;
    }
    const whs = invIsAdmin() ? invX.whs : invX.mine;
    $('rpWh').innerHTML = (whs.length > 1 ? '<option value="">All warehouses</option>' : '') + whs.map(w=> '<option value="' + escapeHtml(w.id) + '">' + escapeHtml(w.code + ' · ' + w.name) + '</option>').join('');
    if($('rpCat').options.length <= 1) $('rpCat').innerHTML = '<option value="">All categories</option>' + PURCH_CATEGORIES.map(c=> '<option>' + escapeHtml(c) + '</option>').join('');
    rpSetTab(rpTab === 'project' && !invIsAdmin() ? 'balance' : rpTab);
  }
  function rpSetTab(tab){
    rpTab = tab;
    $$('#rpTabs [data-rp]').forEach(b=> b.classList.toggle('active', b.dataset.rp === tab));
    $$('.rp-filters .rp-f').forEach(f=>{ f.style.display = f.dataset.for.split(' ').includes(tab) ? '' : 'none'; });
    $('rpMakePo').style.display = tab === 'reorder' && invIsAdmin() ? '' : 'none';
    rpModel = null;
    $('rpSummary').innerHTML = ''; $('rpCheck').textContent = ''; $('rpCheck').className = 'rp-check';
    $('rpOut').innerHTML = '<div class="empty-state">Choose the options and tap <b>Run Report</b>.</div>';
  }
  $('rpTabs').addEventListener('click', (e)=>{ const b = e.target.closest('[data-rp]'); if(b) rpSetTab(b.dataset.rp); });
  $('rpRun').addEventListener('click', ()=> rpRun());
  $('rpSearch').addEventListener('keydown', (e)=>{ if(e.key === 'Enter') rpRun(); });

  async function rpRun(){
    const btn = $('rpRun'); btn.disabled = true; btn.textContent = 'Running…';
    $('rpOut').innerHTML = '<div class="empty-state">Running…</div>';
    try{
      if(!(await purchEnsureSession())) return;
      const fn = { balance: rpBalance, register: rpRegister, project: rpProjectCost, slow: rpSlow, reorder: rpReorder, unreturned: rpUnreturned }[rpTab];
      rpModel = await fn();
      rpRender(rpModel);
    }catch(e){
      rpModel = null;
      $('rpOut').innerHTML = '<div class="empty-state">' + (invMissingTables(e) || /function .*inv_rpt/.test(describeCloudError(e)) ? 'Run migration 20260923_09_inventory_reports.sql in Supabase first.' : 'Couldn\u2019t run the report: ' + escapeHtml(describeCloudError(e))) + '</div>';
    }finally{ btn.disabled = false; btn.textContent = 'Run Report'; }
  }
  async function rpCall(fn, args){
    const { data, error } = await db.rpc(fn, args);
    if(error) throw error;
    return data || [];
  }

  // ---------- 1. Stock balance: beginning → ending ----------
  async function rpBalance(){
    const r = rpMonthRange(), wh = $('rpWh').value || null;
    const rows = (await rpCall('inv_rpt_balance', { p_from: r.first, p_to: r.last, p_warehouse: wh }))
      .filter(x=> rpMatchItem(x.material_id) && rpSearchOk([rpItem(x.material_id).code, rpItem(x.material_id).name].join(' ')));
    const money = rpMoney() && rows.some(x=> x.end_value != null);
    // With values, every quantity sits right beside its peso amount under
    // one heading (Beginning: Qty | ₱, + Purchased: Qty | ₱ …).
    const MEAS = [['Beginning', 'beg'], ['+ Purchased', 'purch'], ['+ Returned', 'ret'], ['− Issued', 'iss'], ['± Transfers', 'trf'], ['± Adjust.', 'adj'], ['= Ending', 'end']];
    const lead = ['Month', 'Warehouse', 'Code', 'Item', 'Unit'];
    const head = money ? lead.concat(...MEAS.map(()=> ['Qty', '₱'])) : lead.concat(MEAS.map(m=> m[0]));
    const headGroups = money ? [['', lead.length]].concat(MEAS.map(m=> [m[0], 2])) : null;
    const moneyCols = money ? MEAS.map((m, i)=> lead.length + i * 2 + 1) : null;
    const sorted = rows.slice().sort((a, b)=> a.month.localeCompare(b.month) || rpWhCode(a.warehouse_id).localeCompare(rpWhCode(b.warehouse_id)) || rpItem(a.material_id).name.localeCompare(rpItem(b.material_id).name, undefined, { numeric:true }));
    const out = sorted.map(x=>{
      const m = rpItem(x.material_id);
      const cells = money ? [].concat(...MEAS.map(([, k])=> [+x[k + '_qty'], +x[k + '_value']])) : MEAS.map(([, k])=> +x[k + '_qty']);
      return [RP_MONTH(x.month), rpWhCode(x.warehouse_id), m.code, m.name, m.unit].concat(cells);
    });
    // month totals (values only — adding feet to kilograms means nothing)
    const months = Array.from(new Set(sorted.map(x=> x.month)));
    const totals = months.map(mo=>{
      const rs = sorted.filter(x=> x.month === mo);
      const sum = (k)=> rs.reduce((a, x)=> a + Number(x[k] || 0), 0);
      return { month: mo, beg: sum('beg_value'), purch: sum('purch_value'), ret: sum('ret_value'), iss: sum('iss_value'), trf: sum('trf_value'), adj: sum('adj_value'), end: sum('end_value') };
    });
    // reconciliation: the To month's ending vs Stock on Hand now (only
    // meaningful when the report runs up to the current month)
    let check = null;
    if(r.last.slice(0, 7) === poToday().slice(0, 7)){
      const last = sorted.filter(x=> x.month.slice(0, 7) === r.last.slice(0, 7));
      const bad = last.filter(x=> Math.abs(Number(x.end_qty) - invAvail(x.warehouse_id, x.material_id)) > 0.0005);
      const onhandOnly = Array.from(invX.avail.entries()).filter(([k, q])=>{
        const [w, m] = k.split('|');
        return q > 0 && (!wh || w === wh) && rpMatchItem(m) && !last.some(x=> x.warehouse_id === w && x.material_id === m);
      });
      check = (bad.length || onhandOnly.length)
        ? { ok:false, text: '⚠ ' + (bad.length + onhandOnly.length) + ' item(s) don\u2019t tie to Stock on Hand — ' + bad.concat(onhandOnly.map(([k])=> ({ material_id:k.split('|')[1] }))).slice(0, 4).map(x=> rpItem(x.material_id).code).join(', ') }
        : { ok:true, text: '✓ This month\u2019s ending balances tie to Stock on Hand' + (search() ? ' (for the items shown)' : '') + '.' };
    }
    function search(){ return ($('rpSearch').value || '').trim() || $('rpCat').value; }
    const lastT = totals[totals.length - 1];
    return {
      title: 'Monthly Stock Balance', subtitle: r.label + ' · ' + (wh ? rpWhCode(wh) : 'All warehouses'),
      summary: money && lastT ? [['Beginning value', invMoney(totals[0].beg)], ['Purchased', invMoney(totals.reduce((a, t)=> a + t.purch, 0))],
        ['Issued', invMoney(totals.reduce((a, t)=> a + t.iss, 0))], ['Ending value', invMoney(lastT.end)]]
        : [['Items', String(new Set(sorted.map(x=> x.material_id)).size)], ['Months', String(months.length)]],
      check,
      sheets: [{ name:'Stock Balance', head, headGroups, rows: out, groupCol: 0, numFrom: 5, moneyCols,
        // month totals: pesos only (feet + kilograms can't be added), each under its own ₱ column
        groupTotals: money ? Object.fromEntries(totals.map(t=> [RP_MONTH(t.month),
          ['', '', '', 'Month total', ''].concat(...['beg', 'purch', 'ret', 'iss', 'trf', 'adj', 'end'].map(k=> ['', t[k]]))])) : null,
        landscape: true }]
    };
  }

  // ---------- 2. Purchases, issuances & returns ----------
  async function rpRegister(){
    const r = rpMonthRange(), wh = $('rpWh').value || null, kind = $('rpKind').value, view = $('rpRegView').value;
    const lines = (await rpCall('inv_rpt_register', { p_from: r.first, p_to: r.last, p_warehouse: wh }))
      .filter(x=> (!kind || x.kind === kind) && rpMatchItem(x.material_id) &&
        rpSearchOk([rpItem(x.material_id).code, rpItem(x.material_id).name, x.doc_ref, x.worker_name, x.supplier, x.po_no, rpPrj(x.project_id, x.job_order_id)].join(' ')));
    const money = rpMoney() && lines.some(x=> x.value != null);
    const K = { purchase:'Purchase', issue:'Issue', 'return':'Return' };
    const tot = (k, f)=> lines.filter(x=> x.kind === k && (!f || f(x))).reduce((a, x)=> a + Number(x.value || 0), 0);
    const summary = money ? [['Purchased', invMoney(tot('purchase'))], ['Issued', invMoney(tot('issue'))], ['Returned (good)', invMoney(tot('return', x=> x.condition === 'good'))],
      ['Net issued', invMoney(tot('issue') - tot('return', x=> x.condition === 'good'))]]
      : [['Lines', String(lines.length)], ['Purchases', String(lines.filter(x=> x.kind === 'purchase').length)], ['Issues', String(lines.filter(x=> x.kind === 'issue').length)], ['Returns', String(lines.filter(x=> x.kind === 'return').length)]];
    const sheets = [];
    // per item
    const byItem = new Map();
    lines.forEach(x=>{
      const e = byItem.get(x.material_id) || { p:0, pv:0, i:0, iv:0, rg:0, rv:0, rd:0 };
      const q = Number(x.qty), v = Number(x.value || 0);
      if(x.kind === 'purchase'){ e.p += q; e.pv += v; }
      else if(x.kind === 'issue'){ e.i += q; e.iv += v; }
      else if(x.condition === 'damaged') e.rd += q; else { e.rg += q; e.rv += v; }
      byItem.set(x.material_id, e);
    });
    const itemRows = Array.from(byItem.entries()).sort((a, b)=> rpItem(a[0]).name.localeCompare(rpItem(b[0]).name, undefined, { numeric:true })).map(([id, e])=>{
      const m = rpItem(id);
      return [m.code, m.name, m.unit, e.p, e.i, e.rg, e.rd, e.i - e.rg].concat(money ? [e.pv, e.iv, e.rv, e.iv - e.rv] : []);
    });
    const itemTot = money ? ['', 'Total', '', '', '', '', '', ''].concat([itemRows.reduce((a, r)=> a + r[8], 0), itemRows.reduce((a, r)=> a + r[9], 0), itemRows.reduce((a, r)=> a + r[10], 0), itemRows.reduce((a, r)=> a + r[11], 0)]) : null;
    if(view === 'summary'){
      sheets.push({ name:'By Item', head:['Code', 'Item', 'Unit', 'Purchased', 'Issued', 'Returned (good)', 'Returned (damaged)', 'Net issued'].concat(money ? ['Purchased ₱', 'Issued ₱', 'Returned ₱', 'Net issued ₱'] : []),
        rows:itemRows, numFrom:3, moneyFrom: money ? 8 : null, totalRow:itemTot, landscape:true });
      // by project / job
      const group = (keyFn, labelFn, filter)=>{
        const g = new Map();
        lines.filter(filter).forEach(x=>{ const k = keyFn(x); const e = g.get(k) || { label: labelFn(x), n:0, v:0, q:0 }; e.n++; e.v += Number(x.value || 0) * (x.kind === 'return' ? -1 : 1); g.set(k, e); });
        return Array.from(g.values()).sort((a, b)=> b.v - a.v || a.label.localeCompare(b.label));
      };
      const prj = group(x=> (x.project_id || '') + '|' + (x.job_order_id || ''), x=> rpPrj(x.project_id, x.job_order_id), x=> x.kind !== 'purchase' && (x.project_id || x.job_order_id) && x.condition !== 'damaged');
      if(prj.length) sheets.push({ name:'By Project', head:['Project / job order', 'Lines'].concat(money ? ['Net material cost ₱'] : []), rows: prj.map(e=> [e.label, e.n].concat(money ? [e.v] : [])), numFrom:1, moneyFrom: money ? 2 : null });
      const wk = group(x=> x.worker_name || '—', x=> x.worker_name || '—', x=> x.kind !== 'purchase' && x.condition !== 'damaged');
      if(wk.length) sheets.push({ name:'By Worker', head:['Worker', 'Lines'].concat(money ? ['Net issued ₱'] : []), rows: wk.map(e=> [e.label, e.n].concat(money ? [e.v] : [])), numFrom:1, moneyFrom: money ? 2 : null });
      const sp = group(x=> x.supplier || '—', x=> x.supplier || 'No supplier', x=> x.kind === 'purchase');
      if(sp.length) sheets.push({ name:'By Supplier', head:['Supplier', 'Lines'].concat(money ? ['Purchased ₱'] : []), rows: sp.map(e=> [e.label, e.n].concat(money ? [e.v] : [])), numFrom:1, moneyFrom: money ? 2 : null });
    }
    // detail (always included in Excel; shown on screen in Detail view)
    const detail = lines.map(x=>{
      const m = rpItem(x.material_id);
      return [mrWhen(x.at), K[x.kind] + (x.condition === 'damaged' ? ' (damaged)' : ''), x.doc_ref, rpWhCode(x.warehouse_id), m.code, m.name, Number(x.qty), m.unit,
        x.kind === 'purchase' ? [x.supplier, x.po_no].filter(Boolean).join(' · ') : (x.worker_name || ''), rpPrj(x.project_id, x.job_order_id), x.note || '']
        .concat(money ? [x.unit_cost != null ? Number(x.unit_cost) : '', x.value != null ? Number(x.value) : ''] : []);
    });
    const detailSheet = { name:'Detail', head:['Date', 'Type', 'Slip no.', 'Warehouse', 'Code', 'Item', 'Qty', 'Unit', 'Supplier / worker', 'Project / job', 'Note'].concat(money ? ['Unit cost ₱', 'Value ₱'] : []),
      rows: detail, numCols:[6], moneyFrom: money ? 11 : null, landscape:true };
    if(view === 'detail') sheets.unshift(detailSheet);
    else{ detailSheet.excelOnly = true; sheets.push(detailSheet); }   // Summary on screen/PDF; Excel gets the detail too
    return { title: 'Purchases, Issuances & Returns', subtitle: r.label + ' · ' + (wh ? rpWhCode(wh) : 'All warehouses') + (kind ? ' · ' + K[kind] + 's only' : ''), summary, sheets };
  }

  // ---------- 3. Project cost by month (admin) ----------
  async function rpProjectCost(){
    const r = rpMonthRange();
    const rows = await rpCall('inv_rpt_project_cost', { p_from: r.first, p_to: r.last });
    const months = [];
    for(let d = new Date(r.first + 'T00:00:00'); d <= new Date(r.last + 'T00:00:00'); d.setMonth(d.getMonth() + 1)) months.push(d.toISOString().slice(0, 7));
    const ids = Array.from(new Set(rows.map(x=> x.project_id)));
    const out = ids.map(pid=>{
      const p = rpProjectsAll.find(x=> x.id === pid) || { project_no:'?', name:'', budget:null };
      const per = months.map(mo=> rows.filter(x=> x.project_id === pid && String(x.month).slice(0, 7) === mo).reduce((a, x)=> a + Number(x.cost), 0));
      const toDate = rows.filter(x=> x.project_id === pid).reduce((a, x)=> a + Number(x.cost), 0);
      const inRange = per.reduce((a, v)=> a + v, 0);
      const budget = p.budget != null ? Number(p.budget) : null;
      return [p.project_no, p.name].concat(per, [inRange, toDate, budget != null ? budget : '', budget ? Math.round(toDate / budget * 1000) / 10 : '']);
    }).sort((a, b)=> b[2 + months.length + 1] - a[2 + months.length + 1]);
    const monthHeads = months.map(mo=> new Date(mo + '-01T00:00:00').toLocaleDateString('en-PH', { month:'short', year:'2-digit' }) + ' ₱');
    const flagged = out.filter(r=> r[r.length - 1] !== '' && r[r.length - 1] >= 80);
    return {
      title: 'Project Material Cost by Month', subtitle: r.label,
      summary: [['Projects', String(out.length)], ['Cost in period', invMoney(out.reduce((a, r)=> a + r[2 + months.length], 0))], ['At / over 80% of budget', String(flagged.length)]],
      sheets: [{ name:'Project Cost', head:['Project', 'Name'].concat(monthHeads, ['In period ₱', 'To date ₱', 'Budget ₱', '% of budget']), rows: out,
        moneyFrom: 2, moneyTo: 2 + months.length + 2, pctCol: 2 + months.length + 3, flagRow: (row)=> row[row.length - 1] !== '' && row[row.length - 1] >= 80, landscape: months.length > 3 }]
    };
  }

  // ---------- 4. Slow-moving / dead stock ----------
  async function rpSlow(){
    const days = Number($('rpDays').value), wh = $('rpWh').value;
    const rows = (await rpCall('inv_rpt_slow_moving', {}))
      .filter(x=> x.days_idle >= days && (!wh || x.warehouse_id === wh) && rpMatchItem(x.material_id) && rpSearchOk([rpItem(x.material_id).code, rpItem(x.material_id).name].join(' ')))
      .sort((a, b)=> b.days_idle - a.days_idle);
    const money = rpMoney() && rows.some(x=> x.value != null);
    const tied = rows.reduce((a, x)=> a + Number(x.value || 0), 0);
    return {
      title: 'Slow-Moving & Dead Stock', subtitle: 'Not issued for ' + days + '+ days · as of ' + poDateLong(poToday()),
      summary: [['Items', String(rows.length)]].concat(money ? [['Value tied up', invMoney(tied)]] : []).concat([['180+ days (dead)', String(rows.filter(x=> x.days_idle >= 180).length)]]),
      sheets: [{ name:'Slow-Moving', head:['Warehouse', 'Code', 'Item', 'On hand', 'Unit', 'Last issued', 'Days idle'].concat(money ? ['Value ₱'] : []),
        rows: rows.map(x=>{ const m = rpItem(x.material_id); return [rpWhCode(x.warehouse_id), m.code, m.name, Number(x.qty_on_hand), m.unit, x.last_out ? poDateLong(x.last_out) : 'never', x.days_idle].concat(money ? [Number(x.value)] : []); }),
        numCols:[3, 6], moneyFrom: money ? 7 : null, flagRow:(row)=> row[6] >= 180, totalRow: money ? ['', '', 'Total', '', '', '', '', tied] : null }]
    };
  }

  // ---------- 5. Reorder suggestions ----------
  async function rpReorder(){
    const win = Number($('rpWindow').value);
    const rows = (await rpCall('inv_rpt_reorder', { p_days: win }))
      .filter(x=> rpMatchItem(x.material_id) && rpSearchOk([rpItem(x.material_id).code, rpItem(x.material_id).name, x.supplier].join(' ')))
      .sort((a, b)=> (b.reorder ? 1 : 0) - (a.reorder ? 1 : 0) || Number(a.months_cover == null ? 999 : a.months_cover) - Number(b.months_cover == null ? 999 : b.months_cover));
    rpReorderRows = rows;
    const money = rpMoney();
    const need = rows.filter(x=> x.reorder);
    return {
      title: 'Reorder Suggestions', subtitle: 'Usage over the last ' + win + ' days · as of ' + poDateLong(poToday()),
      summary: [['To reorder', String(need.length)], ['Tracked items', String(rows.length)]].concat(money ? [['Est. order value', invMoney(need.reduce((a, x)=> a + Number(x.suggested_qty) * Number(x.unit_price || 0), 0))]] : []),
      note: 'Reorder when stock covers less than the supplier\u2019s lead time + ½ month; the suggestion tops it up to lead time + 1 month. Lead time comes from the preferred supplier\u2019s price list (7 days if not set).',
      sheets: [{ name:'Reorder', head:(money ? ['✓'] : []).concat(['Code', 'Item', 'On hand', 'Unit', 'Used / month', 'Months left', 'Lead (days)', 'Suggested qty']).concat(money ? ['Supplier', 'Unit price ₱', 'Est. value ₱'] : []),
        rows: rows.map(x=>{ const m = rpItem(x.material_id);
          return (money ? [x.reorder ? '☐' : ''] : []).concat([m.code, m.name, Number(x.on_hand), m.unit, Number(x.usage_per_month), x.months_cover != null ? Number(x.months_cover) : '—', x.lead_days, Number(x.suggested_qty)])
            .concat(money ? [x.supplier || '—', x.unit_price != null ? Number(x.unit_price) : '', x.unit_price != null ? Number(x.suggested_qty) * Number(x.unit_price) : ''] : []); }),
        numCols: money ? [3, 5, 6, 7, 8] : [2, 4, 5, 6, 7], moneyFrom: money ? 10 : null, flagRow:(row, i)=> rows[i].reorder, selectable: money }]
    };
  }

  // ---------- 6. Unreturned by worker ----------
  async function rpUnreturned(){
    const minDays = Number($('rpHeld').value), wh = $('rpWh').value;
    const rows = (await rpCall('inv_rpt_unreturned', {}))
      .filter(x=> x.days_held >= minDays && (!wh || x.warehouse_id === wh) && rpSearchOk([x.worker_name, rpItem(x.material_id).code, rpItem(x.material_id).name, rpPrj(x.project_id, x.job_order_id)].join(' ')))
      .sort((a, b)=> String(a.worker_name).localeCompare(String(b.worker_name)) || b.days_held - a.days_held);
    const money = rpMoney() && rows.some(x=> x.value != null);
    return {
      title: 'Unreturned Materials by Worker', subtitle: (minDays ? 'Held ' + minDays + '+ days' : 'All held materials') + ' · as of ' + poDateLong(poToday()),
      summary: [['Workers', String(new Set(rows.map(x=> x.worker_id)).size)], ['Lines', String(rows.length)]].concat(money ? [['Value held', invMoney(rows.reduce((a, x)=> a + Number(x.value || 0), 0))]] : []),
      sheets: [{ name:'Unreturned', head:['Worker', 'Code', 'Item', 'Holding', 'Unit', 'Project / job', 'Since', 'Days'].concat(money ? ['Value ₱'] : []),
        rows: rows.map(x=>{ const m = rpItem(x.material_id); return [x.worker_name, m.code, m.name, Number(x.holding), m.unit, rpPrj(x.project_id, x.job_order_id), poDateLong(x.oldest), x.days_held].concat(money ? [Number(x.value || 0)] : []); }),
        groupCol: 0, numCols:[3, 7], moneyFrom: money ? 8 : null, flagRow:(row)=> row[7] >= 60 }]
    };
  }

  // ---------- on-screen rendering ----------
  function rpIsMoney(sheet, ci){
    if(sheet.moneyCols) return sheet.moneyCols.includes(ci);
    return sheet.moneyFrom != null && ci >= sheet.moneyFrom && (sheet.moneyTo == null || ci <= sheet.moneyTo);
  }
  function rpFmt(v, sheet, ci){
    if(v === '' || v == null) return '';
    const isMoney = rpIsMoney(sheet, ci);
    if(ci === sheet.pctCol) return typeof v === 'number' ? v.toFixed(1) + '%' : v;
    if(typeof v === 'number') return isMoney ? poFmt(v) : invQty(v);
    return escapeHtml(v);
  }
  function rpIsNum(sheet, ci){
    return (sheet.numFrom != null && ci >= sheet.numFrom) || (sheet.numCols || []).includes(ci) || rpIsMoney(sheet, ci) || ci === sheet.pctCol;
  }
  // pre: element-id prefix, so other report pages (Tool Reports: 'tr') can
  // reuse the same renderer, PDF and Excel export
  function rpRender(model, pre){
    pre = pre || 'rp';
    $(pre + 'Summary').innerHTML = (model.summary || []).map(([k, v])=> '<div class="tile"><div class="k">' + escapeHtml(k) + '</div><div class="v">' + escapeHtml(v) + '</div></div>').join('');
    const c = $(pre + 'Check');
    c.textContent = model.check ? model.check.text : (model.note || '');
    c.className = 'rp-check' + (model.check ? (model.check.ok ? ' ok' : ' bad') : '');
    $(pre + 'Out').innerHTML = model.sheets.filter(s=> !s.excelOnly).map((sh, si)=>{
      if(!sh.rows.length) return (si ? '<div class="rp-sub">' + escapeHtml(sh.name) + '</div>' : '') + '<div class="empty-state">No data for these options.</div>';
      let body = '', lastGroup = null;
      sh.rows.forEach((row, ri)=>{
        if(sh.groupCol != null && row[sh.groupCol] !== lastGroup){
          if(lastGroup != null && sh.groupTotals && sh.groupTotals[lastGroup]) body += rpTotalRow(sh.groupTotals[lastGroup], sh);
          lastGroup = row[sh.groupCol];
          body += '<tr class="rp-month"><td colspan="' + (sh.head.length - (sh.groupCol != null ? 1 : 0)) + '">' + escapeHtml(lastGroup) + '</td></tr>';
        }
        const flag = sh.flagRow && sh.flagRow(row, ri);
        body += '<tr' + (flag ? ' class="rp-flag"' : '') + ' data-ri="' + ri + '">' + row.map((v, ci)=>{
          if(ci === sh.groupCol) return '';
          if(sh.selectable && ci === 0) return '<td>' + (v ? '<input type="checkbox" class="rp-sel" checked>' : '') + '</td>';
          return '<td class="' + (rpIsNum(sh, ci) ? 'num' : '') + (rpPairStart(sh, ci) ? ' pair' : '') + '">' + rpFmt(v, sh, ci) + '</td>';
        }).join('') + '</tr>';
      });
      if(lastGroup != null && sh.groupTotals && sh.groupTotals[lastGroup]) body += rpTotalRow(sh.groupTotals[lastGroup], sh);
      if(sh.totalRow) body += rpTotalRow(sh.totalRow, sh);
      return (si ? '<div class="rp-sub">' + escapeHtml(sh.name) + '</div>' : '') +
        '<div class="sp-table-wrap"><table class="sp-table rp-table"><thead>' + (sh.headGroups ? '<tr class="rp-hgroup">' + rpGroupSpans(sh).map(([l, n])=>
          '<th colspan="' + n + '"' + (l ? ' class="grp"' : '') + '>' + escapeHtml(l) + '</th>').join('') + '</tr>' : '') + '<tr>' + sh.head.map((h, ci)=> ci === sh.groupCol ? '' : '<th class="' + (rpIsNum(sh, ci) ? 'num' : '') + (rpPairStart(sh, ci) ? ' pair' : '') + '">' + escapeHtml(h) + '</th>').join('') + '</tr></thead><tbody>' + body + '</tbody></table></div>';
    }).join('');
  }
  const rpPairStart = (sh, ci)=> !!(sh.headGroups && sh.moneyCols && sh.moneyCols.includes(ci + 1));
  // heading spans with the hidden group column (e.g. Month) taken out
  function rpGroupSpans(sh){
    let ci = 0;
    return sh.headGroups.map(([l, n])=>{
      const hide = sh.groupCol != null && sh.groupCol >= ci && sh.groupCol < ci + n ? 1 : 0;
      ci += n;
      return [l, n - hide];
    }).filter(([, n])=> n > 0);
  }
  function rpTotalRow(row, sh){ return '<tr class="rp-total">' + row.map((v, ci)=> ci === sh.groupCol ? '' : '<td class="' + (rpIsNum(sh, ci) ? 'num' : '') + (rpPairStart(sh, ci) ? ' pair' : '') + '">' + rpFmt(v, sh, ci) + '</td>').join('') + '</tr>'; }

  // ---------- Excel ----------
  $('rpXlsx').addEventListener('click', ()=> rpExportXlsx(rpModel, $('rpFrom').value));
  async function rpExportXlsx(rpModel, tag){
    if(!rpModel){ toast('Run the report first'); return; }
    try{
      await loadAwesScript('xlsx', awesLibs.xlsx);
      const wb = XLSX.utils.book_new();
      const co = (poSettingsData && poSettingsData.company_name) || 'AW Engineering Services';
      rpModel.sheets.forEach(sh=>{
        const rows = sh.rows.map(r=> r.map((v, ci)=> sh.selectable && ci === 0 ? (v ? 'reorder' : '') : v));
        const band = sh.headGroups ? [[].concat(...sh.headGroups.map(([l, n])=> [l].concat(Array(n - 1).fill(''))))] : [];
        const aoa = [[co], [rpModel.title], [rpModel.subtitle], []].concat(band, [sh.head], rows);
        if(sh.totalRow) aoa.push(sh.totalRow);
        const ws = XLSX.utils.aoa_to_sheet(aoa);
        if(sh.headGroups){
          let c = 0; ws['!merges'] = [];
          sh.headGroups.forEach(([l, n])=>{ if(n > 1 && l) ws['!merges'].push({ s:{ r:4, c }, e:{ r:4, c: c + n - 1 } }); c += n; });
        }
        ws['!cols'] = sh.head.map((h, ci)=> ({ wch: Math.min(48, Math.max(String(h).length + 2, ...rows.slice(0, 200).map(r=> String(r[ci] == null ? '' : r[ci]).length + 1))) }));
        // number formats: money with 2 decimals, quantities up to 3
        const first = 5 + band.length;   // column headings on row 5 (6 with a heading band) → data after
        for(let ri = 0; ri < rows.length + (sh.totalRow ? 1 : 0); ri++){
          sh.head.forEach((h, ci)=>{
            const cell = ws[XLSX.utils.encode_cell({ r: first + ri, c: ci })];
            if(!cell || cell.t !== 'n') return;
            cell.z = ci === sh.pctCol ? '0.0"%"' : rpIsMoney(sh, ci) ? '#,##0.00' : '#,##0.###';
          });
        }
        XLSX.utils.book_append_sheet(wb, ws, sh.name.slice(0, 31));
      });
      const name = rpModel.title.replace(/[^A-Za-z0-9]+/g, '-').replace(/-+$/, '') + '-' + (tag || poToday().slice(0, 7)) + '.xlsx';
      XLSX.writeFile(wb, name);
      toast('Excel file downloaded');
    }catch(e){ console.error('xlsx failed', e); toast('Couldn\u2019t create the Excel file: ' + (e && e.message ? e.message : e)); }
  }

  // ---------- PDF ----------
  $('rpPdf').addEventListener('click', ()=> rpExportPdf(rpModel, $('rpFrom').value));
  async function rpExportPdf(rpModel, tag){
    if(!rpModel){ toast('Run the report first'); return; }
    try{
      await loadAwesScript('jspdf', awesLibs.jspdf); await loadAwesScript('autotable', awesLibs.autotable);
      await poLoadSettings().catch(()=>{});
      const co = poSettingsData || {}, style = co.header_style || 'green';
      const logo = co.logo_path ? await poLoadImage(co.logo_path).then(img=> poLogoForStyle(img, style)) : await poDefaultLogo(style);
      const fonts = await poLoadFonts();
      const land = rpModel.sheets.some(s=> s.landscape && !s.excelOnly);
      const { jsPDF } = window.jspdf;
      const doc = new jsPDF({ orientation: land ? 'l' : 'p', unit:'pt', format:'a4', compress:true });
      let F = 'helvetica', FS = ['helvetica', 'bold'], FB = ['helvetica', 'bold'];
      if(fonts){ try{
        doc.addFileToVFS('Inter-Regular.ttf', fonts.regular); doc.addFont('Inter-Regular.ttf', 'Inter', 'normal');
        doc.addFileToVFS('Inter-SemiBold.ttf', fonts.semibold); doc.addFont('Inter-SemiBold.ttf', 'Inter', 'bold');
        doc.addFileToVFS('Inter-Bold.ttf', fonts.bold); doc.addFont('Inter-Bold.ttf', 'InterBold', 'normal');
        F = 'Inter'; FS = ['Inter', 'bold']; FB = ['InterBold', 'normal'];
      }catch(e){} }
      const peso = F === 'Inter' ? '\u20B1' : 'PHP ';
      const W = doc.internal.pageSize.getWidth(), H = doc.internal.pageSize.getHeight(), M = 30;
      const G = [21, 77, 52], SUB = [96, 108, 101], INK = [28, 34, 30], LINE = [216, 223, 219];
      const green = style !== 'white';
      const header = ()=>{
        if(green){ doc.setFillColor(...G); doc.rect(0, 0, W, 64, 'F'); } else { doc.setFillColor(...G); doc.rect(0, 61, W, 3, 'F'); }
        if(logo && logo.w){ const r = Math.min(110 / logo.w, 32 / logo.h); try{ doc.addImage(logo.dataUrl, 'PNG', M, 16, logo.w * r, logo.h * r, 'rp-logo', 'FAST'); }catch(e){} }
        doc.setTextColor(...(green ? [255, 255, 255] : G));
        doc.setFont(FB[0], FB[1]); doc.setFontSize(15); doc.text(rpModel.title.toUpperCase(), W - M, 30, { align:'right' });
        doc.setFont(F, 'normal'); doc.setFontSize(8.5); doc.text(rpModel.subtitle + '   •   ' + (co.company_name || ''), W - M, 46, { align:'right' });
      };
      header();
      let y = 82;
      if(rpModel.summary && rpModel.summary.length){
        doc.setFont(F, 'normal'); doc.setFontSize(8.5); doc.setTextColor(...INK);
        doc.text(rpModel.summary.map(([k, v])=> k + ': ' + String(v).replace('₱', peso)).join('     '), M, y); y += 12;
      }
      const note = rpModel.check ? rpModel.check.text.replace('✓', '').replace('⚠', '!') : rpModel.note;
      if(note){ doc.setFontSize(7.5); doc.setTextColor(...SUB); doc.text(doc.splitTextToSize(note, W - M * 2), M, y); y += 14; }
      rpModel.sheets.filter(s=> !s.excelOnly).forEach((sh, si)=>{
        if(si){ doc.setFont(FS[0], FS[1]); doc.setFontSize(9); doc.setTextColor(...G); if(y > H - 90){ doc.addPage(); header(); y = 82; } doc.text(sh.name.toUpperCase(), M, y + 4); y += 10; }
        const txt = (v, ci)=>{ const t = rpFmt(v, sh, ci); return typeof t === 'string' ? t.replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'") : t; };
        const body = [];
        let last = null;
        sh.rows.forEach(row=>{
          if(sh.groupCol != null && row[sh.groupCol] !== last){
            if(last != null && sh.groupTotals && sh.groupTotals[last]) body.push({ total:true, cells: sh.groupTotals[last] });
            last = row[sh.groupCol];
            body.push({ group:true, cells:[last] });
          }
          body.push({ cells: row });
        });
        if(last != null && sh.groupTotals && sh.groupTotals[last]) body.push({ total:true, cells: sh.groupTotals[last] });
        if(sh.totalRow) body.push({ total:true, cells: sh.totalRow });
        const cols = sh.head.map((h, ci)=> ci).filter(ci=> !(sh.selectable && ci === 0) && ci !== sh.groupCol);
        doc.autoTable({
          startY: y + 4, margin:{ left:M, right:M, top:78, bottom:36 },
          head: (sh.headGroups ? [rpGroupSpans(sh).map(([l, n])=> ({ content: l, colSpan: n, styles:{ halign:'center', fillColor: l ? [31, 122, 80] : G } }))] : [])
            .concat([cols.map(ci=> sh.head[ci].replace('₱', peso))]),
          body: body.map(b=> b.group ? [{ content: String(b.cells[0]).toUpperCase(), colSpan: cols.length, styles:{ fillColor:[233, 243, 237], textColor:G, fontStyle:'bold', fontSize:7.5 } }]
            : cols.map(ci=> ({ content: txt(b.cells[ci], ci), styles: b.total ? { fontStyle:'bold' } : {} }))),
          theme:'plain',
          styles:{ font:F, fontSize: cols.length > 14 ? 6.4 : cols.length > 10 ? 7 : 8, cellPadding:{ top:3.5, bottom:3.5, left:4, right:4 }, textColor:INK, lineColor:LINE, lineWidth:{ bottom:0.4 } },
          headStyles:{ font:F, fontStyle:'bold', fillColor:G, textColor:255, fontSize: cols.length > 14 ? 6.2 : 7 },
          columnStyles: Object.fromEntries(cols.map((ci, i)=> [i, rpIsNum(sh, ci) ? { halign:'right' } : {}])),
          // column labels line up with their numbers (right-aligned)
          didParseCell: (c)=>{
            if(c.section === 'head' && c.row.index === (sh.headGroups ? 1 : 0) && rpIsNum(sh, cols[c.column.index])) c.cell.styles.halign = 'right';
          },
          didDrawCell: (c)=>{
            if(c.section === 'head' && c.row.index === 0) return;
            const ci = cols[c.column.index];
            if(ci != null && rpPairStart(sh, ci)){ doc.setDrawColor(200, 210, 204); doc.setLineWidth(0.5); doc.line(c.cell.x, c.cell.y, c.cell.x, c.cell.y + c.cell.height); }
          },
          didDrawPage: ()=>{ header(); }
        });
        y = doc.lastAutoTable.finalY + 16;
      });
      const pages = doc.internal.getNumberOfPages();
      for(let p = 1; p <= pages; p++){ doc.setPage(p); doc.setFont(F, 'normal'); doc.setFontSize(7); doc.setTextColor(...SUB);
        doc.text('Generated ' + new Date().toLocaleString('en-PH') + (invIsAdmin() ? '' : ' · quantities only'), M, H - 16); doc.text('Page ' + p + ' of ' + pages, W - M, H - 16, { align:'right' }); }
      const title = rpModel.title;
      $('previewOverlay').querySelector('h3').textContent = title;
      $('previewOkBtn').textContent = 'Close';
      $('previewOverlay').style.zIndex = '99';
      $('previewOverlay').classList.add('open');
      await renderPdfPreview(doc, title.replace(/[^A-Za-z0-9]+/g, '-').replace(/-+$/, '') + '-' + (tag || '') + '.pdf', title);
    }catch(e){ console.error('report pdf failed', e); toast('Couldn\u2019t build the PDF: ' + (e && e.message ? e.message : e)); }
  }

  // ---------- reorder → draft POs (admin) ----------
  $('rpMakePo').addEventListener('click', async ()=>{
    if(!rpModel || rpTab !== 'reorder'){ toast('Run the Reorder report first'); return; }
    const picked = Array.from($$('#rpOut tr[data-ri]')).filter(tr=> tr.querySelector('.rp-sel') && tr.querySelector('.rp-sel').checked)
      .map(tr=> rpReorderRows[Number(tr.dataset.ri)]).filter(x=> x && Number(x.suggested_qty) > 0);
    if(!picked.length){ toast('Tick the items to order'); return; }
    const groups = new Map();
    picked.forEach(x=>{ const k = x.supplier_id || ''; if(!groups.has(k)) groups.set(k, []); groups.get(k).push(x); });
    if(!confirm('Create ' + groups.size + ' draft PO' + (groups.size === 1 ? '' : 's') + ' for ' + picked.length + ' item' + (picked.length === 1 ? '' : 's') + '?\n\n' +
      Array.from(groups.entries()).map(([k, xs])=> (xs[0].supplier || 'No preferred supplier (choose in the PO)') + ': ' + xs.length).join('\n') + '\n\nThey open as drafts — check quantities and prices before issuing.')) return;
    if(!(await purchEnsureSession())) return;
    try{
      await Promise.all([mtLoad({ silent:true }), poLoadSettings(), poLoadSuppliers()]);
      const made = [];
      for(const [sid, xs] of groups){
        const sup = poSuppliers.find(s=> s.id === sid);
        const { data: po, error } = await db.from('purchase_orders').insert({ supplier_id: sid || null, reference: 'Reorder ' + poToday(),
          payment_terms: sup ? (sup.payment_terms || '') : '', deliver_to: (poSettingsData && poSettingsData.deliver_to) || '', vat_mode: (poSettingsData && poSettingsData.vat_mode) || 'exclusive' }).select('id, po_no').single();
        if(error) throw error;
        const rows = xs.map((x, i)=>{ const m = rpItem(x.material_id), pr = poPriceFor(x.material_id, sid || null);
          return { id: poUuid(), po_id: po.id, line_no: i + 1, material_id: x.material_id, code: m.code, description: m.name,
            unit: (pr && pr.unitFromPrice) || m.unit, qty: Number(x.suggested_qty), unit_price: pr ? pr.price : 0 }; });
        const ir = await db.from('purchase_order_items').insert(rows); if(ir.error) throw ir.error;
        made.push(po.po_no);
      }
      toast('Created draft ' + made.join(', ') + ' — review them in Purchase Orders');
    }catch(e){ purchFail('Couldn\u2019t create the POs: ', e); }
  });


  // =====================================================================
  // Tools & Equipment (migration 20260923_10_tools_equipment.sql)
  //
  // Every change of status / custody is ONE call to a tl_* database
  // function (issue, return, handover, sign, defect decision, calibration),
  // which validates it. Admins read the tools table; storekeepers and
  // workers read tools_view (no purchase cost).
  // =====================================================================

  const TL_CATEGORIES = ['Power Tools', 'Hand Tools', 'Testing & Measuring', 'Pumps & Recovery', 'Brazing & Welding',
    'Flaring & Swaging', 'Ladders & Access', 'Safety / PPE', 'Other'];
  const TL_STATUS = { available:'Available', issued:'Issued', defective:'Defective', repair:'In repair', lost:'Lost', retired:'Retired' };
  const TL_COND = { good:'Good', needs_repair:'Needs repair', defective:'Defective', missing_parts:'Missing parts', lost:'Lost' };
  const TL_SLIP = { issue:{ label:'Issue', title:'TOOL ISSUE SLIP' }, 'return':{ label:'Return', title:'TOOL RETURN SLIP' }, handover:{ label:'Handover', title:'TOOL HANDOVER SLIP' } };
  const TL_BUCKET = 'tool-files';
  const tl = { tools:[], whs:[], mine:[], workers:[], jobs:[], projects:[], suppliers:[], isAdmin:false };

  const tlToday = ()=> poToday();
  const tlTool = (id)=> tl.tools.find(t=> t.id === id);
  const tlWh = (id)=> (tl.whs.find(w=> w.id === id) || {}).code || '';
  const tlOverdue = (t)=> t.status === 'issued' && t.due_back && t.due_back < tlToday();
  const tlMaintLate = (t)=> t.next_maint_due && t.next_maint_due < tlToday();
  const tlMaintSoon = (t)=> t.next_maint_due && !tlMaintLate(t) && t.next_maint_due <= new Date(Date.now() + 30 * 864e5 + 8 * 3600e3).toISOString().slice(0, 10);
  const tlStatusPill = (s)=> '<span class="tl-st ' + escapeHtml(s) + '">' + escapeHtml(TL_STATUS[s] || s) + '</span>';
  function tlLabel(t){ return t ? t.asset_tag + ' · ' + t.name : ''; }

  async function tlLoad(){
    tl.isAdmin = invIsAdmin();
    const [tools, whs, keep, wk, jobs, pr] = await Promise.all([
      db.from(tl.isAdmin ? 'tools' : 'tools_view').select('*').order('asset_tag'),
      db.from('warehouses').select('*').order('code'),
      tl.isAdmin ? Promise.resolve({ data:null }) : db.from('warehouse_storekeepers').select('warehouse_id').eq('user_id', currentUser.id),
      db.from('profiles').select('id, name').eq('role', 'technician').eq('active', true).order('name'),
      db.rpc('inv_open_job_orders'),
      db.from('projects').select('id, project_no, name, status').order('project_no', { ascending:false })
    ]);
    if(tools.error) throw tools.error;
    tl.tools = tools.data || [];
    tl.whs = whs.data || [];
    const ids = keep.data ? new Set(keep.data.map(k=> k.warehouse_id)) : null;
    tl.mine = tl.whs.filter(w=> w.is_active && (!ids || ids.has(w.id)));
    tl.workers = wk.data || [];
    tl.jobs = jobs.error ? [] : (jobs.data || []);
    tl.projects = pr.error ? [] : (pr.data || []);
  }
  async function tlEnter(needWh){
    if(!(await ensureCloud())){ toast('Not connected'); return false; }
    try{ await tlLoad(); }
    catch(e){ purchFail(invMissingTables(e) ? 'Run migration 20260923_10_tools_equipment.sql first: ' : 'Couldn\u2019t load tools: ', e); return false; }
    if(needWh && !tl.mine.length){ toast(tl.isAdmin ? 'Add an active warehouse first' : 'You aren\u2019t assigned to a warehouse'); return false; }
    $('purchasingView').classList.add('po-wide');
    return true;
  }
  const tlOpts = (list, val, lab, empty)=> (empty != null ? '<option value="">' + escapeHtml(empty) + '</option>' : '') +
    list.map(x=> '<option value="' + escapeHtml(val(x)) + '">' + escapeHtml(lab(x)) + '</option>').join('');
  const tlWhOpts = ()=> tlOpts(tl.mine, w=> w.id, w=> w.code + ' · ' + w.name);
  const tlWorkerOpts = (empty)=> tlOpts(tl.workers, w=> w.id, w=> w.name, empty || 'Choose a person…');
  const tlPrj = (pid, job)=>{ const p = tl.projects.find(x=> x.id === pid); return [p ? p.project_no + ' ' + p.name : '', job].filter(Boolean).join(' · '); };

  // navigation: hub buttons + "← Tools"
  $('purchasingView').addEventListener('click', (e)=>{
    const go = e.target.closest('[data-tl-go]'); if(go){ showPurchasingView(go.dataset.tlGo); return; }
    if(e.target.closest('[data-tl-hub]')) showPurchasingView('tlHub');
  });
  // "Here / Later on their phone" pickers
  $$('[data-signmode]').forEach(g=> g.addEventListener('click', (e)=>{
    const b = e.target.closest('[data-m]'); if(!b) return;
    g.querySelectorAll('[data-m]').forEach(x=> x.classList.toggle('on', x === b));
  }));
  const tlMode = (id)=> ($(id).querySelector('.on') || {}).dataset.m || 'counter';

  // ---------- signature capture ----------
  let tlPad = null, tlSignResolve = null;
  function tlSign(title, who){
    return new Promise(async (resolve)=>{
      tlSignResolve = resolve;
      $('tlSignTitle').textContent = title; $('tlSignWho').textContent = who || '';
      $('tlSignOverlay').classList.add('open');
      try{
        await loadAwesScript('signature', awesLibs.signature);
        const c = $('tlSignCanvas'), r = Math.max(window.devicePixelRatio || 1, 1);
        c.width = c.offsetWidth * r; c.height = c.offsetHeight * r; c.getContext('2d').scale(r, r);
        tlPad = new SignaturePad(c, { penColor:'#1C2621', backgroundColor:'rgba(255,255,255,0)' });
      }catch(e){ toast('Signature tool couldn\u2019t load — check the connection'); tlSignDone(null); }
    });
  }
  function tlSignDone(v){ $('tlSignOverlay').classList.remove('open'); const r = tlSignResolve; tlSignResolve = null; if(r) r(v); }
  $('tlSignClear').addEventListener('click', ()=>{ if(tlPad) tlPad.clear(); });
  $('tlSignClose').addEventListener('click', ()=> tlSignDone(null));
  $('tlSignOk').addEventListener('click', async ()=>{
    if(!tlPad || tlPad.isEmpty()){ toast('Please sign in the box'); return; }
    const c = poCleanSignature($('tlSignCanvas')) || $('tlSignCanvas');
    tlSignDone(await new Promise(res=> c.toBlob(res, 'image/png')));
  });
  async function tlUpload(blob, ext){
    const path = currentUser.id + '/' + Date.now() + '-' + Math.random().toString(36).slice(2, 8) + '.' + ext;
    const up = await db.storage.from(TL_BUCKET).upload(path, blob, { contentType: ext === 'png' ? 'image/png' : 'image/jpeg', upsert:false });
    if(up.error) throw up.error;
    return path;
  }
  async function tlPhotoBlob(file){
    const c = await poImageToPng(file, 1400, 1400);
    return { blob: await new Promise(res=> c.toBlob(res, 'image/jpeg', 0.8)), url: c.toDataURL('image/jpeg', 0.6) };
  }
  async function tlDownloadUrl(path){
    if(!path) return null;
    try{ const r = await db.storage.from(TL_BUCKET).download(path); return r.data ? await poBlobToDataUrl(r.data) : null; }catch(e){ return null; }
  }

  // ---------- QR scanner (built-in BarcodeDetector, else jsQR, else type it) ----------
  let tlScanStream = null, tlScanResolve = null, tlScanLoop = 0;
  function tlParseTag(txt){ const m = /TL-\d{3,}/i.exec(String(txt || '')); return m ? m[0].toUpperCase() : null; }
  function tlScan(){
    return new Promise(async (resolve)=>{
      tlScanResolve = resolve;
      $('tlScanManual').value = ''; $('tlScanMsg').textContent = 'Point the camera at the label.';
      $('tlScanOverlay').classList.add('open');
      try{
        tlScanStream = await navigator.mediaDevices.getUserMedia({ video:{ facingMode:'environment' }, audio:false });
        const v = $('tlScanVideo'); v.srcObject = tlScanStream; await v.play();
        let detect;
        if('BarcodeDetector' in window){ const bd = new BarcodeDetector({ formats:['qr_code'] }); detect = async ()=>{ const r = await bd.detect(v); return r[0] && r[0].rawValue; }; }
        else{
          await loadAwesScript('jsqr', awesLibs.jsqr);
          const cv = document.createElement('canvas'), cx = cv.getContext('2d', { willReadFrequently:true });
          detect = async ()=>{ if(!v.videoWidth) return null; cv.width = v.videoWidth; cv.height = v.videoHeight; cx.drawImage(v, 0, 0);
            const r = jsQR(cx.getImageData(0, 0, cv.width, cv.height).data, cv.width, cv.height); return r && r.data; };
        }
        const id = ++tlScanLoop;
        const tick = async ()=>{
          if(id !== tlScanLoop || !tlScanResolve) return;
          try{ const raw = await detect(); const tag = tlParseTag(raw); if(tag){ tlScanDone(tag); return; } }catch(e){}
          setTimeout(tick, 250);
        };
        tick();
      }catch(e){ $('tlScanMsg').textContent = 'Camera not available — type the asset tag below.'; }
    });
  }
  function tlScanDone(tag){
    tlScanLoop++;
    if(tlScanStream){ tlScanStream.getTracks().forEach(t=> t.stop()); tlScanStream = null; }
    $('tlScanOverlay').classList.remove('open');
    const r = tlScanResolve; tlScanResolve = null; if(r) r(tag);
  }
  $('tlScanClose').addEventListener('click', ()=> tlScanDone(null));
  $('tlScanManualOk').addEventListener('click', ()=>{ const t = tlParseTag($('tlScanManual').value); if(t) tlScanDone(t); else toast('Enter a tag like TL-0001'); });
  $('tlScanManual').addEventListener('keydown', (e)=>{ if(e.key === 'Enter') $('tlScanManualOk').click(); });

  // ---------- QR labels (vector QR, crisp at any size) ----------
  async function tlLabelsPdf(tools){
    if(!tools.length){ toast('No tools to label'); return; }
    await loadAwesScript('jspdf', awesLibs.jspdf); await loadAwesScript('qrgen', awesLibs.qrgen);
    await poLoadSettings().catch(()=>{});
    const co = (poSettingsData && poSettingsData.company_name) || 'AW Engineering Services';
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ orientation:'p', unit:'mm', format:'a4', compress:true });
    const cols = 3, rows = 8, lw = 64, lh = 33, mx = (210 - cols * lw) / 2, my = (297 - rows * lh) / 2;
    tools.forEach((t, i)=>{
      if(i && i % (cols * rows) === 0) doc.addPage();
      const k = i % (cols * rows), x = mx + (k % cols) * lw, y = my + Math.floor(k / cols) * lh;
      doc.setDrawColor(200); doc.setLineWidth(0.2); doc.roundedRect(x + 1, y + 1, lw - 2, lh - 2, 2, 2);
      const qr = qrcode(0, 'M'); qr.addData('AWES-TOOL:' + t.asset_tag); qr.make();
      const n = qr.getModuleCount(), size = 25, cell = size / n, qx = x + 4, qy = y + (lh - size) / 2;
      doc.setFillColor(0, 0, 0);
      for(let r = 0; r < n; r++) for(let c = 0; c < n; c++) if(qr.isDark(r, c)) doc.rect(qx + c * cell, qy + r * cell, cell + 0.02, cell + 0.02, 'F');
      doc.setTextColor(21, 77, 52); doc.setFont('helvetica', 'bold'); doc.setFontSize(12); doc.text(t.asset_tag, qx + size + 3, y + 11);
      doc.setTextColor(30, 30, 30); doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5);
      doc.text(doc.splitTextToSize(t.name, lw - size - 10).slice(0, 2), qx + size + 3, y + 16);
      doc.setFontSize(6); doc.setTextColor(110); doc.text(doc.splitTextToSize(co, lw - size - 10).slice(0, 1), qx + size + 3, y + lh - 5);
    });
    $('previewOverlay').querySelector('h3').textContent = 'QR Labels';
    $('previewOkBtn').textContent = 'Close';
    $('previewOverlay').style.zIndex = '99';
    $('previewOverlay').classList.add('open');
    await renderPdfPreview(doc, 'tool-labels-' + tlToday() + '.pdf', 'Tool QR Labels');
  }

  // =====================================================================
  // REGISTER
  // =====================================================================
  let tlDetailTool = null, tlEditTool = null, tlKitRows = [];
  function tlRegView(v){
    $('tlRegList').style.display = v === 'list' ? '' : 'none';
    $('tlRegForm').style.display = v === 'form' ? '' : 'none';
    $('tlRegDetail').style.display = v === 'detail' ? '' : 'none';
    window.scrollTo({ top:0 });
  }
  async function tlShowRegister(){
    if(!(await tlEnter(false))) return;
    tlRegView('list');
    $('tlRegWh').innerHTML = '<option value="">All warehouses</option>' + tl.whs.map(w=> '<option value="' + escapeHtml(w.id) + '">' + escapeHtml(w.code) + '</option>').join('');
    tlRenderRegister();
  }
  function tlRegFiltered(){
    const st = $('tlRegStatus').value, wh = $('tlRegWh').value, kind = $('tlRegKind').value;
    const words = ($('tlRegSearch').value || '').trim().toLowerCase().split(/\s+/).filter(Boolean);
    return tl.tools.filter(t=> (!wh || t.home_warehouse_id === wh) && (!kind || t.kind === kind) &&
      (!st || (st === 'overdue' ? tlOverdue(t) : st === 'maint' ? (tlMaintLate(t) || tlMaintSoon(t)) : t.status === st)) &&
      (!words.length || words.every(w=> [t.asset_tag, t.name, t.brand, t.model, t.serial_no, t.holder_name, t.category].join(' ').toLowerCase().includes(w))));
  }
  function tlRenderRegister(){
    const rows = tlRegFiltered(), all = tl.tools;
    const n = (f)=> all.filter(f).length;
    $('tlRegisterCount').textContent = all.length ? all.length + ' tools' : '';
    $('tlRegSummary').innerHTML = [['Available', n(t=> t.status === 'available')], ['Issued', n(t=> t.status === 'issued')], ['Overdue', n(tlOverdue)],
      ['Defective / repair', n(t=> t.status === 'defective' || t.status === 'repair')], ['Calibration overdue', n(tlMaintLate)]]
      .map(([k, v])=> '<div class="tile"><div class="k">' + k + '</div><div class="v">' + v + '</div></div>').join('');
    $('tlRegRows').innerHTML = rows.length ? rows.map(t=>
      '<button type="button" class="mt-row" data-id="' + escapeHtml(t.id) + '"><div class="mt-row-main"><div class="mt-row-title"><span class="mt-code">' + escapeHtml(t.asset_tag) + '</span>' +
      escapeHtml(t.name) + (t.kind === 'kit' ? ' <span class="sp-tag muted">Kit · ' + (t.kit_contents || []).length + ' items</span>' : '') + ' ' + tlStatusPill(t.status) + '</div>' +
      '<div class="sp-row-sub">' + escapeHtml([t.category, [t.brand, t.model].filter(Boolean).join(' '), t.serial_no ? 'S/N ' + t.serial_no : '', tlWh(t.home_warehouse_id)].filter(Boolean).join(' · ')) + '</div>' +
      (t.status === 'issued' ? '<div class="sp-row-sub' + (tlOverdue(t) ? '" style="color:var(--danger);font-weight:700;' : '') + '">With ' + escapeHtml(t.holder_name) + (t.due_back ? ' · due ' + escapeHtml(poDateLong(t.due_back)) + (tlOverdue(t) ? ' — OVERDUE' : '') : '') + '</div>' : '') +
      (t.next_maint_due ? '<div class="sp-row-sub" style="' + (tlMaintLate(t) ? 'color:var(--danger);font-weight:700;' : tlMaintSoon(t) ? 'color:#9A6212;font-weight:700;' : '') + '">' + escapeHtml(t.maint_type === 'inspection' ? 'Inspection' : 'Calibration') + ' due ' + escapeHtml(poDateLong(t.next_maint_due)) + (tlMaintLate(t) ? ' — OVERDUE (can\u2019t be issued)' : '') + '</div>' : '') +
      '</div></button>').join('') : '<div class="empty-state">' + (all.length ? 'Nothing matches.' : 'No tools yet.' + (tl.isAdmin ? ' Tap <b>+ Add Tool / Kit</b> or import a CSV.' : '')) + '</div>';
  }
  ['tlRegSearch'].forEach(id=> $(id).addEventListener('input', tlRenderRegister));
  ['tlRegStatus', 'tlRegWh', 'tlRegKind'].forEach(id=> $(id).addEventListener('change', tlRenderRegister));
  $('tlRegRows').addEventListener('click', (e)=>{ const r = e.target.closest('.mt-row'); if(r) tlOpenDetail(r.dataset.id); });
  $('tlScanBtn').addEventListener('click', async ()=>{
    const tag = await tlScan(); if(!tag) return;
    const t = tl.tools.find(x=> x.asset_tag === tag);
    if(t) tlOpenDetail(t.id); else toast(tag + ' isn\u2019t in the register' + (tl.isAdmin ? '' : ' (or not your warehouse)'));
  });
  $('tlLabelsBtn').addEventListener('click', ()=>{
    const rows = tlRegFiltered();
    if(rows.length > 1 && !confirm('Print QR labels for the ' + rows.length + ' tools shown? (Filter the list first to print fewer.)')) return;
    tlLabelsPdf(rows).catch(e=> toast('Couldn\u2019t make labels: ' + e.message));
  });

  // ---------- add / edit (admin) ----------
  function tlRenderKitRows(){
    $('tlFKitRows').innerHTML = tlKitRows.map((k, i)=> '<div class="tl-kit-row" data-i="' + i + '"><input type="text" data-k="name" value="' + escapeHtml(k.name) + '" placeholder="e.g. Screwdriver set">' +
      '<input type="text" data-k="qty" inputmode="numeric" value="' + escapeHtml(String(k.qty)) + '" placeholder="Qty"><button type="button" class="tl-rm" data-rm="1">&minus;</button></div>').join('');
  }
  $('tlFKitRows').addEventListener('input', (e)=>{ const r = e.target.closest('[data-i]'); if(r) tlKitRows[+r.dataset.i][e.target.dataset.k] = e.target.value; });
  $('tlFKitRows').addEventListener('click', (e)=>{ if(!e.target.closest('[data-rm]')) return; tlKitRows.splice(+e.target.closest('[data-i]').dataset.i, 1); tlRenderKitRows(); });
  $('tlFKitAdd').addEventListener('click', ()=>{ tlKitRows.push({ name:'', qty:1 }); tlRenderKitRows(); });
  function tlFormKind(){
    const kit = $('tlFKind').value === 'kit';
    $('tlFKitSec').style.display = kit ? '' : 'none';
    $('tlFSerialsWrap').style.display = !tlEditTool && Number($('tlFQty').value) > 1 ? '' : 'none';
  }
  $('tlFKind').addEventListener('change', tlFormKind);
  $('tlFQty').addEventListener('input', tlFormKind);
  async function tlOpenForm(t){
    tlEditTool = t || null;
    $('tlFormTitle').textContent = t ? 'Edit ' + t.asset_tag : 'New Tool / Kit';
    $('tlFCat').innerHTML = TL_CATEGORIES.map(c=> '<option>' + escapeHtml(c) + '</option>').join('');
    $('tlFWh').innerHTML = tlOpts(tl.whs.filter(w=> w.is_active || (t && w.id === t.home_warehouse_id)), w=> w.id, w=> w.code + ' · ' + w.name);
    const sup = await db.from('suppliers').select('id, name, trade_name').eq('is_active', true).order('name');
    $('tlFSup').innerHTML = tlOpts(sup.data || [], s=> s.id, s=> s.trade_name || s.name, '— none —');
    const v = (id, x)=>{ $(id).value = x == null ? '' : String(x); };
    v('tlFKind', t ? t.kind : 'tool'); v('tlFName', t && t.name); v('tlFCat', t ? t.category : 'Power Tools'); v('tlFBrand', t && t.brand); v('tlFModel', t && t.model);
    v('tlFSerial', t && t.serial_no); v('tlFWh', t ? t.home_warehouse_id : (tl.mine[0] || tl.whs[0] || {}).id); v('tlFQty', 1); v('tlFSerials', '');
    v('tlFMaint', t && t.maint_type); v('tlFInterval', t && t.maint_interval_days); v('tlFNext', t && t.next_maint_due);
    v('tlFPDate', t && t.purchase_date); v('tlFCost', t && t.purchase_cost); v('tlFSup', t && t.supplier_id); v('tlFPo', t && t.po_no);
    v('tlFWarranty', t && t.warranty_until); v('tlFNotes', t && t.notes);
    $('tlFQtyWrap').style.display = t ? 'none' : '';
    tlKitRows = t ? (t.kit_contents || []).map(k=> Object.assign({}, k)) : [];
    tlRenderKitRows(); tlFormKind();
    tlRegView('form');
  }
  $('tlAddBtn').addEventListener('click', ()=> tlOpenForm(null));
  $('tlFormBack').addEventListener('click', ()=> tlEditTool ? tlOpenDetail(tlEditTool.id) : tlRegView('list'));
  $('tlFSave').addEventListener('click', async ()=>{
    const name = $('tlFName').value.trim();
    if(!name){ toast('Enter the tool name'); return; }
    const cost = spParseMoney($('tlFCost').value), iv = $('tlFInterval').value.trim() ? parseInt($('tlFInterval').value, 10) : null;
    if(Number.isNaN(cost)){ toast('Cost must be a number'); return; }
    if($('tlFMaint').value && !(iv > 0)){ toast('Enter how often it needs ' + $('tlFMaint').value + ' (days)'); return; }
    const kind = $('tlFKind').value;
    const kit = kind === 'kit' ? tlKitRows.filter(k=> String(k.name).trim()).map(k=> ({ name: String(k.name).trim(), qty: Math.max(1, parseInt(k.qty, 10) || 1) })) : [];
    if(kind === 'kit' && !kit.length){ toast('List what\u2019s in the kit'); return; }
    const row = { kind, name, category: $('tlFCat').value, brand: $('tlFBrand').value.trim(), model: $('tlFModel').value.trim(), home_warehouse_id: $('tlFWh').value,
      kit_contents: kit, maint_type: $('tlFMaint').value || null, maint_interval_days: $('tlFMaint').value ? iv : null, next_maint_due: $('tlFMaint').value ? ($('tlFNext').value || null) : null,
      purchase_date: $('tlFPDate').value || null, purchase_cost: cost, supplier_id: $('tlFSup').value || null, po_no: $('tlFPo').value.trim(),
      warranty_until: $('tlFWarranty').value || null, notes: $('tlFNotes').value.trim() };
    if(!(await purchEnsureSession())) return;
    try{
      if(tlEditTool){
        const { error } = await db.from('tools').update(Object.assign(row, { serial_no: $('tlFSerial').value.trim() })).eq('id', tlEditTool.id);
        if(error) throw error;
        toast(tlEditTool.asset_tag + ' saved');
        await tlLoad(); tlOpenDetail(tlEditTool.id);
      }else{
        const qty = Math.max(1, Math.min(200, parseInt($('tlFQty').value, 10) || 1));
        const serials = $('tlFSerials').value.split(/\r?\n/).map(x=> x.trim());
        const rows = Array.from({ length: qty }, (_, i)=> Object.assign({}, row, { serial_no: qty === 1 ? $('tlFSerial').value.trim() : (serials[i] || '') }));
        const { data, error } = await db.from('tools').insert(rows).select('id, asset_tag');
        if(error) throw error;
        toast('Added ' + data.map(x=> x.asset_tag).join(', '));
        await tlLoad(); tlRegView('list'); tlRenderRegister();
        if(confirm('Print QR labels for the new ' + (data.length === 1 ? 'tool' : data.length + ' tools') + ' now?')) tlLabelsPdf(tl.tools.filter(t=> data.some(d=> d.id === t.id)));
      }
    }catch(e){ purchFail('Couldn\u2019t save: ', e); }
  });
  // CSV import (admin): name, kind, category, brand, model, serial_no, warehouse_code, purchase_date, purchase_cost, maint_type, maint_interval_days, next_maint_due
  $('tlImportBtn').addEventListener('click', ()=>{ $('tlImportFile').value = ''; $('tlImportFile').click(); });
  $('tlImportFile').addEventListener('change', async ()=>{
    const f = $('tlImportFile').files && $('tlImportFile').files[0]; if(!f) return;
    const rows = spParseCsv(await f.text()); if(rows.length < 2){ toast('The CSV has no data rows'); return; }
    const h = rows[0].map(x=> x.trim().toLowerCase().replace(/[^a-z0-9]+/g, '_')), col = (r, k)=>{ const i = h.indexOf(k); return i < 0 ? '' : String(r[i] || '').trim(); };
    if(!h.includes('name') || !h.includes('warehouse_code')){ toast('CSV needs at least: name, warehouse_code'); return; }
    const out = [], bad = [];
    rows.slice(1).forEach((r, i)=>{
      const w = tl.whs.find(x=> x.code.toUpperCase() === col(r, 'warehouse_code').toUpperCase());
      if(!col(r, 'name') || !w){ bad.push(i + 2); return; }
      const mt = ['calibration', 'inspection'].includes(col(r, 'maint_type')) ? col(r, 'maint_type') : null;
      out.push({ name: col(r, 'name'), kind: col(r, 'kind') === 'kit' ? 'kit' : 'tool', category: TL_CATEGORIES.find(c=> c.toLowerCase() === col(r, 'category').toLowerCase()) || 'Other',
        brand: col(r, 'brand'), model: col(r, 'model'), serial_no: col(r, 'serial_no'), home_warehouse_id: w.id, purchase_date: col(r, 'purchase_date') || null,
        purchase_cost: col(r, 'purchase_cost') ? spParseMoney(col(r, 'purchase_cost')) : null, maint_type: mt,
        maint_interval_days: mt && parseInt(col(r, 'maint_interval_days'), 10) > 0 ? parseInt(col(r, 'maint_interval_days'), 10) : null, next_maint_due: mt ? (col(r, 'next_maint_due') || null) : null });
    });
    if(!out.length){ toast('Nothing to import' + (bad.length ? ' — check rows ' + bad.slice(0, 5).join(', ') : '')); return; }
    if(!confirm('Add ' + out.length + ' tool' + (out.length === 1 ? '' : 's') + (bad.length ? ' (skipping ' + bad.length + ' row(s) with no name or unknown warehouse)' : '') + '?')) return;
    const { data, error } = await db.from('tools').insert(out).select('id');
    if(error){ purchFail('Import failed: ', error); return; }
    toast('Imported ' + data.length + ' tools'); await tlLoad(); tlRenderRegister();
  });

  // ---------- detail + history ----------
  async function tlOpenDetail(id){
    const t = tlTool(id); if(!t) return;
    tlDetailTool = t;
    $('tlDetTitle').innerHTML = '<span class="mt-code">' + escapeHtml(t.asset_tag) + '</span> ' + escapeHtml(t.name) + ' ' + tlStatusPill(t.status);
    const kv = (k, v)=> v ? '<div><div class="k">' + k + '</div><div class="v">' + v + '</div></div>' : '';
    $('tlDetInfo').innerHTML = kv('Type', t.kind === 'kit' ? 'Kit' : 'Tool / equipment') + kv('Category', escapeHtml(t.category)) + kv('Brand / model', escapeHtml([t.brand, t.model].filter(Boolean).join(' '))) +
      kv('Serial no.', escapeHtml(t.serial_no)) + kv('Home warehouse', escapeHtml(tlWh(t.home_warehouse_id))) +
      (t.status === 'issued' ? kv('With', escapeHtml(t.holder_name) + (t.due_back ? ' · due ' + escapeHtml(poDateLong(t.due_back)) : '') + (tlOverdue(t) ? ' <b style="color:var(--danger)">OVERDUE</b>' : '')) + kv('For', escapeHtml(tlPrj(t.project_id, t.job_order_id))) : '') +
      (t.maint_type ? kv(t.maint_type === 'inspection' ? 'Inspection' : 'Calibration', 'every ' + t.maint_interval_days + ' days · next ' + escapeHtml(poDateLong(t.next_maint_due)) + (tlMaintLate(t) ? ' <b style="color:var(--danger)">OVERDUE</b>' : '')) : '') +
      (t.kind === 'kit' ? '<div class="wide"><div class="k">Kit contents</div><div class="v">' + escapeHtml((t.kit_contents || []).map(k=> k.name + (k.qty > 1 ? ' ×' + k.qty : '')).join(', ')) + '</div></div>' : '') +
      kv('Purchased', escapeHtml([t.purchase_date ? poDateLong(t.purchase_date) : '', t.po_no, t.purchase_cost != null && tl.isAdmin ? '₱' + poFmt(t.purchase_cost) : ''].filter(Boolean).join(' · '))) +
      kv('Warranty until', t.warranty_until ? escapeHtml(poDateLong(t.warranty_until)) + (t.warranty_until < tlToday() ? ' (expired)' : '') : '');
    const b = (a, l, c)=> '<button type="button" class="btn ' + (c || 'btn-secondary') + '" data-da="' + a + '">' + l + '</button>';
    $('tlDetActions').innerHTML = b('label', 'Print QR Label') + (t.maint_type && t.status !== 'issued' ? b('maint', 'Record ' + (t.maint_type === 'inspection' ? 'Inspection' : 'Calibration')) : '') +
      (tl.isAdmin ? b('edit', 'Edit') + (t.status === 'lost' ? b('found', 'Mark Found') : '') + (['available', 'lost', 'defective'].includes(t.status) ? b('retire', 'Retire', 'danger') : '') : '');
    tlRegView('detail');
    const h = await db.from('tool_events').select('*').eq('tool_id', t.id).order('at', { ascending:false }).limit(200);
    $('tlDetHist').innerHTML = (h.data || []).length ? '<thead><tr><th>When</th><th>Event</th><th>Ref.</th><th>Details</th><th>By</th></tr></thead><tbody>' +
      h.data.map(e=> '<tr><td>' + escapeHtml(mrWhen(e.at)) + '</td><td><b>' + escapeHtml(e.event) + '</b></td><td>' + escapeHtml(e.ref) + '</td><td>' + escapeHtml(e.detail) + '</td><td>' + escapeHtml(e.by_name) + '</td></tr>').join('') + '</tbody>'
      : '<tbody><tr><td style="color:var(--text-muted);">No history yet.</td></tr></tbody>';
  }
  $('tlDetBack').addEventListener('click', ()=>{ tlRegView('list'); tlRenderRegister(); });
  $('tlDetActions').addEventListener('click', async (e)=>{
    const b = e.target.closest('[data-da]'); if(!b || !tlDetailTool) return;
    const t = tlDetailTool, a = b.dataset.da;
    if(a === 'label') return tlLabelsPdf([t]);
    if(a === 'edit') return tlOpenForm(t);
    if(a === 'maint'){ showPurchasingView('tlMaint'); setTimeout(()=> tlMaintOpenForm(t.id), 300); return; }
    const reason = prompt(a === 'found' ? 'Where was ' + t.asset_tag + ' found?' : 'Why is ' + t.asset_tag + ' being retired?');
    if(!reason || !reason.trim()) return;
    if(!(await purchEnsureSession())) return;
    const { error } = await db.rpc('tl_admin_status', { p_tool: t.id, p_status: a === 'found' ? 'available' : 'retired', p_note: reason.trim() });
    if(error){ purchFail('Couldn\u2019t update: ', error); return; }
    toast(t.asset_tag + (a === 'found' ? ' back in service' : ' retired')); await tlLoad(); tlOpenDetail(t.id);
  });

  // =====================================================================
  // DEFECTS
  // =====================================================================
  let tlDefects = [], tlDefOpen = null;
  async function tlShowDefects(){
    if(!(await tlEnter(false))) return;
    $('tlDefDetail').style.display = 'none'; $('tlDefList').style.display = '';
    const r = await db.from('tool_defects').select('*').order('created_at', { ascending:false }).limit(500);
    tlDefects = r.data || [];
    tlRenderDefects();
  }
  function tlRenderDefects(){
    const st = $('tlDefStatus').value, q = ($('tlDefSearch').value || '').trim().toLowerCase();
    const rows = tlDefects.filter(d=> (st === 'active' ? d.status !== 'closed' : !st || d.status === st) &&
      (!q || [d.defect_no, tlLabel(tlTool(d.tool_id)), d.worker_name, d.description].join(' ').toLowerCase().includes(q)));
    $('tlDefectsCount').textContent = tlDefects.filter(d=> d.status !== 'closed').length ? tlDefects.filter(d=> d.status !== 'closed').length + ' open' : '';
    $('tlDefRows').innerHTML = rows.length ? rows.map(d=>{ const t = tlTool(d.tool_id) || {};
      return '<button type="button" class="mt-row" data-id="' + escapeHtml(d.id) + '"><div class="mt-row-main"><div class="mt-row-title"><span class="mt-code">' + escapeHtml(d.defect_no) + '</span>' +
        escapeHtml(tlLabel(t)) + ' <span class="tl-st ' + (d.status === 'closed' ? 'retired' : d.status === 'in_repair' ? 'repair' : 'defective') + '">' + escapeHtml(d.status.replace('_', ' ')) + '</span>' +
        (d.under_warranty ? ' <span class="sp-tag">Under warranty</span>' : '') + '</div>' +
        '<div class="sp-row-sub">' + escapeHtml([TL_COND[d.condition] || d.condition, d.worker_name ? 'from ' + d.worker_name : '', mrWhen(d.created_at), d.decision !== 'pending' ? 'decision: ' + d.decision.replace('_', ' ') : ''].filter(Boolean).join(' · ')) + '</div>' +
        (d.description ? '<div class="sp-row-sub">' + escapeHtml(d.description) + '</div>' : '') + '</div></button>'; }).join('')
      : '<div class="empty-state">No defect reports here.</div>';
  }
  $('tlDefSearch').addEventListener('input', tlRenderDefects); $('tlDefStatus').addEventListener('change', tlRenderDefects);
  $('tlDefRows').addEventListener('click', (e)=>{ const r = e.target.closest('.mt-row'); if(r) tlOpenDefect(r.dataset.id); });
  $('tlDefBack').addEventListener('click', ()=>{ $('tlDefDetail').style.display = 'none'; $('tlDefList').style.display = ''; tlRenderDefects(); });
  async function tlOpenDefect(id){
    const d = tlDefects.find(x=> x.id === id); if(!d) return;
    tlDefOpen = d; const t = tlTool(d.tool_id) || {};
    $('tlDefTitle').innerHTML = '<span class="mt-code">' + escapeHtml(d.defect_no) + '</span> ' + escapeHtml(tlLabel(t));
    const kv = (k, v)=> v ? '<div><div class="k">' + k + '</div><div class="v">' + v + '</div></div>' : '';
    $('tlDefInfo').innerHTML = kv('Condition', escapeHtml(TL_COND[d.condition] || d.condition)) + kv('Returned by', escapeHtml(d.worker_name)) + kv('Job / project', escapeHtml(tlPrj(d.project_id, d.job_order_id))) +
      kv('Reported', escapeHtml(mrWhen(d.created_at) + ' by ' + d.reported_by_name)) + kv('Warranty', d.under_warranty ? '<b>Still under warranty</b> — claim from the supplier' : 'Not under warranty') +
      kv('Status', escapeHtml(d.status.replace('_', ' ') + (d.decision !== 'pending' ? ' · ' + d.decision.replace('_', ' ') : ''))) +
      (d.repair_cost != null && tl.isAdmin ? kv('Repair cost', '₱' + poFmt(d.repair_cost) + (d.repair_vendor ? ' · ' + escapeHtml(d.repair_vendor) : '')) : '') +
      (d.chargeable_to_worker ? kv('Chargeable to worker', 'Yes (per company policy)') : '') +
      '<div class="wide"><div class="k">Description</div><div class="v">' + escapeHtml(d.description || '—') + '</div></div>' +
      (d.photo_path ? '<div class="wide"><div class="k">Photo</div><div class="v mr-photo" id="tlDefPhoto">Loading…</div></div>' : '');
    if(d.photo_path) tlDownloadUrl(d.photo_path).then(u=>{ const el = document.getElementById('tlDefPhoto'); if(el) el.innerHTML = u ? '<img src="' + u + '">' : 'Photo unavailable'; });
    $('tlDCause').value = d.cause; $('tlDDec').value = d.decision; $('tlDVendor').value = d.repair_vendor || '';
    $('tlDCost').value = d.repair_cost != null ? String(d.repair_cost) : ''; $('tlDCharge').checked = !!d.chargeable_to_worker; $('tlDNote').value = '';
    $('tlDefDecideSec').style.display = tl.isAdmin && d.status !== 'closed' ? '' : 'none';
    $('tlDefList').style.display = 'none'; $('tlDefDetail').style.display = '';
    window.scrollTo({ top:0 });
  }
  $('tlDefDecideSec').addEventListener('click', async (e)=>{
    const b = e.target.closest('[data-dstat]'); if(!b || !tlDefOpen) return;
    const st = b.dataset.dstat, dec = $('tlDDec').value, cost = spParseMoney($('tlDCost').value);
    if(st === 'closed' && dec === 'pending'){ toast('Choose a decision before closing'); return; }
    if(st === 'in_repair' && dec !== 'repair'){ toast('Set the decision to Repair first'); return; }
    if(Number.isNaN(cost)){ toast('Repair cost must be a number'); return; }
    if(st === 'closed' && !confirm('Close ' + tlDefOpen.defect_no + ' as "' + dec.replace('_', ' ') + '"? ' + (['replace', 'write_off'].includes(dec) ? 'The tool will be retired.' : 'The tool goes back into service.'))) return;
    if(!(await purchEnsureSession())) return;
    const { error } = await db.rpc('tl_decide_defect', { p: { defect_id: tlDefOpen.id, decision: dec, status: st, cause: $('tlDCause').value,
      repair_vendor: $('tlDVendor').value.trim(), repair_cost: cost, chargeable_to_worker: $('tlDCharge').checked, note: $('tlDNote').value.trim() } });
    if(error){ purchFail('Couldn\u2019t save the decision: ', error); return; }
    toast(tlDefOpen.defect_no + ' updated'); await tlShowDefects();
  });

  // =====================================================================
  // CALIBRATION & INSPECTION
  // =====================================================================
  let tlMaintTool = null;
  async function tlShowMaint(){
    if(!(await tlEnter(false))) return;
    $('tlMtForm').style.display = 'none';
    tlRenderMaint();
  }
  function tlRenderMaint(){
    const due = $('tlMtShow').value === 'due', q = ($('tlMtSearch').value || '').trim().toLowerCase();
    const rows = tl.tools.filter(t=> t.maint_type && t.status !== 'retired' && (!due || tlMaintLate(t) || tlMaintSoon(t)) &&
      (!q || [t.asset_tag, t.name, t.serial_no].join(' ').toLowerCase().includes(q))).sort((a, b)=> String(a.next_maint_due).localeCompare(String(b.next_maint_due)));
    $('tlMaintCount').textContent = tl.tools.filter(tlMaintLate).length ? tl.tools.filter(tlMaintLate).length + ' overdue' : '';
    $('tlMtRows').innerHTML = rows.length ? rows.map(t=> '<div class="sp-row" data-id="' + escapeHtml(t.id) + '"><div class="sp-row-top"><div style="min-width:0;"><div class="sp-row-title"><span class="mt-code">' + escapeHtml(t.asset_tag) + '</span> ' + escapeHtml(t.name) + ' ' + tlStatusPill(t.status) + '</div>' +
      '<div class="sp-row-sub">' + escapeHtml((t.maint_type === 'inspection' ? 'Inspection' : 'Calibration') + ' every ' + t.maint_interval_days + ' days · ' + tlWh(t.home_warehouse_id)) + '</div></div>' +
      '<div class="mt-row-price" style="' + (tlMaintLate(t) ? 'color:var(--danger);' : tlMaintSoon(t) ? 'color:#9A6212;' : '') + '">' + escapeHtml(t.next_maint_due ? poDateLong(t.next_maint_due) : 'not set') + '<div class="sp-row-sub">' + (tlMaintLate(t) ? 'OVERDUE' : tlMaintSoon(t) ? 'due soon' : 'next due') + '</div></div></div>' +
      '<div class="user-card-actions"><button type="button" class="primary" data-mt="1"' + (t.status === 'issued' ? ' disabled title="Return it first"' : '') + '>Record result</button></div></div>').join('')
      : '<div class="empty-state">' + (due ? 'Nothing overdue or due in the next 30 days. ✓' : 'No tools have a calibration or inspection schedule yet — set one on the tool.') + '</div>';
  }
  $('tlMtSearch').addEventListener('input', tlRenderMaint); $('tlMtShow').addEventListener('change', tlRenderMaint);
  $('tlMtRows').addEventListener('click', (e)=>{ if(e.target.closest('[data-mt]')) tlMaintOpenForm(e.target.closest('.sp-row').dataset.id); });
  function tlMaintOpenForm(id){
    const t = tlTool(id); if(!t) return;
    tlMaintTool = t;
    $('tlMtFormTitle').textContent = 'Record ' + (t.maint_type === 'inspection' ? 'inspection' : 'calibration') + ' — ' + t.asset_tag + ' ' + t.name;
    $('tlMtDate').value = tlToday(); $('tlMtResult').value = 'pass'; $('tlMtRef').value = ''; $('tlMtNote').value = '';
    $('tlMtForm').style.display = ''; $('tlMtForm').scrollIntoView({ block:'center' });
  }
  $('tlMtCancel').addEventListener('click', ()=>{ $('tlMtForm').style.display = 'none'; });
  $('tlMtSave').addEventListener('click', async ()=>{
    const t = tlMaintTool; if(!t) return;
    if($('tlMtResult').value === 'fail' && !$('tlMtNote').value.trim()){ toast('Describe why it failed'); return; }
    if(!(await purchEnsureSession())) return;
    const { data, error } = await db.rpc('tl_log_maintenance', { p: { tool_id: t.id, type: t.maint_type, done_on: $('tlMtDate').value, result: $('tlMtResult').value,
      cert_ref: $('tlMtRef').value.trim(), note: $('tlMtNote').value.trim() } });
    if(error){ purchFail('Couldn\u2019t save: ', error); return; }
    toast(data && data.defect_no ? 'Failed — ' + data.defect_no + ' opened; tool out of service' : 'Passed — next due ' + poDateLong(data.next_due));
    await tlLoad(); $('tlMtForm').style.display = 'none'; tlRenderMaint();
  });

  // =====================================================================
  // shared: tool line list with type-ahead + scan + optional photo
  // =====================================================================
  function tlLineList(id, pool){        // pool(): tools allowed on this list
    const st = { lines:[], pool };
    const find = $(id + 'Find');
    const add = (t)=>{
      if(!t){ return; }
      if(st.lines.some(l=> l.tool_id === t.id)){ toast(t.asset_tag + ' is already on the list'); return; }
      if(!st.pool().some(x=> x.id === t.id)){ toast(t.asset_tag + ' can\u2019t be added here (' + (TL_STATUS[t.status] || t.status) + (t.status === 'available' ? ', other warehouse' : '') + ')'); return; }
      st.lines.push({ tool_id: t.id, note:'', photo:null });
      render();
    };
    function render(){
      $(id).innerHTML = st.lines.length ? st.lines.map((l, i)=>{ const t = tlTool(l.tool_id);
        return '<div class="tl-line" data-i="' + i + '"><div class="tl-line-top"><div><span class="tl-tag">' + escapeHtml(t.asset_tag) + '</span> <span class="tl-name">' + escapeHtml(t.name) + '</span>' +
          '<div class="tl-sub">' + escapeHtml([t.kind === 'kit' ? 'Kit: ' + (t.kit_contents || []).map(k=> k.name + (k.qty > 1 ? ' ×' + k.qty : '')).join(', ') : '', t.serial_no ? 'S/N ' + t.serial_no : ''].filter(Boolean).join(' · ')) + '</div>' +
          (tlMaintLate(t) ? '<div class="tl-bad">' + escapeHtml((t.maint_type === 'inspection' ? 'Inspection' : 'Calibration') + ' overdue since ' + poDateLong(t.next_maint_due)) + ' — it won\u2019t be issued</div>' : tlMaintSoon(t) ? '<div class="tl-warn">' + escapeHtml((t.maint_type === 'inspection' ? 'Inspection' : 'Calibration') + ' due ' + poDateLong(t.next_maint_due)) + '</div>' : '') +
          '</div><button type="button" class="tl-rm" data-rm="1">&minus;</button></div>' +
          '<div class="tl-line-ctl"><label class="btn btn-secondary mt-small-btn" style="margin:0;">Photo<input type="file" accept="image/*" capture="environment" data-photo="1" style="display:none;"></label>' +
          '<input type="text" data-note="1" placeholder="Note (optional)" value="' + escapeHtml(l.note) + '"></div>' +
          (l.photo ? '<div class="tl-photo"><img src="' + l.photo.url + '"></div>' : '') + '</div>'; }).join('')
        : '<div class="empty-state" style="padding:12px;">No tools yet — type a tag or name below, or scan.</div>';
    }
    $(id).addEventListener('click', (e)=>{ if(e.target.closest('[data-rm]')){ st.lines.splice(+e.target.closest('[data-i]').dataset.i, 1); render(); } });
    $(id).addEventListener('input', (e)=>{ if(e.target.dataset.note) st.lines[+e.target.closest('[data-i]').dataset.i].note = e.target.value; });
    $(id).addEventListener('change', async (e)=>{
      if(!e.target.dataset.photo || !e.target.files[0]) return;
      try{ st.lines[+e.target.closest('[data-i]').dataset.i].photo = await tlPhotoBlob(e.target.files[0]); render(); }catch(err){ toast('Couldn\u2019t read that photo'); }
    });
    find.addEventListener('input', ()=>{
      const row = find.parentElement; let box = row.querySelector('.po-suggest');
      const w = find.value.trim().toLowerCase().split(/\s+/).filter(Boolean);
      const hits = w.length ? st.pool().filter(t=> !st.lines.some(l=> l.tool_id === t.id) && w.every(x=> [t.asset_tag, t.name, t.serial_no, t.brand].join(' ').toLowerCase().includes(x))).slice(0, 8) : [];
      if(!hits.length){ if(box) box.remove(); return; }
      if(!box){ box = document.createElement('div'); box.className = 'po-suggest'; row.appendChild(box); }
      box.innerHTML = hits.map((t, i)=> '<button type="button" data-pick="' + escapeHtml(t.id) + '"' + (i === 0 ? ' class="hl"' : '') + '><span><b>' + escapeHtml(t.asset_tag) + '</b> ' + escapeHtml(t.name) + '</span><span class="s-price">' + escapeHtml(t.serial_no) + '</span></button>').join('');
      box.onclick = (ev)=>{ const b = ev.target.closest('[data-pick]'); if(!b) return; add(tlTool(b.dataset.pick)); find.value = ''; box.remove(); find.focus(); };
    });
    find.addEventListener('keydown', (e)=>{
      const box = find.parentElement.querySelector('.po-suggest');
      if(e.key === 'Enter'){ e.preventDefault(); const tag = tlParseTag(find.value);
        const t = tag ? tl.tools.find(x=> x.asset_tag === tag) : null;
        if(t){ add(t); find.value = ''; if(box) box.remove(); } else if(box){ const h = box.querySelector('.hl'); if(h) h.click(); } }
    });
    $(id + 'Scan').addEventListener('click', async ()=>{ const tag = await tlScan(); if(!tag) return; const t = tl.tools.find(x=> x.asset_tag === tag); if(t) add(t); else toast(tag + ' isn\u2019t in the register'); });
    st.render = render; st.reset = ()=>{ st.lines = []; render(); };
    return st;
  }
  // collect signatures (+ photos) then post
  async function tlSigsAndPost(opts){
    // opts: { keeperTitle, keeperWho, workerTitle, workerWho, needWorker, lines }
    const k = await tlSign(opts.keeperTitle, opts.keeperWho); if(!k) return null;
    let w = null;
    if(opts.needWorker){ w = await tlSign(opts.workerTitle, opts.workerWho); if(!w) return null; }
    const paths = { keeper: await tlUpload(k, 'png'), worker: w ? await tlUpload(w, 'png') : '' };
    for(const l of (opts.lines || [])) if(l.photo && !l.photo_path) l.photo_path = await tlUpload(l.photo.blob, 'jpg');
    return paths;
  }

  // =====================================================================
  // ISSUE
  // =====================================================================
  const tlIs = tlLineList('tlIsLines', ()=> tl.tools.filter(t=> t.status === 'available' && t.home_warehouse_id === $('tlIsWh').value));
  async function tlShowIssue(){
    if(!(await tlEnter(true))) return;
    $('tlIsWh').innerHTML = tlWhOpts(); $('tlIsWorker').innerHTML = tlWorkerOpts();
    $('tlIsJob').innerHTML = tlOpts(tl.jobs, j=> j.id, j=> j.id + (j.cust_name ? ' — ' + j.cust_name : ''), '— none —');
    $('tlIsProject').innerHTML = tlOpts(tl.projects.filter(p=> ['planning', 'active', 'on_hold'].includes(p.status)), p=> p.id, p=> p.project_no + ' — ' + p.name, '— none —');
    $('tlIsDue').value = ''; $('tlIsNote').value = ''; $('tlIsLinesFind').value = '';
    tlIs.reset();
  }
  $('tlIsWh').addEventListener('change', ()=>{ tlIs.lines = tlIs.lines.filter(l=> tlTool(l.tool_id).home_warehouse_id === $('tlIsWh').value); tlIs.render(); });
  $('tlIsPost').addEventListener('click', async ()=>{
    const worker = tl.workers.find(w=> w.id === $('tlIsWorker').value), wh = tl.mine.find(w=> w.id === $('tlIsWh').value);
    if(!worker){ toast('Choose who the tools are issued to'); return; }
    if(!tlIs.lines.length){ toast('Add at least one tool'); return; }
    const late = tlIs.lines.map(l=> tlTool(l.tool_id)).filter(tlMaintLate);
    if(late.length){ toast(late.map(t=> t.asset_tag).join(', ') + ': calibration/inspection overdue — remove it or record a pass first'); return; }
    if($('tlIsDue').value && $('tlIsDue').value < tlToday()){ toast('The due-back date is in the past'); return; }
    const mode = tlMode('tlIsMode');
    if(!(await purchEnsureSession())) return;
    const btn = $('tlIsPost'); btn.disabled = true;
    try{
      const sig = await tlSigsAndPost({ keeperTitle:'Warehouseman signature', keeperWho:'Issued by ' + (currentUser.name || '') + ' — ' + tlIs.lines.length + ' tool(s) to ' + worker.name,
        workerTitle:'Worker signature', workerWho: worker.name + ' — I received the tools listed, in good condition', needWorker: mode === 'counter', lines: tlIs.lines });
      if(!sig) return;
      const { data, error } = await db.rpc('tl_post_issue', { p: { warehouse_id: wh.id, worker_id: worker.id, job_order_id: $('tlIsJob').value || null, project_id: $('tlIsProject').value || null,
        due_back: $('tlIsDue').value || null, note: $('tlIsNote').value.trim(), sign_mode: mode, sig_keeper_path: sig.keeper, sig_worker_path: sig.worker,
        lines: tlIs.lines.map(l=> ({ tool_id: l.tool_id, photo_path: l.photo_path || '', note: l.note })) } });
      if(error) throw error;
      notifyUser(worker.id, 'Tools issued to you', data.slip_no + ' — ' + tlIs.lines.length + ' tool(s)' + (mode === 'phone' ? '. Open My Tools and sign to confirm.' : '.') + ($('tlIsDue').value ? ' Due back ' + poDateLong($('tlIsDue').value) + '.' : ''), 'tis-' + data.id);
      toast(data.slip_no + (mode === 'phone' ? ' posted — waiting for ' + worker.name + '\u2019s signature' : ' posted'));
      tlAfterPost(data.id);
    }catch(e){ purchFail('Couldn\u2019t issue: ', e); }
    finally{ btn.disabled = false; }
  });

  // =====================================================================
  // RETURN — tools held by the chosen worker
  // =====================================================================
  let tlRt = [];
  async function tlShowReturn(){
    if(!(await tlEnter(true))) return;
    $('tlRtWh').innerHTML = tlWhOpts();
    const holders = tl.workers.filter(w=> tl.tools.some(t=> t.status === 'issued' && t.holder_id === w.id));
    $('tlRtWorker').innerHTML = tlOpts(holders, w=> w.id, w=> w.name + ' (' + tl.tools.filter(t=> t.status === 'issued' && t.holder_id === w.id).length + ')', holders.length ? 'Choose a person…' : 'Nobody is holding tools');
    $('tlRtNote').value = ''; tlRt = [];
    $('tlRtLines').innerHTML = '<div class="empty-state" style="padding:12px;">Choose who is returning tools.</div>';
  }
  function tlRenderReturn(){
    $('tlRtLines').innerHTML = tlRt.length ? tlRt.map((l, i)=>{ const t = tlTool(l.tool_id);
      return '<div class="tl-line" data-i="' + i + '"><div class="tl-line-top"><label class="sp-check" style="margin:0;"><input type="checkbox" data-inc="1"' + (l.inc ? ' checked' : '') + '> ' +
        '<span><span class="tl-tag">' + escapeHtml(t.asset_tag) + '</span> <span class="tl-name">' + escapeHtml(t.name) + '</span></span></label>' +
        (tlOverdue(t) ? '<span class="tl-bad">overdue</span>' : '') + '</div>' +
        '<div class="tl-sub">' + escapeHtml([t.job_order_id, t.issued_at ? 'since ' + mrWhen(t.issued_at) : '', t.due_back ? 'due ' + poDateLong(t.due_back) : ''].filter(Boolean).join(' · ')) + '</div>' +
        (l.inc ? '<div class="tl-line-ctl"><select data-cond="1">' + Object.entries(TL_COND).map(([k, v])=> '<option value="' + k + '"' + (l.cond === k ? ' selected' : '') + '>' + v + '</option>').join('') + '</select>' +
          '<input type="text" data-note="1" placeholder="' + (l.cond === 'good' ? 'Note (optional)' : 'What\u2019s wrong? (or add a photo)') + '" value="' + escapeHtml(l.note) + '"></div>' +
          (t.kind === 'kit' && l.cond !== 'lost' ? '<div class="tl-kit"><span class="tl-sub">Missing from kit:</span>' + (t.kit_contents || []).map((k, ki)=> '<label><input type="checkbox" data-kit="' + ki + '"' + (l.missing.includes(ki) ? ' checked' : '') + '> ' + escapeHtml(k.name) + (k.qty > 1 ? ' ×' + k.qty : '') + '</label>').join('') + '</div>' : '') +
          (l.cond !== 'good' && l.cond !== 'lost' ? '<div class="tl-photo"><label class="btn btn-secondary mt-small-btn" style="margin:0;">Photo of the damage<input type="file" accept="image/*" capture="environment" data-photo="1" style="display:none;"></label>' + (l.photo ? '<img src="' + l.photo.url + '">' : '') + '</div>' : '') : '') +
        '</div>'; }).join('') : '<div class="empty-state" style="padding:12px;">This person isn\u2019t holding any tools.</div>';
  }
  $('tlRtWorker').addEventListener('change', ()=>{
    const w = $('tlRtWorker').value;
    tlRt = tl.tools.filter(t=> t.status === 'issued' && t.holder_id === w).map(t=> ({ tool_id: t.id, inc:true, cond:'good', note:'', missing:[], photo:null }));
    tlRenderReturn();
  });
  $('tlRtLines').addEventListener('change', async (e)=>{
    const r = e.target.closest('[data-i]'); if(!r) return; const l = tlRt[+r.dataset.i];
    if(e.target.dataset.inc){ l.inc = e.target.checked; tlRenderReturn(); }
    else if(e.target.dataset.cond){ l.cond = e.target.value; tlRenderReturn(); }
    else if(e.target.dataset.kit != null){ const k = +e.target.dataset.kit; l.missing = e.target.checked ? l.missing.concat(k) : l.missing.filter(x=> x !== k); }
    else if(e.target.dataset.photo && e.target.files[0]){ try{ l.photo = await tlPhotoBlob(e.target.files[0]); tlRenderReturn(); }catch(err){ toast('Couldn\u2019t read that photo'); } }
  });
  $('tlRtLines').addEventListener('input', (e)=>{ if(e.target.dataset.note) tlRt[+e.target.closest('[data-i]').dataset.i].note = e.target.value; });
  $('tlRtPost').addEventListener('click', async ()=>{
    const worker = tl.workers.find(w=> w.id === $('tlRtWorker').value), wh = tl.mine.find(w=> w.id === $('tlRtWh').value);
    const lines = tlRt.filter(l=> l.inc);
    if(!worker || !lines.length){ toast('Choose who is returning and tick the tools'); return; }
    for(const l of lines){ const t = tlTool(l.tool_id);
      if(l.cond !== 'good' && l.cond !== 'lost' && !l.photo && !l.note.trim() && !l.missing.length){ toast(t.asset_tag + ': add a photo or a note about the problem'); return; } }
    const bad = lines.filter(l=> l.cond !== 'good' || l.missing.length).length;
    if(bad && !confirm(bad + ' tool(s) not in good condition — a defect report opens for each and they go out of service. Continue?')) return;
    const mode = tlMode('tlRtMode');
    if(!(await purchEnsureSession())) return;
    const btn = $('tlRtPost'); btn.disabled = true;
    try{
      const sig = await tlSigsAndPost({ keeperTitle:'Warehouseman signature', keeperWho:'Received by ' + (currentUser.name || '') + ' — ' + lines.length + ' tool(s) from ' + worker.name,
        workerTitle:'Worker signature', workerWho: worker.name + ' — I returned the tools listed, in the condition noted', needWorker: mode === 'counter', lines });
      if(!sig) return;
      const { data, error } = await db.rpc('tl_post_return', { p: { warehouse_id: wh.id, worker_id: worker.id, note: $('tlRtNote').value.trim(), sign_mode: mode,
        sig_keeper_path: sig.keeper, sig_worker_path: sig.worker,
        lines: lines.map(l=>{ const t = tlTool(l.tool_id); return { tool_id: l.tool_id, condition: l.cond, note: l.note.trim(), photo_path: l.photo_path || '',
          kit_missing: l.missing.map(k=> t.kit_contents[k]) }; }) } });
      if(error) throw error;
      if(mode === 'phone') notifyUser(worker.id, 'Please sign your tool return', data.slip_no + ' — open My Tools and sign to confirm.', 'trs-' + data.id);
      toast(data.slip_no + ' posted' + (data.defects ? ' — ' + data.defects + ' defect report(s) opened' : ''));
      tlAfterPost(data.id);
    }catch(e){ purchFail('Couldn\u2019t receive: ', e); }
    finally{ btn.disabled = false; }
  });

  // =====================================================================
  // HANDOVER (admin / storekeeper screen; workers use My Tools)
  // =====================================================================
  let tlHo = [];
  async function tlShowHandover(){
    if(!(await tlEnter(false))) return;
    const holders = tl.workers.filter(w=> tl.tools.some(t=> t.status === 'issued' && t.holder_id === w.id));
    $('tlHoFrom').innerHTML = tlOpts(holders, w=> w.id, w=> w.name, holders.length ? 'Choose who has the tools…' : 'Nobody is holding tools');
    $('tlHoTo').innerHTML = tlWorkerOpts(); $('tlHoNote').value = ''; tlHo = [];
    $('tlHoLines').innerHTML = '<div class="empty-state" style="padding:12px;">Choose who is handing over.</div>';
  }
  function tlRenderPick(host, arr){
    $(host).innerHTML = arr.length ? arr.map((l, i)=>{ const t = tlTool(l.tool_id);
      return '<label class="tl-line" style="display:block;" data-i="' + i + '"><input type="checkbox" data-pick="1"' + (l.inc ? ' checked' : '') + '> <span class="tl-tag">' + escapeHtml(t.asset_tag) + '</span> <span class="tl-name">' + escapeHtml(t.name) + '</span>' +
        '<div class="tl-sub">' + escapeHtml([t.job_order_id, t.due_back ? 'due ' + poDateLong(t.due_back) : ''].filter(Boolean).join(' · ')) + '</div></label>'; }).join('')
      : '<div class="empty-state" style="padding:12px;">No tools held.</div>';
  }
  $('tlHoFrom').addEventListener('change', ()=>{ tlHo = tl.tools.filter(t=> t.status === 'issued' && t.holder_id === $('tlHoFrom').value).map(t=> ({ tool_id:t.id, inc:false })); tlRenderPick('tlHoLines', tlHo); });
  $('tlHoLines').addEventListener('change', (e)=>{ if(e.target.dataset.pick) tlHo[+e.target.closest('[data-i]').dataset.i].inc = e.target.checked; });
  async function tlDoHandover(fromId, toId, toolIds, note){
    const from = tl.workers.find(w=> w.id === fromId) || { name: currentUser.name }, to = tl.workers.find(w=> w.id === toId);
    if(!to || fromId === toId){ toast('Choose who is receiving the tools'); return null; }
    if(!toolIds.length){ toast('Tick the tools being handed over'); return null; }
    if(!(await purchEnsureSession())) return null;
    const g = await tlSign('Giver signature', from.name + ' — I handed over ' + toolIds.length + ' tool(s) to ' + to.name); if(!g) return null;
    const r = await tlSign('Receiver signature', to.name + ' — I received ' + toolIds.length + ' tool(s) from ' + from.name); if(!r) return null;
    const { data, error } = await db.rpc('tl_post_handover', { p: { from_worker_id: fromId, to_worker_id: toId, note: note || '',
      sig_giver_path: await tlUpload(g, 'png'), sig_receiver_path: await tlUpload(r, 'png'), lines: toolIds.map(id=> ({ tool_id:id })) } });
    if(error) throw error;
    notifyUser(toId, 'Tools handed over to you', data.slip_no + ' — ' + toolIds.length + ' tool(s) from ' + from.name + '. You\u2019re now responsible for them.', 'tho-' + data.id);
    toast(data.slip_no + ' — custody moved to ' + to.name);
    return data;
  }
  $('tlHoPost').addEventListener('click', async ()=>{
    const btn = $('tlHoPost'); btn.disabled = true;
    try{ const d = await tlDoHandover($('tlHoFrom').value, $('tlHoTo').value, tlHo.filter(l=> l.inc).map(l=> l.tool_id), $('tlHoNote').value.trim()); if(d) tlAfterPost(d.id); }
    catch(e){ purchFail('Couldn\u2019t hand over: ', e); }
    finally{ btn.disabled = false; }
  });

  // =====================================================================
  // SLIPS
  // =====================================================================
  let tlSlips = [], tlSlipOpen = null;
  async function tlAfterPost(slipId){
    showPurchasingView('tlSlips');
    setTimeout(()=> tlOpenSlip(slipId), 150);
  }
  async function tlShowSlips(){
    if(!(await tlEnter(false))) return;
    $('tlSlipDetail').style.display = 'none'; $('tlSlipList').style.display = '';
    const r = await db.from('tool_slips').select('*').order('created_at', { ascending:false }).limit(500);
    tlSlips = r.data || [];
    tlRenderSlips();
  }
  const tlParties = (s)=> s.type === 'issue' ? 'To ' + s.to_worker_name : s.type === 'return' ? 'From ' + s.from_worker_name : s.from_worker_name + ' → ' + s.to_worker_name;
  function tlRenderSlips(){
    const ty = $('tlSlipType').value, q = ($('tlSlipSearch').value || '').trim().toLowerCase();
    const rows = tlSlips.filter(s=> (!ty || (ty === 'pending' ? s.status === 'pending_signature' : s.type === ty)) && (!q || [s.slip_no, tlParties(s), s.job_order_id, s.note].join(' ').toLowerCase().includes(q)));
    $('tlSlipsCount').textContent = tlSlips.filter(s=> s.status === 'pending_signature').length ? tlSlips.filter(s=> s.status === 'pending_signature').length + ' awaiting signature' : '';
    $('tlSlipRows').innerHTML = rows.length ? rows.map(s=> '<button type="button" class="mt-row" data-id="' + escapeHtml(s.id) + '"><div class="mt-row-main"><div class="mt-row-title"><span class="mt-code">' + escapeHtml(s.slip_no) + '</span>' +
      escapeHtml(TL_SLIP[s.type].label) + ' <span class="po-status ' + (s.status === 'complete' ? 'fulfilled' : 'returned') + '">' + (s.status === 'complete' ? 'signed by both' : 'awaiting worker signature') + '</span></div>' +
      '<div class="sp-row-sub">' + escapeHtml([mrWhen(s.created_at), tlParties(s), s.job_order_id, s.warehouse_id ? tlWh(s.warehouse_id) : 'on site'].filter(Boolean).join(' · ')) + '</div></div></button>').join('')
      : '<div class="empty-state">No tool slips yet.</div>';
  }
  $('tlSlipSearch').addEventListener('input', tlRenderSlips); $('tlSlipType').addEventListener('change', tlRenderSlips);
  $('tlSlipRows').addEventListener('click', (e)=>{ const r = e.target.closest('.mt-row'); if(r) tlOpenSlip(r.dataset.id); });
  $('tlSlipBack').addEventListener('click', ()=>{ $('tlSlipDetail').style.display = 'none'; $('tlSlipList').style.display = ''; tlShowSlips(); });
  async function tlLoadSlip(id){
    const [h, l] = await Promise.all([db.from('tool_slips').select('*').eq('id', id), db.from('tool_slip_lines').select('*').eq('slip_id', id)]);
    if(h.error) throw h.error; if(l.error) throw l.error;
    if(!h.data || !h.data[0]) throw new Error('Slip not found');
    return { h: h.data[0], lines: l.data || [] };
  }
  function tlRenderSlipInto(d, pre){
    const s = d.h;
    $(pre + 'Title').innerHTML = '<span class="mt-code">' + escapeHtml(s.slip_no) + '</span> ' + escapeHtml(TL_SLIP[s.type].label) +
      ' <span class="po-status ' + (s.status === 'complete' ? 'fulfilled' : 'returned') + '">' + (s.status === 'complete' ? 'signed by both' : 'awaiting worker signature') + '</span>';
    const kv = (k, v)=> v ? '<div><div class="k">' + k + '</div><div class="v">' + v + '</div></div>' : '';
    $(pre + 'Info').innerHTML = kv('Date', escapeHtml(mrWhen(s.created_at))) + kv(s.type === 'handover' ? 'From' : s.type === 'issue' ? 'Warehouse' : 'Into', escapeHtml(s.type === 'handover' ? s.from_worker_name : tlWh(s.warehouse_id))) +
      kv(s.type === 'return' ? 'Returned by' : 'Received by', escapeHtml(s.type === 'return' ? s.from_worker_name : s.to_worker_name)) +
      kv(s.type === 'handover' ? 'Recorded by' : 'Warehouseman', escapeHtml(s.keeper_name)) + kv('Job / project', escapeHtml(tlPrj(s.project_id, s.job_order_id))) +
      kv('Due back', s.due_back ? escapeHtml(poDateLong(s.due_back)) : '') + kv('Worker signed', s.sign_mode === 'phone' ? 'on their phone' + (s.completed_at ? ' · ' + escapeHtml(mrWhen(s.completed_at)) : '') : 'at the counter') + kv('Note', escapeHtml(s.note));
    $(pre + 'Items').innerHTML = '<thead><tr><th>Tag</th><th>Tool</th><th>Serial</th>' + (s.type === 'return' ? '<th>Condition</th>' : '') + '<th>Note</th></tr></thead><tbody>' +
      d.lines.map(l=>{ const t = tlTool(l.tool_id) || { asset_tag:'?', name:'(tool)', serial_no:'' };
        return '<tr><td><b>' + escapeHtml(t.asset_tag) + '</b></td><td>' + escapeHtml(t.name) + '</td><td>' + escapeHtml(t.serial_no) + '</td>' +
          (s.type === 'return' ? '<td>' + (l.condition === 'good' ? 'Good' : '<span class="sp-tag danger">' + escapeHtml(TL_COND[l.condition]) + '</span>') + '</td>' : '') +
          '<td>' + escapeHtml([l.note, (l.kit_missing || []).length ? 'Missing: ' + l.kit_missing.map(k=> k.name).join(', ') : ''].filter(Boolean).join(' · ')) + '</td></tr>'; }).join('') + '</tbody>';
  }
  async function tlOpenSlip(id){
    try{
      if(!tl.tools.length) await tlLoad();
      tlSlipOpen = await tlLoadSlip(id);
      tlRenderSlipInto(tlSlipOpen, 'tlSlip');
      $('tlSlipList').style.display = 'none'; $('tlSlipDetail').style.display = '';
      window.scrollTo({ top:0 });
    }catch(e){ purchFail('Couldn\u2019t open the slip: ', e); }
  }
  $('tlSlipPdf').addEventListener('click', ()=>{ if(tlSlipOpen) tlSlipPdf(tlSlipOpen); });
  async function tlSlipPdf(d){
    try{
      await loadAwesScript('jspdf', awesLibs.jspdf); await loadAwesScript('autotable', awesLibs.autotable);
      await poLoadSettings().catch(()=>{});
      const co = poSettingsData || {}, style = co.header_style || 'green';
      const logo = co.logo_path ? await poLoadImage(co.logo_path).then(img=> poLogoForStyle(img, style)) : await poDefaultLogo(style);
      const fonts = await poLoadFonts();
      const { jsPDF } = window.jspdf; const doc = new jsPDF({ orientation:'p', unit:'pt', format:'a4', compress:true });
      let F = 'helvetica', FB = ['helvetica', 'bold'];
      if(fonts){ try{ doc.addFileToVFS('Inter-Regular.ttf', fonts.regular); doc.addFont('Inter-Regular.ttf', 'Inter', 'normal');
        doc.addFileToVFS('Inter-Bold.ttf', fonts.bold); doc.addFont('Inter-Bold.ttf', 'InterBold', 'normal'); F = 'Inter'; FB = ['InterBold', 'normal']; }catch(e){} }
      const W = doc.internal.pageSize.getWidth(), H = doc.internal.pageSize.getHeight(), M = 36, G = [21, 77, 52], SUB = [96, 108, 101], INK = [28, 34, 30];
      const s = d.h, green = style !== 'white';
      if(green){ doc.setFillColor(...G); doc.rect(0, 0, W, 96, 'F'); } else { doc.setFillColor(...G); doc.rect(0, 92, W, 4, 'F'); }
      if(logo && logo.w){ const r = Math.min(140 / logo.w, 40 / logo.h); try{ doc.addImage(logo.dataUrl, 'PNG', M, 16, logo.w * r, logo.h * r, 'tl-logo', 'FAST'); }catch(e){} }
      doc.setTextColor(...(green ? [255, 255, 255] : INK));
      doc.setFont(F, 'normal'); doc.setFontSize(9); doc.text(co.company_name || '', M, 76);
      doc.setFont(FB[0], FB[1]); doc.setFontSize(16); doc.text(TL_SLIP[s.type].title, W - M, 36, { align:'right' });
      doc.setFontSize(10.5); doc.text(s.slip_no, W - M, 54, { align:'right' });
      doc.setFont(F, 'normal'); doc.setFontSize(8.8); doc.text(mrWhen(s.created_at), W - M, 68, { align:'right' });
      let y = 116;
      const info = [[s.type === 'handover' ? 'From' : 'Warehouse', s.type === 'handover' ? s.from_worker_name : tlWh(s.warehouse_id) + ' — ' + ((tl.whs.find(w=> w.id === s.warehouse_id) || {}).name || '')],
        [s.type === 'return' ? 'Returned by' : 'Received by', s.type === 'return' ? s.from_worker_name : s.to_worker_name], ['Job / project', tlPrj(s.project_id, s.job_order_id)],
        ['Due back', s.due_back ? poDateLong(s.due_back) : ''], ['Note', s.note]].filter(r=> r[1]);
      info.forEach(([k, v])=>{ doc.setFontSize(7.8); doc.setTextColor(...SUB); doc.text(k, M, y); doc.setFontSize(9); doc.setTextColor(...INK); const ls = doc.splitTextToSize(String(v), W - M * 2 - 90); doc.text(ls, M + 90, y); y += ls.length * 11 + 3; });
      doc.autoTable({ startY: y + 8, margin:{ left:M, right:M, bottom:60 },
        head:[['Tag', 'Tool', 'Serial no.'].concat(s.type === 'return' ? ['Condition'] : [], ['Note'])],
        body: d.lines.map(l=>{ const t = tlTool(l.tool_id) || {};
          return [t.asset_tag || '', t.name || '', t.serial_no || ''].concat(s.type === 'return' ? [TL_COND[l.condition]] : [],
            [[l.note, (l.kit_missing || []).length ? 'Missing: ' + l.kit_missing.map(k=> k.name).join(', ') : '', t.kind === 'kit' && s.type === 'issue' ? 'Kit: ' + (t.kit_contents || []).map(k=> k.name + (k.qty > 1 ? ' ×' + k.qty : '')).join(', ') : ''].filter(Boolean).join(' · ')]); }),
        // explicit row fills: without them the rows inherit the header band's green fill
        theme:'plain', styles:{ font:F, fontSize:8.6, cellPadding:5, textColor:INK, fillColor:[255, 255, 255], lineColor:[216, 223, 219], lineWidth:{ bottom:0.5 } },
        alternateRowStyles:{ fillColor:[247, 250, 248] },
        headStyles:{ font:F, fillColor:G, textColor:255, fontSize:7.8 }, columnStyles:{ 0:{ cellWidth:58, fontStyle:'bold' } } });
      const [kSig, wSig] = await Promise.all([s.sig_keeper_path, s.sig_worker_path].map(async p=>{ const u = await tlDownloadUrl(p); if(!u) return null; const z = await poImageSize(u); return { dataUrl:u, w:z.w, h:z.h }; }));
      const caps = s.type === 'issue' ? [['Issued by (warehouseman)', s.keeper_name, kSig], ['Received by (worker)', s.to_worker_name, wSig]]
        : s.type === 'return' ? [['Returned by (worker)', s.from_worker_name, wSig], ['Received by (warehouseman)', s.keeper_name, kSig]]
        : [['Handed over by', s.from_worker_name, kSig], ['Received by', s.to_worker_name, wSig]];
      const top = H - 46 - 92, sw = (W - M * 2 - 40) / 2;
      if(doc.lastAutoTable.finalY > top - 10) doc.addPage();
      caps.forEach(([cap, nm, img], i)=>{
        const x = M + i * (sw + 40);
        doc.setFont(F, 'normal'); doc.setFontSize(6.8); doc.setTextColor(...SUB); doc.text(cap.toUpperCase(), x, top);
        if(img && img.w){ const r = Math.min((sw - 20) / img.w, 46 / img.h); try{ doc.addImage(img.dataUrl, 'PNG', x + (sw - img.w * r) / 2, top + 58 - img.h * r, img.w * r, img.h * r, undefined, 'FAST'); }catch(e){} }
        else{ doc.setFontSize(7.4); doc.setTextColor(200, 120, 20); doc.text('awaiting signature', x + sw / 2, top + 40, { align:'center' }); }
        doc.setDrawColor(70, 76, 72); doc.setLineWidth(0.6); doc.line(x, top + 60, x + sw, top + 60);
        doc.setFont(FB[0], FB[1]); doc.setFontSize(8.6); doc.setTextColor(...INK); doc.text((nm || '').toUpperCase(), x + sw / 2, top + 72, { align:'center' });
      });
      doc.setFont(F, 'normal'); doc.setFontSize(7); doc.setTextColor(...SUB);
      doc.text(s.slip_no + '   •   ' + (co.company_name || '') + (s.status === 'complete' ? '' : '   •   NOT YET SIGNED BY THE WORKER'), M, H - 20);
      $('previewOverlay').querySelector('h3').textContent = TL_SLIP[s.type].label + ' ' + s.slip_no;
      $('previewOkBtn').textContent = 'Close'; $('previewOverlay').style.zIndex = '99'; $('previewOverlay').classList.add('open');
      await renderPdfPreview(doc, s.slip_no + '.pdf', TL_SLIP[s.type].label + ' ' + s.slip_no);
    }catch(e){ console.error('tool slip pdf', e); toast('Couldn\u2019t build the PDF: ' + (e && e.message ? e.message : e)); }
  }

  // =====================================================================
  // MY TOOLS (worker)
  // =====================================================================
  let tlMinePend = [], tlMineOpen = null, tlMineHo = [];
  async function tlShowMine(){
    $('tlMineSlip').style.display = 'none'; $('tlMineHo').style.display = 'none'; $('tlMineList').style.display = '';
    $('tlMinePending').innerHTML = '<div class="empty-state">Loading…</div>';
    if(!(await ensureCloud())) return;
    try{
      const [t, s, wk] = await Promise.all([db.from('tools_view').select('*').eq('holder_id', currentUser.id).order('asset_tag'),
        db.from('tool_slips').select('*').eq('status', 'pending_signature').order('created_at', { ascending:false }),
        db.from('profiles').select('id, name').eq('role', 'technician').eq('active', true).order('name')]);
      if(t.error) throw t.error;
      tl.tools = t.data || []; tl.workers = wk.data || [];
      tlMinePend = (s.data || []).filter(x=> (x.type === 'issue' && x.to_worker_id === currentUser.id) || (x.type === 'return' && x.from_worker_id === currentUser.id));
      $('tlMinePending').innerHTML = tlMinePend.length ? tlMinePend.map(x=> '<button type="button" class="mt-row" data-id="' + escapeHtml(x.id) + '"><div class="mt-row-main"><div class="mt-row-title"><span class="mt-code">' + escapeHtml(x.slip_no) + '</span>' +
        escapeHtml(TL_SLIP[x.type].label) + ' <span class="po-status returned">sign now</span></div><div class="sp-row-sub">' + escapeHtml(mrWhen(x.created_at) + ' · by ' + x.keeper_name) + '</div></div></button>').join('')
        : '<div class="empty-state" style="padding:12px;">Nothing to sign. 👍</div>';
      $('tlMineHold').innerHTML = tl.tools.length ? tl.tools.map(t=> '<div class="sp-row"><div class="sp-row-top"><div><div class="sp-row-title"><span class="mt-code">' + escapeHtml(t.asset_tag) + '</span> ' + escapeHtml(t.name) + '</div>' +
        '<div class="sp-row-sub">' + escapeHtml([t.job_order_id, t.kind === 'kit' ? (t.kit_contents || []).length + ' items in kit' : t.serial_no ? 'S/N ' + t.serial_no : ''].filter(Boolean).join(' · ')) + '</div></div>' +
        '<div class="mt-row-price" style="' + (tlOverdue(t) ? 'color:var(--danger);' : '') + '">' + (t.due_back ? escapeHtml(poDateLong(t.due_back)) : '—') + '<div class="sp-row-sub">' + (tlOverdue(t) ? 'OVERDUE' : 'due back') + '</div></div></div></div>').join('')
        : '<div class="empty-state" style="padding:12px;">You\u2019re not holding any company tools.</div>';
      $('tlMineHandover').style.display = tl.tools.length ? '' : 'none';
      tlSetMineBadge(tlMinePend.length, tl.tools.filter(tlOverdue).length);
    }catch(e){ $('tlMinePending').innerHTML = '<div class="empty-state">' + (invMissingTables(e) ? 'Tools aren\u2019t set up yet.' : 'Couldn\u2019t load: ' + escapeHtml(describeCloudError(e))) + '</div>'; }
  }
  function tlSetMineBadge(pend, overdue){
    const b = document.getElementById('techQaMyToolsBadge'); if(!b) return;
    const txt = [pend ? pend + ' to sign' : '', overdue ? overdue + ' overdue' : ''].filter(Boolean).join(' · ');
    b.textContent = txt; b.style.display = txt ? '' : 'none';
  }
  async function tlRefreshMineBadge(){
    if(!currentUser || currentUser.role === 'admin' || currentUser.role === 'customer') return;
    try{
      const [t, s] = await Promise.all([db.from('tools_view').select('status, due_back').eq('holder_id', currentUser.id), db.from('tool_slips').select('type, to_worker_id, from_worker_id').eq('status', 'pending_signature')]);
      if(t.error) return;
      tlSetMineBadge((s.data || []).filter(x=> (x.type === 'issue' && x.to_worker_id === currentUser.id) || (x.type === 'return' && x.from_worker_id === currentUser.id)).length, (t.data || []).filter(tlOverdue).length);
    }catch(e){}
  }
  $('techQaMyTools').addEventListener('click', ()=> showPurchasingView('myTools'));
  $('tlMinePending').addEventListener('click', async (e)=>{
    const r = e.target.closest('.mt-row'); if(!r) return;
    try{
      const d = await tlLoadSlip(r.dataset.id);
      const ids = d.lines.map(l=> l.tool_id).filter(id=> !tlTool(id));
      if(ids.length){ const x = await db.from('tools_view').select('*').in('id', ids); (x.data || []).forEach(t=> tl.tools.push(t)); }
      tlMineOpen = d; tlRenderSlipInto(d, 'tlMine');
      $('tlMineList').style.display = 'none'; $('tlMineSlip').style.display = ''; window.scrollTo({ top:0 });
    }catch(err){ purchFail('Couldn\u2019t open the slip: ', err); }
  });
  $('tlMineBack').addEventListener('click', tlShowMine);
  $('tlMineSign').addEventListener('click', async ()=>{
    if(!tlMineOpen) return;
    const s = tlMineOpen.h;
    const blob = await tlSign('Your signature', s.type === 'issue' ? 'I received the tools listed on ' + s.slip_no : 'I returned the tools listed on ' + s.slip_no + ', in the condition noted');
    if(!blob) return;
    if(!(await purchEnsureSession())) return;
    try{
      const path = await tlUpload(blob, 'png');
      const { error } = await db.rpc('tl_sign_slip', { p_slip: s.id, p_path: path });
      if(error) throw error;
      toast(s.slip_no + ' signed — thank you'); tlShowMine();
    }catch(e){ purchFail('Couldn\u2019t sign: ', e); }
  });
  $('tlMineHandover').addEventListener('click', ()=>{
    tlMineHo = tl.tools.map(t=> ({ tool_id:t.id, inc:false }));
    $('tlMineHoTo').innerHTML = tlOpts(tl.workers.filter(w=> w.id !== currentUser.id), w=> w.id, w=> w.name, 'Choose a person…');
    tlRenderPick('tlMineHoLines', tlMineHo);
    $('tlMineList').style.display = 'none'; $('tlMineHo').style.display = '';
  });
  $('tlMineHoLines').addEventListener('change', (e)=>{ if(e.target.dataset.pick) tlMineHo[+e.target.closest('[data-i]').dataset.i].inc = e.target.checked; });
  $('tlMineHoBack').addEventListener('click', tlShowMine);
  $('tlMineHoPost').addEventListener('click', async ()=>{
    const btn = $('tlMineHoPost'); btn.disabled = true;
    try{ tl.workers.push({ id: currentUser.id, name: currentUser.name });
      const d = await tlDoHandover(currentUser.id, $('tlMineHoTo').value, tlMineHo.filter(l=> l.inc).map(l=> l.tool_id), ''); if(d) tlShowMine(); }
    catch(e){ purchFail('Couldn\u2019t hand over: ', e); }
    finally{ btn.disabled = false; }
  });

  // =====================================================================
  // TOOL REPORTS (same engine / PDF / Excel as Inventory Reports)
  // =====================================================================
  let trTab = 'monthly', trModel = null;
  async function tlShowReports(){
    if(!(await tlEnter(false))) return;
    if(!$('trFrom').value){ $('trFrom').value = tlToday().slice(0, 7); $('trTo').value = tlToday().slice(0, 7); }
    $('trWh').innerHTML = '<option value="">All warehouses</option>' + (tl.isAdmin ? tl.whs : tl.mine).map(w=> '<option value="' + escapeHtml(w.id) + '">' + escapeHtml(w.code) + '</option>').join('');
    trSetTab(trTab);
  }
  function trSetTab(t){
    trTab = t; trModel = null;
    $$('#trTabs [data-tr]').forEach(b=> b.classList.toggle('active', b.dataset.tr === t));
    $$('#purchPanel_tlReports [data-trf]').forEach(f=>{ f.style.display = f.dataset.trf.split(' ').includes(t) ? '' : 'none'; });
    $('trSummary').innerHTML = ''; $('trCheck').textContent = ''; $('trOut').innerHTML = '<div class="empty-state">Choose the options and tap <b>Run Report</b>.</div>';
  }
  $('trTabs').addEventListener('click', (e)=>{ const b = e.target.closest('[data-tr]'); if(b) trSetTab(b.dataset.tr); });
  $('trPdf').addEventListener('click', ()=> rpExportPdf(trModel, $('trFrom').value));
  $('trXlsx').addEventListener('click', ()=> rpExportXlsx(trModel, $('trFrom').value));
  $('trRun').addEventListener('click', async ()=>{
    const btn = $('trRun'); btn.disabled = true;
    try{ await tlLoad(); trModel = await ({ monthly: trMonthly, custody: trCustody, defects: trDefects, register: trRegister })[trTab](); rpRender(trModel, 'tr'); }
    catch(e){ $('trOut').innerHTML = '<div class="empty-state">Couldn\u2019t run the report: ' + escapeHtml(describeCloudError(e)) + '</div>'; }
    finally{ btn.disabled = false; }
  });
  function trRange(){
    const f = $('trFrom').value, t = $('trTo').value || f, [y, m] = t.split('-').map(Number);
    return { first: f + '-01', last: new Date(Date.UTC(y, m, 0)).toISOString().slice(0, 10), label: f === t ? RP_MONTH(f + '-01') : RP_MONTH(f + '-01') + ' – ' + RP_MONTH(t + '-01') };
  }
  const trLocal = (ts)=> new Date(new Date(ts).getTime() + 8 * 3600e3).toISOString().slice(0, 10);
  const trWhOk = (id)=> !$('trWh').value || id === $('trWh').value;
  async function trMonthly(){
    const r = trRange();
    const [sl, df] = await Promise.all([db.from('tool_slips').select('*, tool_slip_lines(*)').gte('created_at', r.first + 'T00:00:00+08:00').lte('created_at', r.last + 'T23:59:59+08:00'),
      db.from('tool_defects').select('*').gte('created_at', r.first + 'T00:00:00+08:00').lte('created_at', r.last + 'T23:59:59+08:00')]);
    const months = []; for(let d = new Date(r.first + 'T00:00:00Z'); d.toISOString().slice(0, 10) <= r.last; d.setUTCMonth(d.getUTCMonth() + 1)) months.push(d.toISOString().slice(0, 7));
    const money = tl.isAdmin;
    const rows = months.map(mo=>{
      const bought = tl.tools.filter(t=> t.purchase_date && t.purchase_date.slice(0, 7) === mo && trWhOk(t.home_warehouse_id));
      const inM = (s)=> trLocal(s.created_at).slice(0, 7) === mo && (s.type === 'handover' || trWhOk(s.warehouse_id));
      const lines = (ty)=> (sl.data || []).filter(s=> s.type === ty && inM(s)).reduce((a, s)=> a.concat(s.tool_slip_lines || []), []);
      const ret = lines('return');
      return [RP_MONTH(mo + '-01'), bought.length, lines('issue').length, ret.filter(l=> l.condition === 'good').length, ret.filter(l=> ['needs_repair', 'defective', 'missing_parts'].includes(l.condition)).length,
        ret.filter(l=> l.condition === 'lost').length, lines('handover').length, (df.data || []).filter(d=> trLocal(d.created_at).slice(0, 7) === mo).length]
        .concat(money ? [bought.reduce((a, t)=> a + Number(t.purchase_cost || 0), 0)] : []);
    });
    const sum = (i)=> rows.reduce((a, x)=> a + x[i], 0);
    return { title:'Tools & Equipment — Monthly Movements', subtitle: r.label + ' · ' + ($('trWh').value ? tlWh($('trWh').value) : 'All warehouses'),
      summary: [['Purchased', String(sum(1))], ['Issued', String(sum(2))], ['Returned good', String(sum(3))], ['Defective / lost', String(sum(4) + sum(5))]].concat(money ? [['Spent on tools', invMoney(sum(8))]] : []),
      sheets:[{ name:'Monthly', head:['Month', 'Purchased', 'Issued', 'Returned good', 'Returned defective', 'Lost', 'Handovers', 'Defect reports'].concat(money ? ['Purchase cost ₱'] : []), rows,
        numCols:[1, 2, 3, 4, 5, 6, 7], moneyCols: money ? [8] : null, totalRow: ['Total', sum(1), sum(2), sum(3), sum(4), sum(5), sum(6), sum(7)].concat(money ? [sum(8)] : []) }] };
  }
  async function trCustody(){
    const out = tl.tools.filter(t=> t.status === 'issued' && trWhOk(t.home_warehouse_id)).sort((a, b)=> String(a.holder_name).localeCompare(String(b.holder_name)) || String(a.due_back || '9').localeCompare(String(b.due_back || '9')));
    const days = (t)=> t.issued_at ? Math.round((Date.now() - new Date(t.issued_at).getTime()) / 864e5) : '';
    return { title:'Tools in Custody & Overdue', subtitle:'As of ' + poDateLong(tlToday()),
      summary:[['Tools out', String(out.length)], ['Workers', String(new Set(out.map(t=> t.holder_id)).size)], ['Overdue', String(out.filter(tlOverdue).length)]],
      sheets:[{ name:'Custody', head:['Worker', 'Tag', 'Tool', 'Serial', 'Job / project', 'Issued', 'Due back', 'Days out', 'Status'],
        rows: out.map(t=> [t.holder_name, t.asset_tag, t.name, t.serial_no, tlPrj(t.project_id, t.job_order_id), t.issued_at ? poDateLong(trLocal(t.issued_at)) : '', t.due_back ? poDateLong(t.due_back) : '—', days(t), tlOverdue(t) ? 'OVERDUE' : 'ok']),
        groupCol:0, numCols:[7], flagRow:(row)=> row[8] === 'OVERDUE' }] };
  }
  async function trDefects(){
    const r = trRange();
    const q = await db.from('tool_defects').select('*').gte('created_at', r.first + 'T00:00:00+08:00').lte('created_at', r.last + 'T23:59:59+08:00').order('created_at');
    const ds = (q.data || []).filter(d=>{ const t = tlTool(d.tool_id); return !t || trWhOk(t.home_warehouse_id); });
    const money = tl.isAdmin;
    const grp = (key)=>{ const m = new Map(); ds.forEach(d=>{ const k = key(d) || '—'; const e = m.get(k) || [k, 0, 0]; e[1]++; e[2] += Number(d.repair_cost || 0); m.set(k, e); }); return Array.from(m.values()).sort((a, b)=> b[1] - a[1]); };
    const model = (d)=>{ const t = tlTool(d.tool_id) || {}; return [t.name, t.brand, t.model].filter(Boolean).join(' '); };
    const cut = (rows)=> money ? rows : rows.map(x=> x.slice(0, 2));
    return { title:'Defective Tools Report', subtitle: r.label,
      summary:[['Defect reports', String(ds.length)], ['Still open', String(ds.filter(d=> d.status !== 'closed').length)], ['Under warranty', String(ds.filter(d=> d.under_warranty).length)]].concat(money ? [['Repair cost', invMoney(ds.reduce((a, d)=> a + Number(d.repair_cost || 0), 0))]] : []),
      sheets:[
        { name:'Defects', head:['Date', 'DEF no.', 'Tag', 'Tool', 'Condition', 'Worker', 'Cause', 'Decision', 'Status', 'Warranty'].concat(money ? ['Repair ₱'] : []),
          rows: ds.map(d=>{ const t = tlTool(d.tool_id) || {}; return [poDateLong(trLocal(d.created_at)), d.defect_no, t.asset_tag || '', t.name || '', TL_COND[d.condition] || d.condition, d.worker_name || '—', d.cause, d.decision.replace('_', ' '), d.status.replace('_', ' '), d.under_warranty ? 'yes' : ''].concat(money ? [d.repair_cost != null ? Number(d.repair_cost) : ''] : []); }),
          moneyCols: money ? [10] : null, landscape:true },
        { name:'By Tool Model', head:['Tool model', 'Defects'].concat(money ? ['Repair ₱'] : []), rows: cut(grp(model)), numCols:[1], moneyCols: money ? [2] : null },
        { name:'By Worker', head:['Worker', 'Defects'].concat(money ? ['Repair ₱'] : []), rows: cut(grp(d=> d.worker_name)), numCols:[1], moneyCols: money ? [2] : null },
        { name:'By Cause', head:['Cause', 'Defects'].concat(money ? ['Repair ₱'] : []), rows: cut(grp(d=> d.cause)), numCols:[1], moneyCols: money ? [2] : null }] };
  }
  async function trRegister(){
    const rows = tl.tools.filter(t=> trWhOk(t.home_warehouse_id)).sort((a, b)=> a.category.localeCompare(b.category) || a.asset_tag.localeCompare(b.asset_tag));
    const money = tl.isAdmin, val = (f)=> rows.filter(f).reduce((a, t)=> a + Number(t.purchase_cost || 0), 0);
    return { title:'Tool & Equipment Register', subtitle:'As of ' + poDateLong(tlToday()) + ' · ' + ($('trWh').value ? tlWh($('trWh').value) : 'All warehouses'),
      summary:[['Tools & kits', String(rows.length)], ['In service', String(rows.filter(t=> ['available', 'issued'].includes(t.status)).length)], ['Out of service', String(rows.filter(t=> ['defective', 'repair'].includes(t.status)).length)], ['Lost', String(rows.filter(t=> t.status === 'lost').length)]]
        .concat(money ? [['Value in service', invMoney(val(t=> ['available', 'issued'].includes(t.status)))], ['Value lost', invMoney(val(t=> t.status === 'lost'))]] : []),
      sheets:[{ name:'Register', head:['Category', 'Tag', 'Tool', 'Brand / model', 'Serial', 'Warehouse', 'Status', 'Holder', 'Next calibration', 'Purchased'].concat(money ? ['Cost ₱'] : []),
        rows: rows.map(t=> [t.category, t.asset_tag, t.name + (t.kind === 'kit' ? ' (kit)' : ''), [t.brand, t.model].filter(Boolean).join(' '), t.serial_no, tlWh(t.home_warehouse_id), TL_STATUS[t.status], t.holder_name,
          t.next_maint_due ? poDateLong(t.next_maint_due) + (tlMaintLate(t) ? ' (overdue)' : '') : '', t.purchase_date ? poDateLong(t.purchase_date) : ''].concat(money ? [t.purchase_cost != null ? Number(t.purchase_cost) : ''] : [])),
        groupCol:0, moneyCols: money ? [10] : null, flagRow:(row)=> ['Lost', 'Defective'].includes(row[6]) || String(row[8]).includes('overdue'), landscape:true }] };
  }

  // hub landing
  async function tlShowHub(){ await tlEnter(false); }


// ---------- Record Past Service (admin back-entry) ----------
  // Admin can't author a normal Service Report (it carries the technician's
  // name and signature — see setVis('srTabNewBtn', isTech) in auth.js). This
  // is the honest alternative: record work a technician already performed,
  // filed under that technician, with both signatures left blank and the
  // record stamped with who keyed it in (admin_record_past_service[s] RPC,
  // supabase/migrations/20260924_02 and _03). It shows in the report lists
  // and in each unit's equipment history like any report.
  //
  // Single / Multiple mirrors the technician's own wizard: the work
  // details are shared, and each unit gets its own report, SR number and
  // operation parameters (readings differ per unit).
  let beUnits = [];        // customer_equipment rows for the chosen customer
  let beCards = [];        // [{key}] one per unit being reported
  let beCardSeq = 0;
  let beMulti = false;
  let beLoaded = false;

  const BE_OP = [
    // [row label, [field, placeholder, phase3-only]...]
    ['Amperage',                    [['amp1','Amps'],['amp2','A\u2082',1],['amp3','A\u2083',1]]],
    ['Voltage',                     [['volt1','Volts'],['volt2','V\u2082',1],['volt3','V\u2083',1]]],
    ['Pressure (Suction/Discharge)',[['psuc','Suction'],['pdis','Discharge']]],
    ['Supply Air Temp (\u00b0C)',   [['temp','Supply air temp (\u00b0C)']]],
    ['Air Volume Flow Rate (cfm)',  [['air','Air volume flow (cfm)']]]
  ];

  function beLines(id){
    return String($(id).value || '').split(/\r?\n/).map(x=> x.trim()).filter(Boolean);
  }
  function beReset(){
    ['beTrouble','beServices','beFindings','beRecs','beParts','beRemarks','beCustRep','beTimeIn','beTimeOut'].forEach(id=> $(id).value = '');
    $('beDate').value = '';
    $('beConfirm').checked = false;
    beSetMode(false);
  }

  // ---- unit cards ----
  function beOpTableHtml(key){
    const cell = (side, fields)=> '<td><div class="opdata-cell-inputs">' + fields.map(([f, ph, p3])=>
      '<input type="text" inputmode="decimal" data-op="'+side+'_'+f+'" placeholder="'+ph+'"'+(p3 ? ' class="be-p3" style="display:none;"' : '')+'>').join('') + '</div></td>';
    return '<div class="opdata-table-wrap"><table class="opdata-table"><thead><tr><th></th><th>Before Servicing</th><th>After Servicing</th></tr></thead><tbody>' +
      BE_OP.map(([label, fields])=> '<tr><td class="opdata-row-label">'+label+'</td>'+cell('b', fields)+cell('a', fields)+'</tr>').join('') +
      '</tbody></table></div>';
  }
  function beUnitOptions(selected){
    const taken = beCards.map(c=> beCardEl(c.key)).filter(Boolean).map(el=> el.querySelector('[data-be="unit"]').value);
    return '<option value="">Select unit…</option>' + beUnits.map(u=>{
      const bits = [equipDisplayName(u), u.equipType, u.brand, u.coolCap].map(x=> String(x || '').trim()).filter(Boolean);
      const dis = u.id !== selected && taken.includes(u.id);
      return '<option value="'+escapeHtml(u.id)+'"'+(u.id === selected ? ' selected' : '')+(dis ? ' disabled' : '')+'>'+escapeHtml(bits.join(' · ') + (dis ? ' (already added)' : ''))+'</option>';
    }).join('');
  }
  function beCardEl(key){ return $('beUnitList').querySelector('[data-card="'+key+'"]'); }
  function beRefreshUnitSelects(){
    beCards.forEach((c, i)=>{
      const el = beCardEl(c.key); if(!el) return;
      const sel = el.querySelector('[data-be="unit"]');
      const v = sel.value;
      sel.innerHTML = beUnits.length ? beUnitOptions(v) : '<option value="">'+($('beCustomer').value ? 'No units on file' : 'Choose a customer first…')+'</option>';
      sel.disabled = !beUnits.length;
      el.querySelector('.be-unit-head b').textContent = beMulti ? 'Unit ' + (i + 1) : 'Unit';
      el.querySelector('.be-unit-remove').style.display = (beMulti && beCards.length > 1) ? '' : 'none';
      el.querySelector('.be-copy').style.display = (beMulti && i > 0) ? '' : 'none';
    });
    $('beAddUnitBtn').style.display = beMulti ? '' : 'none';
    $('beAddUnitBtn').disabled = !beUnits.length || beCards.length >= beUnits.length;
    $('beWorkSub').textContent = beMulti ? 'shared by every unit' : '';
    $('beSaveBtn').textContent = beMulti ? 'Save ' + beCards.length + ' Past Service Report' + (beCards.length === 1 ? '' : 's') : 'Save Past Service Report';
  }
  function beAddCard(){
    const key = ++beCardSeq;
    beCards.push({ key });
    const el = document.createElement('div');
    el.className = 'be-unit'; el.dataset.card = key;
    el.innerHTML =
      '<div class="be-unit-head"><b>Unit</b><button type="button" class="be-unit-remove">Remove</button></div>' +
      '<div class="field"><label>Unit serviced <span class="req">*</span></label><select data-be="unit"></select></div>' +
      '<label class="sr-phase-toggle"><input type="checkbox" data-be="p3"><span>This unit is 3-phase (L1/L2/L3)</span></label>' +
      beOpTableHtml(key) +
      '<button type="button" class="be-copy">Copy readings from the unit above</button>';
    $('beUnitList').appendChild(el);
    el.querySelector('[data-be="unit"]').addEventListener('change', beRefreshUnitSelects);
    el.querySelector('[data-be="p3"]').addEventListener('change', (e)=> beApplyPhase(el, e.target.checked));
    el.querySelector('.be-unit-remove').addEventListener('click', ()=>{
      beCards = beCards.filter(c=> c.key !== key); el.remove(); beRefreshUnitSelects();
    });
    el.querySelector('.be-copy').addEventListener('click', ()=>{
      const idx = beCards.findIndex(c=> c.key === key);
      const prev = idx > 0 ? beCardEl(beCards[idx - 1].key) : null;
      if(!prev) return;
      const p3 = prev.querySelector('[data-be="p3"]').checked;
      el.querySelector('[data-be="p3"]').checked = p3; beApplyPhase(el, p3);
      prev.querySelectorAll('[data-op]').forEach(inp=>{ el.querySelector('[data-op="'+inp.dataset.op+'"]').value = inp.value; });
      toast('Readings copied — adjust what differs');
    });
    beRefreshUnitSelects();
  }
  function beApplyPhase(el, on){
    el.querySelectorAll('.be-p3').forEach(inp=>{ inp.style.display = on ? '' : 'none'; if(!on) inp.value = ''; });
  }
  function beSetMode(multi){
    beMulti = !!multi;
    $('beModeSingle').classList.toggle('active', !beMulti);
    $('beModeMulti').classList.toggle('active', beMulti);
    if(!beMulti){
      // back to one card: keep the first, drop the rest
      beCards.slice(1).forEach(c=>{ const el = beCardEl(c.key); if(el) el.remove(); });
      beCards = beCards.slice(0, 1);
    }
    if(!beCards.length) beAddCard();
    else if(beMulti && beCards.length < 2 && beUnits.length > 1) beAddCard();
    beRefreshUnitSelects();
  }
  $('beModeSingle').addEventListener('click', ()=> beSetMode(false));
  $('beModeMulti').addEventListener('click', ()=> beSetMode(true));
  $('beAddUnitBtn').addEventListener('click', ()=> beAddCard());

  // Same shape the normal report stores (before_data / after_data).
  function beReadOp(el, side){
    const v = f=>{ const i = el.querySelector('[data-op="'+side+'_'+f+'"]'); return i ? i.value.trim() : ''; };
    return { amp:[v('amp1'), v('amp2'), v('amp3')], volt:[v('volt1'), v('volt2'), v('volt3')],
             pressure:[v('psuc'), v('pdis')], temp:v('temp'), airflow:v('air') };
  }

  // ---- pickers ----
  async function beLoadPickers(){
    $('beDate').max = todayISO();
    const catSel = $('beCategory');
    if(!catSel.options.length){
      catSel.innerHTML = SERVICE_CATEGORIES.map(c=> '<option value="'+c.key+'">'+escapeHtml(c.label)+'</option>').join('');
      catSel.value = DEFAULT_REPORT_CATEGORY;
    }
    const techs = (await cloudListUsers() || []).filter(u=> u.active !== false)
      .sort((a, b)=> String(a.name || '').localeCompare(String(b.name || '')));
    const keepTech = $('beTech').value;
    $('beTech').innerHTML = '<option value="">Select technician…</option>' +
      techs.map(t=> '<option value="'+escapeHtml(t.id)+'">'+escapeHtml(t.name || t.username || 'Technician')+'</option>').join('');
    if(keepTech) $('beTech').value = keepTech;
    await loadCustomers();
    const keepCust = $('beCustomer').value;
    $('beCustomer').innerHTML = '<option value="">Select customer…</option>' +
      (customersCache || []).map(c=> '<option value="'+escapeHtml(c.id)+'">'+escapeHtml(c.name)+'</option>').join('');
    if(keepCust) $('beCustomer').value = keepCust;
    beLoaded = true;
  }
  async function beLoadUnits(){
    const custId = $('beCustomer').value;
    beUnits = [];
    $('beUnitHint').textContent = '';
    // a new customer means none of the old unit picks are valid
    beCards.forEach(c=>{ const el = beCardEl(c.key); if(el) el.querySelector('[data-be="unit"]').value = ''; });
    if(custId){
      try{
        const { data, error } = await db.from('customer_equipment').select('*').eq('customer_id', custId);
        if(error) throw error;
        beUnits = (data || []).map(equipRowToObj);
      }catch(e){ console.error('load units failed', describeCloudError(e)); toast('Could not load this customer\u2019s units'); }
      if(!beUnits.length) $('beUnitHint').textContent = 'This customer has no units on file. Add the unit under Equipment first, then come back to record the visit.';
    }
    beRefreshUnitSelects();
  }
  async function beOpen(){
    if(!beLoaded) beReset();
    try{ await beLoadPickers(); }
    catch(e){ console.error('record past service: load failed', e); toast('Could not load technicians/customers'); }
    beRefreshUnitSelects();
  }
  $('beCustomer').addEventListener('change', beLoadUnits);

  // ---- save ----
  $('beSaveBtn').addEventListener('click', async ()=>{
    const techId = $('beTech').value, custId = $('beCustomer').value;
    const date = $('beDate').value, services = beLines('beServices');
    if(!techId) return toast('Choose the technician who did the work');
    if(!custId) return toast('Choose the customer');
    const cards = beCards.map(c=> beCardEl(c.key)).filter(Boolean);
    const unitIds = cards.map(el=> el.querySelector('[data-be="unit"]').value);
    const missing = unitIds.findIndex(v=> !v);
    if(missing >= 0) return toast(beMulti ? 'Choose the unit for Unit ' + (missing + 1) : 'Choose the unit that was serviced');
    if(new Set(unitIds).size !== unitIds.length) return toast('The same unit was added twice');
    if(!date) return toast('Enter the date the work was performed');
    if(date > todayISO()) return toast('The date can\u2019t be in the future');
    if(!services.length) return toast('List the work that was done');
    if(!$('beConfirm').checked) return toast('Tick the confirmation box first');

    const cust = (customersCache || []).find(c=> c.id === custId) || {};
    const shared = {
      technician_id: techId, date,
      service_category: $('beCategory').value || DEFAULT_REPORT_CATEGORY,
      customer_id: custId, cust_name: cust.name || '', cust_address: cust.address || '',
      contact_no: cust.contactNo || '', contact_person: cust.contactPerson || '', cust_email: cust.email || '',
      trouble_call: $('beTrouble').value.trim(),
      time_in: $('beTimeIn').value, time_out: $('beTimeOut').value,
      services_done: services, findings: beLines('beFindings'), recommendations: beLines('beRecs'),
      materials: beLines('beParts').map(t=> ({ description: t, qty: '', unit: '' })),
      remarks: $('beRemarks').value.trim(),
      customer_printed_name: $('beCustRep').value.trim(),
      is_install: false
    };
    const reports = cards.map((el, i)=>{
      const u = beUnits.find(x=> x.id === unitIds[i]) || {};
      return Object.assign({}, shared, {
        equipment_id: u.id,
        equip_type: u.equipType || '', equip_location: u.equipLocation || '', brand: u.brand || '',
        mount_type: u.mountType || '', cool_cap: u.coolCap || '', model_cu: u.modelCU || '', serial_cu: u.serialCU || '',
        model_fcu: u.modelFCU || '', serial_fcu: u.serialFCU || '', refrigerant_type: u.refrigerantType || '',
        compressor_type: u.compressorType || '',
        before_data: beReadOp(el, 'b'), after_data: beReadOp(el, 'a')
      });
    });

    const btn = $('beSaveBtn');
    const label = btn.textContent;
    btn.disabled = true; btn.textContent = 'Saving…';
    try{
      if(!(await ensureCloud())) throw new Error('offline');
      // One transaction for every unit: all saved, or none.
      const { data: srNos, error } = await db.rpc('admin_record_past_services', { p_reports: reports });
      if(error) throw error;
      toast(srNos.length === 1 ? 'Saved as ' + srNos[0] : srNos.length + ' reports saved (' + srNos[0] + ' – ' + srNos[srNos.length - 1] + ')');
      // Clear the form, keep technician/customer (often recording several visits in a row).
      ['beTrouble','beServices','beFindings','beRecs','beParts','beRemarks','beCustRep','beTimeIn','beTimeOut','beDate'].forEach(id=> $(id).value = '');
      $('beConfirm').checked = false;
      $('beUnitList').innerHTML = ''; beCards = [];
      beSetMode(beMulti);
      // Show what was filed, in the PDF viewer (Download / Share there).
      const rows = (await Promise.all(srNos.map(sr=> cloudGetReport(sr)))).filter(Boolean);
      if(rows.length === 1){
        await openFileInPdfViewer(await buildPdf(rows[0]), rows[0].srNo + '.pdf', rows[0].custName || rows[0].srNo);
      }else if(rows.length > 1){
        const docs = [];
        for(const d of rows) docs.push({ doc: await buildPdf(d), label: d.srNo + ' · ' + (d.equipLocation || d.equipType || ''), filename: d.srNo + '.pdf' });
        $('previewOverlay').querySelector('h3').textContent = (rows[0].custName || 'Reports') + ' — ' + rows.length + ' units';
        $('previewOkBtn').textContent = 'Close';
        $('previewOverlay').style.zIndex = '99';
        $('previewOverlay').classList.add('open');
        setPreviewZoom(1);
        await renderPdfPreviewMulti(docs);
      }
    }catch(e){
      console.error('record past service failed', describeCloudError(e));
      const msg = (e && e.message) || '';
      toast(msg === 'offline' ? 'You\u2019re offline — this needs a connection to save'
        : /future|Choose|unit|date|twice|at most/i.test(msg) ? msg : 'Could not save — ' + (msg || 'please try again'));
    }finally{
      btn.disabled = false;
      if(btn.textContent === 'Saving…') btn.textContent = label;
      beRefreshUnitSelects();
    }
  });


// ---------- Admin homepage: "Needs you now" + "Technicians today" ----------
  // One ranked list of what's waiting on admin, instead of equal-weight
  // counters. Tiers: urgent (red) → today (amber) → watch (grey); within a
  // tier, oldest first. Built from the same data renderHomeOverview()
  // already fetched, plus a few small reads of its own (service requests,
  // material requisitions, POs, PM dates, reorder). The server-side twin is
  // supabase/functions/admin-alerts (urgent push + 7:00 AM digest) — keep
  // the "late" rule in step with dtIsLateDispatch() in dispatch.js.
  //
  // Quick approve: only where the whole decision fits on one line —
  // leave requests, and material requisitions approved exactly as
  // requested. Cash advance, liquidation, JO review and report sign-off
  // always open the full screen.
  const PRIO_TODAY_SHOWN = 6;
  let prioExpanded = false;
  let prioLastItems = [];

  function prioAge(ms){
    if(!(ms > 0)) return '';
    const m = Math.round(ms / 60000);
    if(m < 60) return m + 'm';
    const h = Math.round(m / 60);
    if(h < 24) return h + 'h';
    const d = Math.round(h / 24);
    return d + (d === 1 ? ' day' : ' days');
  }
  function prioSince(iso){ const t = iso ? new Date(iso).getTime() : NaN; return isFinite(t) ? Date.now() - t : 0; }
  function prioFmtTime(hhmm){
    if(!hhmm) return '';
    const [h, m] = hhmm.split(':').map(Number);
    return ((h % 12) || 12) + ':' + String(m).padStart(2, '0') + (h < 12 ? ' AM' : ' PM');
  }
  function prioDateRange(a, b){ return leaveFmtDate(a) + (b && b !== a ? ' – ' + leaveFmtDate(b) : ''); }
  function prioOverlaps(a1, a2, b1, b2){ return a1 <= (b2 || b1) && b1 <= (a2 || a1); }

  async function prioSafe(fn, fallback){ try{ return await fn(); }catch(e){ console.warn('priority: partial data', e); return fallback; } }

  // ---- extra reads (each best-effort; a failure just drops that row type) ----
  async function prioLoadExtras(){
    if(!(await ensureCloud())) return {};
    const today = todayISO();
    const in7 = new Date(new Date(today + 'T00:00:00+08:00').getTime() + 7 * 86400000).toISOString().slice(0, 10);
    const twoDaysAgo = new Date(Date.now() - 2 * 86400000).toISOString();
    const [srNew, mrs, pos, pms, reorder] = await Promise.all([
      prioSafe(async ()=>{ const { data, error } = await db.from('service_requests').select('id, created_at, description, urgency, customer_id').eq('status', 'new').order('created_at'); if(error) throw error; return data || []; }, []),
      prioSafe(async ()=>{ const { data, error } = await db.from('material_requisitions').select('id, mrf_no, requester_name, requested_by, submitted_at, created_at').eq('status', 'submitted').order('submitted_at'); if(error) throw error; return data || []; }, []),
      prioSafe(async ()=>{ const { data, error } = await db.from('purchase_orders').select('id, po_no, updated_at').eq('status', 'draft').lt('updated_at', twoDaysAgo).order('updated_at'); if(error) throw error; return data || []; }, []),
      prioSafe(async ()=>{ const { data, error } = await db.from('customer_equipment').select('id').gte('next_pm_date', today).lte('next_pm_date', in7); if(error) throw error; return data || []; }, []),
      prioSafe(async ()=>{ const { data, error } = await db.rpc('inv_rpt_reorder', { p_days: 90 }); if(error) throw error; return (data || []).filter(r=> r.reorder); }, [])
    ]);
    // First few lines of each requisition, for the one-line summary.
    let mrItems = {};
    if(mrs.length){
      await prioSafe(async ()=>{
        const { data, error } = await db.from('material_requisition_items').select('mr_id, description, qty_requested, unit').in('mr_id', mrs.map(m=> m.id));
        if(error) throw error;
        (data || []).forEach(it=>{ (mrItems[it.mr_id] = mrItems[it.mr_id] || []).push(it); });
      }, null);
    }
    const custNames = {};
    (customersCache || []).forEach(c=>{ custNames[c.id] = c.name; });
    return { srNew, mrs, mrItems, pos, pms, reorder, custNames };
  }

  // ---- build the ranked list ----
  function prioBuild(base, extra){
    const items = [];
    const today = todayISO();
    const tickets = base.tickets || [];
    const add = (tier, o)=> items.push(Object.assign({ tier, age: 0, actions: [] }, o));
    const openTicket = id=> ()=> dtOpenTicketOverlay(id);

    // URGENT — late job orders (dispatch time passed, nobody en route)
    tickets.filter(t=> t.date === today && dtIsLateDispatch(t) && dtEffectiveStatus(t) !== 'expired').forEach(t=>{
      const lateBy = Date.now() - dtDispatchMs(t);
      add('urgent', {
        key: 'late:' + t.id, age: lateBy,
        title: (t.jobOrderNo || t.id) + ' is ' + prioAge(lateBy) + ' late — not en route',
        sub: (t.custName || 'Customer') + ' · Dispatch ' + prioFmtTime(t.dispatchTime) + ' · ' + ((t.assignedWorkerNames || []).join(', ') || 'no crew'),
        actions: [{ label: 'Open job order', primary: true, run: openTicket(t.id) }]
      });
    });
    // URGENT — expired today (window passed, nobody acknowledged)
    tickets.filter(t=> t.date === today && dtEffectiveStatus(t) === 'expired').forEach(t=>{
      add('urgent', {
        key: 'exp:' + t.id, age: 1,
        title: (t.jobOrderNo || t.id) + ' expired — no one acknowledged',
        sub: (t.custName || 'Customer') + ' · raise a new job order if the visit is still needed',
        actions: [{ label: 'Open', primary: false, run: openTicket(t.id) }]
      });
    });
    // URGENT — customer service requests nobody has acknowledged for 60+ min
    (extra.srNew || []).forEach(r=>{
      const age = prioSince(r.created_at);
      if(age < 60 * 60000) return;
      add('urgent', {
        key: 'sr:' + r.id, age,
        title: 'Service request unanswered for ' + prioAge(age) + (r.urgency === 'urgent' ? ' (marked urgent)' : ''),
        sub: (extra.custNames[r.customer_id] || 'Customer') + ' · ' + String(r.description || '').slice(0, 80),
        actions: [{ label: 'Open requests', primary: true, run: ()=> showServiceRequestsView() }]
      });
    });

    // TODAY — leave (quick approve)
    (base.leaves || []).filter(r=> r.status === 'pending').forEach(r=>{
      const others = (base.leaves || []).filter(o=> o.status === 'approved' && o.userId !== r.userId && prioOverlaps(r.dateFrom, r.dateTo, o.dateFrom, o.dateTo));
      const jos = tickets.filter(t=> !dtIsTerminal(t) && (t.assignedWorkerIds || []).includes(r.userId) && t.date >= r.dateFrom && t.date <= (r.dateTo || r.dateFrom));
      const conflict = [others.length ? others.map(o=> o.userName).join(', ') + ' also off' : 'No one else off',
                        jos.length ? jos.length + ' job order' + (jos.length === 1 ? '' : 's') + ' assigned those days' : ''].filter(Boolean).join(' · ');
      add('today', {
        key: 'leave:' + r.id, age: prioSince(r.submittedAt), kind: 'leave', rec: r, others, jos,
        title: 'Leave — ' + (r.userName || 'Technician') + ', ' + prioDateRange(r.dateFrom, r.dateTo) + ' (' + (r.leaveType || 'Leave') + ')',
        sub: conflict + ' · waiting ' + prioAge(prioSince(r.submittedAt)),
        actions: [{ label: 'Open', run: ()=> showLeaveView() }, { label: 'Quick approve', primary: true, run: ()=> prioQuickApprove('leave:' + r.id) }]
      });
    });
    // TODAY — material requisitions (quick approve = exactly as requested)
    (extra.mrs || []).forEach(m=>{
      const lines = (extra.mrItems[m.id] || []);
      const summary = lines.slice(0, 2).map(it=> it.description + ' ×' + mrQty(it.qty_requested) + (it.unit ? ' ' + it.unit : '')).join(', ') + (lines.length > 2 ? ' …' : '');
      const age = prioSince(m.submitted_at || m.created_at);
      add('today', {
        key: 'mr:' + m.id, age, kind: 'mr', rec: m, lines,
        title: 'Material requisition ' + m.mrf_no + ' — ' + lines.length + ' item' + (lines.length === 1 ? '' : 's'),
        sub: (m.requester_name || 'Technician') + (summary ? ' · ' + summary : '') + ' · waiting ' + prioAge(age),
        actions: [{ label: 'Open', run: async ()=>{ showPurchasingView('requisitions'); await mrOpen(m.id); } },
                  { label: 'Quick approve', primary: true, run: ()=> prioQuickApprove('mr:' + m.id) }]
      });
    });
    // Opens Cash Advance admin on the right section + filter tab.
    const openCa = (reimb, filter)=> async ()=>{
      setSidebarActive(reimb ? 'sbNavReimbursement' : 'sbNavCashAdvance');
      await showCashAdvanceView();
      caShowAdminSection(reimb ? 'reimb' : 'requests');
      const btn = document.querySelector('#' + (reimb ? 'caReimbAdminFilterRow' : 'caAdminFilterRow') + ' button[data-filter="' + filter + '"]');
      if(btn) btn.click();
    };
    // TODAY — cash advance / reimbursement requests (full review only).
    // Reimbursements share the same table and 'pending' status, so they are
    // labelled and routed to their own section instead of passing as a cash
    // advance.
    (base.cashAdvances || []).filter(r=> r.status === 'pending').forEach(r=>{
      const reimb = r.kind === 'reimbursement';
      add('today', {
        key: 'ca:' + r.id, age: prioSince(r.submittedAt),
        title: (reimb ? 'Reimbursement ' : 'Cash advance ') + caFmtPeso(Number(r.amount) || 0) + ' — ' + (r.userName || 'Technician'),
        sub: (r.purpose ? String(r.purpose).slice(0, 70) + ' · ' : '') + 'waiting ' + prioAge(prioSince(r.submittedAt)),
        actions: [{ label: 'Review', run: openCa(reimb, 'pending') }]
      });
    });
    // Approved but the money has not been handed over yet (not "Given" /
    // not "Paid"). Approval alone doesn't put cash in the technician's
    // hand, so this stays on admin's list until Record Disbursement /
    // Record Payment is done. A cash advance whose date needed is today or
    // already past goes to URGENT — the technician needs it for the job.
    (base.cashAdvances || []).filter(r=> r.status === 'approved' && !r.disbursed).forEach(r=>{
      const reimb = r.kind === 'reimbursement';
      const needed = r.dateNeeded || '';
      const due = !reimb && needed && needed <= today;
      const age = prioSince(r.decidedAt || r.submittedAt);
      const neededTxt = reimb || !needed ? '' :
        (needed === today ? 'Needed today' : needed < today ? 'Needed ' + leaveFmtDate(needed) + ' (past due)' : 'Needed ' + leaveFmtDate(needed));
      add(due ? 'urgent' : 'today', {
        key: 'rel:' + r.id, age,
        title: reimb
          ? 'Reimbursement to pay — ' + caFmtPeso(Number(r.amount) || 0) + ' to ' + (r.userName || 'Technician')
          : 'Cash advance to release — ' + caFmtPeso(Number(r.amount) || 0) + ' to ' + (r.userName || 'Technician'),
        sub: [neededTxt, r.purpose ? String(r.purpose).slice(0, 60) : '', (age ? 'approved ' + prioAge(age) + ' ago, ' : 'approved, ') + 'not yet ' + (reimb ? 'paid' : 'given')].filter(Boolean).join(' · '),
        actions: [{ label: reimb ? 'Record payment' : 'Record release', primary: true, run: openCa(reimb, 'approved') }]
      });
    });
    // TODAY — liquidation (full review only)
    (base.cashAdvances || []).filter(r=> r.liquidation && r.liquidation.status === 'pending').forEach(r=>{
      const at = r.liquidation.submittedAt || r.submittedAt;
      add('today', {
        key: 'liq:' + r.id, age: prioSince(at),
        title: 'Liquidation to check — ' + (r.userName || 'Technician'),
        sub: 'Receipts for ' + caFmtPeso(Number(r.amountGiven || r.amount) || 0) + ' · waiting ' + prioAge(prioSince(at)),
        actions: [{ label: 'Review', run: async ()=>{ setSidebarActive('sbNavLiquidation'); await showCashAdvanceView(); caShowTab('liquidate'); } }]
      });
    });
    // TODAY — grouped: JO review, reports to sign off, balances to settle
    const toReview = tickets.filter(t=> t.status === 'completed');
    if(toReview.length){
      const oldest = Math.max(...toReview.map(t=> prioSince(t.completedAt)));
      add('today', {
        key: 'jorev', age: oldest,
        title: toReview.length + ' job order' + (toReview.length === 1 ? '' : 's') + ' to review and close',
        sub: 'Oldest ' + (toReview[0].jobOrderNo || '') + (oldest ? ' · ' + prioAge(oldest) : ''),
        actions: [{ label: 'Review', run: async ()=>{ await showDispatchView('all'); dtSetAdminFilter('completed'); } }]
      });
    }
    const drafts = (base.reports || []).filter(r=> !r.completed);
    if(drafts.length){
      add('today', {
        key: 'srsign', age: 1,
        title: drafts.length + ' service report' + (drafts.length === 1 ? '' : 's') + ' pending sign-off',
        sub: 'Oldest ' + (drafts.map(r=> r.srNo).filter(Boolean).sort()[0] || ''),
        actions: [{ label: 'Review', run: ()=>{ showServiceReport(); srShowTab('draft'); } }]
      });
    }
    const unsettled = (base.cashAdvances || []).filter(r=> r.liquidation && r.liquidation.status === 'approved' && r.liquidation.settlement && !r.liquidation.settlement.settled);
    if(unsettled.length){
      add('today', {
        key: 'settle', age: 1,
        title: unsettled.length + ' balance' + (unsettled.length === 1 ? '' : 's') + ' to settle',
        sub: 'Approved liquidations with money to collect or reimburse',
        actions: [{ label: 'Open', run: async ()=>{ setSidebarActive('sbNavReimbursement'); await showCashAdvanceView(); caShowAdminSection('reimb'); } }]
      });
    }

    // WATCH — chips
    if((extra.reorder || []).length) add('watch', { key: 'reorder', title: extra.reorder.length + ' item' + (extra.reorder.length === 1 ? '' : 's') + ' below reorder level', actions: [{ label: 'Reorder report', run: ()=> showPurchasingView('invReports') }] });
    if((extra.pms || []).length) add('watch', { key: 'pm', title: extra.pms.length + ' PM' + (extra.pms.length === 1 ? '' : 's') + ' due this week', actions: [{ label: 'Calendar', run: ()=> showDispatchView('calendar') }] });
    (extra.pos || []).slice(0, 3).forEach(p=> add('watch', { key: 'po:' + p.id, title: (p.po_no || 'PO') + ' still a draft (' + prioAge(prioSince(p.updated_at)) + ')', actions: [{ label: 'Open', run: ()=> showPurchasingView('purchaseOrders') }] }));
    const noDispatch = tickets.filter(t=> t.date === today && !t.dispatchTime && !dtIsTerminal(t));
    if(noDispatch.length) add('watch', { key: 'nodisp', title: noDispatch.length + ' JO' + (noDispatch.length === 1 ? '' : 's') + ' today without a dispatch time', actions: [{ label: 'Dispatch', run: ()=> showDispatchView('all') }] });

    const rank = { urgent: 0, today: 1, watch: 2 };
    items.sort((a, b)=> rank[a.tier] - rank[b.tier] || b.age - a.age);
    return items;
  }

  // ---- technicians today ----
  function prioTechStatus(base){
    const today = todayISO();
    const users = (base.users || []).filter(u=> u.active !== false).sort((a, b)=> String(a.name).localeCompare(String(b.name)));
    const dtr = {}; (base.dtrToday || []).forEach(d=>{ if(d) dtr[d.technicianId] = d; });
    const tickets = (base.tickets || []).filter(t=> t.date === today || t.status === 'in_progress' || t.status === 'acknowledged');
    const onLeave = new Set((base.leaves || []).filter(l=> l.status === 'approved' && today >= l.dateFrom && today <= (l.dateTo || l.dateFrom)).map(l=> l.userId));
    const rank = { late:0, onsite:1, enroute:2, idle:3, next:4, notin:5, done:6, out:7, off:8 };
    return users.map(u=>{
      const mine = tickets.filter(t=> (t.assignedWorkerIds || []).includes(u.id));
      const live = mine.filter(t=> !dtIsTerminal(t) || t.status === 'in_progress');
      const d = dtr[u.id];
      let key, label, sub;
      const late = live.find(t=> dtIsLateDispatch(t));
      const onsite = live.find(t=> t.status === 'in_progress');
      const enroute = live.find(t=> t.status === 'acknowledged');
      if(onLeave.has(u.id)){ key = 'off'; label = 'Off'; sub = 'On leave'; }
      else if(late){ key = 'late'; label = 'Late'; sub = (late.jobOrderNo || '') + ' · dispatch ' + prioFmtTime(late.dispatchTime); }
      else if(onsite){ key = 'onsite'; label = 'On site'; sub = (onsite.jobOrderNo || '') + ' · ' + (onsite.custName || ''); }
      else if(enroute){ key = 'enroute'; label = 'En route'; sub = (enroute.jobOrderNo || '') + ' · ' + (enroute.custName || ''); }
      else if(live.length){ const n = live.slice().sort((a, b)=> String(a.dispatchTime || '').localeCompare(String(b.dispatchTime || '')))[0];
        key = 'next'; label = 'Next'; sub = (n.jobOrderNo || '') + (n.dispatchTime ? ' · dispatch ' + prioFmtTime(n.dispatchTime) : ''); }
      else if(mine.length){ key = 'done'; label = 'Done'; sub = mine.length + ' job' + (mine.length === 1 ? '' : 's') + ' today'; }
      else if(d && d.otTimeIn && !d.otTimeOut){ key = 'idle'; label = 'Overtime'; sub = 'OT since ' + prioFmtTime(d.otTimeIn) + ' · no job order'; }
      else if(d && d.timeIn && !d.timeOut){ key = 'idle'; label = 'Idle'; sub = 'Timed in ' + prioFmtTime(d.timeIn) + ' · no job order'; }
      else if(d && d.timeOut){ key = 'out'; label = 'Timed out'; sub = 'In ' + prioFmtTime(d.timeIn) + ' · out ' + prioFmtTime(d.otTimeOut || d.timeOut); }
      else { key = 'notin'; label = 'Not timed in'; sub = 'No job order today'; }
      return { id: u.id, name: u.name || u.username || 'Technician', key, label, sub, r: rank[key] };
    }).sort((a, b)=> a.r - b.r || a.name.localeCompare(b.name));
  }

  // ---- render ----
  function prioItemHtml(it, idx){
    return '<div class="prio-item prio-' + it.tier + '">' +
      '<span class="prio-dot" aria-hidden="true"></span>' +
      '<div class="prio-text"><div class="prio-title">' + escapeHtml(it.title) + '</div>' +
        (it.sub ? '<div class="prio-sub">' + escapeHtml(it.sub) + '</div>' : '') + '</div>' +
      '<div class="prio-actions">' + it.actions.map((a, j)=>
        '<button type="button" class="prio-btn' + (a.primary ? ' primary' : '') + '" data-prio="' + idx + ':' + j + '">' + escapeHtml(a.label) + '</button>').join('') +
      '</div></div>';
  }
  function prioRenderList(){
    const items = prioLastItems;
    const urgent = items.filter(i=> i.tier === 'urgent'), today = items.filter(i=> i.tier === 'today'), watch = items.filter(i=> i.tier === 'watch');
    $('prioCountUrgent').textContent = urgent.length + ' urgent';
    $('prioCountToday').textContent = today.length + ' for today';
    $('prioCountWatch').textContent = watch.length + ' to watch';
    $('prioCountUrgent').classList.toggle('zero', !urgent.length);
    $('prioCountToday').classList.toggle('zero', !today.length);
    $('prioCountWatch').classList.toggle('zero', !watch.length);
    if(!items.length){
      $('prioList').innerHTML = '<div class="prio-clear"><b>All clear ✓</b><span>Nothing is waiting on you right now.</span></div>';
      return;
    }
    const idx = it=> items.indexOf(it);
    let html = '';
    if(urgent.length) html += '<div class="prio-tier prio-tier-urgent">Urgent</div>' + urgent.map(it=> prioItemHtml(it, idx(it))).join('');
    if(today.length){
      const shown = prioExpanded ? today : today.slice(0, PRIO_TODAY_SHOWN);
      html += '<div class="prio-tier prio-tier-today">For today</div>' + shown.map(it=> prioItemHtml(it, idx(it))).join('');
      if(today.length > shown.length) html += '<button type="button" class="prio-more" id="prioMoreBtn">+ ' + (today.length - shown.length) + ' more for today</button>';
    }
    if(watch.length) html += '<div class="prio-tier prio-tier-watch">Watch</div><div class="prio-watch">' + watch.map(it=>
      '<button type="button" class="prio-chip" data-prio="' + idx(it) + ':0">' + escapeHtml(it.title) + '</button>').join('') + '</div>';
    $('prioList').innerHTML = html;
  }
  function prioRenderTechs(rows){
    const n = k=> rows.filter(r=> k.includes(r.key)).length;
    const bits = [n(['onsite','enroute']) + ' on a job', n(['late']) ? n(['late']) + ' late' : '', n(['idle']) ? n(['idle']) + ' free' : '', n(['out']) ? n(['out']) + ' timed out' : '', n(['off']) ? n(['off']) + ' off' : ''].filter(Boolean);
    $('prioTechSub').textContent = bits.join(' · ');
    $('prioTechList').innerHTML = rows.length ? rows.map(r=>
      '<div class="prio-tech"><b>' + escapeHtml(r.name) + '</b><span class="prio-tech-sub">' + escapeHtml(r.sub) + '</span>' +
      '<span class="prio-pill prio-pill-' + r.key + '">' + escapeHtml(r.label) + '</span></div>').join('')
      : '<div class="empty-state">No active technicians.</div>';
  }
  // App-icon badge (installed PWA): urgent + today. Also refreshed by the
  // push handler in sw.js whenever an alert arrives with the app closed.
  function prioSetBadge(n){
    try{
      if(n > 0 && navigator.setAppBadge) navigator.setAppBadge(n);
      else if(navigator.clearAppBadge) navigator.clearAppBadge();
    }catch(e){ /* unsupported — ignore */ }
  }

  async function prioRender(base){
    if(!currentUser || currentUser.role !== 'admin'){ $('prioCard').style.display = 'none'; $('prioTechCard').style.display = 'none'; return; }
    $('prioCard').style.display = ''; $('prioTechCard').style.display = '';
    prioStartLive();
    try{
      const extra = await prioLoadExtras();
      prioLastItems = prioBuild(base, Object.assign({ custNames: {} }, extra));
      prioLastBase = base;
      prioRenderList();
      prioRenderTechs(prioTechStatus(base));
      prioSetBadge(prioLastItems.filter(i=> i.tier !== 'watch').length);
    }catch(e){
      console.error('priority render failed', e);
      $('prioList').innerHTML = '<div class="empty-state">Couldn\u2019t load the priority list — pull to refresh.</div>';
    }
  }
  let prioLastBase = null;
  // "Late" is time-based, so re-check every 2 minutes while the admin is
  // looking at the homepage — a job order turns red at its dispatch time
  // without anyone having to refresh.
  //
  // Time-ins/outs and job-order moves must show up without leaving the
  // homepage, so a refresh re-reads today's DTR and the job orders (the
  // two things "Technicians today" and the late rule depend on) instead of
  // re-drawing the data from when the page opened. Triggered by: realtime
  // changes on dtr_records / dispatch_tickets (when those tables publish),
  // a 60-second poll as the safety net, and returning to the app.
  let prioRefreshing = false, prioRefreshTimer = null, prioRt = null;
  function prioHomeVisible(){
    return !!prioLastBase && currentUser && currentUser.role === 'admin' && !document.hidden && $('homeScreen').style.display !== 'none';
  }
  async function prioRefreshLive(){
    if(!prioHomeVisible() || prioRefreshing) return;
    prioRefreshing = true;
    try{
      const [dtrToday, tickets] = await Promise.all([
        dtrListAllForDate(todayISO()).catch(()=> null),
        dtListAll().catch(()=> null)
      ]);
      const base = Object.assign({}, prioLastBase);
      if(dtrToday) base.dtrToday = dtrToday;
      if(tickets) base.tickets = tickets;
      await prioRender(base);
    }finally{ prioRefreshing = false; }
  }
  function prioRefreshSoon(){
    clearTimeout(prioRefreshTimer);
    prioRefreshTimer = setTimeout(prioRefreshLive, 1500);   // bursts of changes → one refresh
  }
  function prioStartLive(){
    if(prioRt || !db || !db.channel) return;
    try{
      prioRt = db.channel('admin-priority-live')
        .on('postgres_changes', { event:'*', schema:'public', table:'dtr_records' }, prioRefreshSoon)
        .on('postgres_changes', { event:'*', schema:'public', table:'dispatch_tickets' }, prioRefreshSoon)
        .subscribe();
    }catch(e){ prioRt = null; }
  }
  setInterval(prioRefreshLive, 60000);
  document.addEventListener('visibilitychange', ()=>{ if(!document.hidden) prioRefreshSoon(); });

  $('prioList').addEventListener('click', async (e)=>{
    if(e.target.closest('#prioMoreBtn')){ prioExpanded = true; prioRenderList(); return; }
    const b = e.target.closest('[data-prio]'); if(!b) return;
    const [i, j] = b.dataset.prio.split(':').map(Number);
    const it = prioLastItems[i]; const act = it && it.actions[j];
    if(!act) return;
    try{ closeMainMenu && closeMainMenu(); }catch(err){}
    try{ await act.run(); }catch(err){ console.error('priority action failed', err); toast('Could not open that'); }
  });

  // ---- quick approve (leave, MR as requested) ----
  let prioQaItem = null;
  function prioQaClose(){ $('prioQaOverlay').classList.remove('open'); prioQaItem = null; }
  function prioQuickApprove(key){
    const it = prioLastItems.find(x=> x.key === key); if(!it) return;
    prioQaItem = it;
    let title, body;
    if(it.kind === 'leave'){
      const r = it.rec;
      title = 'Approve leave for ' + (r.userName || 'this technician') + '?';
      body = '<div>' + escapeHtml((r.leaveType || 'Leave') + ' · ' + prioDateRange(r.dateFrom, r.dateTo) + ' (' + (r.days || 1) + (Number(r.days) === 1 ? ' day' : ' days') + ')') + '</div>' +
        '<div>' + escapeHtml(it.others.length ? 'Also off those days: ' + it.others.map(o=> o.userName).join(', ') : 'No other technician is off those days.') + '</div>' +
        '<div' + (it.jos.length ? ' class="prio-qa-warn"' : '') + '>' + escapeHtml(it.jos.length ? it.jos.length + ' job order' + (it.jos.length === 1 ? ' is' : 's are') + ' assigned to them on those dates: ' + it.jos.map(t=> t.jobOrderNo).join(', ') : 'No job orders assigned to them on those dates.') + '</div>' +
        (r.reason ? '<div class="prio-qa-muted">Reason: ' + escapeHtml(r.reason) + '</div>' : '');
    }else{
      const m = it.rec;
      title = 'Approve ' + m.mrf_no + ' as requested?';
      body = '<div>' + escapeHtml((m.requester_name || 'Technician') + ' · ' + it.lines.length + ' item' + (it.lines.length === 1 ? '' : 's')) + '</div>' +
        '<ul class="prio-qa-lines">' + it.lines.map(l=> '<li>' + escapeHtml(l.description + ' — ' + mrQty(l.qty_requested) + (l.unit ? ' ' + l.unit : '')) + '</li>').join('') + '</ul>' +
        '<div class="prio-qa-muted">To change a quantity, use Open instead.</div>';
    }
    $('prioQaTitle').textContent = title;
    $('prioQaBody').innerHTML = body + '<div class="prio-qa-muted">Recorded as approved by ' + escapeHtml((currentUser && currentUser.name) || 'you') + '. The technician is notified.</div>';
    $('prioQaOverlay').classList.add('open');
  }
  $('prioQaCancel').addEventListener('click', prioQaClose);
  $('prioQaApprove').addEventListener('click', async ()=>{
    const it = prioQaItem; if(!it) return;
    const btn = $('prioQaApprove'); btn.disabled = true; btn.textContent = 'Approving…';
    try{
      if(it.kind === 'leave'){
        await leaveDecide(it.rec.id, 'approved', '');
      }else{
        const m = it.rec;
        const { data, error } = await db.from('material_requisitions').update({ status: 'approved' }).eq('id', m.id).eq('status', 'submitted').select('id');
        if(error) throw error;
        if(!data || !data.length){ toast(m.mrf_no + ' was already decided'); }
        else{
          toast(m.mrf_no + ' approved');
          notifyUser(m.requested_by, 'Material request approved', m.mrf_no + ' was approved.', 'mrf-' + m.id);
        }
      }
      prioQaClose();
      if(typeof renderHomeOverview === 'function') renderHomeOverview();
    }catch(e){
      console.error('quick approve failed', describeCloudError(e));
      toast('Could not approve — ' + ((e && e.message) || 'try again'));
    }finally{ btn.disabled = false; btn.textContent = 'Approve'; }
  });


